#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    size_t packet_size;
    double throughput;
    char hostname[256];
} log_entry;

void* dns_resolve(const char* hostname, u_char* ip);
int log_parse(FILE*, log_entry** entry);
void log_print(const log_entry* entry);

u_char ip[16];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening log file");
        return 2;
    }

    log_entry* current_entry = NULL;
    double last_throughput = 0.0;
    size_t entries_processed = 0;
    while (log_parse(file, &current_entry)) {
        pthread_mutex_lock(&mutex);
            dns_resolve(current_entry->hostname, ip);
        pthread_mutex_unlock(&mutex);

        current_entry->throughput = (current_entry->packet_size / (time(NULL) - current_entry->timestamp)) * 8.0;
        last_throughput = (last_throughput * entries_processed + current_entry->throughput) / (entries_processed + 1);
        log_print(current_entry);

        free(current_entry);
        current_entry = NULL;
        entries_processed++;
    }

    fclose(file);
    return 0;
}

int log_parse(FILE* file, log_entry** entry) {
    char line[4096];
    size_t len = fread(line, sizeof(char), sizeof(line) - 1, file);
    if (len == 0 || feof(file)) return 0;

    line[len] = '\0';
    log_entry* new_entry = malloc(sizeof(log_entry));
    memset(new_entry, 0, sizeof(log_entry));

    sscanf(line, "%ld %lud %lf %255s", &new_entry->timestamp, &new_entry->packet_size, &new_entry->throughput, new_entry->hostname);
    *entry = new_entry;
    return 1;
}

void log_print(const log_entry* entry) {
    printf("%ld,%lud,%lf,%s,%lf\n", entry->timestamp, entry->packet_size, entry->throughput, entry->hostname, last_throughput);
}

void* dns_resolve(const char* hostname, u_char* ip) {
    struct hostent* result = gethostbyname(hostname);
    if (!result) return NULL;

    memcpy(ip, result->h_addr, result->h_length);
    return ip;
}
```

