// Function to generate a SHA-256 hash of the message for rate limiting purposes
char *generateHash(const char *message) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, message, strlen(message));
    SHA256_Final(digest, &ctx);

    char hash[64];
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf(&hash[2*i], "%02x", digest[i]);
    }
    return hash;
}

// Function to manage and route error messages based on their severity and frequency
void log_message(const char *message, Config *config) {
    // Generate SHA-256 hash of the message for rate limiting purposes
    const char *hash = generateHash(message);

    // Check if we should log this message according to its severity and the configured thresholds
    int min_severity = (config->debug > 0) ? config->debug : config->info;
    if (strchr(message, '\n') != NULL) {
        min_severity -= 1; // Decrease the minimum severity for multi-line messages
    }
    if (config->severities[min_severity] >= atoi(message + strcspn(message, ":"))) {
        time_t now = time(NULL);
        double latency;
        rate_limiter_t *rate_limiters[4];

        for (int i = 0; i < 4; ++i) {
            rate_limiters[i] = &config->rate_limiters[i];
            if (now - rate_limiters[i]->timestamp > rate_limiters[i]->rate_limit) {
                rate_limiters[i]->count = 0;
                rate_limiters[i]->timestamp = now;
            }
        }

        // Call the appropriate logging functions for each destination, considering latency variations and resource usage
        for (LogDestination *destination : config->destinations) {
            if (now - destination->last_log[min_severity] > 5) { // Wait 5 seconds before sending logs to console during high load
                destination->func(message);
                destination->last_log[min_severity] = now;
                latency = (double)(now - destination->func_time) / CLOCKS_PER_SEC;
                if (latency > 0.1) { // Logging channel is slow, wait some time before sending logs to other destinations
                    usleep(latency * 1e6);
                }
            }
        }
    }
}
```

