#include <atomic_wrappers/atomic_wrapper.h> // For thread-safe atomic operations (optional, depending on your platform)

#define SEMAPHORE_MAX 100
#define THREAD_MAX 1000

// Custom semaphore structure with additional fields for tracking and management
typedef struct _semaphore {
    sem_t base; // Underlying semaphore
    atomic_int_t ref_count; // Number of active threads using this semaphore
    void * init_val; // Initial value provided by external data source (if any)
} Semaphore;

// Thread-safe list of semaphores, managed with a linked list and mutex for concurrent access
typedef struct _semaphore_list {
    Semaphore *head;
    Semaphore *tail;
    pthread_mutex_t lock;
} SemaphoreList;

// Function to create a new semaphore with the provided initial value (or default 1 if none is given)
Semaphore* create_semaphore(void * init_val) {
    Semaphore *sem = malloc(sizeof(Semaphore));
    sem->ref_count = ATOMIC_INIT(0);
    sem->init_val = (init_val != NULL) ? init_val : malloc(1); // Allocate memory for init_val if provided
    sem_init(&sem->base, 0, sem->init_val ? *(int*)sem->init_val : 1);
    return sem;
}

// Function to manage the lifecycle of semaphores in a thread-safe manner
SemaphoreList* init_semaphore_list() {
    SemaphoreList *list = malloc(sizeof(SemaphoreList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a semaphore to the list, ensuring that we never exceed SEMAPHORE_MAX
void add_semaphore(SemaphoreList *list, Semaphore *sem) {
    pthread_mutex_lock(&list->lock);
        if (list->head == NULL) {
            list->head = sem;
            list->tail = sem;
        } else {
            list->tail->next = sem;
            list->tail = sem;
        }
    pthread_mutex_unlock(&list->lock);

    if (list->head != NULL && list->head->ref_count < SEMAPHORE_MAX) {
        atomic_inc(&(list->head->ref_count));
    }
}

// Function to remove a semaphore from the list, ensuring that we never go below one semaphore
void remove_semaphore(SemaphoreList *list, Semaphore *sem) {
    pthread_mutex_lock(&list->lock);
        if (list->head == NULL) return;

        if (list->head == sem) {
            list->head = list->head->next;
            free(sem->init_val); // Free init_val if provided
            free(sem);
        } else {
            Semaphore *temp = list->head;
            while (temp->next != sem) temp = temp->next;
            temp->next = sem->next;
            free(sem->init_val); // Free init_val if provided
            free(sem);
        }
    pthread_mutex_unlock(&list->lock);
}

// Function to use a semaphore, incrementing its ref_count and waiting if needed
void sem_use(Semaphore *sem) {
    atomic_inc(&(sem->ref_count));
    sem_wait(&sem->base);
}

// Function to release a semaphore, decrementing its ref_count and signaling if needed
void sem_release(Semaphore *sem) {
    atomic_dec(&(sem->ref_count));
    if (atomic_read(&(sem->ref_count)) <= 0) {
        free(sem->init_val); // Free init_val if provided
        sem_destroy(&sem->base);
        remove_semaphore(semaphores, sem);
        free(sem);
    } else {
        sem_post(&sem->base);
    }
}
```

This code provides a basic structure for managing a collection of semaphores in a multi-threaded environment. The `SemaphoreList` struct maintains the list of semaphores, and the functions allow for creating, adding, removing, using, and releasing semaphores in a thread-safe manner.

It is important to note that this code does not include the necessary error handling, logging, and performance monitoring mechanisms as per your requirements (items 4, 6, 7). Additionally, you may need to handle potential race conditions when adding and removing semaphores from the list by using additional synchronization primitives or more advanced data structures.']

