public class CreateDynamicDirectoryFromConfig
{
    private readonly ILogger<CreateDynamicDirectoryFromConfig> _logger;
    private readonly string _logFilePath;
    private readonly int _maxRetries;
    private readonly TimeSpan _retryDelay;

    public CreateDynamicDirectoryFromConfig(ILogger<CreateDynamicDirectoryFromConfig> logger, string logFilePath, int maxRetries = 3, TimeSpan retryDelay = TimeSpan.FromSeconds(5))
    {
        _logger = logger;
        _logFilePath = logFilePath;
        _maxRetries = maxRetries;
        _retryDelay = retryDelay;
    }

    public async Task<string> CreateDynamicDirectoryAsync(string configFile, string targetElementName, string baseDirectoryPath, string environmentVariableName)
    {
        var directoryPath = $"{baseDirectoryPath}/{GetElementPathFromConfig(configFile, targetElementName)}";
        Directory.CreateDirectory(directoryPath);

        if (Environment.SetEnvironmentVariable(environmentVariableName, directoryPath))
        {
            _logger.LogInformation($"Created directory: {directoryPath} and set environment variable '{environmentVariableName}' to its path.");
            return directoryPath;
        }

        var exceptionHandler = new ExceptionHandler(_logger, _logFilePath);

        try
        {
            await CreateDirectoryWithRetryAsync(directoryPath, exceptionHandler);
            Environment.SetEnvironmentVariable(environmentVariableName, directoryPath);
            _logger.LogInformation($"Created directory: {directoryPath} and set environment variable '{environmentVariableName}' to its path.");
            return directoryPath;
        }
        catch (Exception ex)
        {
            exceptionHandler.HandleException(ex, $"Error creating directory '{directoryPath}'");
        }

        return null;
    }

    private XmlElement GetElementFromConfig(XmlDocument configDoc, string targetElementName)
    {
        var elements = configDoc.DocumentElement.SelectNodes($"//{targetElementName}");

        if (elements == null || elements.Count > 1)
        {
            _logger.LogWarning($"Found multiple '{targetElementName}' elements in the configuration file or none at all.");
        }

        return elements?.Cast<XmlElement>().FirstOrDefault();
    }

    private string GetElementPathFromConfig(string configFile, string targetElementName)
    {
        using (var reader = XmlReader.Create(configFile))
        {
            var configDoc = new XmlDocument();
            configDoc.Load(reader);
            return GetElementFromConfig(configDoc, targetElementName)?.OuterXml?.TrimEnd('/');
        }
    }

    private async Task CreateDirectoryWithRetryAsync(string directoryPath, ExceptionHandler exceptionHandler)
    {
        for (int i = 0; i < _maxRetries; i++)
        {
            try
            {
                if (!Directory.Exists(directoryPath))
                {
                    Directory.CreateDirectory(directoryPath);
                }

                return;
            }
            catch (Exception ex)
            {
                exceptionHandler.HandleException(ex, $"Error creating directory '{directoryPath}' (attempt: {i + 1})");

                if (i < _maxRetries - 1)
                {
                    await Task.Delay(_retryDelay);
                }
            }
        }

        throw new Exception($"Failed to create directory '{directoryPath}' after {_maxRetries} attempts");
    }
}

public class ExceptionHandler
{
    private readonly ILogger<ExceptionHandler> _logger;
    private readonly string _logFilePath;

    public ExceptionHandler(ILogger<ExceptionHandler> logger, string logFilePath)
    {
        _logger = logger;
        _logFilePath = logFilePath;
    }

    public void HandleException(Exception exception, string message)
    {
        WriteToLogFile($"{message} - {exception.Message}\nStack Trace:\n{exception.StackTrace}", ExceptionLevel.Error);
    }

    public void WriteToLogFile(string content, ExceptionLevel level)
    {
        using (var writer = new StreamWriter(_logFilePath, true))
        {
            writer.WriteLine($"{DateTime.Now:yyyy-MM-dd HH:mm:ss} [{level}] - {content}");
        }
    }
}

public enum ExceptionLevel { Error, Warning }
```']

