public final class ThemeManager {

 private static final Map<String, Theme> CACHE = new HashMap<>();
 private static final File THEME_CACHE = new File("themes_cache");

 public static Theme loadTheme(String themeName) throws IOException, ParserConfigurationException {
 if (CACHE.containsKey(themeName)) {
 return CACHE.get(themeName);
 }

 File themeFile = new File(THEME_CACHE, themeName + ".xml");
 if (!themeFile.exists()) {
 return null;
 }

 DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
 DocumentBuilder builder = factory.newDocumentBuilder();
 Document doc = builder.parse(themeFile);

 Element root = doc.getDocumentElement();
 String format = root.getAttribute("format");

 if ("PNG".equalsIgnoreCase(format)) {
 InputStream input = new FileInputStream(themeFile);
 BufferedImage image = ImageIO.read(input);
 return new Theme(themeName, image);
 } else if ("XML".equalsIgnoreCase(format)) {
 // Parse XML configuration and construct the corresponding Theme object
 // ...
 }

 return null;
 }

 public static void updateCache() throws FileNotFoundException {
 CACHE.clear();

 if (!THEME_CACHE.exists()) {
 THEME_CACHE.mkdirs();
 }

 File[] themeFiles = THEME_CACHE.listFiles((dir, name) -> name.endsWith(".xml"));
 for (File file : themeFiles) {
 String themeName = file.getName().substring(0, file.getName().length() - 5);
 Theme theme = loadTheme(themeName);
 if (theme != null) {
 CACHE.put(themeName, theme);
 }
 }
 }
}

class Theme {
 private final String name;
 private Object resource; // This can be either an Image or a Gson-parsed XML configuration

 public Theme(String name, Object resource) {
 this.name = name;
 this.resource = resource;
 }

 // Add getters and setters as needed for the specific resource type
}
