```javascript
function RefreshFields(resourceId, url, fieldsToRefresh) {
    var forwardList = this.forwardList || []; // accessing 'this' for class methods

    if (!angular.isArray(fieldsToRefresh)) {
        console.error('Expected fieldsToRefresh to be an array.');
        return;
    }

    function refreshField(field) {
        var deferred = $q.defer();

        // Make the actual API call or data retrieval here.
        $http({
            method: 'GET',
            url: url + '/' + field,
            responseType: 'json'
        })
        .success(function(data) {
            deferred.resolve(data);
        })
        .error(function() {
            // Handle retry logic for network failures or service unavailability here.
            deferred.reject();
        });

        return deferred.promise;
    }

    var promises = fieldsToRefresh.map(refreshField);

    $q.all(promises)
    .then(function(results) {
        results.forEach(function(result, index) {
            if (result.status === 'success') {
                forwardList[fieldsToRefresh[index]] = result.data;
                parent.postMessage({ field: fieldsToRefresh[index], data: result.data }, '*'); // assuming parent is the parent window reference
            }
        });
    })
    .catch(function(error) {
        console.error('Error while refreshing fields:', error);
        // Handle error recovery mechanisms here.
    });
}
