    if (memoryUsage + eventQueue.length > maxMemory) return;
    const dataBatch = eventQueue.slice(0, batchSize);
    eventQueue = eventQueue.slice(batchSize);
    memoryUsage -= dataBatch.length;
    try {
      await sendDataToServer(dataBatch);
    } catch (error) {
      if (retries < maxRetries) {
        setTimeout(() => logEvents(), Math.min(2 ** retries, interval));
        retries++;
      } else {
        console.error(`Failed to send data: ${error}`);
      }
    }
  };
  const processEvent = (event) => {
    if (isPaused) return;
    eventQueue.push(event);
    memoryUsage++;
    if (eventQueue.length >= batchSize || Date.now() - lastLogTime >= interval) {
      logEvents();
    }
  };
  const pause = () => {
    isPaused = true;
  };
  const resume = () => {
    isPaused = false;
    if (eventQueue.length > 0) logEvents();
  };
  let retries = 0;
  let lastLogTime = Date.now();
  return { processEvent, pause, resume };
};

