use std::process::{Command, Stdio};
use std::sync::SyncLazy;
use std::time::Instant;
use rustc_driver::{Configuration, Driver, DriverBuilder, EarlyError, ErrorKind};
use libc::fprintf;

static LOGGER: SyncLazy<Logger> = SyncLazy::new(Logger::new);

struct Logger {
    error_log: File,
}

impl Logger {
    fn new() -> Self {
        let log_path = env::var("RUST_LOG").unwrap_or_else(|_| "rust_log".to_owned());
        let error_log = fs::OpenOptions::new()
            .write(true)
            .create(true)
            .open(format!("{}.error", log_path))
            .expect("Unable to create error log file.");
        Self { error_log }
    }

    fn log(&self, format: &str, args: std::ffi::NlArgs) {
        unsafe {
            let mut fd = self.error_log.as_raw_fd();
            let formatted = format_args!(format, args).to_string();
            let len = formatted.len() as i32;
            let c_args: [std::os::raw::c_char; 1] = [formatted.as_ptr()];

            fprintf(fd, c_args.as_mut_ptr(), len);
            fflush(fd);
        }
    }
}

