    // Compile the project with custom logging hook installed.
    let mut configuration = Configuration::new();
    let mut driver_builder = DriverBuilder::new(&configuration);

    // Use a temporary file to redirect error messages to the Logger instance.
    let tempfile = File::create(".rustc-error").unwrap();
    let mut temp_writer = BufWriter::new(tempfile);
    let stderr = io::stderr().take();
    let stdout = Stdio::piped().unwrap();
    let mut driver = driver_builder
        .stdin(Stdio::null())
        .stderr(move || Box::new(temp_writer))
        .stdout(stdout)
        .build();

    // SyncLogger ensures that the Logger instance is thread-safe.
    let logger = LOGGER.sync_ref().error_log.clone();
    driver.set_error_hook(|driver, early_err| {
        match early_err {
            EarlyError::ErrorKind(ErrorKind::Internal(err)) => {
                eprintln!("{}", err);
                driver.abort();
            }
            _ => {
                let mut args = vec!["rustc".to_string(), "-E".to_string(), "-".to_owned(), &project_path];
                // Customize the error log file for C functions.
                let c_log_path = format!("{}.c-error", log_path);
                args.push(format!("-Cdebugger-agent=dwarf,framework=lldb,library-file={}", c_log_path));

                let mut command = Command::new("rustc");
                command.args(&args)
                    .stdin(temp_writer)
                    .stderr(move || Box::new(logger))
                    .stdout(temp_writer);

                let output = command.spawn().unwrap();
                let status = output.wait().unwrap();
                status.code().unwrap()
            }
        }
    });

    driver.driver(&project_path, &configuration).expect("Unable to compile the project.");

    let rss_end = get_resident_set_size();
    println!(
        "Compilation time: {} seconds\nResident Set Size (start): {}\nResident Set Size (end): {}",
        start.elapsed().as_secs_f64(),
        rss_start,
        rss_end
    );

    // Print the error log file content.
    tempfile.seek(io::SeekFrom::Start(0)).unwrap();
    let mut contents = String::new();
    tempfile.read_to_string(&mut contents).expect("Unable to read the error log file.");
    println!("Error Log:\n{}", contents);

    driver.exit_code()
}

extern "C" {
    fn rust_error_log(format: *const libc::c_char, ...) -> () {
        let args = std::ffi::NlArgs::from_slice(std::ffi::arg_array(format));
        unsafe { LOGGER.sync_ref().log(format, args) };
    }
}
