["```javascript
const { Promisify, delay } = require('bluebird');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const https = require('https');
const url = require('url');

class StreamManager {
  constructor(options) {
    this.paused = false;
    this.buffer = [];
  }

  async write(data) {
    if (!this.paused) this.buffer.push(data);
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  async end() {
    if (this.paused) return;

    const content = Buffer.concat(this.buffer);
    this.buffer = [];
    return content;
  }
}

async function readFile(filePath, streamManager) {
  return new Promise((resolve, reject) => {
    const readStream = fs.createReadStream(filePath);
    streamManager.on('data', data => readStream.write(data));
    readStream.on('end', () => resolve(streamManager.end()));
    readStream.on('error', error => reject(error));
  });
}

async function fetchResource(urlObj) {
  const options = { ...urlObj, method: 'GET' };
  return new Promise((resolve, reject) => {
    const request = https.request(options, (response) => {
      if (!response.statusCode || response.statusCode !== 200) {
        response.destroy();
        return reject(new Error(`Failed to fetch resource: ${urlObj.href}: status code ${response.statusCode}`));
      }

      const streamManager = new StreamManager();
      response.on('data', chunk => streamManager.write(chunk));
      response.on('end', () => resolve(streamManager.end()));
      response.on('error', error => reject(error));
    });

    request.on('error', error => reject(error));
    request.end();
  });
}

async function generateCombinedCertificate(oauthRequest) {
  const privateKeyPath = path.join(__dirname, oauthRequest.private_key);
  const certificatePath = path.join(__dirname, oauthRequest.certificate);

  try {
    const privateKeyStream = await readFile(privateKeyPath, new StreamManager());
    const certificateStream = await fetchResource(url.parse(`https://${oauthRequest.issuer}/${oauthRequest.certificate_path}`));

    // Concatenate private key and certificate streams and save the result to a temporary file
    // ... (You can use any existing library for this purpose, such as node-stream-concat or stream-buffers)

    // Load the concatenated PEM data from the temporary file
    const pemData = await fs.promises.readFile(`${__dirname}/temp-certificate.pem`);

    return pemData.toString();
  } catch (error) {
    if (error.message.includes('ETIMEDOUT')) {
      // Retry after a delay to handle timeouts
      await delay(5000);
      return generateCombinedCertificate(oauthRequest);
    }

    throw error;
  }
}
```"]

