char* processString(const char* str, size_t limit) {
    if (strlen(str) > limit) return NULL;

    size_t new_size = strlen(str) + 1 + (limit - strlen(str)) <= limit ? strlen(str) + 1 : limit + 1;
    char* result = malloc(new_size);
    strcpy(result, str);

    if (strlen(str) < limit) result[strlen(str)] = '/';
    return result;
}
