2. C Function `traverseDOM`:

```c
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    void* element;
    struct Node* next;
} Node;

Node* traverseDOM(void* root, const char* selector, bool (*callback)(void*)) {
    if (!root || !selector) return NULL;

    // External library API for querying elements with a given selector.
    void* matched_elements = externalLibraryQuerySelector(root, selector);

    Node* head = NULL;
    Node* current = NULL;
    void** element_array = malloc((size_t)matched_elements * sizeof(void*));
    memcpy(element_array, matched_elements, (size_t)matched_elements * sizeof(void*));
    free(matched_elements);

    for (int i = 0; i < matched_elements; ++i) {
        void* current_element = element_array[i];
        if (!callback((current_element))) continue;

        Node* new_node = malloc(sizeof(Node));
        new_node->element = current_element;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
            current = head;
        } else {
            current->next = new_node;
            current = current->next;
        }
    }

    free(element_array);
    return head;
}
