    int num_digits = (len + vowel_count < 5) ? (5 - (len + vowel_count)) : 0;
    int i;

    strncpy(buf, filename, sizeof(buf) - num_digits - 4); // leave space for numbers and extension
    buf[sizeof(buf) - num_digits - 4] = '\0'; // create a null-terminated substring for counting vowels
    int count = vowel_count(buf);
    sprintf(&buf[strlen(buf)], "%0*d.", num_digits, count); // append the sequence of numbers
