        fd->result = -1;
        return NULL;
    }

    int res = rename(fd->filename, new_filename);
    if (res == 0)
        fd->result = 0; // Success!

    return NULL;
}

int rename_files(char** filenames, int num_files) {
    pthread_t threads[100];
    FileData files[100];

    for (int i = 0; i < num_files; ++i) {
        files[i].filename = filenames[i];
        pthread_create(&threads[i], NULL, rename_file, &files[i]);
    }

    int success_count = 0;
    for (int i = 0; i < num_files; ++i) {
        if (pthread_join(threads[i], NULL))
            continue; // error occurred during join, ignore this thread and move on to the next one

        if (files[i].result == 0)
            success_count++;
    }

    return success_count;
}
