[' Here is a Java application that meets your requirements using the `ProcessBuilder` class for executing shell commands and the `Files` class for directory cleaning. This application reads configuration from an external properties file, handles multiple potential errors, logs messages to standard output and error streams, and logs exceptions to a specified log file.

```java
import java.io.*;
import java.nio.file.*;
import java.util.Properties;
import java.util.logging.*;

public class Main {
    private static final Logger LOGGER = Logger.getLogger(Main.class.getName());
    private static Properties properties;
    private static String logFilePath;

    public static void main(String[] args) {
        try {
            properties = new Properties();
            properties.load(new FileInputStream("config.properties"));

            String maintenanceDir = properties.getProperty("maintenance.directory");
            logFilePath = properties.getProperty("log.file.path");

            clearDirectory(Paths.get(maintenanceDir));
            executeCommands(properties);

        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Failed to read configuration or clear directory", e);
        }
    }

    private static void clearDirectory(Path path) {
        try {
            Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    Files.deleteIfExists(file);
                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Error while cleaning the directory", e);
        }
    }

    private static void executeCommands(Properties properties) {
        String command = properties.getProperty("command");
        String osCommand = String.format("bash -c '%s'", command);

        try {
            ProcessBuilder pb = new ProcessBuilder("sh", "-c", osCommand);
            pb.redirectErrorStream(true);
            Process process = pb.start();

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                LOGGER.log(Level.WARNING, "Command execution failed with code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Error while executing command", e);
        }
    }
}
```

