#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <openssl/aes.h>
#include <err.h>

typedef struct {
    char *password;
    ConnectionInfo connection_info;
    void (*callback)(void*);
} ConnectionContext;

typedef struct {
    char title[256];
    unsigned char encrypted_message[MAX_MESSAGE_LENGTH];
} ConnectionInfo;

#define MAX_KEY_LENGTH 32
#define MAX_IV_LENGTH 16
#define MAX_MESSAGE_LENGTH 1024

int decryptConnectionMessage(ConnectionContext* context) {
    if (!context || !context->password || strlen(context->password) == 0 ||
        context->connection_info.title[0] == '\0' || !context->callback)
        return EINVAL;

    EVP_CIPHER_CTX *ctx = NULL;
    unsigned char key[MAX_KEY_LENGTH];
    unsigned char iv[MAX_IV_LENGTH];
    int len;

    // Assumption: Password is base64 encoded.
    if (base64_decode(context->password, key, sizeof(key)) != 0)
        goto err;

    // Assumption: IV is always the first 16 bytes of encrypted_message
    memcpy(iv, context->connection_info.encrypted_message, sizeof(iv));

    ctx = EVP_TripleDES_init();
    if (!ctx)
        goto err;

    if (1 != EVP_TripleDES_set_key_and_iv(ctx, key, iv))
        goto err;

    unsigned char *decrypted_message = malloc(MAX_MESSAGE_LENGTH);
    if (!decrypted_message)
        goto err;

    len = MAX_MESSAGE_LENGTH;
    if (1 != EVP_TripleDES_decrypt(&context->connection_info.encrypted_message[sizeof(iv)], decrypted_message, &len, ctx))
        goto err;

    context->connection_info.title[0] = '\0'; // Clear title to avoid modifying original structure
    memcpy(context->connection_info.title, decrypted_message, len);

err:
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    free(decrypted_message);
    return errno;
}
```

This code assumes that the `ConnectionContext`, `ConnectionInfo`, and their respective fields are properly defined elsewhere in your project. The Triple DES decryption is handled using OpenSSL library functions, and error handling is done through standard C functions such as malloc(), free() and EVP_CIPHER_CTX_free()."]

