#include <jansson.h>

typedef struct {
    char *server_address;
    uint16_t port;
    unsigned int max_connections;
    const char *log_level;
} config;

bool parse_config(const char *config_json, config *cfg) {
    json_t *root, *obj;
    json_error_t error;

    root = json_loads(config_json, 0, &error);
    if (!root || !json_is_object(root)) {
        fprintf(stderr, "Invalid JSON configuration: %s\n", error.text);
        return false;
    }

    obj = json_object_get(root, "server_address");
    if (!obj || !json_is_string(obj)) {
        fprintf(stderr, "Missing or invalid server_address field.\n");
        json_decref(root);
        return false;
    }

    cfg->server_address = strdup(json_string_value(obj));

    obj = json_object_get(root, "port");
    if (!obj || !json_is_integer(obj)) {
        fprintf(stderr, "Missing or invalid port field.\n");
        free(cfg->server_address);
        json_decref(root);
        return false;
    }

    cfg->port = json_integer_value(obj);
    if (cfg->port < 1 || cfg->port > 65535) {
        fprintf(stderr, "Invalid port value.\n");
        free(cfg->server_address);
        json_decref(root);
        return false;
    }

    obj = json_object_get(root, "max_connections");
    if (!obj || !json_is_integer(obj)) {
        fprintf(stderr, "Missing or invalid max_connections field.\n");
        free(cfg->server_address);
        json_decref(root);
        return false;
    }

    cfg->max_connections = json_integer_value(obj);
    if (cfg->max_connections <= 0) {
        fprintf(stderr, "Invalid max_connections value.\n");
        free(cfg->server_address);
        json_decref(root);
        return false;
    }

    obj = json_object_get(root, "log_level");
    if (obj && json_is_string(obj)) {
        const char *log_level_str = json_string_value(obj);
        size_t len = strlen(log_level_str);
        if (len > 6) {
            fprintf(stderr, "Invalid log_level value (%zu characters).\n", len);
            free(cfg->server_address);
            json_decref(root);
            return false;
        }

        if (strcasecmp(log_level_str, "DEBUG") == 0 ||
            strcasecmp(log_level_str, "INFO") == 0 ||
            strcasecmp(log_level_str, "WARN") == 0 ||
            strcasecmp(log_level_str, "ERROR") == 0) {
            cfg->log_level = strdup(log_level_str);
        } else {
            fprintf(stderr, "Unrecognized log_level value: %s\n", log_level_str);
            free(cfg->server_address);
            json_decref(root);
            return false;
        }
    } else {
        cfg->log_level = NULL;
    }

    json_decref(root);
    return true;
}
```

