public class EncryptedMessageHandler
{
    private readonly ConcurrentPool<TripleDESCryptoServiceProvider> _keyPool;
    private readonly Random _random = new Random();

    public EncryptedMessageHandler()
    {
        _keyPool = new ConcurrentPool<TripleDESCryptoServiceProvider>(CreateKey);
    }

    private TripleDESCryptoServiceProvider CreateKey()
    {
        var key = new TripleDESCryptoServiceProvider();
        // You can add custom key generation logic here if needed
        return key;
    }

    public async Task<string> DecryptMessage(string id, string base64EncodedMessage)
    {
        ValidateInput(id, base64EncodedMessage);

        var iv = GenerateIV();
        var encryptedData = Convert.FromBase64String(base64EncodedMessage);

        using (var key = await _keyPool.BorrowAsync())
        {
            using (var decryptor = CreateDecryptor(key, iv))
            {
                var decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
                return Encoding.UTF8.GetString(decryptedData);
            }
        }
    }

    private ICryptoTransform CreateDecryptor(TripleDESCryptoServiceProvider key, byte[] iv)
    {
        var transform = key.CreateDecryptor();
        transform.IV = iv;
        return transform;
    }

    private void ValidateInput(string id, string base64EncodedMessage)
    {
        if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("ID is required", nameof(id));
        if (string.IsNullOrWhiteSpace(base64EncodedMessage)) throw new ArgumentException("Base64EncodedMessage is required", nameof(base64EncodedMessage));
        if (id.Length < 1) throw new ArgumentOutOfRangeException("ID must be greater than 0 characters long", nameof(id));
        if (!Base64EncodeValidate(base64EncodedMessage)) throw new ArgumentException("Invalid Base64 encoding", nameof(base64EncodedMessage));
    }

    private bool Base64EncodeValidate(string base64Encoded) => Base64Decode(base64Encoded).Length > 0;

    private byte[] GenerateIV() => new byte[TripleDESCryptoServiceProvider.KeySize/8];

    private byte[] Base64Decode(string base64Encoded) => Convert.FromBase64String(base64Encoded);
}
