['```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly string _connectionString;
    private const int ChunkSize = 1048576; // 1 MB

    public FileHasher(string connectionString)
    {
        _connectionString = connectionString;
    }

    private async Task ProcessChunkAsync(Stream stream, Func<byte[], Task> storeHash)
    {
        using SHA256 sha256 = SHA256.Create();
        byte[] buffer = new byte[ChunkSize];
        int bytesRead;

        while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            sha256.TransformBlock(buffer, 0, bytesRead, null, 0);

            if (buffer.Length == bytesRead) continue; // Not the last chunk

            byte[] hash = sha256.TransformFinalBlock(new byte[sha256.HashSize], 0, 0);
            await storeHash(hash);
            Array.Clear(buffer, 0, buffer.Length);
        }
    }

    public async Task HashFileAsync(Stream fileStream)
    {
        await UsingDatabaseConnectionAsync(async (conn) =>
        {
            using var transaction = conn.BeginTransaction();
            try
            {
                var hashTable = new byte[ChunkSize]; // Buffer for current chunk
                int bytesRead;
                while ((bytesRead = await fileStream.ReadAsync(hashTable, 0, hashTable.Length)) > 0)
                {
                    await ProcessChunkAsync(new MemoryStream(hashTable, 0, bytesRead), async (hash) =>
                    {
                        using var command = new SqlCommand("INSERT INTO Hashes VALUES (@Hash)", conn);
                        command.Parameters.AddWithValue("@Hash", hash);
                        await command.ExecuteNonQueryAsync();
                    });

                    if (bytesRead < hashTable.Length) // Last chunk
                    {
                        byte[] remainingBytes = new byte[bytesRead];
                        Array.Copy(hashTable, 0, remainingBytes, 0, bytesRead);
                        await ProcessChunkAsync(new MemoryStream(remainingBytes), async (hash) =>
                        {
                            using var command = new SqlCommand("INSERT INTO Hashes VALUES (@Hash)", conn);
                            command.Parameters.AddWithValue("@Hash", hash);
                            await command.ExecuteNonQueryAsync();
                        });
                    }
                }

                transaction.Commit();
            }
            catch
            {
                transaction.Rollback();
                throw;
            }
        });
    }

    private async Task UsingDatabaseConnectionAsync(Func<SqlConnection, Task> action)
    {
        using var connection = new SqlConnection(_connectionString);
        try
        {
            await connection.OpenAsync();
            await action(connection);
        }
        catch (SqlException ex)
        {
            Console.WriteLine($"Error occurred while connecting to the database: {ex}");
            await Task.Delay(TimeSpan.FromSeconds(5)); // Retry in 5 seconds
            UsingDatabaseConnectionAsync(action);
        }
    }
}
```

This code creates a `FileHasher` class that processes log files by reading them in chunks and storing their SHA-256 hashes securely in an external database. The code optimizes memory usage, handles potential delays or failures in database connections, and is easily extendable to support additional file formats or hashing algorithms.

To use this class, create a new instance of `FileHasher` with the connection string for your database:

