using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;

namespace DecryptionService
{
    public class DecryptionEngine
    {
        private readonly IConfiguration _configuration;
        private ICryptoTransform _aesEncryptor;
        private byte[] _macKey;
        private ICryptoTransform _hmacSHA256;

        public DecryptionEngine(IConfiguration configuration)
        {
            _configuration = configuration;
            InitializeDependencies();
        }

        private void InitializeDependencies()
        {
            // Load encryption key, IV and MAC key from a reliable source (database, config file etc.)
            // Add failover strategies to handle connectivity issues gracefully.
            var encryptionKey = _configuration.GetValue<string>("EncryptionKey");
            var iv = _configuration.GetValue<string>("IV");
            var macKey = _configuration.GetValue<string>("MACKey");

            using (var aesAlg = AES.Create())
            {
                using (var hmacSHA256Alg = new HMACSHA256(Encoding.UTF8.GetBytes(macKey)))
                {
                    _aesEncryptor = aesAlg.CreateDecryptor(Encoding.UTF8.GetBytes(encryptionKey), Encoding.UTF8.GetBytes(iv));
                    _hmacSHA256 = hmacSHA256Alg.Create();
                }
            }
        }

        public void DecryptStream(Stream ciphertext, Stream output)
        {
            var buffer = new byte[4096]; // Adjust size for performance and memory trade-offs
            int read;

            while ((read = ciphertext.Read(buffer, 0, buffer.Length)) > 0)
            {
                try
                {
                    var macLength = _hmacSHA256.ComputeHashSize();
                    var dataToMac = new byte[buffer.Length - macLength];
                    Array.Copy(buffer, 0, dataToMac, 0, buffer.Length - macLength);
                    var macBytes = new byte[macLength];
                    Array.Copy(buffer, buffer.Length - macLength, macBytes, 0, macLength);

                    using (var cryptoStream = new CryptoStream(ciphertext, _aesEncryptor, CryptoStreamMode.Read))
                    {
                        int decryptedLength;
                        while ((decryptedLength = cryptoStream.Read(dataToMac, 0, dataToMac.Length)) > 0)
                            output.Write(dataToMac, 0, decryptedLength);
                    }

                    if (!_hmacSHA256.ComputeHash(dataToMac).SequenceEqual(macBytes))
                        throw new Exception("MAC validation failed.");
                }
                catch (CryptographicException ex)
                {
                    Console.WriteLine($"Decryption error: {ex.Message}");
                }
            }
        }
    }
}
