    Poco::Net::HTTPClientSession session;
    std::function<void(const char*)> onReceive;

    void MakeRequest(const string& url) {
        Poco::Net::HTTPRequest request(Poco::Net::HTTPMessage::HTTP_GET, url);
        session.sendRequest(request);

        char buffer[4096];
        size_t bytesReceived = 0;
        while (true) {
            std::string response(buffer, buffer + sizeof(buffer));
            bytesReceived += session.receiveUntil(response, "\r\n");
            if (bytesReceived >= response.size())
                break;

            onReceive(response.data());
        }
    }
};

struct RetryStrategy {
public:
    RetryStrategy(int maxRetries, std::chrono::milliseconds initialDelay)
        : maxRetries_(maxRetries), initialDelay_(initialDelay) {}

    bool ShouldRetry(std::exception_ptr e) const {
        return ++attempts_ < maxRetries_;
    }

    std::chrono::milliseconds GetDelay() const {
        auto delay = initialDelay_ * std::pow(2, attempts_);
        if (delay > maxDelay_)
            delay = maxDelay_;
        return delay;
    }

private:
    int attempts_{0};
    int maxRetries_;
    std::chrono::milliseconds initialDelay_;
    std::chrono::milliseconds maxDelay_ = 1000 * 64; // 64 seconds
};

