size_t find_next_free(record *data, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        if (!data[i].key)
            return i;
    }
    return len;
}

void free_records(record *data, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        data[i].key = 0;
    }
}

int main() {
    char terminator;
    printf("Enter a termination character: ");
    scanf("%c", &terminator);

    int max, min;
    printf("Enter the minimum value range: ");
    scanf("%d%*c", &min);
    printf("Enter the maximum value range: ");
    scanf("%d%*c", &max);

    size_t data_len = 128; // Initial buffer length
    record *data = malloc(data_len * sizeof(record));
    if (!data) {
        fprintf(stderr, "Error allocating memory.\n");
        return 1;
    }

    size_t current_len = 0;
    while (true) {
        int value;
        if (scanf("%d%*c", &value)) {
            if (!validate(value, min, max)) {
                fprintf(stderr, "Invalid input: %d is outside the defined bounds.\n", value);
                continue;
            }
            size_t next_free = find_next_free(data, current_len);
            if (current_len == data_len) { // Buffer resizing
                data_len *= 2;
                record *temp = realloc(data, data_len * sizeof(record));
                if (!temp) {
                    fprintf(stderr, "Error allocating memory.\n");
                    free(data);
                    return 1;
                }
                data = temp;
            }
            data[next_free].key = value;
            data[next_free].offset = current_len + 1;
            ++current_len;
        } else if (getchar() == terminator) {
            break;
        }
    }

    int max_value = INT32_MIN;
    for (size_t i = 0; i < current_len; ++i) {
        if (data[i].key > max_value)
            max_value = data[i].key;
    }

    free_records(data, current_len);
    free(data);

    printf("The maximum integer value is: %d\n", max_value);
    return 0;
}
```

This code reads integers from standard input until a given termination character is encountered. It uses efficient memory usage by dynamically allocating the data array and resizing it when necessary. The function handles potential input errors gracefully, validating the input within a specified range. Additionally, it manages resource allocation and deallocation to prevent memory leaks and optimize performance.']

