@Component
public class ForwardListManager {
    private final Map<String, Deque<String>> forwardListMap = new ConcurrentHashMap<>();
    private final ScheduledExecutorService executorService = java.util.concurrent.Executors.newScheduledThreadPool(5);

    public void manageForwardList(String resourceId, String url, String[] fieldNames) {
        Session session = establishWebSocketConnection(url);
        if (session != null) {
            sendRefreshMessage(session, resourceId, fieldNames);
            executorService.scheduleAtFixedRate(() -> reconnectIfNecessary(url, session), 10, 30, TimeUnit.SECONDS);
        }
    }

    private void sendRefreshMessage(Session session, String resourceId, String[] fieldNames) {
        for (Map.Entry<String, Deque<String>> entry : forwardListMap.entrySet()) {
            Deque<String> deque = entry.getValue();
            if (Arrays.binarySearch(fieldNames, entry.getKey()) >= 0) {
                String messageToSend = String.format("{\"resourceId\":\"%s\", \"operation\":\"refresh\", \"field\":\"%s\"}", resourceId, entry.getKey());
                session.getBasicRemote().sendText(messageToSend);
                deque.add(session.getId());
            }
        }
    }

    private void reconnectIfNecessary(String url, Session existingSession) {
        if (existingSession != null && !existingSession.isOpen()) {
            try {
                Session newSession = establishWebSocketConnection(url);
                if (newSession != null) {
                    for (String sessionId : forwardListMap.values().stream().flatMap(Deque::stream).toList()) {
                        if (sessionId.equalsIgnoreCase(existingSession.getId())) {
                            newSession.getBasicRemote().sendText("{\"operation\":\"update\", \"key\":\"" + existingSession.getId() + "\", \"value\":\"" + session.getId() + "\"}");
                        }
                    }
                }
                existingSession.close();
            } catch (IOException | InterruptedException e) {
                // Handle exceptions and log errors
            }
        }
    }

    private Session establishWebSocketConnection(String url) {
        URI serverUri = URI.create(url);
        return WebSocketContainer.createClientSession(serverUri).addEventListener(this::onMessageReceived, this::onError, this::onOpen, this::onClose).getAsync().get()
                .orElse(null);
    }

    @OnMessage
    public void onMessageReceived(String message, Session session) {
        try {
            JSONObject jsonObject = new JSONObject(message);
            String operation = jsonObject.getString("operation");
            if ("update".equalsIgnoreCase(operation)) {
                String key = jsonObject.getString("key");
                updateForwardList(key, session.getId());
            } else if ("refresh".equalsIgnoreCase(operation)) {
                String fieldName = jsonObject.getString("field");
                refreshField(fieldName, session);
            }
        } catch (JSONException e) {
            // Handle exceptions and log errors
        }
    }

    private void updateForwardList(String key, String newSessionId) {
        for (Map.Entry<String, Deque<String>> entry : forwardListMap.entrySet()) {
            if (key.equalsIgnoreCase(entry.getKey())) {
                Deque<String> deque = entry.getValue();
                int index = deque.indexOf(newSessionId);
                if (index != -1) {
                    deque.remove(index);
                } else {
                    deque.add(newSessionId);
                }
            }
        }
    }

    private void refreshField(String fieldName, Session session) {
        if (forwardListMap.containsKey(fieldName)) {
