            int index = deque.indexOf(session.getId());
            if (index != -1) {
                String refreshResult = sendRefreshRequest(deque.get(index));
                updateField(fieldName, refreshResult);
            } else {
                updateField(fieldName, sendRefreshRequest(session.getId()));
            }
        }
