namespace ThemeCache {
    class RNG {
        std::mt19937 m_rng;
    public:
        explicit RNG() {
            std::time_t now = std::time(nullptr);
            unsigned long seed = static_cast<unsigned long>(now);
            m_rng.seed(seed);
        }
        std::mt19937& getRNG() { return m_rng; }
    };

    class ThemeCache {
        static const std::string DEFAULT_THEME_DIR = "themes";
        std::unordered_map<std::string, std::vector<char>> m_cache;
        RNG rng;
        std::filesystem::path m_themeDir;
    public:
        ThemeCache() {
            if (!std::filesystem::exists(m_themeDir)) {
                std::filesystem::create_directory(m_themeDir);
            }
        }
        ~ThemeCache() = default;

        void setDefaultThemeDir(const std::string& dir) {
            if (!std::filesystem::exists(dir)) {
                std::filesystem::create_directory(dir);
            }
            m_themeDir = dir;
        }

        void recycleBitmap(const std::string& key) {
            auto it = m_cache.find(key);
            if (it != m_cache.end()) {
                it->second.clear();
            }
        }

        const std::vector<char>& getBitmap(const std::string& key) {
            auto it = m_cache.find(key);
            if (it == m_cache.end()) {
                loadBitmapFromFile(key);
            }
            return it->second;
        }

    private:
        void loadBitmapFromFile(const std::string& key) {
            std::filesystem::path pngPath = m_themeDir / (m_themeDir + "/" + key + ".png");
            if (!std::filesystem::exists(pngPath)) {
                return;
            }

            FILE *fp = fopen((pngPath.string()).c_str(), "rb");
            if (!fp) {
                std::cout << "Error opening PNG file" << std::endl;
                return;
            }

            png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
            if (!png_ptr) {
                fclose(fp);
                std::cout << "Error creating PNG read struct" << std::endl;
                return;
            }

            png_infop info_ptr = png_create_info_struct(png_ptr);
            if (!info_ptr) {
                png_destroy_read_struct(&png_ptr, (png_infopp)nullptr, (png_infopp)nullptr);
                fclose(fp);
                std::cout << "Error creating PNG info struct" << std::endl;
                return;
            }

            png_init_io(png_ptr, fp);
            png_read_info(png_ptr, info_ptr);

            png_uint_32 width, height;
            png_get_IHDR(png_ptr, info_ptr, &width, &height, nullptr, nullptr, nullptr, 0, PNG_COLOR_TYPE_RGB);

            m_cache[key].resize(static_cast<size_t>(width * height * 3));

            png_read_update_bits(png_ptr, info_ptr, 0, static_cast<png_size_t>(m_cache[key].size()));
            png_read_data(png_ptr, m_cache[key].data(), m_cache[key].size());

            png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)nullptr);
            fclose(fp);
        }
    };

    AES_KEY *initAES256CBC(const char* password) {
        unsigned char key[32], iv[16];
        SHA1_CTX sha;
        SHA1_Init(&sha);
        SHA1_Update(&sha, password, strlen(password));
        SHA1_Final(key, &sha);
        memcpy(iv, rng.getRNG().generate(), 16);

        AES_set_encrypt_key(key, 256, &AES_KEY:: encctx);
        return &AES_KEY::encctx;
    }

    void freeAESContext(AES_KEY* ctx) {
        AES_free_ctx(ctx);
    }
}
