class ConvertAndDeserialize {
public:
    int convertAndDeserialize(const std::string& jpegPath, const std::string& pdfPath, std::istream& objectStream, bool optimizeForSpeed, std::function<void(const std::string&)> log) {
        if (!boost::filesystem::exists(jpegPath) || !boost::filesystem::is_regular_file(jpegPath)) {
            log("Error: JPEG file not found or empty.");
            return -1;
        }

        std::unique_ptr<JpegToPdfConverter> converter = std::make_unique<JpegToPdfConverter>();
        int result = converter->convert(jpegPath, pdfPath);
        if (result != 0) {
            if (!optimizeForSpeed) {
                log("Error: Failed to convert JPEG to PDF.");
            }
            return -1;
        }

        std::ifstream pdfFile(pdfPath, std::ios::binary);
        if (!pdfFile.is_open()) {
            log("Error: Unable to open the generated PDF file.");
            return -1;
        }

        std::stringstream ss;
        ss << pdfFile.rdbuf();
        auto serializedData = ss.str();

        std::istringstream is(serializedData);
        boost::archive::xml_iarchive ia(is);
        try {
            ia >> boost::serialization::make_nvp("", objectStream);
        } catch (const std::exception& e) {
            log("Error: Failed to deserialize the PDF contents.");
            return -1;
        }

        if (!boost::serialization::registry::get<std::string>("")->is_known(objectStream)) {
            log("Error: Unknown object type after deserialization.");
            return -1;
        }

        return 0;
    }
};
