typedef struct {
    nacl_key key;
    nacl_box *box;
    uint8_t iv[16];
    size_t session_id_len;
    uint8_t *session_id;
} gcm_context;

gcm_context* gcm_init(const char *password, size_t password_len, const char *salt, size_t salt_len) {
    if (password_len == 0 || salt_len > 64) {
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    // Derive key using KDF and PBKDF2
    nacl_key kdf_key;
    crypto_pwhash_scrypts256_strategy13(password, password_len, salt, salt_len, 32, 8, 1, &kdf_key.data[0], &kdf_key.length);

    // Generate unique IV per session
    crypto_random(gcm_context->iv, sizeof(gcm_context->iv));

    gcm_context* ctx = malloc(sizeof(gcm_context));
    if (!ctx) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    memset(ctx, 0, sizeof(gcm_context));
    ctx->key = kdf_key;
    ctx->box = nacl_box_new((const uint8_t *)&kdf_key.data[0], kdf_key.length);
    ctx->session_id_len = 16; // Session ID length is fixed for simplicity
    ctx->session_id = malloc(ctx->session_id_len);
    if (!ctx->session_id) {
        fprintf(stderr, "Out of memory\n");
        free(ctx);
        return NULL;
    }
    crypto_random(ctx->session_id, ctx->session_id_len);

    return ctx;
}

void gcm_cleanup(gcm_context *ctx) {
    if (ctx->session_id) free(ctx->session_id);
    nacl_box_free(ctx->box);
    memset(ctx, 0, sizeof(gcm_context));
}

void gcm_encrypt(const gcm_context *ctx, uint8_t *plaintext, size_t plaintext_len, uint8_t *ciphertext) {
    nacl_box_seal(ciphertext, NULL, plaintext, plaintext_len, ctx->iv, ctx->session_id, ctx->session_id_len);
}

void gcm_decrypt(const gcm_context *ctx, uint8_t *ciphertext, size_t ciphertext_len, uint8_t *plaintext) {
    nacl_box_open(plaintext, NULL, ciphertext, ciphertext_len, ctx->iv, ctx->session_id, ctx->session_id_len);
}
```

