#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char *processString(const char *input, size_t limit) {
    if (!input || strlen(input) > limit)
        return NULL;

    char *result = malloc(strlen(input) + 2); // plus trailing slash and null terminator
    if (!result) {
        perror("malloc failed");
        return NULL;
    }

    strcpy(result, input);
    result[strlen(input)] = '/';
    result[strlen(input) + 1] = '\0';

    return result;
}
