```c
#include <stdio.h>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xpath.h>
#include <string.h>
#include <stdlib.h>

typedef struct Node {
    xmlNode *node;
    struct Node *prev, *next;
} Node;

Node *create_node(xmlNode *node) {
    Node *new_node = malloc(sizeof(Node));
    new_node->node = node;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void insert_node(Node **head, Node *new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }

    new_node->next = *head;
    (*head)->prev = new_node;
    *head = new_node;
}

void traverseDOM(xmlDocPtr doc, const xmlChar *xpath) {
    xmlNodeSetPtr nodeset;
    Node *list_head = NULL;
    Node *current_node;

    nodeset = XPathEvalExpression(xpath, doc, NULL, 0);
    if (!nodeset) {
        fprintf(stderr, "XPath evaluation failed\n");
        return;
    }

    for (xmlNode *node = nodeset->nodeTab; node != NULL; node = node->next) {
        current_node = create_node(node);
        insert_node(&list_head, current_node);
    }

    // Traverse the list and process each matched node here.
}
