typedef struct Record {
    int key;
    int value;
} Record;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int compare_records(const void *a, const void *b) {
    return ((Record*)a)->key - ((Record*)b)->key;
}

size_t unique_integers(int *numbers, size_t length) {
    size_t unique = 0;
    for (size_t i = 0; i < length; ++i) {
        bool found = false;
        for (size_t j = 0; j < unique; ++j) {
            if (numbers[i] == numbers[unique_integers(numbers, unique)[j]]) {
                found = true;
                break;
            }
        }
        if (!found) {
            unique++;
        }
    }
    return unique;
}

void allocate_arrays(size_t num_unique, size_t *keys, size_t *offsets) {
    keys = realloc(keys, num_unique * sizeof(*keys));
    if (!keys) {
        log_error("Failed to allocate key array");
    }
    offsets = realloc(offsets, (num_unique + 1) * sizeof(*offsets));
    if (!offsets) {
        log_error("Failed to allocate offset array");
    }
}

int main() {
    size_t threshold;
    scanf("%zu", &threshold);

    int max = INT_MIN;
    int *numbers = NULL;
    size_t num_elements = 0;
    size_t num_unique = 0;
    Record *records = NULL;

    while (true) {
        int input;
        scanf("%d", &input);
        if (feof(stdin)) break;
        if (input > max) max = input;
        numbers = realloc(numbers, ++num_elements * sizeof(*numbers));
        if (!numbers || num_elements * sizeof(*numbers) > threshold) {
            log_error("Memory allocation exceeded limit");
        }
        numbers[num_elements - 1] = input;
    }

    num_unique = unique_integers(numbers, num_elements);
    allocate_arrays(num_unique, NULL, NULL);

    size_t *keys = calloc(num_unique, sizeof(*keys));
    if (!keys) {
        log_error("Failed to allocate key array");
    }
    size_t *offsets = calloc((num_unique + 1), sizeof(*offsets));
    if (!offsets) {
        free(keys);
        log_error("Failed to allocate offset array");
    }

    for (size_t i = 0; i < num_elements; ++i) {
        size_t index = numbers[i];
        keys[index]++;
        if (!offsets[index]) offsets[index] = numbers[i];
    }

    for (size_t i = 0; i < num_unique; ++i) {
        offsets[i + 1] = offsets[i] + keys[i];
    }

    allocate_arrays(num_unique, keys, NULL);

    records = malloc(num_unique * sizeof(*records));
    if (!records) {
        log_error("Failed to allocate record array");
    }

    qsort(keys, num_unique, sizeof(*keys), compare_records);
    for (size_t i = 0; i < num_unique; ++i) {
        size_t index = keys[i];
        records[index].key = index;
        records[index].value = rand() % (max - min(numbers, 1)) + min(numbers, 1);
    }

    qsort(records, num_unique, sizeof(*records), compare_records);

    for (size_t i = 0; i < num_unique; ++i) {
        printf("Key: %zu, Value: %d\n", records[i].key, records[i].value);
    }

    free(keys);
    free(offsets);
    free(numbers);
    free(records);

    return 0;
}
```

Assumptions and design choices:
- The memory threshold is defined by the user.
- The `max()` function is assumed to be available, or can be replaced with a simple implementation within the code provided.
- `qsort()` function from the C standard library is used for sorting arrays.
- Error handling is implemented through logging and graceful termination upon memory allocation failure.
- Random number generation is done using the C standard library's rand() function, which ensures portability across platforms.']

