#include <fcntl.h>
#include <unistd.h>

sem_t sharedSemaphore; // Declare the semaphore globally

int maxValue = -1000000;
int *numbers;
size_t numberCount = 0;

void manageSharedResource() {
    const int MAX_NUMBERS = 1000000;
    sem_init(&sharedSemaphore, 0, MAX_NUMBERS); // Initialize the semaphore with a value of MAX_NUMBERS

    char buffer[32];
    ssize_t bytesRead;
    size_t index = 0;

    while ((bytesRead = getline(&buffer, sizeof(buffer), stdin)) != EOF) {
        // Validate input and handle edge cases
        if (sscanf(buffer, "%d", &numbers[index]) != 1 || numbers[index] < -1000000 || numbers[index] > 1000000) {
            fprintf(stderr, "Invalid integer value: %s\n", buffer);
            break;
        }

        index++;
        sem_wait(&sharedSemaphore); // Wait for the semaphore before modifying the shared resource
        numberCount++;

        if (numbers[index - 1] > maxValue) {
            maxValue = numbers[index - 1];
        }

        sem_post(&sharedSemaphore); // Signal the semaphore after modifying the shared resource
    }

    free(numbers); // Deallocate the dynamically allocated array when done
    sem_destroy(&sharedSemaphore); // Destroy the semaphore to prevent resource leaks
}

void processIntegers() {
    int bufferSize = 1024;
    numbers = malloc(bufferSize * sizeof(int));

    manageSharedResource();
}

int main() {
    processIntegers();
    printf("The maximum integer value is: %d\n", maxValue);

    return 0;
}
```

