#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <limits.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    long value;
} Record;

typedef struct {
    Record *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray create_dynamic_array(size_t initial_capacity) {
    DynamicArray array = {NULL, initial_capacity, 0, PTHREAD_MUTEX_INITIALIZER};
    array.data = calloc(initial_capacity, sizeof(Record));
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->data);
    array->data = NULL;
}

size_t next_power_of_two(size_t n) {
    size_t result = 1;
    while (result < n) result *= 2;
    return result;
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    DynamicArray temp = create_dynamic_array(next_power_of_two(new_capacity));
    memcpy(temp.data, array->data, array->size * sizeof(Record));
    destroy_dynamic_array(array);
    *array = temp;
}

int is_within_range(int value, int min, int max) {
    return (value >= min && value <= max);
}

void generate_random_record(DynamicArray *array, int min, int max) {
    Record random_record = {0};
    do {
        random_record.key = rand() % (max - min + 1) + min;
        random_record.value = (long) lrand48() % LONG_MAX;
    } while (!is_within_range(random_record.key, 0, INT_MAX) || !is_within_range(random_record.value, LONG_MIN, LONG_MAX));
    pthread_mutex_lock(&array->lock);
    array->data[array->size++] = random_record;
    if (array->size == array->capacity) resize_dynamic_array(array, array->capacity * 2);
    pthread_mutex_unlock(&array->lock);
}

void process_network_stream(DynamicArray *array, int socket_fd, char terminator) {
    ssize_t read_len;
    Record record = {0};
    while ((read_len = recv(socket_fd, &record.key, sizeof(int), 0)) > 0) {
        if (read_len != sizeof(int)) {
            fprintf(stderr, "Received corrupted data: expected %zu bytes, got %zd\n", sizeof(int), read_len);
            continue;
        }

        record.offset = ftell64(stdin);
        record.value = ftell64(stdout);

        if (record.key == terminator) break;

        pthread_mutex_lock(&array->lock);
        array->data[array->size++] = record;
        if (array->size == array->capacity) resize_dynamic_array(array, array->capacity * 2);
        pthread_mutex_unlock(&array->lock);
    }
}

void find_maximum(DynamicArray *array) {
    long max_value = LONG_MIN;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].value > max_value)
            max_value = array->data[i].value;
    }
    printf("Maximum value: %ld\n", max_value);
}

int main() {
    DynamicArray array = create_dynamic_array(16);
    int min = 0, max = INT_MAX;
    for (size_t i = 0; i < 1000000; ++i) generate_random_record(&array, min, max);

    int socket_fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    process_network_stream(&array, socket_fd, '\n');
    find_maximum(&array);

    close(socket_fd);
    destroy_dynamic_array(&array);
    return 0;
}
```
