#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} node;

typedef struct {
    char *str;
    bool flag;
} config;

typedef struct record {
    int value;
} record;

void manage_memory(int num_records, int min_value, int max_value, int str_len_min, int str_len_max, size_t *offsets, int *keys, record **records, config **configs) {
    size_t total_offsets_size = num_records * sizeof(long);
    void *offsets_mem = aligned_alloc(sizeof(long), total_offsets_size + sizeof(long) - 1); // Ensure alignment for external library
    size_t total_keys_size = num_records * sizeof(int);
    void *keys_mem = malloc(total_keys_size);
    size_t total_records_size = num_records * sizeof(record);
    record *records_mem = calloc(num_records, sizeof(record)); // Zero-initialized for convenience
    size_t total_configs_size = num_records * sizeof(config) + num_records * str_len_max;
    config *configs_mem = malloc(total_configs_size);

    if (!offsets_mem || !keys_mem || !records_mem || !configs_mem) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    *offsets = offsets_mem;
    *keys = keys_mem;
    *records = records_mem;
    *configs = configs_mem;

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = i; // Store offsets for later use
        (*keys)[i] = i; // Temporary keys, will be replaced with actual keys later

        // Generate random value within the specified range
        int random_value = (rand() % (max_value - min_value + 1)) + min_value;
        if (random_value < INT_MIN || random_value > INT_MAX) {
            fprintf(stderr, "Value generation overflow.\n");
            exit(EXIT_FAILURE);
        }
        (*records)[i].value = random_value;

        // Allocate and initialize config structures
        char *str = malloc((rand() % (str_len_max - str_len_min + 1) + str_len_min) * sizeof(char));
        if (!str) {
            fprintf(stderr, "Memory allocation for strings failed.\n");
            exit(EXIT_FAILURE);
        }

        memset(str, '\0', (rand() % (str_len_max - str_len_min + 1) + str_len_min)); // Fill string with random characters
        (*configs)[i].str = str;
        (*configs)[i].flag = rand() % 2 == 0;
    }

    // Replace temporary keys with actual offset values to maintain order
    for (int i = 0; i < num_records; ++i) {
        (*keys)[(*offsets)[i]] = i;
    }
}

