// Thread-safe logging function
void log_entry(Log *log, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Allocate necessary memory for the log message buffer
    size_t len = vasprintf(&log->message, format, args) + 1;
    if (len == -1 || !log->message) {
        handle_error("Out of memory", errno);
        exit(EXIT_FAILURE);
    }

    log->timestamp = time(NULL);
    log->level = LOG_INFO; // Set the default log level

    va_end(args);
}

// Thread-safe function to append log entries from multiple threads
void append_log_entries(Log **logs, size_t *num_logs) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    while (1) {
        pthread_mutex_lock(&lock);

        Log *new_log = malloc(sizeof(Log));
        if (!new_log) {
            handle_error("Out of memory", errno);
            exit(EXIT_FAILURE);
        }

        new_log->message = NULL; // Reset message pointer for reuse

        if (*num_logs >= 10000) { // Optimization: avoid allocating too many logs at once
            pthread_mutex_unlock(&lock);
            sleep(1); // Give other threads a chance to log
            continue;
        }

        *new_log = (Log){0};
        new_log->message = NULL; // Reset message pointer for reuse
        logs[*num_logs] = new_log;
        (*num_logs)++;

        pthread_mutex_unlock(&lock);

        if (*num_logs >= 1000) { // Optimization: process large batches of logs to reduce overhead
            process_log_batch(logs, *num_logs);
            *num_logs = 0;
        }
    }

    pthread_mutex_destroy(&lock);
}

