Record* create_record() {
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return new_record;
}

void append(Record* record) {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        size_t new_capacity = capacity ? capacity * 2 : 16;
        Record* new_records = realloc(records, new_capacity * sizeof(Record));
        if (!new_records) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        records = new_records;
        capacity = new_capacity;
    }
    records[size++] = *record;
    pthread_mutex_unlock(&lock);
}

Record* find(int key) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key == key && &records[i] <= &records[cache_size]) {
            cache_size = i + 1;
        }
        if (records[i].key == key) {
            pthread_mutex_unlock(&lock);
            return &records[i];
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

Record* get_from_cache(int key) {
    for (size_t i = 0; i < cache_size; ++i) {
        if (records[i].key == key) {
            return &records[i];
        }
    }
    return NULL;
}

