#define HASH_TABLE_SIZE 1024

typedef struct {
    time_t timestamp;
    int event_id;
    char* message;
    struct Event *next; // Linked list pointer
} Event;

typedef struct {
    pthread_mutex_t lock;
    size_t session_id;
    Event** events; // Hash table array of linked lists
} Session;

void init_memory() {
    time_t* timestamp_array = calloc(TIMESTAMP_ARRAY_SIZE, sizeof(time_t));

    if (!timestamp_array) {
        perror("Memory allocation error for timestamp_array");
        exit(EXIT_FAILURE);
    }

    Event** event_linked_list = malloc(HASH_TABLE_SIZE * sizeof(Event*));

    if (!event_linked_list) {
        perror("Memory allocation error for event_linked_list");
        free(timestamp_array);
        exit(EXIT_FAILURE);
    }

    Session* session_hash_table = calloc(HASH_TABLE_SIZE, sizeof(Session));

    if (!session_hash_table) {
        perror("Memory allocation error for session_hash_table");
        free(timestamp_array);
        free(event_linked_list);
        exit(EXIT_FAILURE);
    }

    // Initialize hash table locks and event linked lists
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&session_hash_table[i].lock, NULL);
        session_hash_table[i].events = event_linked_list[i];
    }
}

void deallocate_memory() {
    // Deallocate memory for each data structure in reverse order of initialization
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        Event* current = session_hash_table[i].events;
        while (current != NULL) {
            Event* temp = current;
            current = current->next;
            free(temp->message);
            free(temp);
        }
    }
    free(session_hash_table);
    free(event_linked_list);
    free(timestamp_array);
}

// Implementation details for the event-linked list and session hash table omitted for brevity.
