    size_t total_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (total_size > max_buffer_size) {
        return -1; // Error: buffer too small
    }

    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!data) {
        return -2; // Error: memory allocation failed
    }

    size_t seed = time(NULL); // Seed for reproducible shuffling algorithm

    // Fisher-Yates shuffle, using a seed to control the sequence of random numbers generated
    for (size_t i = count - 1; i > 0; --i) {
        size_t j = rand_r(&seed) % i;
        NFAPI_CRC_INDICATION_PDU_T temp = data[j];
        data[j] = data[i];
        data[i] = temp;
    }

    // Initialize the CRCFLAG field with a randomly set value within the structure
    for (size_t i = 0; i < count; ++i) {
        data[i].CRCFLAG = rand() % 2;
    }

    *p_data = data;
    return 0; // Success
}
