#include <sys/wait.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <getopt.h>
#include <stdbool.h>
#include <sys/stat.h>
#include <semaphore.h>
#include <signal.h>
#include <execinfo.h>
#include "log4cxx/logger.h"
#include "log4cxx/initialization/factory.h"
#include "log4cxx/helpers/exception.h"

struct source {
    FILE *file;
    char *path;
    regex_t re;
    sem_t sem;
};

static log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("merge"));

void* process_source(void *arg) {
    struct source *src = static_cast<struct source*>(arg);
    int line_count = 0;

    regmatch_t match;
    if (src->re != REG_NULL) {
        regcomp(&src->re, src->path + optind, REG_EXTENDED | REG_NEWLINE | REG_NOSUB);
    }

    char buf[4096];
    while (fgets(buf, sizeof(buf), src->file)) {
        line_count++;
        if (src->re != REG_NULL && regexec(&src->re, buf, 1, &match, 0) == 0) continue;

        sem_post(&src->sem);
    }

    if (src->file != stdin) fclose(src->file);
    regfree(&src->re);
    free(src->path);
    free(src->file);
    free(arg);

    return &line_count;
}

int main(int argc, char **argv) {
    const char *output_file = "output.txt";
    regex_t filter_re = REG_NULL;
    bool summarize = false;

    static const struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"out", required_argument, 0, 'o'},
        {"filter", required_argument, 0, 'f'},
        {"summarize", no_argument, 0, 's'},
        {0, 0, 0, 0}
    };

    int opt = getopt_long(argc, argv, "ho:f:s", long_options, NULL);
    while (opt != -1) {
        switch (opt) {
            case 'h':
                fprintf(stderr, "Usage: %s [OPTION]... [FILE]...\n", argv[0]);
                return 0;
            case 'o':
                output_file = optarg;
                break;
            case 'f':
                if (regcomp(&filter_re, optarg, REG_EXTENDED | REG_NEWLINE | REG_NOSUB) != 0) {
                    logger->error("Invalid filter regex: " + log4cxx::Helpers::getExceptionMessage());
                    return 1;
                }
                break;
            case 's':
                summarize = true;
                break;
        }
        opt++;
    }

    int file_count = argc - optind;
    if (file_count < 0) {
        file_count = 1;
        argv += optind;
    }

    sem_t global_sem;
    sem_init(&global_sem, 0, 0);
    pthread_t threads[file_count];
    struct source *sources = (struct source *)calloc(file_count, sizeof(struct source));

    int total_line_count = 0;
    for (int i = optind; i < argc; ++i) {
        int fd = open(argv[i], O_RDONLY);
        if (fd == -1) {
            perror("open");
            continue;
        }

        sources[i - optind].file = fdopen(fd, "r");
        sources[i - optind].path = argv[i];
        sources[i - optind].re = filter_re;
        sem_init(&sources[i - optind].sem, 0, 0);
        pthread_create(&threads[i - optind], NULL, process_source, &sources[i - optind]);
    }

    if (filter_re != REG_NULL) regfree(&filter_re);

    void **trace = 0;
    size_t trace_size = 0;
    for (int i = 0; i < file_count && sem_trywait(&global_sem) == 0; ++i) {
        int line_count = *static_cast<int*>(threads[i]);
        total_line_count += line_count;
        pthread_join(threads[i], NULL);
    }

    if (total_line_count > 0) {
        FILE *out = fopen(output_file, "w");
        for (int i = optind; i < argc && sem_trywait(&sources[i - optind].sem) == 0; ++i) {
            const char *src_path = sources[i - optind].path;
            int line_count = *static_cast<int*>(threads[i]);

            fprintf(out, "%s: %d\n", src_path, line_count);
            fflush(out);

            pthread_join(threads[i], NULL);
        }
        free(sources);

        if (summarize) {
            fprintf(out, "Total lines: %d\n", total_line_count);
            fprintf(out, "Average lines per file: %.2f\n", static_cast<double>(total_line_count) / file_count);
        }
    } else {
        free(sources);
    }

    fclose(out);
    return 0;
}
```

