#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    float value;
    char label;
    size_t index;
} dataPoint;

struct movingAverage {
    void* buffer; // Can be an array of floats, doubles, or struct dataPoints
    size_t windowSize;
    size_t bufferSize;
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
};

void ma_init(struct movingAverage* ma, enum dataType type, size_t windowSize) {
    if (windowSize < 1) return;

    ma->bufferSize = windowSize * sizeof(union {float f; double d; dataPoint dp; }) + sizeof(size_t);
    ma->buffer = malloc(ma->bufferSize);
    memset(ma->buffer, 0, ma->bufferSize);

    ma->windowSize = windowSize;
    ma->head = ma->tail = 0;
    pthread_mutex_init(&ma->mutex, NULL);
}

void ma_push(struct movingAverage* ma, union {float f; double d; dataPoint dp;} value) {
    pthread_mutex_lock(&ma->mutex);

    size_t index = (ma->head + 1) % ma->bufferSize;

    if ((index - ma->tail) >= ma->windowSize) {
        union {float f; double d; dataPoint dp;} tempValue;
        memcpy(&tempValue, (union*)((char*)ma->buffer + ma->head * sizeof(union union_t)), sizeof(union union_t));
        ma->head--;

        if (value.dp.index < tempValue.dp.index) {
            // Handle the case where the new data point has a smaller index than the oldest data point in the buffer
            size_t offset = tempValue.dp.index - value.dp.index + ma->windowSize;
            memcpy((union*)((char*)ma->buffer + index * sizeof(union union_t)), (union*)((char*)ma->buffer + (index + offset) % ma->bufferSize * sizeof(union union_t)), sizeof(union union_t));
        }
    }

    memcpy((union*)((char*)ma->buffer + index * sizeof(union union_t)), &value, sizeof(union union_t));
    value.dp.index = index;

    ma->head++;
    if (ma->head >= ma->bufferSize) {
        ma->head -= ma->bufferSize;
    }

    ma->tail++;
    if (ma->tail >= ma->bufferSize) {
        ma->tail -= ma->bufferSize;
    }

    pthread_mutex_unlock(&ma->mutex);
}

double ma_get_average(struct movingAverage* ma) {
    double sum = 0.0;
    size_t count = 0;

    pthread_mutex_lock(&ma->mutex);

    for (size_t i = ma->tail; i != ma->head; i = (i + 1) % ma->bufferSize) {
        union {float f; double d; dataPoint dp;} value = *(union*)((char*)ma->buffer + i * sizeof(union union_t));
        if (value.dp.index >= ma->tail && value.dp.index < ma->head) {
            sum += value.f;
            count++;
        }
    }

    pthread_mutex_unlock(&ma->mutex);

    return count ? (sum / count) : 0.0;
}
```

