#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct node {
    int key;
    char* str;
    struct node* next;
} Node;

Node* create_node(char* str) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->key = hash(str);
    new_node->str = strdup(str);
    new_node->next = NULL;
    return new_node;
}

void read_metadata(char* str, FILE* fp) {
    char buffer[1024];
    sprintf(buffer, "%s_meta.txt", str);
    if (access(buffer, F_OK) == 0) {
        FILE* metadata = fopen(buffer, "r");
        char line[256];
        while (fgets(line, sizeof(line), metadata)) {
            // Parse and process metadata here
        }
        fclose(metadata);
    }
}

int hash(char* str) {
    int len = strlen(str);
    unsigned long hash = 5381;
    for (int i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) ^ str[i];
    return hash % INT_MAX;
}

void link_list(Node** head, Node* node) {
    if (*head == NULL) {
        *head = node;
        return;
    }
    Node* current = *head;
    while (current->next != NULL)
        current = current->next;
    current->next = node;
}

Node** create_lists(int size, char** strings, FILE* fp) {
    Node** lists = malloc(sizeof(Node*) * size);
    for (int i = 0; i < size; ++i)
        lists[i] = NULL;

    for (int i = 0; i < size; ++i) {
        Node* node = create_node(strings[i]);
        read_metadata(strings[i], fp);
        link_list(lists + hash(strings[i]), node);
    }
    return lists;
}
