#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/types.h>
#include <pthread.h>
#include <sqlite3.h>

typedef struct Record {
    long offset;
    int flag;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

struct Heap {
    Node** array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    sqlite3* db;
};

void swap(Node** a, Node** b) {
    Node* temp = *a;
    *a = *b;
    *b = temp;
}

void heapify(struct Heap* heap, size_t i) {
    size_t left = 2 * i + 1;
    size_t right = 2 * i + 2;
    size_t maxIndex = i;

    if (left < heap->size && heap->array[left]->data.offset >= 0) {
        maxIndex = left;
    }

    if (right < heap->size && heap->array[right]->data.offset >= 0) {
        maxIndex = right;
    }

    if (maxIndex != i && heap->array[maxIndex]->data.offset >= 0) {
        swap(&heap->array[i], &heap->array[maxIndex]);
        heapify(heap, maxIndex);
    }
}

void build_heap(struct Heap* heap) {
    for (size_t i = heap->size / 2 - 1; i >= 0; --i) {
        heapify(heap, i);
    }
}

void push(struct Heap* heap, Record data) {
    if (heap->capacity == heap->size) {
        size_t newCapacity = heap->capacity * 2 + 1;
        Node** newArray = realloc(heap->array, newCapacity * sizeof(Node*));

        if (!newArray) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }

        heap->array = newArray;
        heap->capacity = newCapacity;
    }

    heap->array[heap->size] = malloc(sizeof(Node));

    if (!heap->array[heap->size]) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    Node* newNode = heap->array[heap->size];
    newNode->data = data;
    newNode->next = NULL;
    heap->size++;
    build_heap(heap);
}

Record pop(struct Heap* heap) {
    if (heap->size == 0) {
        fprintf(stderr, "No elements in the heap\n");
        exit(EXIT_FAILURE);
    }

    Record data = heap->array[0]->data;
    Node* lastNode = heap->array[--heap->size];
    Node* currentNode = heap->array[0];

    if (currentNode->next) {
        currentNode->next->prev = NULL;
    }

    free(currentNode);

    if (heap->size == 0) {
        free(lastNode);
        return data;
    }

    Node* newRoot = heap->array[0];
    size_t newSize = heap->size;

    while (newSize > 1) {
        --newSize;
        swap(&heap->array[newSize], &heap->array[0]);
        heapify(heap, 0);
    }

    return newRoot->data;
}

void sort_records(struct Heap* heap) {
    build_heap(heap);
    qsort(heap->array, heap->size, sizeof(Node*), (int(*)(const void*, const void*))comparator);
}

int comparator(const void* a, const void* b) {
    return ((Record*)a)->flag - ((Record*)b)->flag;
}

bool delete_record(struct Heap* heap, long offset) {
    for (size_t i = 0; i < heap->size; ++i) {
        if (heap->array[i]->data.offset == offset) {
            Node* currentNode = heap->array[i];

            if (currentNode->next) {
                currentNode->next->prev = currentNode->prev;
            }

            if (currentNode->prev) {
                currentNode->prev->next = currentNode->next;
            } else {
                Node** array = heap->array;
                size_t index = i;

                while (index > 0 && array[index - 1] == currentNode) {
                    --index;
                }

                if (index > 0) {
                    array[index] = currentNode->next;
                } else {
                    free(heap->array[i]);
                }
            }

            heap->size--;
            return true;
        }
    }

    return false;
}

void init_database(struct Heap* heap) {
    if (sqlite3_open("records.db", &heap->db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(heap->db));
        exit(EXIT_FAILURE);
    }

    const char* sql_create = "CREATE TABLE IF NOT EXISTS records(" \
                             "offset INTEGER PRIMARY KEY," \
                             "flag INTEGER NOT NULL);";

    char* errMsg = NULL;

    if (sqlite3_exec(heap->db, sql_create, NULL, NULL, &errMsg)) {
        fprintf(stderr, "SQL error: %s\n", errMsg);
        sqlite3_free(errMsg);
        exit(EXIT_FAILURE);
    }
}

void save_records(struct Heap* heap) {
    char* errMsg = NULL;

    for (size_t i = 0; i < heap->size; ++i) {
        sqlite3_stmt* stmt;
        const char sql_insert[] = "REPLACE INTO records(offset, flag) VALUES(?, ?);";

        if (sqlite3_prepare_v2(heap->db, sql_insert, -1, &stmt, NULL)) {
            fprintf(stderr, "Can't prepare statement: %s\n", sqlite3_errmsg(heap->db));
            exit(EXIT_FAILURE);
        }

        sqlite3_bind_int64(stmt, 1, heap->array[i]->data.offset);
        sqlite3_bind_int(stmt, 2, heap->array[i]->data.flag);

        if (sqlite3_step(stmt) != SQLITE_DONE) {
            fprintf(stderr, "SQL error while inserting record: %s\n", sqlite3_errmsg(heap->db));
            exit(EXIT_FAILURE);
        }

        sqlite3_finalize(stmt);
    }
}

void load_records(struct Heap* heap) {
    char* errMsg = NULL;

    sqlite3_stmt* stmt;
    const char sql_select[] = "SELECT offset, flag FROM records WHERE 1";

    if (sqlite3_prepare_v2(heap->db, sql_select, -1, &stmt, NULL)) {
        fprintf(stderr, "Can't prepare statement: %s\n", sqlite3_errmsg(heap->db));
        exit(EXIT_FAILURE);
    }

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        Node* newNode = malloc(sizeof(Node));

        newNode->data.offset = sqlite3_column_int64(stmt, 0);
        newNode->data.flag = sqlite3_column_int(stmt, 1);

        if (heap->array) {
            heap->array[heap->size++] = newNode;
        } else {
            heap->array = &newNode;
            heap->size = 1;
        }
    }

    sqlite3_finalize(stmt);
}

struct Heap* create_heap() {
    struct Heap* heap = malloc(sizeof(struct Heap));
    heap->db = NULL;
    heap->array = NULL;
    heap->size = 0;

    return heap;
}

void destroy_heap(struct Heap* heap) {
    sqlite3_close(heap->db);
    free(heap);
}

int main() {
    struct Heap* heap = create_heap();
    init_database(heap);

    // Load records from the database into the heap.
    load_records(heap);

    sort_records(heap);

    // Perform some operations on the sorted records.
