void init_heap(struct Heap *heap, const char *dbname) {
    sqlite3_open(dbname, &heap->db); // Open the database.

    if (sqlite3_errcode(heap->db) != SQLITE_OK) {
        fprintf(stderr, "Can't open or initialize the database: %s\n", sqlite3_errmsg(heap->db));
        sqlite3_close(heap->db);
        exit(EXIT_FAILURE);
    }

    // Check if the table already exists and load records from the database into the heap.
    char *sql = "SELECT offset, flag FROM records WHERE 1";
    sqlite3_stmt *statement;
    if (sqlite3_prepare(heap->db, sql, strlen(sql), &statement, NULL) == SQLITE_OK) {
        while (sqlite3_step(statement) == SQLITE_ROW) {
            struct Node* newNode = malloc(sizeof(struct Node));
            if (!newNode) {
                fprintf(stderr, "Out of memory!\n");
                sqlite3_finalize(statement);
                sqlite3_close(heap->db);
                exit(EXIT_FAILURE);
            }

            newNode->data.offset = sqlite3_column_int64(statement, 0);
            newNode->data.flag = sqlite3_column_int(statement, 1);

            if (heap->array) {
                heap->array->prev = newNode;
                newNode->next = heap->array;
                heap->array = newNode;
                heap->size++;
            } else {
                heap->array = newNode;
                heap->size = 1;
            }
        }
        sqlite3_finalize(statement);
    } else {
        fprintf(stderr, "Failed to prepare the SQL statement: %s\n", sqlite3_errmsg(heap->db));
        sqlite3_close(heap->db);
        exit(EXIT_FAILURE);
    }
}

void destroy_heap(struct Heap *heap) {
    struct Node *current = heap->array;
    while (current != NULL) {
        struct Node *temp = current;
        current = current->next;
        free(temp);
