void load_records(struct Heap *heap) {
    char *sql = "SELECT offset, flag FROM records WHERE 1";
    sqlite3_stmt *statement;
    if (sqlite3_prepare(heap->db, sql, strlen(sql), &statement, NULL) == SQLITE_OK) {
        while (sqlite3_step(statement) == SQLITE_ROW) {
            struct Node* newNode = malloc(sizeof(struct Node));
            if (!newNode) {
                fprintf(stderr, "Out of memory!\n");
                sqlite3_finalize(statement);
                sqlite3_close(heap->db);
                exit(EXIT_FAILURE);
            }

            newNode->data.offset = sqlite3_column_int64(statement, 0);
            newNode->data.flag = sqlite3_column_int(statement, 1);

            if (heap->array) {
                heap->array->prev = newNode;
                newNode->next = heap->array;
                heap->array = newNode;
                heap->size++;
            } else {
                heap->array = newNode;
                heap->size = 1;
            }
        }
        sqlite3_finalize(statement);
    } else {
        fprintf(stderr, "Failed to prepare the SQL statement: %s\n", sqlite3_errmsg(heap->db));
        sqlite3_close(heap->db);
        exit(EXIT_FAILURE);
    }
}

void sort_records(struct Heap *heap) {
    // Implement the sorting algorithm here.
}

void delete_record(struct Heap *heap, long offset) {
    struct Node* current = heap->array;
    while (current != NULL && current->data.offset != offset) {
        if (current == heap->array) {
            current = current->next;
            continue;
        }
        current = current->prev;
    }

    if (current == NULL) {
        fprintf(stderr, "Record not found!\n");
        return;
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        heap->array = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    free(current);
}
