char* percentEncode(const char *str, size_t length) {
    if (!length) return "";

    size_t encoded_len = 0;
    for (size_t i = 0; i < length; ++i) {
        char c = str[i];
        if (isalnum(c) || c == '-' || c == '_' || c == '.') continue;
        encoded_len += 3; // for each non-alphanumeric, alphanumeric or special character add 1 (encoded char) + 2 (% and space)
    }

    char *encoded = malloc(length + encoded_len);
    size_t j = 0;
    for (size_t i = 0; i < length; ++i) {
        char c = str[i];
        if (isalnum(c) || c == '-' || c == '_' || c == '.') {
            encoded[j++] = c;
        } else {
            sprintf(&encoded[j], "%%%2X", (unsigned char)c);
            j += 3;
        }
    }
    encoded[j] = '\0';
    return encoded;
}

size_t getConsonantCount(const char *filename) {
    size_t count = 0;
    for (size_t i = 0; filename[i]; ++i) {
        if (isalpha(filename[i])) {
            char c = tolower(filename[i]);
            if (!isspace(c) && (c != 'a' && c != 'e' && c != 'i' && c != 'o' && c != 'u')) ++count;
        }
