    char *new_filename = malloc(MAX_FILENAME_LENGTH + 2 + digit_count);
    snprintf(new_filename, MAX_FILENAME_LENGTH + 2 + digit_count, "%s-%0*d-modified.v2", encoded_filename, (int)digit_count, consonant_count);

