['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/types.h>
#include <pthread.h>
#include <time.h>
#include <inttypes.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    pthread_t thread_id;
    int64_t *buffer;
    size_t capacity;
    size_t head, tail;
} stream_queue;

// Compare function for qsort
int cmp(const void *a, const void *b) {
    return (*(int64_t *)a - *(int64_t *)b);
}

// Thread function to read data from the input stream and push it into the queue
void *read_and_push(void *arg) {
    stream_queue *queue = arg;
    int fd, val;
    while ((fd = open("/path/to/input", O_RDONLY)) > 0) {
        read(fd, &val, sizeof(int64_t));
        pthread_mutex_lock(&queue->buffer[queue->tail]);
        queue->buffer[queue->tail] = val;
        if (++queue->tail == queue->capacity) queue->tail = 0;
        pthread_mutex_unlock(&queue->buffer[queue->tail]);
        close(fd);
    }
    return NULL;
}

// Function to filter the duplicate values and sort the list
void process_stream(stream_queue *queue) {
    size_t i, j, unique = 0;
    int64_t *sorted = malloc(queue->capacity * sizeof(int64_t));

    pthread_mutex_lock(&queue->buffer[queue->head]);
    for (i = queue->head; i != queue->tail; i = (i + 1) % queue->capacity) {
        int found = false;
        for (j = unique; j < unique + unique; ++j) {
            if (queue->buffer[i] == sorted[j]) {
                found = true;
                break;
            }
        }
        if (!found) {
            sorted[unique++] = queue->buffer[i];
        }
    }
    pthread_mutex_unlock(&queue->buffer[queue->head]);

    qsort(sorted, unique, sizeof(int64_t), cmp);
}

// Function to find the median value of the sorted list
void compute_median(const int64_t *numbers, size_t length) {
    if (length == 0) {
        printf("Error: empty list\n");
        return;
    }

    qsort(numbers, length, sizeof(int64_t), cmp);
    double median = 0.0;

    if (length % 2 == 1) {
        median = numbers[length / 2];
    } else {
        median = (numbers[(length - 1) / 2] + numbers[(length + 1) / 2]) / 2.0;
    }

    printf("Median: %.f\n", median);
}

int main() {
    const size_t buffer_size = 1000000;
    stream_queue queue = { .buffer = malloc(buffer_size * sizeof(int64_t)), .capacity = buffer_size };
    pthread_mutex_init(&queue.buffer[queue.head], NULL);

    pthread_t read_thread;
    pthread_create(&read_thread, NULL, read_and_push, &queue);

    while (true) {
        process_stream(&queue);
        if (queue.tail - queue.head > buffer_size / 2) {
            process_stream(&queue);
        }
        compute_median(queue.buffer + queue.head, queue.tail - queue.head);
    }

    pthread_join(read_thread, NULL);
    pthread_mutex_destroy(&queue.buffer[queue.head]);
    free(queue.buffer);

    return 0;
}
```

This C program uses a circular buffer and threading to efficiently process a large stream of integers from an external source, minimizing latency and memory footprint. It filters duplicates and sorts the unique values using qsort. The median value is then computed and printed. The solution can scale to handle millions of integers and is designed for integration with an existing data pipeline. Trade-offs have been made between processing speed, memory consumption, and computational complexity to accommodate the given constraints.']

