char *process_string(const char *input, size_t limit, bool truncate) {
    if (input == NULL || limit <= 0) {
        return NULL;
    }

    // Allocate memory for the output string and ensure it's large enough to hold the input string or the specified limit.
    size_t input_len = strlen(input);
    char *output = malloc((input_len > limit) ? limit + 1 : input_len + 1);
    if (output == NULL) {
        // Memory allocation failed, return NULL.
        perror("Memory allocation error");
        return NULL;
    }

    // Copy the input string into the output buffer, truncating it if necessary.
    size_t len_to_copy = (input_len > limit) ? limit : input_len;
    strncpy(output, input, len_to_copy);

    if (truncate && input_len > limit) {
        // Overwrite the remaining characters in the output buffer with null characters.
        output[limit] = '\0';
    }

    return output;
}
