2. Union-Find Data Structure Implementation (C File)

```cpp
#include <algorithm>
#include <vector>

struct UF {
private:
    std::vector<int> parent;
    int count;

public:
    UF(int size);
    int find(int x);
    void unionSet(int x, int y);
};

UF::UF(int size) : parent(size), count(size) {
    for (int i = 0; i < size; ++i) {
        parent[i] = i;
    }
}

int UF::find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void UF::unionSet(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);

    if (rootX == rootY) return;

    if (parent[rootX] < parent[rootY])
        parent[rootY] = rootX;
    else
        parent[rootX] = rootY;

    --count;
}
```

