} Record;

static GHashTable *table = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned int records_count = 0;
static size_t min_length = 10, max_length = 50;

void init(unsigned int num_records) {
    if (table != NULL) return;

    // Initialize hash table with a suitable size for the number of records
    table = g_hash_table_new_full(g_int_hash, g_int_equal, NULL, free_record);

    pthread_mutex_init(&mutex, NULL);
}

void free_resources() {
    g_hash_table_destroy(table);
    pthread_mutex_destroy(&mutex);
}

void insert_record(Record *record) {
    pthread_mutex_lock(&mutex);

    // Hash table put operation will automatically handle memory allocation and error handling for the record
    g_hash_table_insert(table, GINT_TO_POINTER(record->key), record);

    pthread_mutex_unlock(&mutex);
}

Record *get_record(int key) {
    pthread_mutex_lock(&mutex);

    Record *record = g_hash_table_lookup(table, GINT_TO_POINTER(key));
    if (record == NULL) {
        // You can implement a not found error handling mechanism here
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    pthread_mutex_unlock(&mutex);
    return record;
}

void delete_record(int key) {
    pthread_mutex_lock(&mutex);

    Record *record = g_hash_table_lookup(table, GINT_TO_POINTER(key));
    if (record == NULL) {
        // You can implement a not found error handling mechanism here
        pthread_mutex_unlock(&mutex);
        return;
    }

    g_free(record->description);
    g_hash_table_remove(table, GINT_TO_POINTER(key));
    --records_count;

    pthread_mutex_unlock(&mutex);
}

void set_min_max_length(size_t min, size_t max) {
    if (min > max) return; // Validate input parameters

    min_length = min;
    max_length = max;
}

Record *create_random_record() {
    char *description = malloc(rand() % (max_length - min_length + 1) + min_length);
    memset(description, rand(), description ? strlen(description) : 0);
    return calloc(1, sizeof(Record) + strlen(description));
}

void free_record(gconstpointer key) {
    Record *record = (Record *)key;
    free(record->description);
    free(record);
}

