#include <chrono>
#include <numeric>
#include <cmath>
#include <Eigen/Dense> // For mathematical operations and vectorization
#include <hdf5.h> // For exporting data in HDF5 format

// Define the data structure
struct Data {
    double value;
    uint64_t timestamp;
    enum Status { VALID, INVALID } status;
};

std::mutex mtx;
std::vector<Data> dataPool;
size_t dataPoolSize = 0;
const size_t maxDataPoolSize = 100000;

// Function to generate random values within a specified range
Data generateRandomData(double min, double max) {
    Data d;
    d.value = std::uniform_real_distribution<double>(min, max)(std::random_device{}());
    d.timestamp = std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();
    d.status = Data::VALID;
    return d;
}

// Function to handle data computation and exporting using an external numerical library
void processData(const Data& d, h5::Group& group) {
    // Replace this with the actual computations and vectorization using Eigen or any other library
    double result = sin(d.value);
    group.createDataspace(h5::PredType{H5T_I8}, 1);
    h5::DataSet dataSet = group.createDataset("result", {1});
    dataSet.write(reinterpret_cast<const char*>(&result), H5S_SCALAR);
}

// Function to perform the task in a thread-safe manner
void processThread(int threadId) {
    std::unique_lock<std::mutex> lock(mtx);

    // Check if dataPool is empty or reaches maxDataPoolSize
    while (dataPool.empty() && dataPoolSize < maxDataPoolSize) {
        dataPool.push_back(generateRandomData(-10, 10));
        ++dataPoolSize;
        lock.unlock();
        std::this_thread::yield(); // Give other threads a chance to run
        lock.lock();
    }

    if (!dataPool.empty()) {
        auto d = dataPool.back();
        dataPool.pop_back();
        --dataPoolSize;

        h5::H5::Exception::dontPrintExceptions(true); // Disable printing of HDF5 exceptions
        try {
            h5::File file("output.h5", h5::FileAccess::TRUNC);
            auto rootGroup = file.rootgroup();
            auto dataGroup = rootGroup.createGroup("data");

            processData(d, *dataGroup);
        } catch (const std::exception& e) {
            std::cerr << "Error processing data: " << e.what() << std::endl;
        }
    }
}

int main() {
    const int numThreads = 4;
    std::vector<std::thread> threads(numThreads);

    for (int i = 0; i < numThreads; ++i) {
        threads[i] = std::thread(processThread, i);
    }

    for (auto& t : threads) {
        t.join();
    }

    return 0;
}
