// Allocate memory for an array of transaction structures with a given capacity, ensuring sufficient memory for the longest name
Transaction* transactions_init(size_t capacity) {
    size_t max_len = 0;
    for (size_t i = 0; i < num_names; ++i) {
        max_len = (max_len < strlen(names[i])) ? strlen(names[i]) : max_len;
    }

    size_t name_size = max_len + 1;
    Transaction *transactions = malloc(capacity * sizeof(Transaction));

    if (!transactions) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < capacity; ++i) {
        transactions[i].name = malloc(name_size);
        if (!transactions[i].name) {
            fprintf(stderr, "Out of memory\n");
            free(transactions);
            exit(EXIT_FAILURE);
        }
    }

    return transactions;
}

// Process dynamically sized lists of integers received via a high-latency network stream
void process_transactions(Transaction *transactions, size_t capacity) {
    int terminator = -1; // Termination character
    size_t transaction_index = 0;

    while (transaction_index < capacity && terminator == -1) {
        int value;
        if (!scanf("%d", &value)) {
            fprintf(stderr, "Invalid input\n");
            exit(EXIT_FAILURE);
        }

        if (value == terminator) {
            terminator = -2; // Mark as termination character read
            continue;
        }

        // Set transaction fields to random values within specified ranges and validate against defined boundaries
        transactions[transaction_index].flt = rand() / (RAND_MAX / 10.0);
        transactions[transaction_index].dbl = rand() * ((double)LONG_MAX - 1) / RAND_MAX + 1.0;
        if (transactions[transaction_index].dbl >= LONG_MAX || transactions[transaction_index].dbl <= -(LONG_MAX-1)) {
            transactions[transaction_index].dbl = rand() * ((double)LONG_MAX / RAND_MAX + 1.0);
        }

        transactions[transaction_index].name = names[rand() % num_names];
        transaction_index++;
    }

    // Find and print the maximum integer value among processed transactions
    int max_value = INT_MIN;
    for (size_t i = 0; i < transaction_index && terminator == -2; ++i) {
        if (transactions[i].value > max_value) {
            max_value = transactions[i].value;
        }
    }

    printf("Maximum integer value: %d\n", max_value);
}

// Free allocated memory after processing
void cleanup(Transaction *transactions, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free(transactions[i].name);
    }

    free(transactions);
}
