enum Status { IDLE, PROCESSING, ERROR };

struct Data {
    double value;
    std::uintmax_t timestamp;
    Status status;
};

class DataManager {
private:
    std::vector<Data> data_;
    mutex mtx_;
    tbb::concurrent_vector<std::unique_ptr<Data>> data_pool_;
    double min_value_, max_value_;
    std::uintmax_t chunk_size_;
    atomic<int> error_count_; // to track errors for logging purposes

public:
    DataManager(double min_val, double max_val, std::uintmax_t chunk_sz)
        : min_value_(min_val), max_value_(max_val), chunk_size_(chunk_sz), error_count_(0) {}

    void initialize(std::function<void(Data&)> initializer); // initialize data structures with random values or other custom logic

    Data* allocate() { // allocate data from the pool
        std::unique_lock<mutex> lock(mtx_);
        if (data_pool_.empty()) {
            data_pool_.emplace_back(new Data);
        }
        auto ptr = data_pool_.front().release();
        data_pool_.pop_front();
        return ptr;
    }

    void deallocate(Data* data) { // deallocate data back to the pool
        std::unique_lock<mutex> lock(mtx_);
        new (data) Data; // reset data to its default state
        data_pool_.emplace_back(data);
    }

    void processDataChunk(std::vector<Data*>& chunk, std::function<void(Data&)> processingFn); // process data chunks in parallel using the provided function

    void exportData(const std::string& filePath) const; // export processed data to a standardized format (e.g., HDF5 or NetCDF)
};
