```c
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    unsigned int size;
    Node* head;
    Node* tail;
} List;

void initList(List* list) {
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

void addNode(List* list, Node* node) {
    if (list->size == 0) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        node->prev = list->tail;
        list->head->prev = node;
        list->tail->next = node;
        list->size++;
    }
}

Node* getNodeById(List* list, unsigned int id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void removeNodeById(List* list, unsigned int id) {
    Node* nodeToRemove = getNodeById(list, id);
    if (nodeToRemove == NULL) {
        return;
    }
    if (list->size == 1) {
        free(nodeToRemove);
        list->head = NULL;
        list->tail = NULL;
    } else if (nodeToRemove == list->head) {
        list->head = nodeToRemove->next;
        list->head->prev = NULL;
        free(nodeToRemove);
    } else if (nodeToRemove == list->tail) {
        list->tail = nodeToRemove->prev;
        list->tail->next = NULL;
        free(nodeToRemove);
    } else {
        nodeToRemove->prev->next = nodeToRemove->next;
        nodeToRemove->next->prev = nodeToRemove->prev;
        free(nodeToRemove);
    }
    list->size--;
}
```

