#include <curl/curl.h>
#include <stdio.h>

typedef struct {
    CURL* curl;
    size_t size;
} Request;

Request* createRequest() {
    Request* req = malloc(sizeof(Request));
    if (!req) {
        return NULL;
    }
    req->curl = curl_easy_init();
    if (!req->curl) {
        free(req);
        return NULL;
    }
    req->size = 0;
    return req;
}

void resetRequest(Request* req) {
    if (req->curl) {
        curl_easy_reset(req->curl);
    }
    req->size = 0;
}

int performRequest(Request* req, const char* url, CURLrequest method, const void* data, size_t size) {
    int ret;
    struct curl_slist* headers = NULL;

    // Set up request
    resetRequest(req);
    req->size = size;
    if (data) {
        curl_easy_setbuf(req->curl, data, size);
    }

    // Add required headers
    headers = curl_slist_append(headers, "Content-Type: application/json");

    // Perform request
    ret = curl_easy_setopt(req->curl, CURLOPT_URL, url);
    if (ret != CURLE_OK) {
        goto cleanup;
    }
    ret = curl_easy_setopt(req->curl, CURLOPT_CUSTOMREQUEST, method);
    if (ret != CURLE_OK) {
        goto cleanup;
    }
    ret = curl_easy_setopt(req->curl, CURLOPT_HTTPHEADER, headers);
    if (ret != CURLE_OK) {
        goto cleanup;
    }

    // Perform the request and check for errors
    CURLcode res;
    res = curl_easy_perform(req->curl);
    if (res != CURLE_OK) {
        printf("Request failed: %s\n", curl_easy_strerror(res));
        goto cleanup;
    }

cleanup:
    if (headers) {
        curl_slist_free_all(headers);
    }
    if (req->curl) {
        curl_easy_cleanup(req->curl);
    }
    return res;
}
```']

