class GameCharacter {
private:
    std::vector<int> records;
    int lastAttackType = -1;
    std::uint64_t lastAttackTime = 0;

    void initializeRecords(size_t size, int minVal, int maxVal) {
        std::random_device seed_gen;
        std::mt19937 rng(seed_gen());
        std::uniform_int_distribution<> distr(minVal, maxVal);

        records.resize(size);
        for (auto& record : records) {
            record = distr(rng);
        }
    }

public:
    GameCharacter(size_t size, int minVal, int maxVal) {
        initializeRecords(size, minVal, maxVal);
    }

    void executeRandomAttack() {
        auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        std::chrono::seconds cooldown(9);
        if (now - lastAttackTime >= cooldown.count()) {
            lastAttackType = records[rand() % records.size()];
            lastAttackTime = now;
            std::cout << "Elapsed time: " << (now - lastAttackTime) / 1e9 << " seconds" << std::endl;
        }
    }
};
