['```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <functional>
#include <stdexcept>
#include <future>

class MessagingSystem {
public:
    virtual void publish(const std::string& message) = 0;
};

class MemoizedMessagingSystem : public MessagingSystem {
private:
    std::mutex mtx;
    std::queue<std::string> queue;
    std::condition_variable cv;
    bool canPublish = true;

public:
    void publish(const std::string& message) {
        std::unique_lock<std::mutex> lock(mtx);
        if (!canPublish) {
            queue.push(message);
            cv.wait(lock, [this] { return canPublish; });
        }
        canPublish = false;
        // Simulate delay with random sleep
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % (MAX_DELAY + 1)));
        // Ensure high-frequency message loads don't degrade performance
        lock.unlock();
        cv.notify_one();
        this_thread::yield();
        canPublish = true;
        // Publish the message
        std::cout << "Message: " << message << "\n";
    }
};

void processList(std::forward_list<std::string>& list, const std::string& first, const std::string& second, MessagingSystem& messagingSystem, int MAX_DELAY) {
    auto it = list.begin();
    if (it == list.end()) return; // Empty list case

    std::forward_list<std::string> tempList;
    bool inserted = false;

    std::mutex mtx;
    std::condition_variable cv;
    std::unique_ptr<std::future<void>> serviceFuture;

    auto startService = [&]() {
        if (!inserted) {
            // Start the simulated service and handle delays
            serviceFuture = std::async(std::launch::async, [this, it, first, second, messagingSystem, MAX_DELAY]() mutable {
                this_thread::sleep_for(std::chrono::milliseconds(rand() % (MAX_DELAY + 1)));
                // Ensure thread safety when modifying the list
                std::unique_lock<std::mutex> lock(mtx);
                if (it != list.end() && *it == first) {
                    list.insertafter(it, second);
                    inserted = true;
                } else {
                    tempList.splice(tempList.end(), list, it, list.end());
                }
                lock.unlock();
            });
        }
    };

    for (; it != list.end(); ++it) {
        if (*it == first) {
            startService();
            inserted = true;
            break;
        }
        tempList.push_back(*it);
    }

    if (!inserted) {
        tempList.push_back(second);
        list.splice(list.end(), tempList, tempList.begin(), tempList.end());
    }

    if (serviceFuture) serviceFuture->wait();
    messagingSystem.publish("Service started");
}
```']

