typedef struct offset_t {
    long *values;
    size_t capacity, size;
} offset_t;

typedef struct key_t {
    int *values;
    size_t capacity, size;
} key_t;

typedef struct record_t {
    int value;
} record_t;

typedef struct config_t {
    char *str;
    bool flag;
} config_t;

void validate_alignment(size_t alignment, void *ptr) {
    size_t offset = (size_t) ptr & (alignment - 1);
    if (offset != 0) {
        fprintf(stderr, "Invalid memory alignment: expected %lu bytes alignment, got %lu\n", alignment, offset);
        exit(EXIT_FAILURE);
    }
}

offset_t *init_offsets(size_t capacity, size_t alignment) {
    offset_t *result = malloc(sizeof(offset_t));
    validate_alignment(alignment, result);
    result->capacity = capacity;
    result->size = 0;
    result->values = calloc(capacity, sizeof(long));
    validate_alignment(alignment, result->values);
    return result;
}

key_t *init_keys(size_t capacity, size_t alignment) {
    key_t *result = malloc(sizeof(key_t));
    validate_alignment(alignment, result);
    result->capacity = capacity;
    result->size = 0;
    result->values = calloc(capacity, sizeof(int));
    validate_alignment(alignment, result->values);
    return result;
}

record_t *init_records(size_t capacity, size_t record_size, size_t alignment) {
    record_t *result = malloc(capacity * record_size);
    validate_alignment(alignment, result);
    memset(result, 0, capacity * record_size);
    return result;
}

config_t *init_configs(size_t capacity, size_t string_length, size_t alignment) {
    config_t *result = malloc(sizeof(config_t));
    validate_alignment(alignment, result);
    result->str = malloc((string_length + 1) * sizeof(char)); // additional byte for null terminator
    validate_alignment(alignment, result->str);
    memset(result->str, 0, (string_length + 1) * sizeof(char));
    result->flag = false;
    return result;
}

void free_offsets(offset_t *offsets) {
    free(offsets->values);
    free(offsets);
}

void free_keys(key_t *keys) {
    free(keys->values);
    free(keys);
}

void free_records(record_t *records) {
    free(records);
}

void free_configs(config_t *configs) {
