#include <time.h>

void deserializeAndInitializeRecords(const char *filename, size_t *offsets, int *keys, size_t capacity, size_t *num_records, int min_value, int max_value) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Unable to open the file.\n");
        return;
    }

    size_t num_read = 0;
    *num_records = 0;

    offsets[*num_records] = 0;

    int buffer;
    while ((num_read = fread(&buffer, sizeof(int), 1, file)) > 0) {
        if (*num_records == capacity) {
            size_t new_capacity = *num_records * 2; // Doubling the array capacity
            offsets = realloc(offsets, new_capacity * sizeof(size_t));
            keys = realloc(keys, new_capacity * sizeof(int));
        }

        offsets[*num_records + 1] = ftell(file);
        keys[*num_records] = buffer;
        keys[*num_records] = rand() % (max_value - min_value + 1) + min_value; // Modify each record's value
        *num_records += 1;
    }

    if (ferror(file)) {
        printf("Error: I/O operation failed.\n");
    } else {
        fclose(file);
    }
}
