void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int parse_csv_row(char **fields, size_t fields_count, Measurement **measurements, size_t *measurements_count, char **locations, size_t *locations_count) {
    if (fields_count < 3) {
        log_error("Incorrect number of fields in CSV row.");
        return -1;
    }

    // Allocate memory for a new measurement and location
    Measurement *new_measurement = realloc(*measurements, sizeof(Measurement) * (*measurements_count + 1));
    if (!new_measurement) {
        log_error("Memory allocation failure.");
        return -errno;
    }
    *measurements = new_measurement;

    // Parse timestamp and temperature from the CSV row
    (*measurements)[*measurements_count].timestamp = strtol(fields[0], NULL, 10);
    (*measurements)[*measurements_count].temperature = atof(fields[1]);

    // Allocate memory for a new location and copy it into the measurement
    char *new_location = strdup(fields[2]);
    if (!new_location) {
        log_error("Memory allocation failure.");
        return -errno;
    }
    (*measurements)[*measurements_count].location = new_location;

    // Increment the number of measurements and locations allocated
    ++(*measurements_count);
    if (fields_count > 3) {
        // If there are more fields than required, store them in the locations array
        char *new_location_ptr = &new_location[strlen(new_location)];
        strcpy(new_location_ptr, fields[3]);

        // Allocate memory for a new location and increment the number of locations allocated
        char *new_locations = realloc(*locations, sizeof(char *) * (*locations_count + 1));
        if (!new_locations) {
            log_error("Memory allocation failure.");
            return -errno;
        }
        *locations = new_locations;
        (*locations)[*locations_count] = new_location_ptr;
        ++(*locations_count);
    }

    // Return success code
    return 0;
}

int parse_csv(FILE *file, Measurement **measurements, size_t *measurements_count, char **locations, size_t *locations_count) {
    char line[4096];
    size_t row_index = 0;
    while (fgets(line, sizeof(line), file)) {
        char *fields[4] = {NULL};
        char *field = strtok(line, ",");
        size_t field_index = 0;
        while (field) {
            fields[field_index] = field;
            field = strtok(NULL, ",");
            ++field_index;
        }

        if (parse_csv_row(fields, field_index + 1, measurements, measurements_count, locations, locations_count) < 0) {
            return -1;
        }
    }

    // Handle the case where there is an odd number of temperature readings or location identifiers
    if (*measurements_count != *locations_count) {
        log_error("Mismatch between the number of temperature readings and location identifiers.");
        return -1;
    }

    // Return success code
    return 0;
