// Config and Record structures
typedef struct Config {
    char *name;
    bool flag;
} Config;

typedef struct Record {
    int value;
} Record;

// Function to calculate memory requirements
size_t memReq(int numConfig, int numRecord, int recordSize, int configNameSize) {
    size_t configMemory = (numConfig * (sizeof(Config.name) + 1)); // Account for null character
    size_t configAlignment = alignof(Config) - sizeof(Config.name);
    size_t configTotal = ((configMemory + configAlignment - 1) / configAlignment) * configAlignment;

    size_t recordAlignment = alignof(Record) - sizeof(Record.value);
    size_t recordMemory = (numRecord * recordSize + recordAlignment - 1) / recordAlignment * recordAlignment;

    return configTotal + recordMemory;
}

// Function to allocate and initialize memory for the structures
void* initMem(int numConfig, int numRecord, int recordSize, int configNameSize, LibInterface *extLib) {
    void *memory = calloc(1, memReq(numConfig, numRecord, recordSize, configNameSize));
    if (!memory) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

