#define ALIGNMENT 16

typedef struct {
    int severity;
    time_t timestamp;
    void* metadata; // Variable fields will be added dynamically using offsets within this structure
    char* message;
} LogEntry;

void* align(size_t size, size_t alignment) {
    return (void*)(((size_t)size + alignment - 1) & ~(alignment - 1));
}

LogEntry* create_log_entry(int severity, time_t timestamp, const void* metadata, const char* message) {
    size_t total_size = align(sizeof(LogEntry) + sizeof(void*) * (num_metadata_fields() + 1) + strlen(message) + 1);
    LogEntry* entry = (LogEntry*)malloc(total_size);

    if (!entry) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    memset(entry, 0, total_size);

    entry->severity = severity;
    entry->timestamp = timestamp;
    entry->metadata = (void*)align((sizeof(void*) * (num_metadata_fields() + 1)), ALIGNMENT);

    if (!entry->metadata) {
        free(entry);
        perror("Metadata allocation failed");
        exit(EXIT_FAILURE);
    }

    size_t message_offset = offsetof(LogEntry, message);
    char* aligned_message = (char*)align((strlen(message) + 1), ALIGNMENT) + entry->metadata;

    if (!aligned_message) {
        free(entry->metadata);
        free(entry);
        perror("Message alignment failed");
        exit(EXIT_FAILURE);
    }

    strcpy(aligned_message, message);

    return entry;
}

void destroy_log_entry(LogEntry* entry) {
    if (entry->metadata) free(entry->metadata);
    if (entry->message) free(entry->message);
    free(entry);
}
