['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_NAME_LENGTH 100
#define ENTRY_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    double score;
} Entry;

struct entry_collection {
    Entry* entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void entry_collection_init(struct entry_collection* ec) {
    ec->entries = malloc(ENTRY_CAPACITY * sizeof(Entry));
    if (!ec->entries) exit(1);
    memset(ec->entries, 0, ENTRY_CAPACITY * sizeof(Entry));

    ec->capacity = ENTRY_CAPACITY;
    ec->size = 0;

    pthread_mutex_init(&ec->lock, NULL);
}

void entry_collection_destroy(struct entry_collection* ec) {
    if (ec->entries) free(ec->entries);
    pthread_mutex_destroy(&ec->lock);
}

static void swap(Entry* a, Entry* b) {
    Entry tmp = *a;
    *a = *b;
    *b = tmp;
}

static void merge(Entry* base, Entry* aux, size_t begin, size_t mid, size_t end) {
    for (size_t i = begin; i < end; ++i)
        aux[i] = base[i];

    size_t left_end = mid - 1;
    size_t right_start = mid;
    size_t current = begin;

    while (left_end >= right_start) {
        if ((right_start + 1 < end && aux[right_start + 1].score > aux[right_start].score) ||
            (left_end == right_start)) {
            swap(&aux[current], &aux[right_start]);
            current++;
            right_start++;
        } else if (aux[left_end].score >= aux[right_start].score) {
            left_end--;
        } else {
            swap(&aux[current], &aux[right_start]);
            current++;
            right_start++;
        }
    }
}

static void merge_sort(Entry* arr, size_t len, size_t capacity) {
    if (len < 2) return;

    size_t mid = len / 2;
    Entry* aux = malloc(capacity * sizeof(Entry));
    if (!aux) exit(1);

    merge_sort(arr, mid, capacity);
    merge_sort(&arr[mid], len - mid, capacity);
    merge(arr, aux, 0, mid, len);
    free(aux);
}

void entry_collection_sort(struct entry_collection* ec) {
    pthread_mutex_lock(&ec->lock);

    Entry* sorted = malloc((ec->size + 1) * sizeof(Entry));
    if (!sorted) exit(1);

    memcpy(sorted, ec->entries, ec->size * sizeof(Entry));
    merge_sort(sorted, ec->size, ec->capacity);

    size_t i = 0;
    for (size_t j = 0; j < ec->size; ++j) {
        if (i == ec->size) break;
        ec->entries[i] = sorted[j];
        ++i;
    }

    pthread_mutex_unlock(&ec->lock);
}

void entry_collection_push(struct entry_collection* ec, const char* name, int age, double score) {
    if (ec->size + 1 >= ec->capacity) {
        size_t new_capacity = ec->capacity * GROWTH_FACTOR;
        Entry* temp = realloc(ec->entries, new_capacity * sizeof(Entry));

        if (!temp) exit(1);
        ec->entries = temp;
        ec->capacity = new_capacity;
    }

    pthread_mutex_lock(&ec->lock);
    Entry* entry = &ec->entries[ec->size];
    strcpy(entry->name, name);
    entry->age = age;
    entry->score = score;
    ec->size++;
    pthread_mutex_unlock(&ec->lock);
}

void* find_entry(const void* data, const void* key, size_t size_key, size_t size_data) {
    for (int i = 0; i < size_data; ++i) {
        if (!memcmp(&((Entry*)data)[i].name, key, size_key)) return &((Entry*)data)[i];
    }
    return NULL;
}

bool entry_collection_remove(struct entry_collection* ec, const char* name) {
    pthread_mutex_lock(&ec->lock);

    Entry** it = (Entry**)bsearch(name, ec->entries, ec->size, sizeof(Entry), find_entry);
    if (!it || ec->size == 0) {
        pthread_mutex_unlock(&ec->lock);
        return false;
    }

    memmove(*it, *(it + 1), (ec->size - it - 1) * sizeof(Entry));
    ec->size--;
    pthread_mutex_unlock(&ec->lock);

    return true;
}
```

This code creates a dynamic collection of `entry` objects, handles concurrent access from multiple threads using a mutex, and provides functions to push new entries, remove existing ones by name, and sort the collection based on scores in descending order. The entry_collection structure dynamically resizes when it reaches a specified capacity threshold (here set to 16, but easily customizable) using a growth factor of 2. Memory is managed robustly to prevent memory leaks under high load conditions.']

