class ThreadSafeLogManager {
public:
    std::list<std::string>& getLog() { return logs; }
    size_t getInsertionCount() const { return insertions; }

    void insert(const std::string& entry, const std::string& searchTerm) {
        // Normalize strings for case-insensitive matching and avoid malformed entries
        auto normalizedEntry = std::move(entry);
        std::transform(normalizedEntry.begin(), normalizedEntry.end(), normalizedEntry.begin(), ::toupper);

        std::mutex mtx;
        {
            std::lock_guard<std::mutex> lock(mtx);

            auto normalizedSearchedTerm = searchTerm;
            std::transform(normalizedSearchedTerm.begin(), normalizedSearchedTerm.end(), normalizedSearchedTerm.begin(), ::toupper);

            auto it = std::find_if(logs.cbegin(), logs.cend(), [&](const auto& log) {
                return std::equal(normalizedEntry.cbegin(), normalizedEntry.cend(), log.cbegin()) &&
                    std::equal(log.cend(), log.cend(), normalizedSearchedTerm.cbegin());
            });

            if (it != logs.cend()) {
                // Insert new entry after found position
                auto pos = it;
                ++pos;
                logs.insert(pos, std::move(normalizedEntry));
                ++insertions;
            } else {
                // Append new entry if not found
                logs.push_back(std::move(normalizedEntry));
                ++insertions;
            }
        }
    }

private:
    std::list<std::string> logs;
    size_t insertions = 0;
    mutable std::mutex mtx;
};
```

