#include <semaphore.h>
#include <syslog.h>

typedef struct {
    int key;
    long offset;
} record;

struct memory_pool {
    void *start, *end;
    size_t block_size;
    struct mmap_control *control;
};

struct mmap_control {
    struct memory_pool *mem_pool;
    pthread_mutex_t lock;
};

void* mem_pool_alloc(struct memory_pool *pool, size_t n) {
    void *addr = pool->start + (pool->block_size * pool->control->allocs);
    if ((pool->control->allocs + n) > (pool->end - addr)) {
        syslog(LOG_ERR, "Memory pool overflow");
        exit(1);
    }

    pthread_mutex_lock(&pool->control->lock);
    pool->control->allocs += n;
    pthread_mutex_unlock(&pool->control->lock);

    return addr;
}

void mem_pool_free(struct memory_pool *pool, void *ptr) {
    pthread_mutex_lock(&pool->control->lock);
    pool->control->allocs -= (ptr - pool->start) / pool->block_size;
    pthread_mutex_unlock(&pool->control->lock);
}

void deserializeAndInitializeRecords(const char *filename, size_t record_count) {
    FILE *file = fopen(filename, "rb");

    if (!file) {
        syslog(LOG_ERR, "Failed to open file: %s", filename);
        exit(1);
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    if (file_size > MAX_FILE_SIZE) {
        syslog(LOG_ERR, "File too large: %s", filename);
        exit(1);
    }

    record *records = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (!records) {
        syslog(LOG_ERR, "Failed to map file: %s", filename);
        exit(1);
    }
    fseek(file, 0, SEEK_SET);
    fread(records, 1, file_size, file);
    fclose(file);

    struct memory_pool mem_pool = { records, records + record_count, sizeof(record), NULL };
    struct mmap_control mem_ctrl = { &mem_pool, PTHREAD_MUTEX_INITIALIZER };

    sem_t locks[record_count];
    for (size_t i = 0; i < record_count; ++i) {
        sem_init(&locks[i], 0, 1);
    }

    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        int rc = pthread_create(&threads[i], NULL, processRecord, &mem_ctrl, locks + i * (record_count / NUM_THREADS), records);
        if (rc) {
            syslog(LOG_ERR, "Thread creation failed: %s", strerror(rc));
            exit(1);
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    munmap(records, file_size);
}

