['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char *str;
    int flag;
} data_point;

#define GROWTH_FACTOR 2

data_point* create_collection(size_t initial_size) {
    data_point *collection = malloc(initial_size * sizeof(data_point));
    if (!collection) {
        fprintf(stderr, "Out of memory: Failed to allocate initial collection.\n");
        return NULL;
    }
    return collection;
}

void resize_collection(data_point **collection, size_t *current_size, size_t new_size) {
    if (new_size <= *current_size) {
        fprintf(stderr, "Invalid operation: Trying to shrink the collection.\n");
        return;
    }

    data_point *new_collection = realloc(*collection, new_size * sizeof(data_point));
    if (!new_collection) {
        fprintf(stderr, "Out of memory: Failed to resize collection.\n");
        return;
    }
    *collection = new_collection;
    *current_size = new_size;
}

void destroy_collection(data_point *collection, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(collection[i].str);
    }
    free(collection);
}

int add_data_point(data_point **collection, size_t *current_size, data_point new_data) {
    if (*current_size == 0) {
        *collection = create_collection(1);
        if (!*collection) return -1;
        *current_size = 1;
    } else if ((*current_size + 1) > (*current_size * GROWTH_FACTOR)) {
        resize_collection(collection, current_size, *current_size * GROWTH_FACTOR);
        if (*collection == NULL) return -1;
    }

    (*collection)[*current_size] = new_data;
    ++(*current_size);

    return 0;
}
```

This code provides a dynamic collection of `data_point` structures. The `create_collection()` function initializes the collection with a given size, and the `resize_collection()` function allows for efficient resizing based on a growth factor (defined as GROWTH_FACTOR). The `add_data_point()` function adds new data points to the collection, handling memory allocation failures gracefully. The collection is destroyed using the `destroy_collection()` function when it's no longer needed.']

