            long elapsedTime = TimeUnit.MILLISECONDS.between(Instant.now(), timestamps.get(Thread.currentThread().getId()));
            return elapsedTime > periodMillis;
        }
        timestamps.put(Thread.currentThread().getId(), Instant.now());
        return true;
    }
}
