typedef struct record {
    long offset;
    int key;
    double weight;
    int status;
} Record;

#if defined(_WIN32) || defined(_WINDOWS)
    #define ALLOC(type, n) _aligned_malloc((n)*sizeof(type), 64)
    #define FREE(ptr) _aligned_free(ptr)
#else
    #define ALLOC(type, n) aligned_alloc(64, (n)*sizeof(type))
    #define FREE(ptr) free(ptr)
#endif

static pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;
static Record* records = NULL;
static size_t capacity = 0;
static size_t count = 0;

void init_records(size_t initial_capacity) {
    if (initial_capacity > 0) {
        records = ALLOC(Record, initial_capacity);
        capacity = initial_capacity;
        for (size_t i = 0; i < initial_capacity; ++i) {
            records[i].offset = -1;
            records[i].key = -1;
            records[i].weight = 0.0;
            records[i].status = 0;
        }
    }
}

Record* get_record(long offset) {
    Record* record;
    pthread_mutex_lock(&records_lock);
    for (size_t i = 0; i < count; ++i) {
        if (records[i].offset == offset) {
            record = &records[i];
            break;
        }
    }
    if (record == NULL && capacity > 0 && count < capacity) {
        record = &records[count++];
        record->offset = offset;
    }
    pthread_mutex_unlock(&records_lock);
    return record;
}

void resize_records(size_t new_capacity) {
    if (new_capacity > capacity && new_capacity > count) {
        Record* new_records = ALLOC(Record, new_capacity);
        for (size_t i = 0; i < count; ++i) {
            new_records[i] = records[i];
        }
        FREE(records);
        records = new_records;
        capacity = new_capacity;
    }
}

// Implement a destructor to free allocated memory when the program terminates
void destroy_records() {
    pthread_mutex_destroy(&records_lock);
    FREE(records);
}
```
