#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/syscall.h>

static sem_t *sem;

void createAndDeleteSemaphore(int initial_value) {
    int count = 0;
    while (1) {
        if ((sem = sem_open("my_semaphore", O_CREAT | O_EXCL, 0644, initial_value)) != SEM_FAILED) {
            break;
        }
        count++;
        usleep(500 * count); // Retry delay increases exponentially to minimize contention.
        if (count > 1000) {
            perror("Failed to create semaphore");
            exit(EXIT_FAILURE);
        }
    }
}

void deleteSemaphore() {
    if (sem_destroy(sem) == -1) {
        perror("Failed to destroy semaphore");
    }
    sem_close(sem);
}

int processIntegers(int max_size, FILE *stream) {
    int arrSize = 0;
    long long max = LONG_MIN;
    int *numbers = malloc(max_size * sizeof(int));
    sem_t *inputSem = NULL;

    createAndDeleteSemaphore(1);
    inputSem = sem;

    int i = 0;
    long long currentNum;
    while (i < max_size && fscanf(stream, "%lld", &currentNum) == 1) {
        if (!sem_wait(inputSem)) { // Wait for access to the shared resource.
            if (currentNum >= -1000000 && currentNum <= 1000000) {
                numbers[arrSize++] = (int)currentNum;
                max = (max < currentNum ? currentNum : max);
            } else {
                fprintf(stderr, "Invalid integer value: %lld\n", currentNum);
            }
        } else {
            fprintf(stderr, "Failed to acquire semaphore\n");
            break;
        }
    }

    deleteSemaphore();

    qsort(numbers, arrSize, sizeof(int), (int(*)(const void*, const void*))cmp); // Sort the array for finding maximum efficiently.

    printf("Maximum integer: %d\n", numbers[arrSize - 1]);

    free(numbers);
    return arrSize;
}

int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
```

