void init_record(record* rec) {
    rec->key = rand() % MAX_KEY_VALUE;
    rec->value = rand() % MAX_VALUE_RANGE;
}

size_t calculate_memory_required(size_t num_records) {
    return sizeof(record) * num_records;
}

void* allocate_memory(size_t size) {
    void* mem = malloc(size);
    if (!mem) {
        fprintf(stderr, "Error: Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    return mem;
}

void deallocate_memory(void* mem, size_t size) {
    free(mem);
}

void log_memory_usage(size_t allocated_memory) {
    printf("Allocated memory: %zu bytes\n", allocated_memory);
}

void* initialize_records(size_t num_records, size_t seed) {
    pthread_mutex_t lock;
    record* records = NULL;
    size_t memory_required = calculate_memory_required(num_records);
    void* mem = allocate_memory(memory_required);
    records = mem;
    pthread_mutex_init(&lock, NULL);

    init_record(records);

    #pragma omp parallel for shared(records, lock) firstprivate(seed) schedule(static)
    for (size_t i = 1; i < num_records; ++i) {
        pthread_mutex_lock(&lock);
        init_record(records + i);
        pthread_mutex_unlock(&lock);
    }

    log_memory_usage(memory_required);

    pthread_mutex_destroy(&lock);
    return records;
}
