Record** init_record_array(size_t* capacity) {
    Record **records;
    pthread_mutex_t *lock = calloc(1, sizeof(pthread_mutex_t));

    if (!lock || !capacity || !(records = malloc(*capacity * sizeof(Record*)))) {
        perror("Failed to allocate memory");
        free(lock);
        return NULL;
    }

    pthread_mutex_init(&lock[0], NULL);

    // Initialize each record pointer to NULL
    for (size_t i = 0; i < *capacity; ++i) {
        records[i] = NULL;
    }

    return records;
}

// Function to dynamically resize the record array
void resize_record_array(Record** records, size_t* capacity, size_t new_capacity) {
    if (*capacity == new_capacity) {
        return;
    }

    Record **new_records = malloc(new_capacity * sizeof(Record*));

    pthread_mutex_init(&((new_records + 1)[0]), NULL);

    for (size_t i = 0; i < *capacity && i < new_capacity; ++i) {
        if (records[i]) {
            new_records[i] = records[i];
        }
    }

    free(records);
    *capacity = new_capacity;
    records = new_records;
}

// Function to perform the actual work concurrently using C11 threads
void work(Record** records, size_t capacity) {
    pthread_t threads[MAX_NUM_THREADS];
    int rc;

    for (size_t i = 0; i < MAX_NUM_THREADS; ++i) {
        rc = pthread_create(&threads[i], NULL, process_records, (void*)(records + i * (capacity / MAX_NUM_THREADS)));
        if (rc) {
            perror("Failed to create thread");
        }
    }

    for (size_t i = 0; i < MAX_NUM_THREADS; ++i) {
        rc = pthread_join(threads[i], NULL);
        if (rc) {
            perror("Failed to join thread");
        }
    }
}

