    for (size_t i = buffer_count - 1; i >= 0; --i) {
        if (buffer_pool[i] == buffer) {
            memmove(&buffer_pool[i], &buffer_pool[i + 1], (buffer_count - i - 1) * sizeof(char*));
            buffer_pool[--buffer_count] = NULL;
            break;
