void compress_image(const char* inputFilename, const char* outputFilename) {
    // Load input image data
    WebPDecConfig config;
    WebPDecInput input;
    WebPDecOutput output;
    WebPPicture picture;

    webp_dec_config_init(&config);
    if (webp_dec_configure(&config, NULL) < 0) error_handler("Failed to configure WebP decoder");

    input.data = NULL;
    input.size = 0;
    input.filename = strdup(inputFilename);

    if (webp_dec_read_image(&config, &input, &output, &picture) < 0) error_handler("Failed to load input image");

    // Compress the picture using WebP encoder
    WebPEncConfig enc_cfg;
    WebPEncInput enc_in;
    WebPEncOutput enc_out;

    webp_enc_config_init(&enc_cfg);
    if (webp_enc_configure(&enc_cfg, &config) < 0) error_handler("Failed to configure WebP encoder");

    enc_in.data = NULL;
    enc_in.size = 0;

    if (webp_enc_encode(&enc_cfg, picture.data, picture.stride, &enc_out, &enc_in) < 0) error_handler("Failed to compress image");

    // Save output WebP file
    FILE *outputFile = fopen(outputFilename, "wb");
    if (!outputFile) error_handler("Failed to open output file");
    fwrite(enc_out.data, enc_out.size, 1, outputFile);
    fclose(outputFile);

    // Cleanup
    webp_picture_data_free(&picture);
    free(input.filename);
}
