#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum { ACTIVE, INACTIVE, PENDING } State;

struct Record {
    long offset;
    int key;
    State state;
    struct Record *next;
};

struct ListConfig {
    size_t initial_capacity;
    size_t growth_factor;
};

typedef struct MutexLock {
    pthread_mutex_t lock;
} MutexLock;

void init_list(struct Record** head, const struct ListConfig* config) {
    if (!head || !config) return;
    *head = NULL;
    *head = malloc(config->initial_capacity * sizeof(struct Record));
    if (!*head) return;
    for (size_t i = 0; i < config->initial_capacity; ++i) {
        (*head)[i].next = &((*head)[(i + 1) % config->initial_capacity]);
    }
    (*head)->next = *head;
}

struct Record* alloc_record(const struct ListConfig* config) {
    if (!config) return NULL;
    struct Record *new_node = malloc(sizeof(struct Record));
    if (!new_node) return NULL;
    new_node->next = NULL;
    return new_node;
}

void push_back(struct Record** head, struct Record* node, const struct ListConfig* config) {
    MutexLock lock;
    pthread_mutex_init(&lock.lock, NULL);
    pthread_mutex_lock(&lock.lock);

    if (!head || !node) {
        pthread_mutex_unlock(&lock.lock);
        return;
    }

    if (!*head) {
        init_list(head, config);
    }

    struct Record *current = *head;
    while (current->next != *head) current = current->next;

    current->next = node;
    node->next = *head;

    pthread_mutex_unlock(&lock.lock);
}

void deallocate(struct Record** node) {
    if (!node || !*node) return;
    free(*node);
    *node = NULL;
}

// Implement additional functions to support filtering, thread-safety, and external data processing library integration as needed.
