#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sqlite3.h>
#include <pthread.h>

typedef struct {
    int id;
    int value;
} Record;

typedef struct DataAccessLayer {
    sqlite3 *db;
    char *table_name;
} DataAccessLayer;

DataAccessLayer *data_access_layer_init(const char *db_path, const char *table_name) {
    DataAccessLayer *dal = malloc(sizeof(DataAccessLayer));
    if (dal == NULL) exit(EXIT_FAILURE);
    if (sqlite3_open(db_path, &dal->db)) exit(EXIT_FAILURE);
    dal->table_name = table_name;
    return dal;
}

void data_access_layer_close(DataAccessLayer *dal) {
    sqlite3_close(dal->db);
    free(dal);
}

static int callback(void *notUsed, int argc, char **argv, char **azColName) {
    (void) notUsed;
    for (int i = 0; i < argc; ++i)
        printf("%s = %s\n", azColName[i], argv[i] ? argv[i] : "NULL");
    return 0;
}

Record *create_records(DataAccessLayer *dal, int num_records, int range_max) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) exit(EXIT_FAILURE);

    for (int i = 0; i < num_records; ++i) {
        records[i].id = i + 1;
        records[i].value = rand() % range_max + 1;
    }

    char sql[] = "DELETE FROM %s";
    sprintf(sql + strlen(sql), dal->table_name);
    if (sqlite3_exec(dal->db, sql, NULL, NULL, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to delete records\n");
        exit(EXIT_FAILURE);
    }

    char insert_sql[] = "INSERT INTO %s (id, value) VALUES (?, ?)";
    sqlite3_stmt *stmt;
    if (sqlite3_prepare_v2(dal->db, insert_sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        sqlite3_bind_int(stmt, 1, records[i].id);
        sqlite3_bind_int(stmt, 2, records[i].value);
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            fprintf(stderr, "Failed to insert record\n");
            exit(EXIT_FAILURE);
        }
    }

    return records;
}

// Sort records using quicksort with Lomuto partition scheme.
void qsort_records(Record *records, int left, int right) {
    if (left < right) {
        int pivot = partition(records, left, right);
        qsort_records(records, left, pivot - 1);
        qsort_records(records, pivot + 1, right);
    }
}

int partition(Record *records, int left, int right) {
    Record pivot = records[right];
    int storeIndex = left;

    for (int i = left; i < right; ++i) {
        if (records[i].value <= pivot.value) {
            std::swap(records[storeIndex], records[i]);
            storeIndex++;
        }
    }

    std::swap(records[storeIndex], records[right]);
    return storeIndex;
}

void free_records(Record *records, int num_records) {
    free(records);
}
```

The function `create_records()` initializes the records array with random IDs and values, then deletes any existing data in the database table and inserts the new data. It uses a prepared statement for better performance when executing the same SQL query multiple times.

The sorting algorithm used is quicksort, which has an average time complexity of O(n log n) with space complexity O(log n). In this case, we're using the Lomuto partition scheme to reduce additional memory requirements compared to other quicksort implementations.

