#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct DataContainer {
    Record *records;
    int *offsets;
    int *keys;
    size_t capacity;
    size_t size;
} DataContainer;

DataContainer* createDataContainer(size_t maxSize) {
    DataContainer *dc = malloc(sizeof(DataContainer));
    if (!dc) return NULL;

    dc->records = calloc(maxSize, sizeof(Record));
    if (!dc->records) {
        free(dc);
        return NULL;
    }

    dc->offsets = calloc(maxSize + 1, sizeof(int));
    if (!dc->offsets) {
        free(dc->records);
        free(dc);
        return NULL;
    }

    dc->keys = calloc(maxSize, sizeof(int));
    if (!dc->keys) {
        free(dc->offsets);
        free(dc->records);
        free(dc);
        return NULL;
    }

    dc->capacity = maxSize;
    dc->size = 0;
    dc->records[0].key = -1; // sentinel value for empty containers

    return dc;
}

bool addRecord(DataContainer *dc, int key, int value) {
    if (dc->size >= dc->capacity) {
        return false;
    }

    int index = binarySearch(dc->keys, dc->size, key);
    if (index < 0) { // key not found
        index = ~index;
    } else {
        memmove(&dc->records[index + 1], &dc->records[index], sizeof(Record) * (dc->size - index));
    }

    dc->keys[index] = key;
    dc->offsets[index + 1] = dc->offsets[index] + 1;
    dc->records[index].key = key;
    dc->records[index].value = value;
    dc->size++;

    return true;
}

int getValue(DataContainer *dc, int key) {
    int index = binarySearch(dc->keys, dc->size, key);
    if (index >= 0 && dc->records[index].key == key) {
        return dc->records[index].value;
    }
    return -1; // not found
}

int binarySearch(const int *arr, size_t size, int target) {
    int left = 0;
    int right = size;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] > target) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return ~left; // not found, return negative index
}

void freeDataContainer(DataContainer *dc) {
    if (!dc) return;
    free(dc->keys);
    free(dc->offsets);
    free(dc->records);
    free(dc);
}
```

