    rec->name = name;
    pthread_mutex_lock(&mutex);
    rec->offset = pthread_rwlock_wrlock(&rw_lock) * RAND_MAX / 100 + offset;
    pthread_rwlock_unlock(&rw_lock);
}

void merge_sort(Record *arr, int left, int right) {
    if (left >= right) return;
    int mid = (left + right) / 2;
    merge_sort(arr, left, mid);
    merge_sort(arr, mid + 1, right);
    merge(arr, left, mid, right);
}

void merge(Record *arr, int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;
    Record *L = malloc((n1 + 1) * sizeof(Record));
    Record *R = malloc((n2 + 1) * sizeof(Record));

    for (int i = 0; i < n1; ++i) L[i] = arr[left + i];
    for (int j = 0; j < n2; ++j) R[j] = arr[mid + j + 1];

    L[n1] = R[-1]; // sentinel value
    R[n2] = L[-1]; // sentinel value

    int i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        if (L[i].offset <= R[j].offset) arr[k++] = L[i++];
        else arr[k++] = R[j++];
    }
