const depthLimit = 10;
let selectedElements = new Set();
let pendingPromises = [];

function findElementsBySelector(root, selector) {
    const stack = [root];
    let currentDepth = 0;

    function traverse(node) {
        if (!node || currentDepth > depthLimit) return;

        if (node.matches && node.matches(selector)) {
            selectedElements.add(node);
        }

        if (node.children) {
            for (const child of Array.from(node.children)) {
                stack.push(child);
            }
        }

        if (node.hasOwnProperty('then') && !node.then.done) {
            pendingPromises.push(node.then);
        }

        currentDepth++;
        traverse(stack[stack.length - 1]);
    }

    function processPendingPromises() {
        if (!pendingPromises.length) return;

        const promise = pendingPromises.shift();
        promise.then(result => {
            const newNode = result;
            traverse(newNode);
            processPendingPromises();
        });
    }

    traverse(root);
    processPendingPromises();

    return Array.from(selectedElements);
}
```

