#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    double reading;
} sensor;

void process_line(char* line, sensor* sensors, size_t* sensor_count) {
    char* token = strtok(line, " ");
    size_t index = 0;
    for (; token != NULL && index < *sensor_count; ++index) {
        if (sscanf(token, "%ld %lf", &(sensors[index].timestamp), &(sensors[index].reading)) == 2) {
            token = strtok(NULL, " ");
        } else {
            sensors[index].reading = 0;
            if (index >= *sensor_count) {
                resize_sensor_array(sensor_count, sizeof(sensor), 50); // Increase array size by 50%
            }
        }
    }
}

void resize_sensor_array(size_t* array_ptr, size_t element_size, size_t increment) {
    size_t current_size = *array_ptr;
    *array_ptr += (current_size + increment);
    sensor* new_data = malloc(*array_ptr * element_size);
    memcpy(new_data, *(void**) array_ptr, current_size * element_size);
    free(*(void**) array_ptr);
    *(void**) array_ptr = new_data;
}

double compute_average(sensor* sensors, size_t count) {
    double sum = 0;
    for (size_t i = 0; i < count - 3; ++i) {
        sum += sensors[i].reading;
    }
    return sum / 4.0;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 2;
    }

    size_t sensor_count = 4; // Initialize with at least four sensors
    sensor* sensors = malloc(sensor_count * sizeof(sensor));
    for (size_t i = 0; i < sensor_count; ++i) {
        sensors[i].reading = rand() % 100 + 1; // Set random reading value within [1, 100] range
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        process_line(buffer, sensors, &sensor_count);
    }

    fclose(file);

    double* averages = malloc(sensor_count * sizeof(double));
    for (size_t i = 0; i < sensor_count; ++i) {
        if ((i + 3) < sensor_count) {
            averages[i] = compute_average(sensors, sensor_count);
        }
    }

    for (size_t i = 0; i < sensor_count; ++i) {
        printf("%ld %lf", sensors[i].timestamp, sensors[i].reading);
        if ((i + 3) < sensor_count && !isnan(averages[i])) {
            printf(" %lf\n", averages[i]);
        } else {
            printf("\n");
        }
    }

    free(sensors);
    free(averages);

    return 0;
}
