['```java
import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPoolConfig;
import java.nio.channels.SelectionKey;
import java.util.ConcurrentModificationException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DistributedCacheManager {
    private final JedisPoolConfig poolConfig = new JedisPoolConfig();
    private final JedisPool jedisPool = new JedisPool(poolConfig, "redis-server-ip", 6379);
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final LRUCache lruCache = new LRUCache();
    private int evictionFrequencyThreshold;
    private long memoryUsageLimit;

    public DistributedCacheManager(int evictionFrequencyThreshold, long memoryUsageLimit) {
        this.evictionFrequencyThreshold = evictionFrequencyThreshold;
        this.memoryUsageLimit = memoryUsageLimit;
        scheduler();
    }

    private void scheduler() {
        executor.scheduleAtFixedRate(() -> cleanup(), evictionFrequencyThreshold, evictionFrequencyThreshold, TimeUnit.SECONDS);
    }

    private void cleanup() {
        try {
            Map<String, Long> accessMap = lruCache.getAccessMap();
            long currentMemoryUsage = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();

            if (currentMemoryUsage > memoryUsageLimit) {
                for (Map.Entry<String, Long> entry : accessMap.entrySet()) {
                    if (currentMemoryUsage > memoryUsageLimit && entry.getValue() + TimeUnit.SECONDS.toMillis(10) < System.currentTimeMillis()) {
                        String key = entry.getKey();
                        Long value = entry.getValue();
                        removeFromCache(key);
                    }
                }
            }
        } catch (ConcurrentModificationException e) {
            // Handle the exception if needed, e.g., logging or retrying.
        }
    }

    public void put(String key, String value) {
        Jedis jedis = jedisPool.getResource();
        try {
            long currentMemoryUsage = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
            if (currentMemoryUsage + value.length() > memoryUsageLimit) {
                removeOldestEntryFromCache();
            }

            lruCache.put(key, System.currentTimeMillis());
            jedis.setex(key, 60, value);
        } finally {
            jedis.close();
        }
    }

    public String get(String key) {
        Jedis jedis = jedisPool.getResource();
        try {
            Long valueTime = jedis.ttl(key);
            if (valueTime <= 0) {
                return null;
            }

            long currentMemoryUsage = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
            lruCache.access(key);

            if (currentMemoryUsage > memoryUsageLimit) {
                removeOldestEntryFromCache();
            }

            return jedis.get(key);
        } finally {
            jedis.close();
        }
    }

    private void removeFromCache(String key) {
        lruCache.remove(key);
        jedisPool.returnBrokenResourceToPool(null, false);
    }

    private void removeOldestEntryFromCache() {
        long currentMemoryUsage = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
        Map<String, Long> accessMap = lruCache.getAccessMap();
        if (!accessMap.isEmpty()) {
            for (Map.Entry<String, Long> entry : accessMap.entrySet()) {
                removeFromCache(entry.getKey());
                if (currentMemoryUsage - (Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory()) < memoryUsageLimit) {
                    break;
                }
            }
        }
    }

    private static class LRUCache extends LinkedHashMap<String, Long> {
        public LRUCache() {
            super(128, 0.75f, true);
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > this.size();
        }
    }
}
```

This is a basic implementation of the distributed cache manager using Redis and NIO. It includes a custom LRU cache with adjustable thresholds for eviction frequency and memory usage, as well as background cleanup tasks to ensure memory usage remains within specified limits without affecting application performance.

You may need to modify it based on your specific requirements such as handling network delays, intermittent service outages from the external inventory service, optimizing for frequent read-heavy operations, and ensuring data consistency across multiple nodes.']

