// Custom memory allocator, thread-safe and cache-efficient (optional)
// ...

struct Record { int value; };

class UnionFind {
public:
    template<typename T>
    UnionFind(size_t capacity) : parents_(capacity), ranks_(capacity, 0) {}

    // Perform standard union-find operations with optimizations for performance and space efficiency
    void makeSet(T key) {
        if (parents_.find(key) != parents_.end()) return;
        parents_[key] = key;
        ranks_[key] = 0;
    }

    int findSet(T key) {
        auto it = parents_.find(key);
        if (it == parents_.end()) throw std::out_of_range("Key not found in UnionFind set");

        if (it->second != it->first) {
            it->second = parents_[it->second];
        }
        return it->second;
    }

    void unionSet(T x, T y) {
        int rootX = findSet(x);
        int rootY = findSet(y);

        if (rootX == rootY) return;

        if (ranks_[rootX] < ranks_[rootY]) {
            parents_[rootX] = rootY;
        } else if (ranks_[rootX] > ranks_[rootY]) {
            parents_[rootY] = rootX;
        } else {
            parents_[rootY] = rootX;
            ++ranks_[rootX];
        }
    }

private:
    std::unordered_map<T, T> parents_;
    std::unordered_map<T, int> ranks_;
};

// Random number generator with thread-safety (optional)
