#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <sys/mman.h>

#define MAX_RECORDS 1024
#define BUFFER_SIZE 256
#define POOL_LIMIT 8192
#define LOGGING 1

typedef struct Record {
    long offset;
    int key;
    float weight;
    double intensity;
    char buffer[BUFFER_SIZE];
    void* descriptor; // struct descriptor pointer
    size_t buffer_len;
} Record;

// Memory pool structure
typedef struct Pool {
    Record records[MAX_RECORDS];
    size_t used;
    size_t free_index;
    pthread_mutex_t lock;
} Pool;

Pool* create_pool() {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) return NULL;

    memset(pool, 0, sizeof(Pool));
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_pool(Pool* pool) {
    if (!pool) return;

    free(pool);
}

Record* allocate_record(Pool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used < MAX_RECORDS && pool->free_index != pool->used) {
        Record* record = &pool->records[pool->used];
        pool->used++;
        pthread_mutex_unlock(&pool->lock);
        return record;
    }

    size_t new_size = (pool->used + 1 < POOL_LIMIT) ? MAX_RECORDS : POOL_LIMIT - pool->used;
    Record* new_records = realloc(pool->records, sizeof(Record) * new_size);
    if (!new_records) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    memset(new_records + pool->used, 0, sizeof(Record) * (new_size - MAX_RECORDS));
    pool->records = new_records;
    pool->free_index = pool->used;
    pthread_mutex_unlock(&pool->lock);

    return &pool->records[pool->used - 1];
}

void free_record(Pool* pool, Record* record) {
    if (!pool || !record) return;

    pthread_mutex_lock(&pool->lock);
    record->buffer_len = 0;
    pool->records[pool->free_index] = *record;
    pool->free_index++;
    pthread_mutex_unlock(&pool->lock);
}

// Implement asynchronous data processing function that takes Record* as input, using the external library
void process_data(Record* record) {
    // Use the external library here
}

int main() {
    Pool* pool = create_pool();
    if (!pool) return 1;

    Record* record = allocate_record(pool);
    if (!record) goto clean_exit;

    // Initialize record fields
    record->offset = 0;
    record->key = 12345;
    record->weight = 3.14f;
    record->intensity = 2.71828;
    record->buffer_len = strlen("Some data");
    strcpy(record->buffer, "Some data");

    // Log allocation event
    if (LOGGING) printf("Allocated record: %p\n", record);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_data, record)) {
        free_record(pool, record);
        goto clean_exit;
    }

clean_exit:
    destroy_pool(pool);
    return 0;
}
