    for (int i = 0; i < num_nodes; ++i) {
        node_t* predecessor = node_to_delete->predecessors[i];
        if (predecessor) predecessor->next = node_to_delete->next;
    }

    free(node_to_delete->measurement);
    free(node_to_delete);
}

