#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

#define MAX_NAME_LENGTH 64
#define NUM_TRANSACTIONS 10000

typedef struct {
    float value;
    double timestamp;
    char name[MAX_NAME_LENGTH];
} transaction;

typedef struct {
    transaction transactions[NUM_TRANSACTIONS];
    // Add other fields as needed for the record structure
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory = 0;

void initialize_transactions() {
    record *records = mmap(NULL, sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (!records) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    total_memory += sizeof(record);

    // Allocate memory for transaction arrays
    float *precision_values = calloc(NUM_TRANSACTIONS, sizeof(float));
    double *timestamp_values = calloc(NUM_TRANSACTIONS, sizeof(double));
    char **transaction_names = malloc(NUM_TRANSACTIONS * MAX_NAME_LENGTH);

    if (!(precision_values && timestamp_values && transaction_names)) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    total_memory += sizeof(precision_values) + sizeof(timestamp_values) + sizeof(transaction_names);

    // Predefine list of names
    const char *names[] = {"Alice", "Bob", "Charlie", "Dave", "Eve"};

    pthread_t threads[NUM_TRANSACTIONS];

    for (size_t i = 0; i < NUM_TRANSACTIONS; ++i) {
        void* threadarg = &records->transactions[i];
        int rc = pthread_create(&threads[i], NULL, initialize_transaction_worker, (void*)threadarg);

        if (rc) {
            perror("pthread_create failed");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all worker threads to finish
    for (size_t i = 0; i < NUM_TRANSACTIONS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(transaction_names);
    free(precision_values);
    free(timestamp_values);
    munmap(records, sizeof(record));

    printf("Total memory allocated: %zu bytes\n", total_memory);
}

void* initialize_transaction_worker(void *arg) {
    transaction *transaction = (transaction *) arg;

    pthread_mutex_lock(&mutex);

    // Set name using the predefined list of names
    strncpy(transaction->name, names[random() % 5], MAX_NAME_LENGTH);

    // Set float and double fields with random values within given ranges
    transaction->value = random() / (RAND_MAX / 100.0);
    transaction->timestamp = random() * RAND_MAX * time(NULL) / RAND_MAX;

    pthread_mutex_unlock(&mutex);

    return NULL;
}
```
