#include <string.h>
#include <dom/api.h> // External DOM library API

typedef struct Node {
    Element element;
    struct Node* next;
} Node;

Node* traverseDOM(Element root, const char *selector, void (*callback)(Element)) {
    Node* head = NULL;
    Node* current = NULL;

    // Recursive traversal function
    void traverse(Element node) {
        if (is_element_matching_selector(&node, selector)) {
            if (!head) {
                head = malloc(sizeof(Node));
                head->next = NULL;
                head->element = node;
                current = head;
            } else {
                current->next = malloc(sizeof(Node));
                current = current->next;
                current->next = NULL;
                current->element = node;
            }
            callback(node);
        }

        // Traverse children and recursively call traverse() on matching elements
        for (size_t i = 0; i < node.childrenCount; ++i) {
            traverse(node.children[i]);
        }
    }

    traverse(root);
    return head;
}
