record* allocate_records(size_t count) {
    record *records = malloc(count * sizeof(record));

    if (!records) {
        perror("malloc failed");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count && records; ++i) {
        size_t str_len = rand() % 256 + 1;
        char str[256];

        // Ensure no duplicates by comparing to previously allocated strings
        for (size_t j = 0; j < i; ++j) {
            if (strncmp(records[i].str, records[j].str, str_len) == 0) {
                --count;
                break;
