#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct Record {
    size_t offset;
    unsigned long key;
    void* data; // Record structure
    size_t str_len;
    char* str;
} Record;

typedef struct HashNode {
    Record rec;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode** table;
    unsigned long table_size;
    pthread_mutex_t mutex;
} HashTable;

unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % TABLE_SIZE;
}

void free_record(Record* rec) {
    if (rec->str)
        free(rec->str);
    free(rec);
}

HashTable* create_hash_table(unsigned long size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->table = calloc(size, sizeof(HashNode*));
    ht->table_size = size;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

void insert_record(HashTable* ht, Record* rec) {
    unsigned long index = hash(rec->str);
    pthread_mutex_lock(&ht->mutex);
    HashNode* current = ht->table[index];
    while (current != NULL && strcmp(current->rec.str, rec->str))
        current = current->next;

    if (current == NULL) { // String not found, insert the record
        Record* new_rec = malloc(sizeof(Record));
        *new_rec = *rec;
        new_rec->str = strdup(rec->str);
        HashNode* new_node = malloc(sizeof(HashNode));
        new_node->rec = *new_rec;
        new_node->next = ht->table[index];
        ht->table[index] = new_node;
    }
    pthread_mutex_unlock(&ht->mutex);
}

Record* get_record(HashTable* ht, const char* str) {
    unsigned long index = hash(str);
    Record* rec = NULL;
    pthread_mutex_lock(&ht->mutex);
    HashNode* current = ht->table[index];
    while (current != NULL && strcmp(current->rec.str, str))
        current = current->next;

    if (current != NULL)
        rec = &current->rec;
    pthread_mutex_unlock(&ht->mutex);
    return rec;
}

void free_hash_table(HashTable* ht) {
    for (unsigned long i = 0; i < ht->table_size; ++i) {
        HashNode* current = ht->table[i];
        while (current != NULL) {
            HashNode* temp = current;
            current = current->next;
            free_record(&temp->rec);
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->mutex);
    free(ht);
}

Record* generate_records(unsigned int count) {
    Record *records = malloc(count * sizeof(Record));
    for (unsigned int i = 0; i < count; ++i) {
        records[i].offset = i;
        records[i].key = rand();
        size_t str_len = rand() % 256 + 1;
        records[i].str_len = str_len;
        records[i].str = malloc(str_len + 1);
        for (size_t j = 0; j < str_len; ++j)
            records[i].str[j] = 'A' + rand() % 26 + rand() % 26 * 26;
        records[i].str[str_len] = '\0';
    }
    return records;
}

void* create_records(unsigned int count, HashTable* ht) {
    Record* records = generate_records(count);
    for (unsigned int i = 0; i < count && i < 10; ++i) {
        Record *rec = &records[i];
        if (!get_record(ht, rec->str))
            insert_record(ht, rec);
    }
    return records;
}

int main() {
    unsigned long TABLE_SIZE = 1024;
    HashTable* ht = create_hash_table(TABLE_SIZE);
    pthread_t threads[8];
    void* results[8];

    for (unsigned int i = 0; i < 8; ++i) {
        unsigned int count = rand() % 1000 + 1;
        if (pthread_create(&threads[i], NULL, create_records, &count, ht)) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (unsigned int i = 0; i < 8; ++i) {
        if (pthread_join(threads[i], &results[i])) {
            fprintf(stderr, "Failed to join thread\n");
            return 1;
        }
    }

    printf("First 10 records:\n");
    for (unsigned int i = 0; i < 10 && i < 8 * results[i]; ++i) {
        Record* rec = &((Record*)results[0])[i];
        printf("Offset: %ld, Key: %ld, String: %s\n", rec->offset, rec->key, rec->str);
    }

    free_hash_table(ht);
    return 0;
}
```

This code provides a basic implementation of the given task. It creates a hash table using a linked list for string pointers and uses a mutex to ensure thread safety. The function `create_records()` generates records with unique strings (under heavy load conditions) and inserts them into the hash table, returning only the first 10 initialized records.

The code does not include optimization strategies such as resizing the hash table or switching to a Bloom filter for faster space-time complexity at the cost of false positives. To improve performance under heavy loads, consider implementing these optimizations and assessing their impact on overall system performance when integrating with external data sources that provide strings of varying lengths.']

