    client: Client,
    log: RwLock<LoggingAdapter>,
    config: Config,
}

// LoggingAdapter implementation for different log levels and formats
impl LoggingAdapter {
    async fn info(&self, msg: &str) { self.log(LevelFilter::Info, msg).await }
    async fn debug(&self, msg: &str) { self.log(LevelFilter::Debug, msg).await }
}

// Function to create the HTTP client with dynamic configuration via environment variables
async fn create_http_client() -> HttpClient {
    let SSL_VERIFY = env::var("SSL_VERIFY").is_ok();
    let timeout = Duration::from_secs(env::var("REQUEST_TIMEOUT")
        .unwrap_or_else(|_| "5".to_string())
