    let user_agent = env::var("USER_AGENT").unwrap_or_else(|_| "MyApp/1.0".to_string());
    let retry_max = env::var("RETRY_MAX")
        .unwrap_or_else(|_| "3".to_string())
        .parse::<u32>()
        .unwrap();
    let retry_delay = Duration::from_millis(env::var("RETRY_DELAY")
        .unwrap_or_else(|_| "500".to_string())
        .parse::<u64>()
        .unwrap() as u64)
        .mul(Duration::seconds(1));
    let log_level = match env::var("LOG_LEVEL") {
        Ok("DEBUG") => LevelFilter::Debug,
        Ok("INFO") => LevelFilter::Info,
        _ => LevelFilter::Error,
    };
    let log_format = if env::var("LOG_FORMAT").unwrap() == "json" { LogFormat::Json } else { LogFormat::Plain };

    // Validate and initialize the logging dependency here
    validate_and_init_logger().await;

    HttpClient {
        client: Client::builder()
            .timeout(Duration::from_secs(timeout))
            .user_agent(UserAgent::parse(&user_agent).unwrap())
            .build()
            .expect("Failed to create HTTP client"),
        log: RwLock::new(LoggingAdapter),
        config: Config {
            timeout,
            user_agent,
            retry_max,
            retry_delay,
            log_level,
            log_format,
            SSL_VERIFY,
            cache_TTL: Duration::from_secs(60), // Default cache TTL
            rate_limit: None,
        },
    }
}

