#define MAX_OFFSET 1000000000 // Maximum offset value
#define EPSILON 0.000001 // Precision epsilon for floating-point numbers

typedef struct {
    long *offsets;
    int *keys;
    double *values;
    size_t capacity;
    size_t size;
    sem_t sem; // Semaphore for synchronization
} DataManager;

DataManager* create_data_manager(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DataManager *dm = malloc(sizeof(DataManager));
    dm->offsets = malloc(initial_capacity * sizeof(long));
    dm->keys = malloc(initial_capacity * sizeof(int));
    dm->values = malloc(initial_capacity * sizeof(double));

    if (!dm->offsets || !dm->keys || !dm->values) {
        free(dm);
        return NULL;
    }

    sem_init(&dm->sem, 0, 1);
    dm->capacity = initial_capacity;
    dm->size = 0;

    return dm;
}

void destroy_data_manager(DataManager *dm) {
    free(dm->offsets);
    free(dm->keys);
    free(dm->values);
    sem_destroy(&dm->sem);
    free(dm);
}

void validate_allocation(DataManager *dm, size_t new_size) {
    if (new_size > dm->capacity) {
        size_t old_capacity = dm->capacity;
        dm->capacity *= 2;

        long *tmp_offsets = realloc(dm->offsets, dm->capacity * sizeof(long));
        int *tmp_keys = realloc(dm->keys, dm->capacity * sizeof(int));
        double *tmp_values = realloc(dm->values, dm->capacity * sizeof(double));

        if (!tmp_offsets || !tmp_keys || !tmp_values) {
            fprintf(stderr, "Memory allocation failed. Increasing capacity from %zu to %zu\n", old_capacity, dm->capacity);
            return;
        }

        dm->offsets = tmp_offsets;
        dm->keys = tmp_keys;
        dm->values = tmp_values;
    }
}

void add_record(DataManager *dm, long offset, int key, double value) {
    validate_allocation(dm, dm->size + 1);

    sem_wait(&dm->sem);

    dm->offsets[dm->size] = offset;
    dm->keys[dm->size] = key;
    dm->values[dm->size] = value;
    dm->size++;

    sem_post(&dm->sem);
}

