        Validate(filePath);

        currentFile = memoryPool.Allocate();
        currentFile.path = filePath;
        currentFile.status = FileInfo::Status::TRANSFORMING;
    }

    if (currentFile.status == FileInfo::Status::TRANSFORMING) {
        Transform(currentFile.path, request['transform']);
        currentFile.status = FileInfo::Status::STORING;
    }

    if (currentFile.status == FileInfo::Status::STORING) {
