#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

record* initialize_data(unsigned int MAX_OFFSETS, unsigned int MAX_KEYS, unsigned int MAX_RECORDS) {
    // Allocate memory for each data structure using malloc and ensure proper error handling in case of memory allocation failure.
    long *offsets = (long*)malloc((size_t)MAX_OFFSETS * sizeof(long));
    if (!offsets) {
        perror("Error allocating memory for offsets");
        return NULL;
    }

    int *keys = (int*)calloc((size_t)MAX_KEYS, sizeof(int));
    if (!keys) {
        perror("Error allocating memory for keys");
        free(offsets);
        return NULL;
    }

    record *records = (record*)calloc((size_t)MAX_RECORDS, sizeof(record));
    if (!records) {
        perror("Error allocating memory for records");
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize each long offset in the first array with a sequential value starting from 0.
    for (unsigned int i = 0; i < MAX_OFFSETS; ++i) {
        offsets[i] = i;
    }

    // Initialize each int key in the second array with a random value between 1 and 1000, ensuring no duplicates within the array.
    unsigned int used_keys = 0;
    for (unsigned int i = 0; i < MAX_KEYS && used_keys < MAX_RECORDS; ++i) {
        int key = rand() % 1000 + 1;
        if (!key_in_array(keys, used_keys, key)) {
            keys[used_keys++] = key;
        }
    }

    // Initialize the offset field of each record structure with a corresponding value from the first array, and the key field with a corresponding value from the second array.
    for (unsigned int i = 0; i < MAX_RECORDS && used_keys < MAX_KEYS; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Use a loop to generate random keys for the int keys array, ensuring no duplicate keys are generated within the array.
    srand(time(NULL));

    return &records[0];
}

int key_in_array(const int *arr, unsigned int size, int key) {
    for (unsigned int i = 0; i < size; ++i) {
        if (arr[i] == key) {
            return 1;
        }
    }
    return 0;
}
