public class ProductCatalog {
    private static final String API_URL = "https://api.store.com/v1/products";
    private static final String STATE_FILE = "product_catalog_state.ser";
    private static final int MAX_THREADS = 5;
    private static final long EXPONENTIAL_BACKOFF_BASE = 1000L;
    private static ExecutorService executor;
    private transient MoSTState state;
    private OkHttpClient httpClient;

    public ProductCatalog() {
        // Create a ThreadPoolExecutor with a fixed thread count and a daemon thread
        executor = new ThreadPoolExecutor(MAX_THREADS, MAX_THREADS, 0L, TimeUnit.MILLISECONDS,
                new LinkedBlockingQueue<>());
        httpClient = new OkHttpClient();
    }

    public void retrieveAndDisplayProductCatalog(Map<String, String> criteria) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(STATE_FILE))) {
            state = (MoSTState) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            loadInitialState();
        }

        if (state != null) {
            // Check if the cached product catalog is still valid based on user-specified criteria
            if (matchesCriteria(criteria)) {
                displayProductCatalog(state.getProductCatalog());
                return;
            }
        }

        Callback callback = new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                logError("Failed to fetch product catalog", e);
                handleApiError(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                if (!response.isSuccessful()) {
                    logError("Unsuccessful API response for product catalog", null);
                    handleApiError(new IOException("Received unsuccessful API response"));
                    return;
                }

                JsonArray jsonProducts = new JSONArray(response.body().string());
                List<Product> products = fromJson(jsonProducts, new TypeToken<List<Product>>() {}.getType());
                state = new MoSTState(products);
                logSuccess("Fetched product catalog");
            }
        };

        RetryPolicy retryPolicy = new ExponentialBackoffRetry(EXPONENTIAL_BACKOFF_BASE, 3);
        Request request = new Request.Builder()
                .url(API_URL + buildQueryString(criteria))
                .build();

        Call call = httpClient.newCall(request).retryOnConnectionFailure(true).retry(retryPolicy).call();
        executor.submit(() -> call.enqueue(callback));
    }

    private void loadInitialState() {
        // Implement loading initial state from the API or any other source
        state = new MoSTState(fetchProductCatalogFromApi());
        saveStateToFile();
