#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
} record;

// Function to initialize and return a hash table for efficient key storage
void* init_hash_table(int size) {
    void* hash_table = calloc(size, sizeof(bool));
    if (!hash_table) {
        fprintf(stderr, "Error: Failed to allocate memory for the hash table\n");
        return NULL;
    }
    return hash_table;
}

// Function to generate a random key between 1 and 1000 without duplicates using the hash table
int gen_key(void* hash_table, int size) {
    bool keys[1001] = {false};
    int key;
    do {
        key = rand() % 1000 + 1;
    } while (keys[(int)(key - 1)] || *(bool*)((int)(key - 1) % size + hash_table));
    keys[(int)(key - 1)] = true;
    return key;
}

// Function to initialize and synchronize memory allocation for offsets, keys, and records
record* init_memory(int MAX_OFFSETS, int MAX_KEYS, int MAX_RECORDS) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    long* offsets = malloc(MAX_OFFSETS * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets\n");
        return NULL;
    }
    int* keys = malloc(MAX_KEYS * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Error: Failed to allocate memory for keys\n");
        return NULL;
    }
    void* hash_table = init_hash_table(MAX_OFFSETS + MAX_KEYS);
    if (!hash_table) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Error: Failed to allocate memory for the hash table\n");
        return NULL;
    }
    record* records = malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        free(hash_table);
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize offsets sequentially starting from 0
    *offsets = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 1; i < MAX_OFFSETS; ++i) {
        offsets[i] = offsets[i - 1] + 1;
    }
    pthread_mutex_unlock(&mutex);

    // Generate random keys without duplicates using the hash table
    for (int i = 0; i < MAX_KEYS; ++i) {
        keys[i] = gen_key(hash_table, MAX_OFFSETS + MAX_KEYS);
    }

    // Optimized linear probing for handling potential collisions in the hash table
    int curr = 0;
    for (int i = 0; i < MAX_RECORDS && curr < MAX_OFFSETS + MAX_KEYS; ++i) {
        while (*(bool*)((int)(curr % (MAX_OFFSETS + MAX_KEYS)) + hash_table)) {
            curr = (curr + 1) % (MAX_OFFSETS + MAX_KEYS);
        }
        records[i].offset = offsets[*((long*)(&curr))];
        records[i].key = keys[(int)(curr - 1)];
        *(bool*)((int)(curr % (MAX_OFFSETS + MAX_KEYS)) + hash_table) = true;
        ++curr;
    }

    return records;
}
```

This code initializes and synchronizes memory allocation for three distinct data structures, using `pthread_mutex_lock` to protect shared resources. It handles memory allocation errors and race conditions by logging detailed error messages. The hash table balances performance and memory usage by using linear probing for collision handling, ensuring key uniqueness and minimizing lookup times.

Memory deallocation is handled within the function, freeing all allocated memory upon function exit. Edge cases such as zero or near-zero values for `MAX_RECORDS` are managed by optimizing the hash table to handle potential collisions efficiently.']

