// Record structure definition
typedef struct {
    long offset;
    int key;
    int value;
} record;

// Global variables for memory management and error handling
pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
size_t records_allocated = 0;
size_t records_used = 0;
record *records;
bool leak_detect = false;

// External data processing library interface (assume it has a process function)
typedef void (*process_func)(int key, int value);
void* external_lib(process_func func, void* arg);

void init_memory(size_t capacity) {
    // Align memory for better performance in multi-threaded environments
    size_t aligned_capacity = (capacity + (sizeof(record) - 1)) & ~(sizeof(record) - 1);

    records = mmap(NULL, aligned_capacity * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    // Validate memory and set up leak detection mechanism
    if (posix_memalign(&records, sizeof(record), aligned_capacity * sizeof(record)) != 0) {
        perror("posix_memalign failed");
        exit(EXIT_FAILURE);
    }
    records_allocated = aligned_capacity;
    leak_detect = true;
}

void free_memory() {
    if (leak_detect && records != NULL) {
        munmap(records, records_allocated * sizeof(record));
        records = nullptr;
        records_allocated = 0;
    }
}

record* get_record(size_t index) {
    pthread_mutex_lock(&mem_lock);

    if (index >= records_used) {
        // Allocate more memory if needed, ensuring that the array is at least 50% full to avoid frequent reallocations
        if ((records_allocated - records_used) < records_used / 2) {
            size_t new_capacity = records_allocated * 2;
            init_memory(new_capacity);
        }
    }

    record* result = &records[index];
    records_used++;

    pthread_mutex_unlock(&mem_lock);
    return result;
}

void put_record(size_t index, record r) {
    pthread_mutex_lock(&mem_lock);

    if (index < records_used) {
        record* target = &records[index];
        *target = r;
        records_used--;
    }

    pthread_mutex_unlock(&mem_lock);
}

void process_records(process_func func, void* arg) {
    for (size_t i = 0; i < records_used; ++i) {
        record r = get_record(i);
        func(r.key, r.value);
        put_record(i, (record){-1, -1, -1}); // Mark processed records for garbage collection
    }
}

int main() {
    // Seed random number generator with current time to ensure statistical integrity
    srand((unsigned)time(NULL));

    // Initialize memory and external data processing library (assuming it has an appropriate interface)
    init_memory(1024);

    process_func process = [](int key, int value) { ... }; // Define your processing logic here
    void* arg = nullptr; // Set argument for the external library function as needed

    pthread_t threads[4]; // Number of threads to use can be adjusted based on system resources and desired throughput

    // Create and start worker threads
    for (int i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        if (pthread_create(&threads[i], nullptr, external_lib, (void*){process, arg})) {
            perror("pthread_create failed");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all worker threads to finish processing data
    for (int i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        pthread_join(threads[i], nullptr);
    }

    free_memory();
    return 0;
}
```

