// Predicate function to determine whether a state should be included
typedef bool (*state_predicate)(int);

// Function to process the subset of states from an FSA based on user-defined criteria
void* filter_states(void* args) {
    // Cast the argument to the appropriate type
    FilterArgs* data = (FilterArgs*)args;

    // Initialize a thread-safe queue for managing concurrent access and preventing data races
    pthread_queue* q = pthread_queue_create();

    // Loop through the states and enqueue them if they meet the predicate condition
    for (int i = 0; i < data->num_states; ++i) {
        if (data->predicate(data->states[i])) {
            pthread_queue_push(q, &data->states[i]);
        }
    }

    // Process the enqueued states in parallel using dynamic concurrency management strategy
    int concurrency = data->concurrency_limit;
    while (!pthread_queue_is_empty(q)) {
        pthread_t tid;
        pthread_queue_pop(q, &tid);

        // Adjust the number of active threads based on system load and resource availability
        if (concurrency > 1 && pthread_queue_size(q) < concurrency / 2) {
            --concurrency;
            pthread_detach(tid);
        } else {
            pthread_create(&tid, NULL, filter_states, data);
        }
    }

    // Join all the active threads and wait for them to complete
    for (int i = 0; i < concurrency; ++i) {
        pthread_join(tid, NULL);
    }

    // Return the processed state list
    return data->output_mempool->mem;
}

void* allocate_output_memory(size_t size) {
    MemPool* pool = create_mempool(size);
    void* mem = malloc(size);
    if (!mem) {
        free(pool);
        return NULL;
    }
    memcpy(pool->mem, mem, size);
    return pool->mem;
}

void deallocate_output_memory(void* memory) {
