// Thread-pool-based system
class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop_(false) {
        for (size_t i = 0; i < numThreads; ++i)
            workers_.emplace_back(&ThreadPool::worker, this);
    }

    template<class F>
    void enqueue(F&& f) {
        data_.push_back(std::move(f));
        cond_.notify_one();
    }

private:
    void worker() {
        for (;;) {
            auto task = data_.pop_front();
            try {
                task();
            } catch (const std::exception& e) {
                std::cerr << "Error in worker thread: " << e.what() << '\n';
            }
        }
    }

    void join_all() {
        stop_ = true;
        cond_.notify_all();
        for (auto& w : workers_) w.join();
    }

    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> data_;
    std::mutex mtx_;
    std::condition_variable cond_;
    std::atomic_bool stop_;
};

