#define MAX_NAME_LENGTH 32
#define ALIGNMENT 64

typedef struct {
    int key;
    int value;
    int type;
} record;

void set_random(record* r, int min, int max) {
    if (max - min + 1 <= INT_MAX)
        r->value = rand() % (max - min + 1) + min;
    else {
        fprintf(stderr, "Value range too large for an integer\n");
        exit(EXIT_FAILURE);
    }
}

void check_type(int t, const char* library[], size_t lib_len, int (*functions[lib_len])(const record*, char*, size_t)) {
    if (t < 0 || t >= lib_len) {
        fprintf(stderr, "Invalid type identifier\n");
        exit(EXIT_FAILURE);
    }
    if (!functions[t]) {
        fprintf(stderr, "No library function found for the given type\n");
        exit(EXIT_FAILURE);
    }
}

size_t total_memory(int n_records, int min, int max, size_t name_len) {
    size_t long_bytes = n_records * sizeof(long);
    size_t key_bytes = n_records * sizeof(int);
    size_t record_bytes = n_records * sizeof(record);
    size_t type_bytes = lib_len * sizeof(int);
    size_t name_bytes = lib_len * name_len;
    size_t func_ptr_bytes = lib_len * sizeof(void*);
    size_t library_bytes = lib_len * sizeof(int);

    return long_bytes + key_bytes + record_bytes + type_bytes + name_bytes + func_ptr_bytes + library_bytes;
}

void* aligned_malloc(size_t bytes, size_t alignment) {
    void* ptr = malloc(bytes);
    if (ptr == NULL) return NULL;
    size_t remainder = (size_t)(ptr - (unsigned long)0) % alignment;
    if (remainder != 0) {
        void* aligned_ptr = posix_memalign(ptr, alignment, bytes);
        free(ptr);
        return aligned_ptr;
    }
    return ptr;
}

int main() {
    int n_records = 10000;
    int min = 0;
    int max = 1000;
    size_t name_len = MAX_NAME_LENGTH;
    const char* library[] = {"lib1", "lib2"};
    size_t lib_len = sizeof(library) / sizeof(char*);
    int (*functions[lib_len])(const record*, char*, size_t) = {get_record_name_from_lib1, get_record_name_from_lib2};

    size_t total_bytes = total_memory(n_records, min, max, name_len);
    void* data = aligned_malloc(total_bytes, ALIGNMENT);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    long* offsets = (long*)data;
    int* keys = ((int*)offsets + n_records);
    record* records = ((int*)keys + n_records);
    int* types = ((record*)records + n_records);
    char* names = ((int*)types + lib_len);
    void** functions_ptr = ((char*)names + lib_len * name_len);
    int* libraries = ((void**)functions_ptr + lib_len);

    srand(time(NULL));

    for (int i = 0; i < n_records; ++i) {
        set_random(&records[i], min, max);
        records[i].key = i;
        records[i].type = rand() % lib_len;
    }

    for (int i = 0; i < n_records; ++i) {
        check_type(records[i].type, library, lib_len, functions);
        functions[records[i].type](&records[i], names + records[i].key * name_len, name_len);
    }

    free(data);

    return EXIT_SUCCESS;
}
