typedef struct Transaction {
    float value;
    double timestamp;
    char *name;
} Transaction;

void init_transaction(Transaction *tx) {
    tx->value = (float)rand() / RAND_MAX * 100.f; // within 0 to 100 range
    tx->timestamp = ((double)time(NULL)) + rand() % INT_MAX; // timestamp in future, within Int_max range
    size_t name_len = 0;
    while((name_len < strlen(transaction_names[0]))){
        name_len *= 2;
    }
    tx->name = malloc(name_len);
    strcpy(tx->name, transaction_names[rand() % NUM_NAMES]); // assign name from predefined list
}

void free_transaction(Transaction *tx) {
    free(tx->name);
}

int process_list(int sockfd) {
    char buffer[BUFF_SIZE];
    Transaction tx;
    int n = 0, max_val = INT_MIN;

    while((n = recv(sockfd, buffer, BUFF_SIZE - 1, 0)) > 0){
        if(buffer[n - 1] == '\n'){ // termination character received
            init_transaction(&tx);
            sscanf(buffer, "%*[^,],%f,%lf,%s\n", &tx.value, &tx.timestamp, tx.name);
            if(tx.value > max_val) {
                max_val = tx.value;
            }
            free_transaction(&tx); // free allocated memory for this transaction
        }
    }

    if (n < 0) {
        perror("recv");
        exit(EXIT_FAILURE);
    }

    return max_val;
}

int main() {
    int sockfd, portno;
    struct sockaddr_in serv_addr;
    char *configuration_file = "config.ini"; // configuration file for application settings
    srand(time(NULL)); // seed random number generator

    // load vendor autoloader, set environment variables for web application, configure the application using a configuration file

    sockfd = socket(AF_INET, SOCK_STREAM, 0); // create socket
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    portno = atoi(getenv("PORT")); // get port number from environment variable

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(portno);
    serv_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(sockfd, BACKLOG) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    int client_sockfd;
    struct sockaddr_in client_addr;
    socklen_t addr_size = sizeof(client_addr);

    while(1){
        client_sockfd = accept(sockfd, (struct sockaddr *) &client_addr, &addr_size); // accept a new connection
        if (client_sockfd < 0) {
            perror("accept");
            continue;
        }

        process_list(client_sockfd); // process list of integers received from client_sockfd
    }

    close(sockfd);
    return 0;
}
