#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    size_t length;
    void *data;
} Chunk;

void processAndInitializeRecords(const char *filepath, size_t chunkSize, size_t maxChunks, size_t randomRange) {
    int intKey;
    long longOffset;
    off_t pos = 0;
    ssize_t nread;
    Chunk *chunks = mmap(NULL, maxChunks * chunkSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (chunks == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    Chunk currentChunk = {.length = 0, .data = chunks + pos / chunkSize};

    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("open failed");
        exit(EXIT_FAILURE);
    }

    while ((nread = read(fd, &intKey, sizeof(int))) > 0) {
        currentChunk.length += nread;
        if (currentChunk.length >= chunkSize) {
            // Process the completed chunk
            processCompletedChunk(&currentChunk, randomRange);

            // Move to the next chunk
            pos += chunkSize;
            currentChunk = chunks + pos / chunkSize;
            currentChunk->length = 0;
        } else {
            // Continue reading into the current chunk
            lseek(fd, -sizeof(int), SEEK_CUR);
        }
    }

    if (currentChunk.length > 0) {
        processCompletedChunk(&currentChunk, randomRange);
    }

    munmap(chunks, maxChunks * chunkSize);
    close(fd);
}

void processCompletedChunk(const Chunk *chunk, size_t randomRange) {
    int *intArray = malloc(chunk->length / sizeof(int));
    long *longArray = malloc(chunk->length / sizeof(long));
    memcpy(intArray, chunk->data, chunk->length);

    for (size_t i = 0; i < chunk->length / sizeof(int); ++i) {
        intKey = intArray[i];
        longOffset = i * sizeof(int);

        // Modify the key with a random value within the specified range
        intKey = (rand() % randomRange) + 1;

        // Store the offset and modified key in their respective arrays
        longArray[i] = longOffset;
        intArray[i] = intKey;
    }

    // Initialize your data structures using longArray and intArray as needed.
