        if (!themeDir.exists()) {
            themeDir.mkdir();
        }
    }

    public static Image loadThemeBitmap(String filePath) throws IOException {
        Image image;
        synchronized (this) {
            semaphore.acquire();
            File themeFile = new File(filePath);
            try (InputStream inputStream = new FileInputStream(themeFile)) {
                BufferedImage bufferedImage = ImageIO.read(inputStream);
                image = Toolkit.getDefaultToolkit().getImage(bufferedImage.getSource());
            } catch (IOException e) {
                // Handle exceptions gracefully
                return null;
            } finally {
                semaphore.release();
            }
        }
        return image;
    }

    public static Image lazyLoadThemeBitmap(String filePath, Runnable onLoadedCallback) {
        Image image = loadThemeBitmap(filePath);
        if (image == null) {
            new Thread(() -> {
                try {
                    synchronized (this) {
                        semaphore.acquire();
                        image = loadThemeBitmap(filePath);
                        semaphore.release();
                    }
                    if (image != null && !Thread.currentThread().isInterrupted()) {
                        onLoadedCallback.run();
                    }
                } catch (Exception e) {
                    // Handle exceptions gracefully
                }
            }).start();
        }
        return image;
    }

