        Pointer buffer = UNSAFE.allocateMemory(Integer.BYTES * 4); // Allocate memory for an array of 4 ints (assuming IP address as 4 bytes per integer)
        int errorCode = resolveHostnameToIP(hostname, buffer);
        if (errorCode != 0) {
            UNSAFE.freeMemory(buffer); // Free the memory if the resolution fails
            throw new RuntimeException("Failed to resolve hostname: " + hostname);
        }

        int[] ipArray = new int[4];
        for (int i = 0; i < 4; ++i) {
            ipArray[i] = UNSAFE.getInt(buffer, i * Integer.BYTES);
        }

        return Arrays.stream(ipArray).mapToPrimative(u_char.class::valueOf).toArray(u_char[]::new);
    }
}
