In the C code (native_lib.c):

```c
#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>
#include <jni.h>

JNIEXPORT jint JNICALL Java_com_example_MostStateLoader_resolveHostnameToIP(JNIEnv *env, jobject this, jstring hostnameJStr) {
    const char* hostname = (*env)->GetStringUTFChars(env, hostnameJStr, NULL);
    struct addrinfo hints;
    struct addrinfo *res, *r;
    int status;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        freeaddrinfo(res);
        return status;
    }

    // Iterate through the address list and find a suitable one.
    r = res;
    for (r = res; r != NULL; r = r->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        if (r->ai_family == AF_INET) {
            struct sockaddr_in *v4_addr = (struct sockaddr_in *)r->ai_addr;
            addr = &v4_addr->sin_addr;
            inet_ntop(AF_INET, addr, ipstr, sizeof(ipstr));
            if (!strcmp(ipstr, "127.0.0.1")) continue; // Ignore localhost if it's not intended to be resolved
        } else if (r->ai_family == AF_INET6) {
            struct sockaddr_in6 *v6_addr = (struct sockaddr_in6 *)r->ai_addr;
            addr = &v6_addr->sin6_addr;
            inet_ntop(AF_INET6, addr, ipstr, sizeof(ipstr));
        } else continue; // Unsupported address family

        freeaddrinfo(res);
        return 0; // Successful resolution
    }

    freeaddrinfo(res); // Free the allocated memory
    return -1; // Resolution failed
}
```

