#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct data {
    double value;
    unsigned int timestamp;
    enum status { ACTIVE, INACTIVE } status;
} Data;

struct mem_pool {
    Data *data;
    size_t capacity;
    size_t count;
};

void init_mem_pool(struct mem_pool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->count = 0;
    pool->data = malloc(capacity * sizeof(Data));
}

Data acquire_data(struct mem_pool *pool) {
    Data *data;

    if (pool->count == pool->capacity) {
        fprintf(stderr, "Memory pool is full.\n");
        exit(1);
    }

    data = &pool->data[pool->count];
    ++pool->count;
    return *data;
}

void release_data(struct mem_pool *pool, const Data *data) {
    if (data->status == ACTIVE) {
        data->status = INACTIVE;
    } else {
        fprintf(stderr, "Trying to release inactive data.\n");
        exit(1);
    }
}

Data* allocate_data_array(size_t size) {
    Data *data = malloc(sizeof(Data) * size);

    if (!data) {
        fprintf(stderr, "Failed to allocate memory for data array.\n");
        exit(1);
    }

    return data;
}

void free_data_array(Data *data, size_t size) {
    free(data);
}

// Function for generating random values within a specified range
double rand_in_range(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

void init_data(Data *data, unsigned int timestamp, enum status status) {
    data->value = rand_in_range(-1e8, 1e8);
    data->timestamp = timestamp;
    data->status = status;
}

// External numerical computation library interface (assuming it's a function with the following signature: int compute(Data *data, enum mode mode))
int compute(Data *data, enum mode mode) {
    // Implementation details go here
}

void manage_data(struct mem_pool *pool, size_t data_count, unsigned int timestamp, enum status status, enum mode mode) {
    Data *data_array = allocate_data_array(data_count);

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < data_count; ++i) {
        Data data = acquire_data(pool);
        init_data(&data, timestamp + i, status);
        data_array[i] = data;
    }

    // Process the data array using the external numerical computation library
    for (size_t i = 0; i < data_count; ++i) {
        pthread_mutex_lock(&lock);
        compute(&data_array[i], mode);
        pthread_mutex_unlock(&lock);
    }

    // Free the allocated memory and release resources
    free_data_array(data_array, data_count);
    pthread_mutex_destroy(&lock);
}
