['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <limits.h>

typedef struct Record {
    int key;
    char *data;
} Record;

struct MemPool {
    void *offsets;
    void *keys;
    void *records;
    size_t offsetSize;
    size_t keySize;
    size_t recordSize;
    size_t maxRecords;
    size_t allocatedRecords;
    sem_t semaphore;
};

MemPool *init_mempool(size_t max_records, size_t offset_size, size_t key_size, size_t record_size) {
    MemPool *pool = malloc(sizeof(MemPool));
    if (!pool) return NULL;

    pool->offsetSize = offset_size;
    pool->keySize = key_size;
    pool->recordSize = record_size;
    pool->maxRecords = max_records;

    pool->offsets = mmap(NULL, max_records * offset_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->offsets == MAP_FAILED) goto cleanup;

    pool->keys = mmap(NULL, max_records * key_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->keys == MAP_FAILED) goto cleanup_offsets;

    pool->records = mmap(NULL, max_records * record_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->records == MAP_FAILED) goto cleanup_keys;

    pool->allocatedRecords = 0;
    sem_init(&(pool->semaphore), 0, max_records);

    return pool;

cleanup_records: munmap(pool->records, max_records * record_size);
cleanup_keys:   munmap(pool->keys, max_records * key_size);
cleanup_offsets: munmap(pool->offsets, max_records * offset_size);
    free(pool);

cleanup: return NULL;
}

void *get_record(MemPool *pool) {
    void *record = NULL;

    if (sem_wait(&(pool->semaphore)) < 0) {
        perror("Semaphore wait failed");
        exit(EXIT_FAILURE);
    }

    if (pool->allocatedRecords < pool->maxRecords) {
        record = pool->records + pool->allocatedRecords * pool->recordSize;
        pool->allocatedRecords++;
    } else {
        fprintf(stderr, "Maximum number of records reached\n");
    }

    sem_post(&(pool->semaphore));

    return record;
}

Record *new_record(MemPool *pool) {
    Record *record = get_record(pool);
    if (!record) return NULL;

    record->key = *(int *)((char *)pool->keys + pool->allocatedRecords * pool->keySize);
    record->data = ((char *)pool->offsets + record->key * pool->offsetSize);

    return record;
}

void log_memory(MemPool *pool) {
    printf("Memory usage:\n");
    printf("\tOffset array: %ld bytes\n", (long) pool->offsetSize * pool->allocatedRecords);
    printf("\tKey array: %ld bytes\n", (long) pool->keySize * pool->allocatedRecords);
    printf("\tRecord array: %ld bytes\n", (long) pool->recordSize * pool->allocatedRecords);
}
```

