2. Union-Find implementation using Path Compression (for single-threaded version):

```c
#include <stdbool.h>

struct UF {
    int count; // Number of disjoint sets
    int* id;   // ID for each object in the union set
};

void init_UF(struct UF *uf, int n) {
    uf->count = n;
    uf->id = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i) uf->id[i] = i;
}

int find_set(struct UF *uf, int p) {
    return (uf->id[p] == p) ? p : (uf->id[p] = find_set(uf, uf->id[p]));
}

bool union_set(struct UF *uf, int x, int y) {
    int rootX = find_set(uf, x);
    int rootY = find_set(uf, y);
    if (rootX == rootY) return false; // Already in the same set
    uf->id[rootY] = rootX; --uf->count;
    return true;
}
```

3. Customizable thread-safe wrapper around the UF implementation:

```c
#include <pthread.h>

// Wrapper for Union-Find to handle multi-threading using a Mutex lock
struct TUF {
    struct UF uf;
    pthread_mutex_t lock;
};

void init_TUF(struct TUF *uf, int n) {
    init_UF(&uf->uf, n);
    pthread_mutex_init(&uf->lock, NULL);
}

int find_set_TUF(struct TUF *uf, int p) {
    pthread_mutex_lock(&uf->lock);
    int root = find_set(&uf->uf, p);
    pthread_mutex_unlock(&uf->lock);
    return root;
}

bool union_set_TUF(struct TUF *uf, int x, int y) {
    bool res;
    pthread_mutex_lock(&uf->lock);
    res = union_set(&uf->uf, x, y);
    pthread_mutex_unlock(&uf->lock);
    return res;
}
