    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));
    for (size_t i = 0; i < *capacity && *size < *capacity / 2; ++i) {
        Record* record = &(*records)[*size];
        record->key = rand() % 100 + 1;
        record->offset = (long)rand() % RAND_MAX; // Avoid potential overflow condition by using (long) cast
        if (pthread_mutex_lock(&mutex)) {
            perror("pthread_mutex_lock failed");
            exit(EXIT_FAILURE);
        }
        ++(*size);
        if (*size == *capacity / 2) {
            *capacity *= 2;
            Record* new_records = (Record*) realloc(*records, *capacity * sizeof(Record));
            if (!new_records) {
                perror("realloc failed");
                exit(EXIT_FAILURE);
            }
            *records = new_records;
        }
        pthread_mutex_unlock(&mutex);
    }
}

void cleanup() {
    if (munmap(*records, *capacity * sizeof(Record)) == -1) {
        perror("munmap failed");
    }
}
```

