struct Record { int value; };

class CustomMemoryPool {
public:
    CustomMemoryPool(size_t capacity) : pool_(capacity), used_(0) {}

    Record* allocate() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (used_ < capacity) {
            ++used_;
            return &pool_[used_ - 1];
        }
        return nullptr;
    }

    void deallocate(Record* record) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (record >= &pool_[0] && record < &pool_[capacity]) {
            new (record) Record(); // Construct a new empty Record object at the address of the deallocated Record.
            --used_;
        }
    }

private:
    std::vector<Record> pool_;
    size_t used_;
    mutex mutex_;
};

