        if (m_characters[index]->canAttack()) {
            m_characters[index]->attack();
            updateAttackLog(index);
            m_network.sendAttackSelection(index);

            auto cooldownEndTime = std::chrono::system_clock::now() + std::chrono::duration<double>(m_characters[index]->getCooldown());
            auto self = this;
            auto task = std::async(std::launch::async, [self, index, cooldownEndTime]() {
