```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include "pjlog.h"

#define LOG_ARRAY_INITIAL_SIZE 1024
#define LOG_ENTRY_SIZE (sizeof(struct log) + MAX_MESSAGE_LENGTH)

struct log {
    time_t timestamp;
    int status_code;
    char message[MAX_MESSAGE_LENGTH];
};

typedef struct {
    void* buffer;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t full;
    pthread_cond_t empty;
} LogQueue;

LogQueue* log_queue_create(size_t initial_size) {
    LogQueue *queue = malloc(sizeof(LogQueue));
    if (!queue) return NULL;

    queue->buffer = mmap(NULL, initial_size * LOG_ENTRY_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (queue->buffer == MAP_FAILED) {
        free(queue);
        return NULL;
    }

    queue->size = initial_size * LOG_ENTRY_SIZE;
    queue->count = 0;

    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->full, NULL);
    pthread_cond_init(&queue->empty, NULL);

    return queue;
}

void log_queue_push(LogQueue* queue, const struct log *log) {
    size_t index = queue->count % queue->size;
    memcpy((char*)queue->buffer + index * LOG_ENTRY_SIZE, log, sizeof(*log));
    pthread_mutex_lock(&queue->mutex);
    queue->count++;
    if (queue->count == 1) {
        pthread_cond_signal(&queue->empty);
    }
    pthread_mutex_unlock(&queue->mutex);
}

int log_queue_pop(LogQueue* queue, struct log *log) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == 0) {
        pthread_cond_wait(&queue->full, &queue->mutex);
    }

    size_t index = queue->count % queue->size;
    memcpy(log, (char*)queue->buffer + index * LOG_ENTRY_SIZE, sizeof(*log));

    queue->count--;
    if (queue->count == queue->size - 1) {
        pthread_cond_signal(&queue->empty);
    }

    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

void log_queue_destroy(LogQueue* queue) {
    munmap(queue->buffer, queue->size);
    free(queue);
}

// Integrate with the external logging library and implement multi-threading functionality here.
```

