unsigned int find_next_prime(unsigned int n) {
    if (n <= 2) return 3;

    bool isPrime = true;
    unsigned int root = (unsigned int)sqrt((double)n);
    for (unsigned int i = 2; i <= root; ++i) {
        if (n % i == 0) {
            isPrime = false;
            break;
        }
    }

    return isPrime ? n : find_next_prime(n + 2);
}

size_t find_primes_in_range(unsigned int min, unsigned int max, size_t *primes, size_t capacity) {
    size_t count = 0;

    if (capacity < 2) return 0;

    primes[0] = 2;
    primes[1] = 3;
    count += 2;

    for (unsigned int i = 4; i <= max; i += 2) {
        bool isPrime = true;
        for (size_t j = 0; j < count && i % primes[j] != i; ++j) {}
        if (j == count) primes[count++] = i;
    }

    size_t num_primes = count;
    if (num_primes >= capacity) return capacity;

    size_t additional_capacity = num_primes < min ? max - min + 1 : 0;
    size_t new_capacity = capacity + additional_capacity;

    unsigned int *new_primes = realloc(primes, new_capacity * sizeof(unsigned int));
    if (!new_primes) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    primes = new_primes;

    for (unsigned int i = min + num_primes; i <= max; ++i) {
        bool isPrime = true;
        for (size_t j = 0; j < count && i % primes[j] != i; ++j) {}
        if (j == count) primes[count++] = i;
        if (count >= new_capacity) break;
    }

    return count;
}

