        exit(EXIT_FAILURE);
    }

    unsigned int max_prime = ULONG_MAX / (size + 1);
    size_t num_primes = find_primes_in_range(0, max_prime - 1, NULL, 0);
    if (num_primes < size) {
        fprintf(stderr, "Not enough prime numbers for requested key size!\n");
        exit(EXIT_FAILURE);
    }
    size_t *primes = malloc(num_primes * sizeof(size_t));
    find_primes_in_range(0, max_prime - 1, primes, num_primes);

    for (size_t i = 0; i < size; ++i) {
        bool found = false;
        int key = primes[i];
        for (size_t j = i + 1; j < size && !found; ++j) {
            if (primes[j] == key) found = true;
            else primes[j] -= found ? 0 : 1;
        }

        if (!found) continue;

        int next_key = primes[(i + size - 1) % size];
        while (next_key < key) next_key += primes[i];
        keys[i] = next_key;
    }

