typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

Record* create_records(int num) {
    Record *records = (Record*)malloc(num * sizeof(Record));

    for (int i = 0; i < num; ++i) {
        records[i].offset = i;
        records[i].key = rand() % 100 + 1; // Custom range 1 to 100
        records[i].value = (double)rand() / RAND_MAX * 100.0; // Uniformly distributed within [0, 100]
    }

    return records;
}

void sort_records(Record* records, int num) {
    qsort(records, num, sizeof(Record), [](const void* a, const void* b) -> int {
        const Record *ra = static_cast<const Record*>(a);
        const Record *rb = static_cast<const Record*>(b);

        return ra->key - rb->key;
    });
}

void* run_sort(void* arg) {
    int num = *(int*)arg;
    Record* records = create_records(num);

    sort_records(records, num);

    // You can implement any operation on the sorted array here.

    free(records);

    return NULL;
}

void perform_sort(int num) {
    pthread_t threads[num];

    for (int i = 0; i < num; ++i) {
        if (pthread_create(&threads[i], NULL, run_sort, &num) != 0) {
            perror("Error creating thread");
            return;
        }
    }

    for (int i = 0; i < num; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
            return;
        }
    }
}

