ResourceMetadata* loadResourceBundle(const char* bundlePath, ResourceType type) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static const char* versions[] = {"1.0", "1.1"}; // Version history for backward compatibility
    const char* currentVersion = versions[0];
    struct stat fileStats;
    FILE* bundleFile = fopen(bundlePath, "rb");
    if (!bundleFile) {
        perror("Error opening bundle file");
        return NULL;
    }
    if (fstat(fileno(bundleFile), &fileStats) == -1) {
        perror("Error getting file stats");
        fclose(bundleFile);
        return NULL;
    }
    rewind(bundleFile);
    char versionBuffer[10];
    if (fread(versionBuffer, sizeof(char), 9, bundleFile) != 9) {
        perror("Error reading bundle file version");
        fclose(bundleFile);
        return NULL;
    }
    versionBuffer[9] = '\0'; // Null-terminate the version string
    const char* fileVersion = versionBuffer;
    int versionIndex = -1;
    for (size_t i = 0; versions[i]; ++i) {
        if (!strcmp(fileVersion, versions[i])) {
            versionIndex = i;
            break;
        }
    }
    if (versionIndex == -1) { // Unsupported bundle version
        perror("Error: Unsupported bundle version");
        fclose(bundleFile);
        return NULL;
    }
    currentVersion = versions[versionIndex];

    size_t resourceOffset, resourceSize;
    if (fread(&resourceOffset, sizeof(size_t), 1, bundleFile) != 1 ||
        fread(&resourceSize, sizeof(size_t), 1, bundleFile) != 1) {
        perror("Error reading resource offset or size");
        fclose(bundleFile);
        return NULL;
    }
    char* buffer = malloc(resourceSize + 1); // Allocate extra byte for null termination
    if (!buffer) {
        perror("Memory allocation failure");
        fclose(bundleFile);
        return NULL;
    }
    if (fread(buffer, resourceSize, 1, bundleFile) != 1 ||
        fseek(bundleFile, resourceOffset + resourceSize, SEEK_SET) == -1) { // Seek past the current resource
        perror("Error reading resource data or seeking to next resource");
        free(buffer);
        fclose(bundleFile);
        return NULL;
    }
    buffer[resourceSize] = '\0';

    ResourceMetadata* metadata = malloc(sizeof(ResourceMetadata));
    if (!metadata) {
        perror("Memory allocation failure");
        free(buffer);
        fclose(bundleFile);
        return NULL;
    }
    metadata->path = bundlePath;
    metadata->size = resourceSize;

    // Type-specific data allocation and parsing
    switch (type) {
        case IMAGE: {
            // Handle image data parsing for specific image format here, such as PNG or JPEG
            break;
        }
        case TEXT_FILE: {
            metadata->data = malloc(resourceSize + 1); // Allocate extra byte for null termination
            if (!metadata->data) {
                perror("Memory allocation failure");
                free(buffer);
                free(metadata);
                fclose(bundleFile);
                return NULL;
            }
            strcpy((char*)metadata->data, buffer); // Copy text data into metadata's data field
            break;
        }
        case BINARY_DATA: {
            metadata->data = malloc(resourceSize);
            if (!metadata->data) {
                perror("Memory allocation failure");
                free(buffer);
                free(metadata);
                fclose(bundleFile);
                return NULL;
            }
            memcpy(metadata->data, buffer, resourceSize); // Copy binary data into metadata's data field
            break;
        }
    }

    pthread_mutex_lock(&mutex);
    rewind(bundleFile);
    while (fread(&resourceOffset, sizeof(size_t), 1, bundleFile) == 1 &&
           fread(&resourceSize, sizeof(size_t), 1, bundleFile) == 1) {
        char* nextBuffer = malloc(resourceSize + 1); // Allocate extra byte for null termination
        if (!nextBuffer) {
            perror("Memory allocation failure");
            free(buffer);
            free(metadata->data);
            pthread_mutex_unlock(&mutex);
            fclose(bundleFile);
            return NULL;
        }
        if (fread(nextBuffer, resourceSize, 1, bundleFile) != 1 ||
            fseek(bundleFile, resourceOffset + resourceSize, SEEK_SET) == -1) { // Seek past the current resource
            perror("Error reading next resource data or seeking to next resource");
            free(nextBuffer);
            free(buffer);
            free(metadata->data);
            pthread_mutex_unlock(&mutex);
            fclose(bundleFile);
            return NULL;
        }
        nextBuffer[resourceSize] = '\0';

        ResourceMetadata* nextMetadata = malloc(sizeof(ResourceMetadata));
        if (!nextMetadata) {
            perror("Memory allocation failure");
            free(buffer);
            free(nextBuffer);
            free(metadata->data);
            pthread_mutex_unlock(&mutex);
            fclose(bundleFile);
            return NULL;
        }
        nextMetadata->path = bundlePath;
        nextMetadata->size = resourceSize;

        switch (type) {
            case IMAGE: {
                // Handle image data parsing for specific image format here, such as PNG or JPEG
                break;
            }
            case TEXT_FILE: {
                nextMetadata->data = malloc(resourceSize + 1); // Allocate extra byte for null termination
                if (!nextMetadata->data) {
                    perror("Memory allocation failure");
                    free(buffer);
                    free(nextBuffer);
                    free(metadata->data);
                    pthread_mutex_unlock(&mutex);
                    fclose(bundleFile);
                    return NULL;
                }
                strcpy((char*)nextMetadata->data, nextBuffer); // Copy text data into metadata's data field
                break;
            }
            case BINARY_DATA: {
                nextMetadata->data = malloc(resourceSize);
                if (!nextMetadata->data) {
                    perror("Memory allocation failure");
                    free(buffer);
                    free(nextBuffer);
                    free(metadata->data);
                    pthread_mutex_unlock(&mutex);
                    fclose(bundleFile);
