    if (auto it = cache.find(offset); it != cache.end()) {
        // Found in cache, return the cached record.
        return it->second;
    }

    if (records[offset].key == 0) {
        // Key is not initialized, initialize it with a random value within a specified range to prevent overflow.
        records[offset].key = std::rand() % 100 + 1;
    }

    auto usedMem = static_cast<float>(queue.size()) + static_cast<float>(records.get()->size());
    auto freeMem = static_cast<float>(records.get()->size()) - usedMem;

    if (freeMem / static_cast<float>(records.get()->size()) < freeMemPercent / 100) {
        initMemory(records.get()->size() * 2); // Resize memory when more than 10% is unused.
    }

    if (queue.empty()) {
        queue.push_back(&records[offset]); // Add the record to the queue for potential reuse.
    } else if (queue.back()->key == 0) {
        std::swap(queue.back(), &records[offset]); // Replace an unused record with the one being accessed.
    }

    cache[offset] = &records[offset]; // Cache the record for future accesses.
    return &records[offset];
}

void processData() {
    std::vector<std::future<void>> futures;

    while (true) {
        int dataSize = getDataRequest(); // Get the incoming data size request.
        std::priority_queue<Record*, std::vector<Record*>, std::greater<Record*>> priorityQueue;

        for (long i = 0; i < dataSize; ++i) {
            Record* record = getRecord(i); // Get the record to process.
            priorityQueue.push(record);
        }

        while (!priorityQueue.empty()) {
            auto record = priorityQueue.top();
            priorityQueue.pop();

            processRecord(*record); // Process the record using an external data processing library.

            if (record->key == 0) { // Mark the record as processed and return it to the cache/queue.
                record->key = 1;

                if (!priorityQueue.empty()) {
                    queue.push(record);
                } else if (cache.find(record - records.get()) == cache.end()) {
                    cache[record - records.get()] = record;
                }
            }
        }

        futures.clear(); // Reset the future vector before processing a new batch of data.
    }
}

