**C++ Function (Processing a Forward List)**
```cpp
#include <list>
#include <mutex>
#include <thread>
#include <chrono>

std::list<std::string>& processList(std::list<std::string>& list, const std::string& searchStr, const std::string& insertStr) {
    std::mutex mtx;
    auto it = list.begin();
    if (it == list.end()) return list;

    std::unique_lock<std::mutex> lock(mtx);
    while (it != list.end() && (*it) != searchStr) {
        it++;
        lock.unlock();
        std::this_thread::yield();
        lock.lock();
    }

    if (it == list.end()) {
        list.push_back(insertStr);
        return list;
    }

    list.insert(++it, insertStr);
    return list;
}
