} Record;

struct MemPool {
    size_t capacity;
    size_t used;
    Record *data;
    pthread_mutex_t lock;
};

void checksum(Record *, size_t);
void log_event(const char*, ...);
void export_records(Record*, size_t, const char*);

struct MemPool* mem_pool_init(size_t cap) {
    struct MemPool *pool = malloc(sizeof(struct MemPool));
    pool->capacity = cap;
    pool->used = 0;
    pool->data = calloc(cap, sizeof(Record));
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    return pool;
}

Record* mem_pool_get(struct MemPool*) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used < pool->capacity) {
        ++pool->used;
        Record *record = &pool->data[pool->used - 1];
        record->offset = time(NULL);
        record->key = rand() % RAND_MAX;
        pthread_mutex_unlock(&pool->lock);
        return record;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void mem_pool_free(struct MemPool*, Record*) {
    pthread_mutex_lock(&pool->lock);
    pool->used--;
    pthread_mutex_unlock(&pool->lock);
}

