```cpp
#include <boost/noncopyable.hpp>
#include <cstdlib> // rand(), srand()
#include <memory>
#include <vector>

class RecordManager : boost::noncopyable {
public:
    explicit RecordManager(size_t numRecords, size_t chunkSize)
        : mChunks(), mMetaCache(), mNumChunks(numRecords / chunkSize + 1), srand(time(0)) {}

    ~RecordManager() {
        // Tear down resources here (e.g., closing connections or freeing memory)
    }

    Record& getRandomRecord() {
        auto it = mMetaCache.find(mNextIndex);
        if (it != mMetaCache.end()) {
            Record& record = *it->second;
            // Increment the index for the next time to avoid picking the same record again
            ++mNextIndex %= mNumChunks;
            return record;
        }

        auto chunkIt = std::find_if(std::begin(mChunks), std::end(mChunks), [this](const auto& c) {
            return c->size() < static_cast<int>(c->capacity() / 2);
        });

        if (chunkIt == mChunks.end()) {
            // Extend a chunk if all are full
            mChunks.emplace_back();
            chunkIt = std::prev(mChunks.end());
        }

        Record& record = (*chunkIt)->at(mNextIndex);
        record.offset = static_cast<long>(*chunkIt - std::begin(mChunks[0]));
        record.key = rand() % kMaxKeyValue;

        ++mNextIndex %= mNumChunks;

        // Add to the metadata cache and update the chunk size
        auto metadataPtr = &(*chunkIt)->front();
        mMetaCache[metadataPtr] = record;
        (*chunkIt)->erase(metadataPtr);

        return record;
    }

private:
    struct Chunk {
        std::vector<Record> records;
        int capacity;

        Chunk() : records(), capacity(0) {}
    };

    // A cache for previously computed metadata pointers (to reduce lookups and promote performance)
    std::unordered_map<const Record*, size_t> mMetaCache;
    std::vector<std::unique_ptr<Chunk>> mChunks;
    int mNumChunks;
    int mNextIndex;

    static constexpr int kMaxKeyValue = /*your desired max key value here*/;
};
```

