Record* create_records(size_t num_elements, size_t* offsets, int* keys, size_t* total_size) {
    if (num_elements > 1000000 || *total_size > 2000000) {
        fprintf(stderr, "Input parameters exceed the specified limits.\n");
        return NULL;
    }

    Record* records = malloc(num_elements * sizeof(Record));
    if (!records) {
        perror("Memory allocation for records failed.");
        return NULL;
    }

    HashTable ht = create_hash_table(num_elements);
    if (!ht.keys || !ht.data) {
        free(records);
        perror("Memory allocation for hash table failed.");
        return NULL;
    }

    populate_hash_table(&ht, offsets, keys, num_elements);

    for (size_t i = 0; i < num_elements; ++i) {
        int key = ht.keys[i];
        long offset = *offsets++;
        bool found = false;

        // Use a linked list to store records with the same key
        Record* current = (Record*)ht.data[key];
        if (!current) {
            current = malloc(sizeof(Record));
            if (!current) {
                perror("Memory allocation for record failed.");
                goto cleanup;
            }
            ht.data[key] = current;
            current->offset = offset;
            current->key = key;
        } else {
            Record* prev = current;
            while (current && current->key == key) {
                prev = current;
                current = current->next;
            }

            current = malloc(sizeof(Record));
            if (!current) {
                perror("Memory allocation for record failed.");
                goto cleanup;
            }
            prev->next = current;
            current->offset = offset;
            current->key = key;
        }

        records[i] = *current;
    }

cleanup:
    free(ht.keys);
    for (int i = 0; i < ht.size; ++i) {
        Record* record = (Record*)ht.data[i];
        while (record) {
            Record* temp = record;
            record = record->next;
            free(temp);
        }
    }
    free(ht.data);

    *total_size -= num_elements * sizeof(Record);
    return records;
}

