             metadata->resolution, (metadata->color_space == RGB) ? "RGB" : "CMYK", metadata->orientation, metadata->quality_level);
    if (*metadata->icc_profile) {
        strcat(report, "ICC Profile: ");
        strncat(report, metadata->icc_profile, sizeof(metadata->icc_profile));
