```cpp
#include <iostream>
#include <unordered_map>
#include <list>
#include <pthread.h>

struct Value {
    double value;
};

class DataStructure {
private:
    std::unordered_map<int, std::list<Value>::iterator> keys; // Store the iterators for fast key lookup
    std::list<Value> values; // The sorted list of values
    pthread_mutex_t mutex; // Mutex to control concurrent access

public:
    DataStructure() {
        pthread_mutex_init(&mutex, NULL);
    }

    ~DataStructure() {
        pthread_mutex_destroy(&mutex);
    }

    void insert(int key, double value) {
        pthread_mutex_lock(&mutex);

        auto it = keys.find(key);
        if (it == keys.end()) { // Key not found, add at the end of the list
            values.push_back({value});
            keys[key] = --values.end();
        } else {
            it->second->value = value; // Update existing value
        }

        std::list<Value>::iterator iter = values.begin();
        std::advance(iter, key); // Iterate to the correct position based on the key's index

        while (++iter != values.end() && iter->value >= (*it)->value) {
            it = iter; // Move 'it' if necessary
        }

        if (iter != values.end()) { // If there are other values after 'it', move them after the new value
            values.insert(iter, *it);
            ++it;
        }

        pthread_mutex_unlock(&mutex);
    }

    void getValues(int key, std::list<Value>& result) const {
        auto it = keys.find(key);
        if (it != keys.end()) {
            result = *it->second;
        }
    }

    void iterate(std::function<void(const Value&)> callback) const {
        pthread_mutex_lock(&mutex);
        auto it = values.begin();
        while (it != values.end()) {
            callback(*it);
            ++it;
        }
        pthread_mutex_unlock(&mutex);
    }
};
