```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

typedef struct GAL {
    Record *data;
    size_t capacity;
    size_t size;
} GAL;

GAL gal_init(size_t initial_capacity) {
    GAL gal;
    gal.data = malloc(initial_capacity * sizeof(Record));
    if (!gal.data) {
        fprintf(stderr, "Error: Failed to allocate memory for GAL.\n");
        exit(EXIT_FAILURE);
    }
    gal.capacity = initial_capacity;
    gal.size = 0;
    return gal;
}

void gal_resize(GAL *gal) {
    if (gal->capacity == gal->size) {
        gal->capacity *= 2;
        gal->data = realloc(gal->data, gal->capacity * sizeof(Record));
        if (!gal->data) {
            fprintf(stderr, "Error: Failed to resize GAL.\n");
            exit(EXIT_FAILURE);
        }
    }
}

void record_init(Record *record, long offset, int key) {
    record->offset = offset;
    record->key = key;
    record->value = rand() % 100 + 50; // Random number within [50, 149] range
}

void gal_push(GAL *gal, Record r) {
    gal_resize(gal);
    gal->data[gal->size] = r;
    gal->size++;
}

