struct Value {
    double value;
    Value(double v) : value(v) {}
};

class SortedMap {
private:
    std::vector<Node*> nodes; // Array of node pointers (or linked list with next pointer, as per your choice)
    ILogging* _log;

public:
    SortedMap(ILogging* log) : _log(log) {}

    void insert(int key, double value) {
        int index = std::lower_bound(nodes.begin(), nodes.end(), Node{key, _log},
            [](const Node& lhs, const Node& rhs) { return lhs.key < rhs.key; }) - nodes.begin();

        if (index == nodes.size() || nodes[index]->key != key) {
            nodes.insert(nodes.begin() + index, new Node{key, _log});
        }

        nodes[index]->values.emplace_back(value);
        std::sort(nodes[index]->values.begin(), nodes[index]->values.end());

        _log->log(std::string("Inserted key: ") + std::to_string(key) + ", value: " + std::to_string(value));
    }

    void getValues(int key, std::vector<double>& values) const {
        for (const auto& node : nodes) {
            if (node->key == key) {
                values = node->values;
                break;
            }
        }

        _log->log(std::string("Retrieved key: ") + std::to_string(key));
    }
};
