#include <sys/mman.h> // For posix_memalign()

typedef struct Node {
    int key;
    double value;
    struct Node *prev, *next;
} Node;

typedef struct DataStructure {
    size_t count;
    pthread_mutex_t lock;
    Node *head, *tail;
    // Serialize/deserialize functions here
} DataStructure;

DataStructure* create_data_structure() {
    DataStructure *ds = malloc(sizeof(DataStructure));
    pthread_mutex_init(&ds->lock, NULL);
    ds->count = 0;
    ds->head = NULL;
    ds->tail = NULL;
    // Other initialization here
}

void destroy_data_structure(DataStructure *ds) {
    // Cleanup and free nodes here
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

Node* new_node(int key, double value) {
    Node *n = malloc(sizeof(Node));
    n->key = key;
    n->value = value;
    n->prev = NULL;
    n->next = NULL;
    return n;
}

void insert_node(DataStructure *ds, Node *n) {
    pthread_mutex_lock(&ds->lock);

    if (ds->head == NULL) {
        ds->head = n;
        ds->tail = n;
    } else {
        if (n->key < ds->head->key) {
            n->next = ds->head;
            ds->head->prev = n;
            ds->head = n;
        } else if (n->key > ds->tail->key) {
            ds->tail->next = n;
            n->prev = ds->tail;
            ds->tail = n;
        } else {
            Node *cur = ds->head;
            while (cur != NULL && cur->key < n->key) {
                cur = cur->next;
            }
            n->next = cur;
            n->prev = cur->prev;
            if (n->prev != NULL) {
                n->prev->next = n;
            } else {
                ds->head = n;
            }
            cur->prev = n;
        }
    }

    ds->count++;
    pthread_mutex_unlock(&ds->lock);
}

double get_value(DataStructure *ds, int key) {
    pthread_mutex_lock(&ds->lock);
    Node *cur = ds->head;
    while (cur != NULL && cur->key < key) {
        cur = cur->next;
    }
    if (cur == NULL || cur->key != key) {
        pthread_mutex_unlock(&ds->lock);
        return -1.0;
    }
    double value = cur->value;
    pthread_mutex_unlock(&ds->lock);
    return value;
}
```

