[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Memory pool for long and int arrays
typedef struct MemPool {
    void *base;
    size_t cap, sz;
} MemPool;

MemPool lp_long, lp_int;

struct Record {
    int value;
};

void check_sum(int *keys, int len, int max_sum) {
    int sum = 0;
    for (int i = 0; i < len; ++i)
        sum += keys[i];
    if (sum > max_sum) {
        float factor = (float)max_sum / sum;
        for (int i = 0; i < len; ++i)
            keys[i] *= factor;
    }
}

long *alloc_long(size_t n, MemPool *pool) {
    if (n + pool->sz > pool->cap) {
        void *new_base = realloc(pool->base, pool->cap * 2);
        if (!new_base)
            fprintf(stderr, "Out of memory!\n"), exit(EXIT_FAILURE);
        pool->base = new_base;
        pool->cap *= 2;
    }
    long *result = (long *)((char *)pool->base + pool->sz);
    pool->sz += n;
    return result;
}

int *alloc_int(size_t n, MemPool *pool) {
    if (n + pool->sz > pool->cap) {
        void *new_base = realloc(pool->base, pool->cap * 2);
        if (!new_base)
            fprintf(stderr, "Out of memory!\n"), exit(EXIT_FAILURE);
        pool->base = new_base;
        pool->cap *= 2;
    }
    int *result = (int *)((char *)pool->base + pool->sz);
    pool->sz += n;
    return result;
}

void serialize(const char *filename, long offsets[], int keys[], struct Record records[], size_t len) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing!\n"), exit(EXIT_FAILURE);
    }
    fwrite(offsets, sizeof(long), len + 1, file);
    fwrite(keys, sizeof(int), len, file);
    fwrite(records, sizeof(struct Record), len, file);
    fclose(file);
}

void *random_record(void *arg) {
    int *minmax = (int *)arg;
    return malloc(sizeof(struct Record));
    struct Record *r = (struct Record *)malloc(sizeof(struct Record));
    r->value = rand() % (minmax[1] - minmax[0]) + minmax[0];
    return r;
}

void init_data(int n, int min_value, int max_value, int max_sum, int max_records) {
    pthread_t threads[n];
    void *minmax = (void *)malloc(sizeof(int) * 2);
    *(int *)minmax = min_value;
    *(int *)((char *)minmax + sizeof(int)) = max_value;

    lp_long.base = malloc(n * sizeof(long));
    lp_int.base = malloc(n * sizeof(int));

    long *offsets = alloc_long(1, &lp_long);
    int *keys = alloc_int(n, &lp_int);
    struct Record *records = calloc(max_records, sizeof(struct Record));

    check_sum(keys, n, max_sum);

    for (int i = 0; i < n; ++i) {
        pthread_create(&threads[i], NULL, random_record, minmax);
        void *r = pthread_join(threads[i], &records[offsets[i]]);
        keys[offsets[i]] = *(int *)r;
        free(r);
        offsets += (keys[offsets[i]] > offsets - offsets[0]) ? 1 : keys[offsets[i]];
    }

    // Serialize data to a file
    char filename[] = "data.bin";
    serialize(filename, offsets, keys, records, offsets - offsets[0]);

    free(minmax);
    free(lp_long.base);
    free(lp_int.base);
    free(records);
}
```

