```java
class Record {
    long offset;
    int key;

    // constructor, getters, and setters
}

Random random = new Random();

public void initializeRecords(int size) throws IOException {
    Record[] records = new Record[size];
    ExecutorService executor = Executors.newFixedThreadPool(Math.min(Runtime.getRuntime().availableProcessors(), 10));

    List<Future<Record>> futures = executor.invokeAll(() -> {
        Record record = new Record();
        record.key = random.nextInt((int) Long.MAX_VALUE); // use an appropriate range to prevent overflow
        return Future.completedFuture(record);
    }, size);

    for (int i = 0; i < records.length; i++) {
        Record record = futures.get(i).get();
        records[i] = record;
    }
}
```

