typedef struct hash_entry {
    record rec;
    struct hash_entry* next;
} hash_entry;

const int MAX_RECORDS = 10000;
const int KEY_RANGE = 1000;

hash_entry** table;
pthread_mutex_t mutex;

void init() {
    table = malloc(sizeof(hash_entry*) * (KEY_RANGE + 1));
    pthread_mutex_init(&mutex, NULL);
}

int hash(int key) {
    return key % KEY_RANGE;
}

bool insert(record r) {
    pthread_mutex_lock(&mutex);
    int h = hash(r.key);
    if (!table[h]) table[h] = malloc(sizeof(hash_entry));
    hash_entry* head = table[h];
    while (head->next) head = head->next;
    head->next = malloc(sizeof(hash_entry));
    head = head->next;
    head->rec = r;
    head->next = NULL;
    pthread_mutex_unlock(&mutex);
    return true;
}

record* find(int key) {
    pthread_mutex_lock(&mutex);
    int h = hash(key);
    if (!table[h]) return NULL;
    hash_entry* head = table[h];
    while (head) {
        if (head->rec.key == key) break;
        head = head->next;
    }
    pthread_mutex_unlock(&mutex);
    return &head->rec;
}

