import json
import requests
from angularjs import $scope, $window, $http

def config_manager(config_id, base_url, fields_to_refresh, insert_after_id=None):
    config_list = JSON.parse($scope.configs)
    sorted_configs = sorted(config_list, key=lambda x: x['key'])

    def connection_handler():
        try:
            sess = requests.Session()
            sess.headers.update({'Content-Type': 'application/json'})
            response = sess.get(f"{base_url}/connect")
            response.raise_for_status()
            return sess
        except Exception as e:
            console.log("Error connecting:", e)
            return None

    def send_message(sess, message):
        try:
            response = sess.post(f"{base_url}/message", json=json.dumps(message))
            response.raise_for_status()
            return response.json()
        except Exception as e:
            console.log("Error sending message:", e)
            return None

    def receive_message(sess):
        try:
            response = sess.get(f"{base_url}/message")
            response.raise_for_status()
            return response.json()
        except Exception as e:
            console.log("Error receiving message:", e)
            return None

    def update_config_list(sess, config_id, insert_after_id=None):
        if insert_after_id:
            index = next((i for i, config in enumerate(sorted_configs) if config['id'] == insert_after_id), len(sorted_configs))
            sorted_configs.insert(index, { 'id': config_id, 'key': '', 'value': '' })
        else:
            sorted_configs.append({ 'id': config_id, 'key': '', 'value': '' })

    def handle_connection_state(sess):
        while True:
            message = receive_message(sess)
            if not message:
                continue

            if message['type'] == 'connected':
                $scope.$apply()
                return
            elif message['type'] == 'disconnected':
                console.log("Disconnected from service")

    sess = connection_handler()
    if not sess:
        return

    version_number = None
    for config in sorted_configs:
        if 'version' in config['key']:
            version_number = config['value']
            break

    if not version_number:
        console.log("No version number found")
        return

    for field in fields_to_refresh:
        for i, config in enumerate(sorted_configs):
            if config['key'] == field:
                message = {'type': 'refresh', 'field': field}
                result = send_message(sess, message)
                if result and result['success']:
                    config['value'] = result['data']
                    $scope.$apply()

    update_config_list(sess, config_id, insert_after_id)

    handle_connection_state(sess)
