    private String fallbackData;

    public AuthHelper(ConcurrentMap<String, AccessToken> accessTokens, long sessionTimeoutMs, URI identityProviderUri, String fallbackData) {
        this.accessTokens = accessTokens;
        this.sessionTimeoutMs = sessionTimeoutMs;
        this.identityProviderUri = identityProviderUri;
        this.fallbackData = fallbackData;
    }

    public String authenticate(String userName, String password) {
        long startTime = System.currentTimeMillis();
        int retries = 3;

        while (retries > 0 && !isSessionExpired()) {
            try {
                Response response = makeAuthRequest(userName, password);
                if (!response.isSuccessful()) {
                    retries--;
                } else {
                    AccessToken accessToken = parseAccessTokenResponse(response);
                    storeAccessToken(accessToken);
                    return accessToken.getAccessToken();
                }
            } catch (Exception e) {
                if (retries == 0 || shouldRetryNow(e)) {
                    throw e;
                }
                retries--;
            }
        }

        // Fallback mechanism when identity provider service is unavailable
        return calculateMD5(fallbackData);
    }

    private Response makeAuthRequest(String userName, String password) throws Exception {
        Request request = new Request.Builder()
                .url(identityProviderUri.resolve("/oauth2/token"))
                .post(new FormBody.Builder()
                        .add("grant_type", "password")
                        .add("username", userName)
                        .add("password", password)
                        .build())
                .build();

        return httpClient.newCall(request).execute();
    }

    private AccessToken parseAccessTokenResponse(Response response) {
        // Implement parsing the access token from the OAuth2 response
    }

    private void storeAccessToken(AccessToken accessToken) {
        accessTokens.putIfAbsent(accessToken.getUserId(), accessToken);
    }

    private boolean isSessionExpired() {
        long currentTime = System.currentTimeMillis();
        return (currentTime - getAccessTokenLastRefreshTime()) > sessionTimeoutMs;
    }

    private long getAccessTokenLastRefreshTime() {
        // Implement getting the last refresh time of the access token
    }

    private void loadUserProfileImage(String userId) {
        try {
            IMAGE_SEMAPHORE.acquire();
            loadAndCacheImage(userId);
            IMAGE_SEMAPHORE.release();
        } catch (Exception e) {
            // Handle exceptions and log the issue
        }
    }

    private void loadAndCacheImage(String userId) {
        // Implement loading and caching user profile images
    }

    private String calculateMD5(String input) {
        if (input == null || input.isEmpty()) {
            return "";
        }

        try {
            MessageDigest messageDigest = MessageDigest.getInstance("MD5");
            messageDigest.update(input.getBytes());
            byte[] digest = messageDigest.digest();

            StringBuilder result = new StringBuilder();
            for (byte b : digest) {
                result.append(String.format("%02x", b));
            }

            return result.toString();
        } catch (Exception e) {
            // Handle exceptions and log the issue
        }

        return "";
    }
}
