// Custom memory management system, supports logging and resetting
typedef struct _mem_block {
    void* data;
    size_t size;
    struct _mem_block* next;
} MemBlock;

sem_t mutex; // Thread-safe lock for accessing shared memory region

// Initialize custom memory management system
void mem_init() {
    sem_init(&mutex, 0, 1);
}

// Allocate memory and log the allocation
MemBlock* mem_alloc(size_t size) {
    MemBlock* block = malloc(sizeof(MemBlock));
    if (!block) {
        // Handle out-of-memory condition gracefully
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    block->data = malloc(size);
    if (!block->data) {
        free(block);
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    block->size = size;
    block->next = NULL;
    sem_post(&mutex); // Release the lock
    return block;
}

// Free memory and log the deallocation
void mem_free(MemBlock* block) {
    if (!block) return;

    free(block->data);
    free(block);
}

// Record number of allocations, deallocations, and errors
int allocations = 0;
int deallocations = 0;
int errors = 0;

typedef struct record {
    int key;
    int value;
    bool valid; // Flag to check data integrity
} Record;

Record* create_record(int key) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        errors++;
        return NULL;
    }
    record->key = key;
    record->value = 0;
    record->valid = true;
    return record;
}

void init_records(MemBlock** records, int size) {
    sem_wait(&mutex); // Lock the shared memory region

    for (int i = 0; i < size; ++i) {
        records[i] = create_record(i);
        if (!records[i]) break; // Exit early if error occurred
    }

    sem_post(&mutex); // Unlock the shared memory region
}

bool validate_record(Record* record) {
    return record && record->key >= 0 && record->value >= 0 && record->valid;
}

void log_stats() {
    printf("Allocations: %d\n", allocations);
    printf("Deallocations: %d\n", deallocations);
    printf("Errors: %d\n", errors);
}

// Function to dynamically allocate memory for and initialize an array of record structures
Record* allocate_records(int max_size) {
    if (max_size <= 0) return NULL;

    MemBlock** records = malloc(sizeof(MemBlock*) * (max_size + 1));
    if (!records) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    int size = 0;
    sem_wait(&mutex); // Lock the shared memory region

    for (int i = 0; i < max_size + 1; ++i) {
        records[i] = NULL;
    }

    sem_post(&mutex); // Unlock the shared memory region

    mem_alloc(sizeof(MemBlock) * (max_size + 1)); // Pre-allocate space for the total number of records
    init_records(records, max_size);

    return records;
}

void deallocate_records(Record* records, int size) {
    if (!records || !size) return;

    sem_wait(&mutex); // Lock the shared memory region

    for (int i = 0; i < size; ++i) {
        Record* record = records[i];
        if (record) mem_free(record);
    }

    free(records);

    sem_post(&mutex); // Unlock the shared memory region
}

void reset_state() {
    while (allocations > 0) deallocate_records(NULL, 0);
    mem_init();
}
