    private int _maxConcurrency;

    public ServiceConfigLoader(int maxConcurrency)
    {
        _maxConcurrency = maxConcurrency;
        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        var configJson = File.ReadAllText("config.json");
        try
        {
            _config = JsonConvert.DeserializeObject<Dictionary<string, Dictionary<string, object>>>(configJson)
                .Where(e => e.Value.Keys.Contains("endpoint") && e.Value.Keys.Contains("token") && e.Value.Keys.Contains("timeout") && e.Value.Keys.Contains("retryLimit") && e.Value.Keys.Contains("backoffFactor"))
                .ToDictionary(e => e.Key, e => e.Value);
        }
        catch (Exception ex)
        {
            Log.Warn($"Failed to load configuration file: {ex}");
        }
    }

    public async Task<IDictionary<string, Dictionary<string, object>>> GetEndpointsAsync()
    {
        var endpoints = new ConcurrentDictionary<string, Dictionary<string, object>>();
        var semaphore = new SemaphoreSlim(_maxConcurrency);

        Parallel.ForEach(_config, async entry =>
        {
            await semaphore.WaitAsync();
            try
            {
                ValidateConfig(entry.Value);
                var endpoint = entry.Key;
                var config = entry.Value;

                using (var httpClient = new HttpClient())
                {
                    httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {config["token"]}");
                    var timeout = TimeSpan.FromMilliseconds(double.Parse(config["timeout"]));
                    using (var response = await httpClient.GetAsync(entry.Key, HttpCompletionOption.ResponseHeadersRead, timeout))
                    {
                        endpoints[endpoint] = config;
                    }
                }
            }
            catch (Exception ex)
            {
                Log.Warn($"Error processing endpoint '{endpoint}': {ex}");
            }
            finally
            {
                semaphore.Release();
            }
        });

        return endpoints;
    }

    private void ValidateConfig(Dictionary<string, object> config)
    {
        if (!config.ContainsKey("endpoint") || !config.ContainsKey("token") || !config.ContainsKey("timeout") || !config.ContainsKey("retryLimit") || !config.ContainsKey("backoffFactor"))
            throw new ArgumentException("Invalid configuration format.");

        if (!long.TryParse(config["retryLimit"], out _) || int.TryParse(config["backoffFactor"], out _))
            throw new ArgumentException("Incorrect data type for retryLimit or backoffFactor.");
    }
}
```

This code assumes that the configuration file is named "config.json" and located in the same directory as the solution. The JSON structure should follow this format:

```json
[
  {
    "endpoint": "<api_url>",
    "token": "<auth_token>",
    "timeout": <milliseconds>,
    "retryLimit": <integer>,
    "backoffFactor": <integer>
  },
  ...
]
```']

