['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>
#include <tbb/tbb.h>

typedef struct Node {
    char *key;
    double value;
    struct Node* next;
    pthread_mutex_t mutex;
} Node;

typedef struct Map {
    int size;
    Node **nodes;
    tbb::spin_rw_lock lock;
} Map;

Map *create_map(int capacity) {
    Map *map = malloc(sizeof(Map));
    map->size = 0;
    map->nodes = calloc((capacity + 1), sizeof(Node*));
    for (int i = 0; i <= capacity; ++i) {
        map->nodes[i] = NULL;
    }
    tbb::spin_rw_lock::initialize_static(&map->lock, false);
    return map;
}

Node *create_node(char *key, double value) {
    Node *new_node = malloc(sizeof(Node));
    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);
    return new_node;
}

void add_node(Map *map, Node *node) {
    tbb::spin_rw_lock::scoped_lock lock(map->lock);
    int index = hash(node->key, map->size);
    node->next = map->nodes[index];
    map->nodes[index] = node;
}

double get_value(Map *map, char *key) {
    tbb::spin_rw_lock::scoped_lock lock(map->lock);
    int index = hash(key, map->size);
    Node *current = map->nodes[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_lock(&current->mutex);
            double value = current->value;
            pthread_mutex_unlock(&current->mutex);
            return value;
        }
        current = current->next;
    }
    return -1.0;
}

void update_value(Map *map, char *key, double new_value) {
    tbb::spin_rw_lock::scoped_lock lock(map->lock);
    int index = hash(key, map->size);
    Node *current = map->nodes[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_lock(&current->mutex);
            current->value = new_value;
            pthread_mutex_unlock(&current->mutex);
            break;
        }
        current = current->next;
    }
}

void print_nodes(Map *map) {
    tbb::spin_rw_lock::scoped_lock lock(map->lock);
    for (int i = 0; i <= map->size; ++i) {
        Node *current = map->nodes[i];
        while (current != NULL) {
            printf("Key: %s, Value: %.2f\n", current->key, current->value);
            current = current->next;
        }
    }
}

int hash(char *str, int capacity) {
    unsigned long hash = 5381;
    int len = strlen(str);
    for (int i = 0; i < len; ++i) {
        hash += (hash << 5) + hash + str[i];
    }
    return hash % capacity;
}
```

This implementation uses a hash table to store the nodes, where each key is hashed into an index within the table. The nodes are dynamically allocated and linked together in a list to allow efficient traversal of the data. Each node also contains a mutex to ensure thread safety when accessing or modifying its contents.

The `create_map` function initializes the map with a given capacity, while `create_node` creates new nodes containing a key and value. The `add_node`, `get_value`, and `update_value` functions allow for adding, retrieving, and updating nodes in the map, respectively.

To handle large-scale datasets efficiently, the design minimizes memory overhead by using dynamic allocation only when necessary and utilizing a spin lock for concurrent access to improve performance. Additionally, the implementation leverages TBB's `spin_rw_lock` class to ensure thread safety without introducing significant overhead.

The solution scales well with increased load, as it uses a hash table that distributes nodes evenly across indices and allows for efficient traversal using a linked list. However, one trade-off made in this design is the potential increase in complexity compared to other data structures like red-black trees or hash maps. This might affect maintainability and ease of integration with other systems. To mitigate these concerns, it's essential to follow good coding practices such as thorough documentation and modularization of functions.']

