typedef struct {
    char identifier[32];
    double measurement;
    unsigned long timestamp;
} Record;

Record* create_records(size_t num_records, bool sequential_timestamps, double min_measurement, double max_measurement) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));
    size_t unique_identifiers[num_records] = {};
    unsigned long current_timestamp = 0;

    for (size_t i = 0; i < num_records; ++i) {
        bool duplicate_identifier = false;

        do {
            snprintf(records[i].identifier, sizeof(records[i].identifier), "%c%lu", 'A' + rand() % 26, rand());
            for (size_t j = 0; j < i; ++j) {
                if (!strcasecmp(records[i].identifier, records[j].identifier)) {
                    duplicate_identifier = true;
                    break;
                }
            }
        } while (duplicate_identifier);

        if (sequential_timestamps) {
            current_timestamp++;
        } else {
            current_timestamp += rand() % 100 + 1; // Generate a random interval within [1, 100] milliseconds
            current_timestamp = current_timestamp < records[i - 1].timestamp ? current_timestamp : current_timestamp;
        }
        records[i].timestamp = current_timestamp;
        records[i].measurement = min_measurement + rand() / (RAND_MAX / (max_measurement - min_measurement));
    }

    return records;
}

void free_records(Record *records, size_t num_records) {
    if (!records) return;
    free(records);
}

void sort_and_print_records(const Record *records, size_t num_records) {
    qsort(records, num_records, sizeof(Record), compare_timestamps);

    for (size_t i = 0; i < num_records; ++i) {
        printf("%s: measurement=%.2f, timestamp=%lu\n", records[i].identifier, records[i].measurement, records[i].timestamp);
    }
}

int compare_timestamps(const void *a, const void *b) {
    return (*(const Record *)a)->timestamp - *(const Record *)b)->timestamp;
}
```
