const axios = require('axios');
const lodash = require('lodash');
const cliProgress = require('cli-progress');
const { v4: uuidv4 } = require('uuid');

// Constants and configurations
const MAX_CONCURRENCY = 50;
const REQUEST_TIMEOUT = 10000; // in milliseconds
const MIN_BATCH_SIZE = 100;
const LOGGER = console.log;
const LOGGING_DETAILS = { level: 'info' };

// Custom error handling
function handleError(error) {
  if (error.response) {
    // Request made and server responded
    LOGGER.error(`Error request: ${error.response.status} - ${error.response.statusText}`);
  } else if (error.request) {
    // The request was made but no response was received
    LOGGER.error('No Response Received');
  } else {
    // Something happened in setting up the request and it didn't happen
    LOGGER.error(`Error: ${error.message}`);
  }
}

// Memory management data structures
const longOffsetMap = new Map();
const intKeyMap = new Map();

// Generate random 'int' value within a specified range
function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Process a single record and send it to the external service
async function processRecord(record) {
  const requestOptions = {
    url: 'YOUR_EXTERNAL_SERVICE_URL',
    method: 'POST',
    data: record,
    timeout: REQUEST_TIMEOUT,
  };

  try {
    await axios.request(requestOptions);
    LOGGER.debug(`Record processed successfully: ${record}`);
  } catch (error) {
    handleError(error);
  }
}

// Batch records and send them to the external service
async function batchRecords(records) {
  let currentBatchSize = MIN_BATCH_SIZE;
  let batchedRecords = [];

  for (const record of records) {
    batchedRecords.push(record);

    if (batchedRecords.length === currentBatchSize || records.length === 1) {
      await processBatch(batchedRecords);

      // Adjust batch size based on system load and available resources
      currentBatchSize = Math.min(Math.max(currentBatchSize * 2, MIN_BATCH_SIZE), records.length / 3);
      batchedRecords = [];
    }
  }

  if (batchedRecords.length > 0) {
    await processBatch(batchedRecords);
  }
}

// Process a batch of records and send them to the external service
async function processBatch(records) {
  const promises = records.map((record) => processRecord(record));

  try {
    const results = await Promise.allSettled(promises);
    LOGGER.debug(`Processed batch: ${results.length}`);
  } catch (error) {
    handleError(error);
  }
}

// Main function to upload files from multiple URLs concurrently
async function uploadFiles(urls, logDetails = {}) {
  Object.assign(LOGGING_DETAILS, logDetails);
  const bar = new cliProgress.SingleBar({}, cliProgress.Presets.shades_classic);

  // Track progress and handle errors
  let completedCount = 0;
  const totalUrls = urls.length;
  bar.start(totalUrls, 0);

  const fetchedUrlData = [];

  for (const url of urls) {
    try {
      const response = await axios.get(url, { responseType: 'arraybuffer' });
      // Process and send each record to the external service
      const records = Array.from({ length: response.data.length }, () => getRandomInt(100, 999));
      await batchRecords(records);

      fetchedUrlData.push({ url, data: response.data });
      completedCount++;
      bar.update(completedCount);
    } catch (error) {
      handleError(error);
    }
  }

  // Log final progress and cleanup
  bar.stop();
  LOGGER.info(`Completed uploading files: ${completedCount} out of ${totalUrls}`);
  LOGGER.info(`Fetched data from ${fetchedUrlData.length} URL(s)`);
}
```"]

