#define MAX_ENTRIES 10000
#define MIN_DOUBLE 0.0
#define MAX_DOUBLE 100.0
#define EXT_ARRAY_SIZE 5
#define MEM_POOL_SIZE (1024 * 1024) // 1MB memory pool for small data

typedef struct {
    double value;
    char ext[16];
    size_t index;
} data_entry;

// External metadata storage structure and interface (abstracted)
typedef struct ext_meta {
    char *data;
    size_t len;
} ext_meta;

ext_meta *fetch_metadata(const char *ext);

// Custom memory pool for small data
void *mem_pool, *free_list = NULL;

pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;

data_entry* create_data_entry(double value, const char *ext) {
    data_entry *entry = malloc(sizeof(data_entry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(1);
    }

    entry->value = value;
    strcpy(entry->ext, ext);
    entry->index = 0; // Not applicable here, use as appropriate for your data structure

    return entry;
}

void init_mem_pool() {
    if (mem_pool) return;

    pthread_mutex_lock(&mem_lock);
    void *chunk;

    while ((chunk = mmap(NULL, MEM_POOL_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0)) == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }

    free_list = chunk;
    mem_pool = free_list + MEM_POOL_SIZE;
    pthread_mutex_unlock(&mem_lock);
}

void* get_memory(size_t size) {
    void *data;
    pthread_mutex_lock(&mem_lock);

    if (free_list) {
        data = free_list;
        free_list = ((char *)free_list) + size;
    } else {
        data = malloc(size);
        if (!data) {
            perror("malloc");
            exit(1);
        }
    }

    pthread_mutex_unlock(&mem_lock);
    return data;
}

void free_memory(void *ptr, size_t size) {
    if (ptr == mem_pool || ((char *)ptr < mem_pool && (char *)free_list > ((char *)ptr + size))) {
        fprintf(stderr, "Memory pool overflow\n");
        exit(1);
    }

    pthread_mutex_lock(&mem_lock);
    free(ptr);
    pthread_mutex_unlock(&mem_lock);
}

data_entry** create_data_array(size_t size) {
    data_entry **arr = get_memory(sizeof(data_entry *) * size);
    for (size_t i = 0; i < size; ++i) {
        arr[i] = create_data_entry(rand() * ((MAX_DOUBLE - MIN_DOUBLE) / RAND_MAX) + MIN_DOUBLE, EXT_ARRAY[i % EXT_ARRAY_SIZE]);
    }

    // Fetch additional metadata and store it with the data entries (assuming ext_meta has been populated via fetch_metadata())
    for (size_t i = 0; i < size; ++i) {
        ext_meta *meta = fetch_metadata(arr[i]->ext);
        arr[i]->len = meta->len;
        arr[i]->data = get_memory(meta->len + 1); // +1 for null terminator
        strcpy(arr[i]->data, meta->data);
    }

    return arr;
}

void destroy_data_array(data_entry **arr, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(arr[i]->ext);
        free(arr[i]->data);
        free(arr[i]);
    }

    free(arr);
}
