typedef struct {
    double timestamp;
    float sensor_value;
    char identifier;
    size_t index;
    void *sensorConfig; // Dynamically allocated memory for sensorConfig structure
} sensorReading;

typedef struct {
    long offset;
} offset;

typedef struct {
    int key;
} key;

typedef struct {
    int value;
} record;

typedef struct {
    char *device_name; // Dynamically allocated memory for device name string
    uint32_t sampling_rate;
    bool status_flag;
} config;

// Function to calculate the total memory required for a given number of sensor readings and input parameters
size_t calculate_memory(int num_readings, int record_size, int string_size) {
    size_t total = 0;

    // Calculate memory for sensorReading structures
    total += num_readings * sizeof(sensorReading);

    // Calculate memory for offset arrays
    total += num_readings * sizeof(offset);

    // Calculate memory for key arrays
    total += num_readings * sizeof(key);

    // Calculate memory for record structures
    total += num_readings * record_size;

    // Calculate memory for config structures
    total += num_readings * string_size + (num_readings * sizeof(config) - 1);

    return total;
}

// Function to initialize a flexible array of sensorReading entities and other dynamic structures in a high-performance data processing pipeline
void init_pipeline(int num_readings, int record_size, int string_size, char **device_names) {
    size_t total = calculate_memory(num_readings, record_size, string_size);
    void *data = calloc(1, total);

    if (!data) {
        perror("Memory allocation error");
        return;
    }

    sensorReading *sensor_array = data;
    offset *offset_array = (offset *)((char*)sensor_array + num_readings * sizeof(sensorReading));
    key *key_array = (key *)((char*)offset_array + num_readings * sizeof(offset));
    record *record_array = (record *)((char*)key_array + num_readings * sizeof(key));
    config *config_array = (config *)((char*)record_array + num_readings * record_size);

    // Initialize sensor readings with random values and timestamps within specified ranges
    for (int i = 0; i < num_readings; ++i) {
        sensor_array[i].timestamp = rand() % MAX_TIMESTAMP + MIN_TIMESTAMP;
        sensor_array[i].sensor_value = ((double)rand() / RAND_MAX) * (MAX_SENSOR - MIN_SENSOR) + MIN_SENSOR;
        sensor_array[i].identifier = i % 26 + 'A';

        // Allocate memory for sensorConfig dynamically and initialize with random values
        sensor_array[i].sensorConfig = malloc(sizeof(config));
        config *config = (config *)((char*)sensor_array[i].sensorConfig + i % ALIGNMENT);
        config->sampling_rate = rand() % MAX_SAMPLING_RATE + MIN_SAMPLING_RATE;
        config->status_flag = rand() % 2 == 0 ? true : false;
        if (device_names) {
            config->device_name = device_names[i % num_devices];
        } else {
            // Allocate memory for device name dynamically
            size_t string_length = rand() % MAX_DEVICE_NAME + MIN_DEVICE_NAME;
            config->device_name = malloc(string_length + 1);
            snprintf((char*)config->device_name, string_length + 1, "Device_%d", i);
        }
    }

    // Initialize offset arrays with random values within specified ranges
    for (int i = 0; i < num_readings; ++i) {
        offset_array[i].offset = rand() % MAX_OFFSET + MIN_OFFSET;
    }

    // Initialize key arrays with sequential integers as keys
    for (int i = 0; i < num_readings; ++i) {
        key_array[i].key = i;
    }

    // Initialize record array with random integer values within specified range
    for (int i = 0; i < num_readings; ++i) {
        record_array[i].value = rand() % MAX_RECORD + MIN_RECORD;
    }
}
