```cpp
#include <new> // For std::nothrow and std::bad_alloc exceptions
#include <vector>
#include <mutex>
#include <memory>

struct Record {
    double value;
};

class MemoryManager {
private:
    std::vector<long*> offsets;
    std::vector<int*> keys;
    std::vector<std::unique_ptr<Record[]>> records;
    mutex mtx;
    size_t capacity = 0;

public:
    MemoryManager(size_t initial_capacity) {
        reserve(initial_capacity);
    }

    ~MemoryManager() {
        clear();
    }

    void reserve(size_t new_capacity) {
        if (new_capacity > capacity) {
            auto old_offsets = std::move(offsets);
            auto old_keys = std::move(keys);
            auto old_records = std::move(records);
            offsets.reserve(new_capacity);
            keys.reserve(new_capacity);
            records.reserve(new_capacity);

            for (size_t i = capacity; i < new_capacity; ++i) {
                offsets.push_back(nullptr);
                keys.push_back(-1);
                records.emplace_back(std::make_unique<Record[]>(new_capacity));
            }

            for (auto& offset : old_offsets) {
                if (offset != nullptr) {
                    auto new_offset = offset + capacity;
                    std::swap(*offset, *new_offset);
                }
            }

            capacity = new_capacity;
        }
    }

    void clear() {
        for (auto& offset : offsets) delete[] offset;
        offsets.clear();
        keys.clear();
        records.clear();
        capacity = 0;
    }

    long* allocate_offset(size_t size) {
        if (capacity == 0 || size > capacity) reserve(size);
        auto result = offsets[size - 1];
        if (result == nullptr) {
            result = new long[capacity];
            std::unique_lock<mutex> lock(mtx);
            for (size_t i = size; i < capacity; ++i) {
                offsets[i] = result + i - size;
            }
        }
        return result;
    }

    int* allocate_key() {
        if (capacity == 0) reserve(1);
        auto key = keys.back();
        if (key == -1) {
            keys.pop_back();
            key = capacity - 1;
        } else {
            --capacity;
        }
        return &key;
    }

    Record* update_record(int key, double value, size_t range_start, size_t range_end) {
        auto it = std::find_if(records.begin(), records.end(),
                               [&](const auto& record_ptr) { return *allocate_key() == *(record_ptr->get()); });
        if (it != records.end()) {
            for (size_t i = range_start; i < range_end; ++i) {
                (*it)->value = value;
                ++(*allocate_offset(range_end));
            }
        } else {
            throw std::invalid_argument("Key not found");
        }
        return &((*it)->at(key));
    }
};
```

