#include <stdlib.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

struct Collection {
    size_t capacity;
    size_t count;
    Record *records;
    pthread_mutex_t lock;
};

void collection_init(struct Collection *collection, size_t initial_capacity) {
    if (initial_capacity == 0) {
        initial_capacity = 16;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->records = malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        fprintf(stderr, "Error: Failed to allocate memory for the collection.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);
}

void* record_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Failed to allocate memory for the record.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record* collection_get_record(struct Collection *collection, size_t index) {
    if (index >= collection->capacity) {
        size_t new_capacity = (collection->capacity + 1) * 2;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            fprintf(stderr, "Error: Failed to reallocate memory for the collection.\n");
            exit(EXIT_FAILURE);
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    pthread_mutex_lock(&collection->lock);
    Record *record = &collection->records[index];
    if (collection->count <= index) {
        collection->count = index + 1;
        record->offset = -1;
        record->key = -1;
        record->value = -1;
    }
    pthread_mutex_unlock(&collection->lock);
    return record;
}

Record* collection_find(struct Collection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }
    return NULL;
}

void collection_add(struct Collection *collection, long offset, int key, int value) {
    Record *record = collection_get_record(collection, collection->count);
    record->offset = offset;
    record->key = key;
    record->value = value;
    ++collection->count;
}

void collection_update(struct Collection *collection, int key, int new_value) {
    Record *record = collection_find(collection, key);
    if (record) {
        record->value = new_value;
    }
}

void collection_serialize(const struct Collection *collection, FILE *file) {
    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->records[i].offset, sizeof(long), 1, file);
        fwrite(&collection->records[i].key, sizeof(int), 1, file);
        fwrite(&collection->records[i].value, sizeof(int), 1, file);
    }
}

void collection_deserialize(struct Collection *collection, FILE *file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    collection->capacity = (count + 1) * 2;
    collection->records = realloc(collection->records, collection->capacity * sizeof(Record));
    if (!collection->records) {
        fprintf(stderr, "Error: Failed to reallocate memory for the collection during deserialization.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < count; ++i) {
        Record *record = &collection->records[i];
        fread(&record->offset, sizeof(long), 1, file);
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(int), 1, file);
    }
    collection->count = count;
}
```

