    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    if (num_records <= 0 || min_val > max_val) {
        fprintf(stderr, "Invalid arguments. num_records must be greater than zero and min_val should be less than max_val.\n");
        pthread_mutex_destroy(&lock);
        return;
    }

    size_t offset_capacity = num_records;
    size_t key_capacity = num_records;
    void* records_capacity = num_records * sizeof(Record);

    long* offsets_arr = malloc(offset_capacity * sizeof(long));
    if (!offsets_arr) {
        fprintf(stderr, "Failed to allocate memory for offset array.\n");
        pthread_mutex_destroy(&lock);
        return;
    }

    int* keys_arr = malloc(key_capacity * sizeof(int));
    if (!keys_arr) {
        fprintf(stderr, "Failed to allocate memory for key array.\n");
        free(offsets_arr);
        pthread_mutex_destroy(&lock);
        return;
    }

    Record* records_arr = malloc(records_capacity);
    if (!records_arr) {
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        free(offsets_arr);
        free(keys_arr);
        pthread_mutex_destroy(&lock);
        return;
    }

    pthread_mutex_lock(&lock);

    *offsets = offset_capacity;
    *keys = key_capacity;
    *records = records_arr;

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        long* offset_ptr = offsets_arr + i;
        int* key_ptr = keys_arr + i;
        Record* record_ptr = records_arr + i;

        *offset_ptr = (long)i;
        *key_ptr = rand() % (max_val - min_val + 1) + min_val;
        record_ptr->key = *key_ptr;
        record_ptr->offset = *offset_ptr;
    }

    pthread_mutex_unlock(&lock);
}
