typedef struct {
    uint64_t session_id;
    time_t last_active;
    bool active;
} Session;

#define SESSION_IDLE_DURATION 300 // seconds

// Define max and current array sizes
#define MAX_SESSIONS 1024
#define CURRENT_SESSIONS 64

Session *sessions;
pthread_mutex_t sessions_lock = PTHREAD_MUTEX_INITIALIZER;
size_t num_sessions = 0;

void session_init() {
    if (num_sessions >= MAX_SESSIONS) return;

    // Check for memory fragmentation and contiguous allocation when resizing
    size_t new_size = num_sessions ? (num_sessions * 2) : CURRENT_SESSIONS;
    Session *new_array = mmap(NULL, new_size * sizeof(Session), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_array == MAP_FAILED) return;

    // Copy existing sessions to the new array
    if (num_sessions > 0) {
        memcpy(new_array, sessions, num_sessions * sizeof(Session));
        free(sessions);
    }

    sessions = new_array;
}

void session_update(uint64_t session_id) {
    pthread_mutex_lock(&sessions_lock);

    for (size_t i = 0; i < num_sessions; ++i) {
        if (sessions[i].session_id == session_id) {
            sessions[i].last_active = time(NULL);
            break;
        }

        // Check for inactivity and remove expired sessions if needed
        if (sessions[i].active && (difftime(time(NULL), sessions[i].last_active) > SESSION_IDLE_DURATION)) {
            memmove(&sessions[i], &sessions[i+1], --num_sessions - i);
            --i;
        }
    }

    pthread_mutex_unlock(&sessions_lock);
}
```

This code implements a basic session management system in C using a dynamically resizable array of `Session` structures. The main function is `session_init()`, which handles array resizing when necessary, and the `session_update()` function updates the last active timestamps and removes expired sessions from memory.

The critical section for concurrent access is protected using a mutex (`pthread_mutex_t sessions_lock`). The system can handle sudden increases in session traffic by periodically resizing the array based on the current number of sessions (using `session_init()`). To minimize overhead, the system balances efficient memory allocation and garbage collection.']

