#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <getopt.h>
#include <sys/mman.h>

#define MAX_MEMORY 10490000 // (10MB * sizeof(int))

typedef struct Record {
    int value;
    long offset;
} Record;

struct ThreadData {
    Record **buffer;
    size_t *offsets;
    size_t capacity, index;
};

void* thread_func(void *data) {
    struct ThreadData *td = data;
    while (td->index < td->capacity) {
        if (td->buffer[td->index]->value >= LOWER && td->buffer[td->index]->value <= UPPER) {
            td->offsets[td->buffer[td->index]->offset] = 1;
        }
        ++td->index;
    }
    return NULL;
}

int main(int argc, char **argv) {
    int c;
    FILE *input_file = stdin, *output_file = NULL;
    bool sensitive = false, help = false;
    long lower = 0, upper = 0;

    static struct option long_options[] = {
        {"help", no_argument, nullptr, 'h'},
        {"sensitive", no_argument, nullptr, 's'},
        {"output", required_argument, nullptr, 'o'},
        {nullptr, 0, nullptr, 0}
    };

    while ((c = getopt_long(argc, argv, "hs:o:", long_options, nullptr)) != -1) {
        switch (c) {
            case 'h':
                help = true;
                break;
            case 's':
                sensitive = true;
                break;
            case 'o':
                output_file = fopen(optarg, "w");
                break;
        }
    }

    if (help || argc - optind < 1) {
        printf("Usage: %s [-h] [-s] [-o outfile] input_file\n", argv[0]);
        exit(0);
    }

    input_file = fopen(argv[optind], "r");
    if (!input_file) {
        perror("Error opening input file");
        exit(1);
    }

    pthread_t *threads;
    Record **buffer, *record;
    size_t num_threads, buffer_capacity, i, j;
    MAP_FAILED_t err;

    if ((err = posix_memalign((void **)&buffer, sizeof(Record), MAX_MEMORY)) != MAP_FAILED) {
        buffer_capacity = MAX_MEMORY / sizeof(Record);
        buffer[0] = (Record *)map_initialize(buffer, buffer_capacity);
    } else {
        perror("Error allocating memory");
        exit(1);
    }

    num_threads = strtoul(getenv("OMP_NUM_THREADS"), nullptr, 10);
    if (num_threads == 0) {
        num_threads = sysconf(_SC_NPROCESSORS_ONLN);
    }

    threads = (pthread_t *)calloc(num_threads, sizeof(pthread_t));
    if (!threads) {
        perror("Error allocating memory");
        exit(1);
    }

    struct ThreadData td;
    td.buffer = buffer;
    td.offsets = (size_t *)calloc(buffer_capacity, sizeof(size_t));
    if (!td.offsets) {
        perror("Error allocating memory");
        exit(1);
    }
    td.capacity = buffer_capacity;
    td.index = 0;

    for (i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], nullptr, thread_func, &td);
    }

    char line[1024];
    int count = 0;
    while (fgets(line, sizeof(line), input_file)) {
        sscanf(line, "%d", &record->value);
        record->offset = ftell(input_file);
        if (!sensitive) {
            // Skip sensitive parsing for non-sensitive mode
        }
        buffer[count++] = record;
    }

    Record *end = buffer + count;

    td.index = 0;
    for (i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], nullptr);
    }

    // Save the results to output file if specified
    if (output_file) {
        fprintf(output_file, "Value\tOffset\n");
        for (i = 0; i < count; ++i) {
            if (td.offsets[i]) {
                fprintf(output_file, "%d\t%ld\n", buffer[i]->value, buffer[i]->offset);
            }
        }
    }

    // Free memory and exit
    free(threads);
    free(td.offsets);
    munmap(buffer, MAX_MEMORY);
    fclose(input_file);
    if (output_file) {
        fclose(output_file);
    }

    return 0;
}
```

