            if (!Files.exists(stateFilePath)) {
                LOGGER.warn("No saved state found at {}!", stateFilePath);
                return null;
            }

            try (ObjectInputStream objectStream = new ObjectInputStream(new FileInputStream(stateFilePath.toFile()))) {
                Object object = objectStream.readObject();
                if (object instanceof MoSTState) {
                    return (MoSTState) object;
                }
            } catch (IOException | ClassNotFoundException e) {
                LOGGER.error("Error loading state from file: {}", e.getMessage());
            }
        } catch (IOException e) {
            LOGGER.error("Error accessing configuration service: {}", e.getMessage());
        }

        return null;
    }

