        BufferedImage themeBitmap = THEME_CACHE.get(themeName);
        if (themeBitmap == null) {
            Path themeBitmapPath = Paths.get(".", THEME_CACHE_DIRECTORY, themeName + ".png");
            try {
                if (!Files.exists(themeBitmapPath)) {
                    // Download PNG file from a specified URL and cache it to the themeCacheDirPath
                }

                themeBitmap = ImageIO.read(Files.newInputStream(themeBitmapPath));
                THEME_CACHE.putIfAbsent(themeName, themeBitmap);
            } catch (IOException | ExecutionException e) {
                LOGGER.error("Error loading or caching theme bitmap for {}: {}", themeName, e.getMessage());
            }
        } else {
            // Recycle the previous themeBitmap if it's already in use
        }

        return themeBitmap;
    }
}
