#include <iostream>
#include <chrono>
#include <vector>
#include <list>
#include <unordered_map>
#include <utility>
#include <algorithm>
#include <ctime>
#include <cassert>
#include <functional>
#include <random>

using namespace std;
using clock = chrono::high_resolution_clock;

struct Session {
    string id;
    time_t lastActive;
    bool active;
};

struct Record {
    char identifier;
    double value;
    time_t timestamp;
};

class DataManager {
private:
    // Session management
    unordered_map<string, list<Session>::iterator> sessionIterators;
    list<Session> sessions;
    int maxSessions = 1000;
    constexpr static time_t idleTimeoutSecs = 60;

    // Record management
    vector<Record> records;
    random_device rd;
    default_random_engine generator(rd());
    uniform_int_distribution<> dis(0, 9);

public:
    void update() {
        auto now = chrono::system_clock::to_time_t(chrono::system_clock::now());
        for (auto it = sessions.begin(); it != sessions.end();) {
            if ((now - it->lastActive) > idleTimeoutSecs) {
                it = sessions.erase(it);
                continue;
            }
            it->lastActive = now;
            ++it;
        }
    }

    void addSession(const string& id) {
        if (sessionIterators.find(id) != sessionIterators.end())
            return;
        Session s{ id, chrono::system_clock::to_time_t(chrono::system_clock::now()), true };
        sessions.push_back(s);
        sessionIterators[id] = --sessions.end();
    }

