typedef struct Node {
    Session session;
    struct Node* next;
} Node;

struct SessionManager {
    int capacity, size;
    Node** nodes;
    sem_t resize_mutex;
    pthread_mutex_t stats_mutex;
    // Query API and logging mechanisms go here
};

void session_manager_init(struct SessionManager* sm, int initial_capacity) {
    sm->capacity = initial_capacity;
    sm->size = 0;
    sm->nodes = malloc(initial_capacity * sizeof(Node*));
    for (int i = 0; i < initial_capacity; ++i) {
        sm->nodes[i] = NULL;
    }
    sem_init(&sm->resize_mutex, 0, 1);
    pthread_mutex_init(&sm->stats_mutex, NULL);
}

void session_manager_cleanup(struct SessionManager* sm) {
    for (int i = 0; i < sm->capacity; ++i) {
        Node* current = sm->nodes[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(sm->nodes);
    sem_destroy(&sm->resize_mutex);
    pthread_mutex_destroy(&sm->stats_mutex);
}

void session_manager_resize(struct SessionManager* sm) {
    if (sem_trywait(&sm->resize_mutex) == 0) {
        int new_capacity = 2 * sm->capacity;
        Node** new_nodes = malloc(new_capacity * sizeof(Node*));
        for (int i = 0; i < new_capacity; ++i) {
            new_nodes[i] = NULL;
        }
        for (int i = 0; i < sm->capacity; ++i) {
            Node* current = sm->nodes[i];
            while (current != NULL) {
                Node* next = current->next;
                if (i < new_capacity) {
                    new_nodes[i] = current;
                } else {
                    Node* temp = current;
                    current = current->next;
                    free(temp);
                }
                current = next;
            }
        }
        free(sm->nodes);
        sm->nodes = new_nodes;
        sm->capacity = new_capacity;
        sem_post(&sm->resize_mutex);
    }
}

