#include <time.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    double value;
    int id; // Unique identifier within the record set
} Record;

Record* create_records(size_t num_records, int min_id, int max_id) {
    Record *records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = i;
        records[i].key = min_id + rand() % (max_id - min_id + 1);
        records[i].value = ((double)rand() / RAND_MAX) * 100.0; // Random double within [0, 100)
        records[i].id = i;
    }

    return records;
}

void qsort_int(Record* arr, size_t left, size_t right, size_t size) {
    if (left < right) {
        size_t pivotIndex = left + rand() % (right - left + 1);
        size_t pivot = partition(arr, left, right, size);
        qsort_int(arr, left, pivot - 1, size);
        qsort_int(arr, pivot + 1, right, size);
    }
}

size_t partition(Record* arr, size_t left, size_t right, size_t size) {
    Record pivot = arr[right];
    size_t i = left;
    for (size_t j = left; j < right; ++j)
        if (arr[j].key <= pivot.key) {
            swap(&arr[i], &arr[j]);
            ++i;
        }
    swap(&arr[i], &arr[right]);
    return i;
}

void swap(Record* a, Record* b) {
    Record temp = *a;
    *a = *b;
    *b = temp;
}

int compare_sorted(Record* arr, size_t length) {
    for (size_t i = 0; i < length - 1; ++i) {
        if (arr[i + 1].key < arr[i].key || (arr[i + 1].key == arr[i].key && arr[i + 1].value <= arr[i].value))
            return 0;
    }
    return 1;
}

void* sort_and_store_keys(void *arg) {
    SortFuncParams* params = (SortFuncParams*) arg;
    Record **records = params->records;
    size_t num_records = params->num_records;
    int *sorted_keys = params->sorted_keys;
    long *sorted_offsets = params->sorted_offsets;

    qsort_int(*records, 0, num_records - 1, sizeof(**records));

    for (size_t i = 0; i < num_records; ++i) {
        sorted_keys[i] = (*records)[i].key;
        sorted_offsets[i] = (*records)[i].offset;
    }

    free(*records); // Free the dynamically allocated records

    return NULL;
}

int main(void) {
    srand(time(NULL));
    int num_records, min_id, max_id;
    printf("Enter the number of records, min id, and max id:\n");
    scanf("%d %d %d", &num_records, &min_id, &max_id);

    Record **sorted_records = calloc(1, sizeof(Record*) * (num_records + 1));
    int *sorted_keys = calloc(1, num_records * sizeof(int));
    long *sorted_offsets = calloc(1, num_records * sizeof(long));

    SortFuncParams params = { create_records(num_records, min_id, max_id), num_records, sorted_keys, sorted_offsets };
    pthread_t tid;
    pthread_create(&tid, NULL, sort_and_store_keys, &params);
    pthread_join(tid, NULL);

    // Further processing of the sorted keys and offsets in the application framework

    return 0;
}
