#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

typedef struct Record {
    long offset;
    int key;
    struct Record *next; // singly-linked list pointer
} Record;

struct HashTable {
    size_t size;
    Record **records;
    pthread_mutex_t lock;
};

// Hash function for unique offsets and keys
unsigned long hash(long key) {
    unsigned long hash = 0;
    for (int i = 0; i < sizeof(key) * 8; ++i) {
        hash = (hash << 5) + hash + key >> 27;
        hash &= ~(unsigned long)(-1);
    }
    return hash % size;
}

// Open addressing strategy: quadratic probing
int find_empty_slot(struct HashTable *ht, unsigned long hash) {
    int i = hash;
    do {
        if (!ht->records[i]) {
            return i;
        }
        i = (i + 1 + (i - hash) * 2) % ht->size;
    } while (i != hash);
    return -1; // slot not found
}

// Thread-safe initialization function
void init(struct HashTable *ht, size_t capacity, long offset_min, long offset_max, int key_min, int key_max) {
    ht->size = capacity;
    ht->records = mmap(NULL, sizeof(Record *) * capacity, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    ht->lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < capacity; ++i) {
        ht->records[i] = NULL;
    }

    // Initialize offsets and keys within the specified ranges
    for (long o = offset_min; o <= offset_max; ++o) {
        unsigned long hash = hash(o);
        int slot = find_empty_slot(ht, hash);
        if (slot != -1) {
            Record *r = malloc(sizeof(Record));
            r->offset = o;
            r->key = -1; // unassigned key
            r->next = ht->records[slot];
            ht->records[slot] = r;
        }
    }

    for (int k = key_min; k <= key_max; ++k) {
        Record *r = find_record(ht, k);
        if (!r) {
            r = malloc(sizeof(Record));
            r->offset = -1; // unassigned offset
            r->key = k;
            r->next = NULL;

            unsigned long hash = hash(k);
            int slot = find_empty_slot(ht, hash);
            if (slot != -1) {
                ht->records[slot] = r;
            }
        }
    }
}

// Find a record by its key or offset
Record *find_record(struct HashTable *ht, long key) {
    if (key >= 0) {
        unsigned long hash = hash(key);
        int slot = find_empty_slot(ht, hash);
        for (Record *r = ht->records[slot]; r; r = r->next) {
            if (r->key == key) {
                return r;
            }
        }
    } else {
        Record *r = ht->records[-key];
        while (r && r->offset != -key) {
            r = r->next;
        }
        if (r) {
            return r;
        }
    }
    return NULL;
}

// Implement iterators for forward and backward traversals
struct Iterator {
    struct HashTable *ht;
    size_t index;
    Record *current;
};

void iterator_init(struct Iterator *it, struct HashTable *ht) {
    it->ht = ht;
    it->index = 0;
    it->current = NULL;
}

bool iterator_has_next(struct Iterator *it) {
    return it->current || it->index < it->ht->size;
}

Record *iterator_next(struct Iterator *it) {
    if (!it->current) {
        Record *first = it->ht->records[it->index];
        it->current = first;
        it->index++;
    } else {
        it->current = it->current->next;
    }
    return it->current;
}
```

