typedef struct Record {
    long offset;
    int key;
    struct Record *next;
    void *metadata; // Variable-length data
} Record;

typedef struct Collection {
    size_t num_records;
    size_t metadata_size;
    Record *head;
    pthread_mutex_t mutex;
} Collection;

Collection* initialize_collection(size_t num_records, long min_offset, long max_offset, int min_key, int max_key, size_t metadata_size) {
    Collection *coll = mmap(NULL, sizeof(Collection), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!coll) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    coll->num_records = num_records;
    coll->metadata_size = metadata_size;
    coll->head = NULL;
    pthread_mutex_init(&coll->mutex, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = mmap(NULL, sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (!record) {
            perror("mmap failed");
            exit(EXIT_FAILURE);
        }

        record->offset = min_offset + i;
        record->key = min_key + i % (max_key - min_key + 1);
        record->next = NULL;

        void *metadata = mmap(NULL, metadata_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (!metadata) {
            perror("mmap failed");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&coll->mutex);
        record->metadata = metadata;
        if (i == 0) {
            coll->head = record;
        } else {
            Record *curr = coll->head;
            while (curr->next != NULL) {
                curr = curr->next;
            }
            curr->next = record;
        }
        pthread_mutex_unlock(&coll->mutex);
    }

    return coll;
}
