typedef struct SlidingWindow {
    size_t capacity;
    size_t windowSize;
    Record *data;
    pthread_mutex_t lock;
    pthread_cond_t notEmpty;
    pthread_cond_t notFull;
} SlidingWindow;

void initSlidingWindow(SlidingWindow *window, size_t capacity, size_t windowSize) {
    window->capacity = capacity;
    window->windowSize = windowSize;
    window->data = mmap(NULL, capacity * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (window->data == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate sliding window memory\n");
        exit(EXIT_FAILURE);
    }
    window->lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_init(&window->notEmpty, NULL);
    pthread_cond_init(&window->notFull, NULL);
}

void enqueue(SlidingWindow *window, Record record) {
    pthread_mutex_lock(&window->lock);
    while (window->data + windowSize == window->data + window->capacity && windowSize < window->capacity) {
        pthread_cond_wait(&window->notFull, &window->lock);
    }
    memcpy(window->data + windowSize, &record, sizeof(Record));
    if (++windowSize == window->capacity) {
        pthread_cond_signal(&window->notEmpty);
    }
    pthread_mutex_unlock(&window->lock);
}

Record dequeue(SlidingWindow *window) {
    Record record;
    pthread_mutex_lock(&window->lock);
    while (windowSize == 0) {
        pthread_cond_wait(&window->notEmpty, &window->lock);
    }
    memcpy(&record, window->data, sizeof(Record));
    if (--windowSize == window->windowSize) {
        pthread_cond_signal(&window->notFull);
    }
    pthread_mutex_unlock(&window->lock);
    return record;
}

void freeSlidingWindow(SlidingWindow *window) {
    munmap(window->data, window->capacity * sizeof(Record));
    pthread_cond_destroy(&window->notEmpty);
    pthread_cond_destroy(&window->notFull);
}

