["```javascript
function dynamicLoadScript(filename) {
  const extension = determineExtension(filename);
  let loadedFile = document.createElement('script');
  loadedFile.src = `scripts/${filename}.js`;

  // Create a numeric suffix if the original filename already exists as a script file
  let suffix = 0;
  do {
    if (document.querySelector(`#${loadedFile.src}`)) {
      suffix++;
      loadedFile.src = `scripts/${filename}_${suffix}${extension}.js`;
    } else {
      break;
    }
  } while (true);

  // Attempt to load the script dynamically, handle errors and log detailed messages
  try {
    document.head.appendChild(loadedFile);
    loadedFile.onload = () => console.log(`Loaded script: ${filename}`);
  } catch (error) {
    const errorMessage = `Failed to load script '${filename}'. Reason: ${error.message}`;
    console.error(errorMessage);
    if (XMLHttpRequest && XMLHttpRequest.prototype.send) { // Check for XMLHttpRequest support
      const xhr = new XMLHttpRequest();
      xhr.open('HEAD', loadedFile.src, false);
      xhr.send();

      if (xhr.status === 404 || !xhr.getResponseHeader('Content-Type').includes(extension)) {
        console.error(`${errorMessage}\nThe specified file '${filename}' was not found or is not executable.\nAttempting to load alternative scripts...`);
        // Iterate through alternative script names based on the original filename and attempt to load them dynamically
        const baseName = filename.split('.').slice(0, -1).join('.');
        for (let suffix = 1; ; suffix++) {
          let alternativeFileName = `${baseName}_${suffix}.js`;
          if (!document.querySelector(`#${loadedFile.src}`)) { // Check if the alternative file is not already loaded
            loadedFile.src = `scripts/${alternativeFileName}`;
            try {
              document.head.appendChild(loadedFile);
              loadedFile.onload = () => console.log(`Loaded alternative script: ${alternativeFileName}`);
              break;
            } catch (error) {
              const errorMessage = `Failed to load alternative script '${alternativeFileName}'. Reason: ${error.message}`;
              console.error(errorMessage);
            }
          }
        }
      }
    } else {
      console.error(`${errorMessage}\nXMLHttpRequest is not supported or network connectivity is not available.`);
    }
  }

  function determineExtension(filename) {
    const extension = filename.split('.').pop().toLowerCase();
    if (extension === '' || !['js', 'json'].includes(extension)) {
      // Derive a new file type identifier based on the first three alphanumeric characters of the original filename and pad with zeros if necessary
      const id = `${filename.match(/[A-Za-z0-9]{1,3}/)[0]}.js`.padStart(4, '0');
      return id;
    } else {
      return extension;
    }
  }
}
