    void *offsets_mem;
    size_t keys_capacity, keys_size;
    void *keys_mem;
    size_t records_capacity, records_size;
    void *records_mem;
    sem_t mem_pool_sem;
} DataManager;

DataManager* data_manager_init(size_t offsets_capacity, size_t keys_capacity, size_t records_capacity) {
    DataManager *dm = malloc(sizeof(DataManager));
    pthread_mutex_init(&dm->lock, NULL);
    sem_init(&dm->mem_pool_sem, 0, records_capacity);
    dm->offsets_capacity = offsets_capacity;
    dm->keys_capacity = keys_capacity;
    dm->records_capacity = records_capacity;
    dm->offsets_size = 0;
    dm->keys_size = 0;
    dm->records_size = 0;
    return dm;
}

void* data_manager_alloc(DataManager *dm, size_t type) {
    void *mem;
    switch (type) {
        case OFFSET:
            if (dm->offsets_capacity == dm->offsets_size) {
                dm->offsets_capacity *= 2;
                mem = realloc(dm->offsets_mem, dm->offsets_capacity * sizeof(int));
            } else {
                mem = dm->offsets_mem + dm->offsets_size * sizeof(int);
            }
            pthread_mutex_lock(&dm->lock);
            dm->offsets_size++;
            pthread_mutex_unlock(&dm->lock);
            break;
        case KEY:
            if (dm->keys_capacity == dm->keys_size) {
                dm->keys_capacity *= 2;
                mem = realloc(dm->keys_mem, dm->keys_capacity * sizeof(int));
            } else {
                mem = dm->keys_mem + dm->keys_size * sizeof(int);
            }
            pthread_mutex_lock(&dm->lock);
            dm->keys_size++;
            pthread_mutex_unlock(&dm->lock);
            break;
        case RECORD:
            sem_wait(&dm->mem_pool_sem);
            if (dm->records_capacity == dm->records_size) {
                dm->records_capacity *= 2;
                mem = realloc(dm->records_mem, dm->records_capacity * sizeof(int));
            } else {
                mem = dm->records_mem + dm->records_size * sizeof(int);
            }
            pthread_mutex_lock(&dm->lock);
            dm->records_size++;
            sem_post(&dm->mem_pool_sem);
            break;
    }
    return mem;
}

void data_manager_deinit(DataManager *dm) {
    free(dm->offsets_mem);
    free(dm->keys_mem);
    free(dm->records_mem);
    free(dm);
}
