    for (size_t i = 0; i < initial_size; ++i) {
        records[i].offset = rand(); // Initialize offset with random value to prevent overflow
        records[i].key = rand(); // Initialize key with random value
    }
}

void resizeRecords(struct MemoryPool pool, size_t new_size) {
    Record *new_records = realloc(pool.pool, new_size * sizeof(Record));
    if (new_records == NULL) {
        logEvent(&g_logger, "Failed to allocate memory for record array.");
        return;
    }
    pool.capacity = new_size;

    pthread_mutex_lock(&records_mutex);
    // Notify waiting threads that the record array has been resized
    pthread_cond_signal(&records_cond);
    pthread_mutex_unlock(&records_mutex);

    Record *current_records = (Record *)pool.pool;
    for (size_t i = initial_size; i < new_size; ++i) {
        current_records[i].offset = rand(); // Initialize offset with random value to prevent overflow
        current_records[i].key = rand(); // Initialize key with random value
    }
}

// Implement concurrency-safe mechanisms for simultaneous access from multiple threads
void lockRecords() {
    pthread_mutex_lock(&records_mutex);
}

void unlockRecords() {
    pthread_mutex_unlock(&records_mutex);
}

void waitForRecordsResize() {
    pthread_mutex_lock(&records_mutex);
    while (pool.capacity == initial_size) {
        pthread_cond_wait(&records_cond, &records_mutex);
    }
    pthread_mutex_unlock(&records_mutex);
}

