// Log level enumeration
enum log_level { DEBUG, INFO, WARN, ERROR, CRITICAL };

// Custom memory pool structure
struct mem_pool {
    void *memory;
    size_t allocated;
    size_t used;
};

typedef struct log {
    time_t timestamp;
    enum log_level level;
    char *message; // Dynamically allocated buffer
} log;

// Memory pool initialization function
void mem_pool_init(struct mem_pool *pool, size_t capacity) {
    pool->memory = malloc(capacity);
    if (!pool->memory) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->allocated = capacity;
    pool->used = 0;
}

// Memory pool reclaim function
void *mem_pool_reclaim(struct mem_pool *pool) {
    if (pool->used < pool->allocated / 2) return NULL;

    void *block = pool->memory + pool->used - sizeof(log);
    log *log_to_free = (log *)block;
    free(log_to_free->message);
    pool->used -= sizeof(log);
    return block;
}

// Function to add a log entry to the log array, handling memory allocation and synchronization
void add_log_entry(struct mem_pool *pool, log **logs, enum log_level level, const char *format, ...) {
    va_list args;
    log *new_log;
    size_t message_capacity = 4096; // Adjust based on your needs

    // Allocate memory for new log entry and message buffer
    new_log = malloc(sizeof(log) + message_capacity);
    if (!new_log) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize new log entry
    new_log->timestamp = time(NULL);
    new_log->level = level;
    new_logs = realloc(*logs, sizeof(**new_logs) * (1 + (*logs ? strlen(*logs) : 0) / message_capacity + 1));

    if (!new_logs) {
        fprintf(stderr, "Memory allocation failed\n");
        free(new_log);
        exit(EXIT_FAILURE);
    }
    *new_logs = new_logs + (*logs ? strlen(*new_logs) : 0);

    // Set up message buffer and arguments
    va_start(args, format);
    vsnprintf((char *)new_log + sizeof(log), message_capacity, format, args);
    va_end(args);

    // Check if message is too large for allocated memory
    if (strlen((char *)new_log + sizeof(log)) >= message_capacity) {
        free(new_log->message);
        fprintf(stderr, "Message exceeded buffer capacity\n");
        exit(EXIT_FAILURE);
    }

    // Adjust message buffer to account for log header and null terminator
    new_log->message = (char *)new_log + sizeof(log) + strlen((char *)new_log + sizeof(log));

    // Move memory pool pointer if necessary
    if (pool->used + sizeof(log) + strlen((char *)new_log + sizeof(log)) >= pool->allocated) {
        void *to_reclaim = mem_pool_reclaim(pool);
        if (to_reclaim) {
            free(to_reclaim);
            pool->used -= sizeof(log);
        } else {
            fprintf(stderr, "Memory pool is full\n");
            exit(EXIT_FAILURE);
        }
    }
    pool->used += sizeof(log) + strlen((char *)new_log + sizeof(log));
}

// Concurrent logging function for multiple threads
void log_thread_func(struct mem_pool *pool, log **logs) {
    char buffer[256]; // Adjust based on your needs
    while (1) {
        add_log_entry(pool, logs, INFO, "Thread %d doing some logging\n", pthread_self());
        sleep(1);
    }
}
