typedef struct Node {
    double value;
    int key;
    struct Node* next;
} Node;

Node** nodes = NULL;
long* offsets = NULL;
int num_nodes = 0, capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Generate a random double within [min, max]
double rand_double(double min, double max) {
    return min + (max - min) * rand() / RAND_MAX;
}

int find_empty_slot() {
    for (long i = 0; i < capacity; ++i) {
        if (!nodes[i])
            return i;
    }
    return -1;
}

void init_list(size_t size) {
    capacity = size;
    nodes = calloc(capacity, sizeof(Node*));
    offsets = malloc(sizeof(long) * (capacity + 1));
    offsets[0] = -1; // marker for end of list
}

void destroy_list() {
    for (long i = 0; i < capacity; ++i)
        free(nodes[i]);
    free(offsets);
    free(nodes);
}

Node* create_node(double value, int key) {
    Node* new_node = malloc(sizeof(Node));
    new_node->value = value;
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

void push_back(double value, int key) {
    pthread_mutex_lock(&mutex);
    long empty_slot = find_empty_slot();
    if (empty_slot == -1 && capacity != 0) {
        // Resize array when it's full
        size_t new_capacity = capacity * 2;
        Node** new_nodes = calloc(new_capacity, sizeof(Node*));
        long* new_offsets = malloc(sizeof(long) * (new_capacity + 1));
        for (long i = 0; i < capacity; ++i) {
            new_nodes[i] = nodes[i];
            if (nodes[i]) {
                if (offsets[i+1] == -1) {
                    new_offsets[i+1] = find_empty_slot();
                } else {
                    new_offsets[i+1] = offsets[i+1];
                }
            }
        }
        free(nodes);
        free(offsets);
        nodes = new_nodes;
        offsets = new_offsets;
        capacity *= 2;
    }
    if (empty_slot != -1) {
        nodes[empty_slot] = create_node(value, key);
        offsets[empty_slot+1] = empty_slot + 1;
    }
    pthread_mutex_unlock(&mutex);
}

// External data processing library interface
typedef void (*processing_func)(double value, int key);
void process(processing_func func) {
    pthread_mutex_lock(&mutex);
    for (long i = 0; i < capacity && offsets[i+1] != -1; ++i) {
        if (!nodes[i]) continue; // Skip empty slots
        Node* current = nodes[i];
        while (current) {
            func(current->value, current->key);
            current = current->next;
        }
    }
    pthread_mutex_unlock(&mutex);
}
