import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import java.util.stream.Stream;

@RegisterBean
public class OrderManagement {
    private final ConcurrentHashMap<Long, Order> orderMap = new ConcurrentHashMap<>();
    private final Lusk<Handle> db;

    @SqlQuery("SELECT * FROM orders WHERE id = :id")
    Order getOrder(@Bind("id") Long id);

    @SqlUpdate("INSERT INTO orders (id, productId, customerId, status) VALUES (:id, :productId, :customerId, :status)")
    void addOrder(
            @Bind("id") Long id,
            @Bind("productId") Long productId,
            @Bind("customerId") Long customerId,
            @Bind("status") String status);

    @SqlUpdate("UPDATE orders SET productId = :productId, customerId = :customerId, status = :status WHERE id = :id")
    void updateOrder(
            @Bind("id") Long id,
            @Bind("productId") Long productId,
            @Bind("customerId") Long customerId,
            @Bind("status") String status);

    Stream<Order> getOrders() {
        return orderMap.values().stream();
    }

    public void saveOrder(Long id, Order order) throws SQLException, InterruptedException, ExecutionException {
        Preconditions.checkArgument(id != null && id > 0);
        Preconditions.checkArgument(order != null);

        Order existing = orderMap.get(id);
        if (existing != null)
            throw new IllegalArgumentException("Order with ID " + id + " already exists.");

        var handle = db.get();
        try {
            handle.createQuery("INSERT INTO orders (id, productId, customerId, status) VALUES (?, ?, ?, ?)")
                    .bind(id, order.getProductId(), order.getCustomerId(), order.getStatus())
                    .execute();

            handle.createQuery("SELECT * FROM orders WHERE id = ?")
                    .bind(id)
                    .map((Function<ResultSet, Order>) rs -> new Order(rs.getLong("id"),
                            rs.getLong("productId"), rs.getLong("customerId"), rs.getString("status")))
                    .one();
        } finally {
            handle.close();
        }
        orderMap.putIfAbsent(id, order);
    }

    // Add methods for external service integration here
}

