class RecordCollection {
private:
    static std::mt19937 generator;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::unordered_set<int> uniqueKeys;
    std::mutex mtx;

    RecordCollection(size_t numRecords) {
        for (size_t i = 0; i < numRecords; ++i) {
            offsets.push_back(i);
        }

        boost::thread_pool pool(16); // Adjust thread count according to your needs

        auto generateKey = [&]() -> int {
            int key;
            do {
                key = generator();
            } while (uniqueKeys.count(key));
            uniqueKeys.insert(key);
            return key;
        };

        std::queue<std::function<void()>> tasks;
        for (size_t i = 0; i < numRecords; ++i) {
            tasks.push([=]() { keys[offsets[i]] = generateKey(); });
        }

        while (!tasks.empty()) {
            auto task = tasks.front();
            pool.enqueue(task);
            tasks.pop();
        }

        pool.join();
    }

public:
    ~RecordCollection() {}

    static std::unique_ptr<RecordCollection> create(size_t numRecords) {
        if (numRecords == 0) {
            throw std::runtime_error("Number of records cannot be zero.");
        }

        try {
            auto instance = std::make_unique<RecordCollection>(numRecords);
            return instance;
        } catch (const std::exception& e) {
            std::cerr << "Error initializing RecordCollection: " << e.what() << '\n';
            return nullptr;
        }
    }

    record* getFirstRecord() {
        if (!offsets.empty()) {
            auto record = new record{ keys[offsets.front()], offsets.front() };
            offsets.erase(offsets.begin());
            return record;
        } else {
            throw std::runtime_error("No records available.");
        }
    }
};

std::mt19937 RecordCollection::generator; // Initialize the generator statically

}  // namespace my_namespace
