typedef struct Record {
    int key;
    double value;
    char *str;
} Record;

static pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t capacity = 0;
static size_t count = 0;
static Record **records = NULL;

void resize() {
    if (capacity == count) {
        size_t new_capacity = count ? 2 * count : 8;
        Record **new_records = realloc(records, sizeof(Record *) * new_capacity);
        if (!new_records) {
            pthread_mutex_destroy(&records_mutex);
            free(records);
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        records = new_records;
        capacity = new_capacity;
    }
}

Record *create_record() {
    resize();
    Record *new_record = &records[count++];
    new_record->key = 0;
    new_record->value = 0.0;
    new_record->str = NULL;
    return new_record;
}

void validate_and_set(Record *record, int min, int max, double min_value, double max_value) {
    record->key = (rand() % (max - min + 1)) + min;
    record->value = ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value;
}

void* thread_init(void *arg) {
    Record *record = create_record();
    validate_and_set(record, 1, INT_MAX, -1.0, 1.0);
    pthread_mutex_lock(&records_mutex);
    record->str = strdup("Random string");
    pthread_mutex_unlock(&records_mutex);
    return NULL;
}

void init_data() {
    const size_t num_threads = 10;
    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_init, NULL)) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Failed to join thread\n");
            exit(EXIT_FAILURE);
        }
    }
}
