        metadata[i] = alphabet[seed % 36];
        seed = (seed * 27 + 1) % INT32_MAX;
    }

    metadata[metadata_length] = '\0';
    return metadata;
}

int random_value(int min, int max, size_t seed) {
    int range = max - min + 1;
    int value = (rand() % range + min);
    seed = (seed * 27 + 1) % INT32_MAX;
    return value;
}

void add_record(int key, Record *record) {
    pthread_rwlock_wrlock(&record_lock);

    if (records_length == records_capacity) {
        records_capacity *= 2;
        records = realloc(records, records_capacity * sizeof(Record));
    }

    strncpy(records[records_length].value, generate_metadata(key), 500);
    records[records_length++].key = key;
    records[records_length - 1]->value = realloc(records[records_length - 1]->value, strlen(records[records_length - 1].value) + 1);
    records[records_length - 1]->timestamp = time(NULL);
    records[records_length - 1]->int_value = random_value(-1000000, 1000000, key);

    pthread_rwlock_unlock(&record_lock);
}

Record* get_record_by_key(int key) {
    pthread_rwlock_rdlock(&record_lock);

    Record *found = NULL;
    for (size_t i = 0; i < records_length; ++i) {
        if (records[i].key == key) {
            found = &records[i];
            break;
        }
    }

    pthread_rwlock_unlock(&record_lock);
    return found;
}
