async function generateCompositeCredential(oauthRequest) {
  const { dataSources, config } = oauthRequest;
  let privateKey, certificate, metadata = {};

  // Use Promise.all to handle concurrent data retrieval from multiple sources
  const promises = dataSources.map(async (source) => {
    if (source.type === 'privateKey') {
      privateKey = await source.fetch();
    } else if (source.type === 'certificate') {
      certificate = await source.fetch();
    } else if (source.type === 'metadata') {
      metadata = await source.fetch();
    }
  });

  await Promise.all(promises);

  // Merge the fetched data based on dynamic configuration settings
  const mergedCredentials = {
    privateKey,
    certificate,
    ...metadata,
  };

  if (config && config.mergeStrategy) {
    Object.keys(mergedCredentials).forEach((key) => {
      if (Array.isArray(mergedCredentials[key])) {
        mergedCredentials[key] = config.mergeStrategy(mergedCredentials[key]);
      }
    });
  }

  // Convert the composite credential to PEM format
  const pem = `-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----\n---BEGIN RSA PRIVATE KEY-----\n${privateKey}\n---END RSA PRIVATE KEY-----\n`;

  return pem;
}
