const axios = require('axios');
const urlValidate = require('url-validate');
const { promises: fsPromises } = require('fs');
const crypto = require('crypto');
const cache = new Map();
const MAX_STREAMS = 20;
const WHITELIST = ['https://allowed.com', 'https://another.com']; // Replace with your whitelist

async function combineOAuthData(oauthRequest) {
  const { clientId, accessToken, refreshToken } = oauthRequest;

  if (!clientId || !accessToken || !refreshToken) {
    throw new Error('Missing required fields');
  }

  let privateKeyStreams = [];
  let certificateStreams = [];

  // Fetch private key and certificate from endpoints
  const fetchData = async (url, streams, cacheKey) => {
    if (!cache.has(cacheKey)) {
      try {
        const response = await axios.get(url);
        if (response.data && urlValidate.isSafeURL(url)) {
          cache.set(cacheKey, response.data);
          streams.push(response.data);
        }
      } catch (error) {
        console.error(`Error fetching data from ${url}:`, error);
      }
    } else {
      streams.push(cache.get(cacheKey));
    }
  };

  // Fetch private key and certificate in parallel, ensuring no more than MAX_STREAMS at a time
  for (let i = 0; i < MAX_STREAMS && privateKeyStreams.length + certificateStreams.length < MAX_STREAMS * 2; ++i) {
    const url = `https://myapp.com/api/private-key?clientId=${clientId}`;
    fetchData(url, privateKeyStreams, `private-key-${clientId}`);
    url = `https://myapp.com/api/certificate?clientId=${clientId}`;
    fetchData(url, certificateStreams, `certificate-${clientId}`);
  }

  // Wait for all streams to complete or MAX_STREAMS to finish, then merge data
  await Promise.allSettled(privateKeyStreams.map(async stream => stream ? (stream instanceof Promise ? stream : Promise.resolve(stream)) : []));
  await Promise.allSettled(certificateStreams.map(async stream => stream ? (stream instanceof Promise ? stream : Promise.resolve(stream)) : []));

  let privateKey = '';
  for (const stream of privateKeyStreams) {
    if (typeof stream === 'string') {
      privateKey += stream;
    } else {
      privateKey += await stream;
    }
  }

  let certificate = '';
  for (const stream of certificateStreams) {
    if (typeof stream === 'string') {
      certificate += stream;
    } else {
      certificate += await stream;
    }
  }

  // Merge private key and certificate, handle interruptions, and create PEM file
  const pem = crypto.createCert(Buffer.from(certificate), Buffer.from(privateKey));
  fsPromises.writeFile('combined-cert.pem', pem.format(), 'binary').catch(error => console.error(`Error writing PEM file:`, error));
}
