class Tensor {
public:
    explicit Tensor(int size, double mean = 0.0, double stddev = 1.0) {
        data_.resize(size);
        std::mt19937 gen(std::random_device{}());
        std::normal_distribution<double> distr(mean, stddev);
        for (auto& value : data_)
            value = distr(gen);
    }

    Tensor(const Tensor&) = delete; // Disallow copy construction
    Tensor& operator=(const Tensor&) = delete; // Disallow assignment

    Tensor(Tensor&& other) noexcept {
        data_ = std::move(other.data_);
        other.data_.clear();
    }

    Tensor& operator=(Tensor&& other) noexcept {
        data_ = std::move(other.data_);
        other.data_.clear();
        return *this;
    }

    ~Tensor() {} // Default destructor, but ensure it's virtual to support polymorphic deletion in derived classes

    const std::vector<double>& data() const { return data_; }

private:
    std::vector<double> data_;
};

class MultiDimensionalMatrix {
public:
    explicit MultiDimensionalMatrix(const std::array<int, 2>& shape, double mean = 0.0, double stddev = 1.0) {
        resize(shape);
        for (auto* tensor : tensors_)
            new (tensor) Tensor(*tensor->shape(), mean, stddev);
    }

    MultiDimensionalMatrix(MultiDimensionalMatrix&& other) noexcept {
        shape_ = other.shape_;
        tensors_.swap(other.tensors_);
    }

    MultiDimensionalMatrix& operator=(MultiDimensionalMatrix&& other) noexcept {
        if (this != &other) {
            shape_ = other.shape_;
            tensors_.swap(other.tensors_);
        }
        return *this;
    }

    ~MultiDimensionalMatrix() {
        for (auto* tensor : tensors_)
            tensor->~Tensor();
    }

