    }

    Eigen::MatrixXd& operator[](size_t i) { return *(tensors_[i]->data()); }
    const Eigen::MatrixXd& operator[](size_t i) const { return *(tensors_[i]->data()); }

private:
    struct TensorWrapper {
        std::unique_ptr<Tensor> tensor;
        std::array<int, 2> shape;
    };

    std::vector<TensorWrapper> tensors_;
    std::array<int, 2> shape_;
};
