struct Record {
    int value;
};

std::vector<long> offsets;
std::vector<int> keys;
std::vector<Record> records;
std::map<int, bool> used_keys;
std::mutex mtx;

void allocate(unsigned long minOffset, unsigned long maxOffset, unsigned int minKey, unsigned int maxKey, unsigned int recordCount) {
    offsets.resize(minOffset);
    for (long i = minOffset; i < maxOffset; ++i) {
        offsets[i] = i + 1;
    }
    keys.resize(minKey);
    for (int i = minKey; i < maxKey; ++i) {
        keys[i] = i;
        used_keys[i] = false;
    }
    records.resize(recordCount);
}

void generateRecords() {
    std::vector<int> uniqueValues;
    for (int i = *std::min_element(keys.begin(), keys.end()); i <= *std::max_element(keys.end()); ++i) {
        if (!used_keys[i]) {
            used_keys[i] = true;
            uniqueValues.push_back(i);
        }
    }

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(0, uniqueValues.size() - 1);

    std::lock_guard<std::mutex> lock(mtx);
    for (Record &record : records) {
        int index = distribution(generator);
        record.value = uniqueValues[index];
        used_keys[record.value] = true;
        uniqueValues.erase(uniqueValues.begin() + index);
    }
}

void saveData(const std::string &filename) {
    std::ofstream file(filename, std::ios::binary | std::ios::trunc);

    if (!file.is_open()) {
        std::cerr << "Could not open file for writing." << std::endl;
        return;
    }

    uint64_t offsetCount = offsets.size();
    uint32_t keyCount = keys.size();
    uint32_t recordCount = records.size();
    file.write(reinterpret_cast<const char*>(&offsetCount), sizeof(uint64_t));
    file.write(reinterpret_cast<const char*>(&keyCount), sizeof(uint32_t));
    file.write(reinterpret_cast<const char*>(&recordCount), sizeof(uint32_t));

    file.write(reinterpret_cast<const char*>(offsets.data()), offsetCount * sizeof(long));
    file.write(reinterpret_cast<const char*>(keys.data()), keyCount * sizeof(int));
    file.write(reinterpret_cast<const char*>(records.data()), recordCount * sizeof(Record));
}

void loadData(const std::string &filename) {
    std::ifstream file(filename, std::ios::binary);

    if (!file.is_open()) {
        std::cerr << "Could not open file for reading." << std::endl;
        return;
    }

    uint64_t offsetCount;
    uint32_t keyCount, recordCount;
    file.read(reinterpret_cast<char*>(&offsetCount), sizeof(uint64_t));
    file.read(reinterpret_cast<char*>(&keyCount), sizeof(uint32_t));
    file.read(reinterpret_cast<char*>(&recordCount), sizeof(uint32_t));

    offsets.resize(offsetCount);
    keys.resize(keyCount);
    records.resize(recordCount);
    file.read(reinterpret_cast<char*>(offsets.data()), offsetCount * sizeof(long));
    file.read(reinterpret_cast<char*>(keys.data()), keyCount * sizeof(int));
    file.read(reinterpret_cast<char*>(records.data()), recordCount * sizeof(Record));
}
