    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    strm.avail_in = total_in;
    strm.next_in = buffer;

    strm.avail_out = 0;
    strm.next_out = NULL;

    err = deflateInit(&strm, Z_DEFAULT_COMPRESSION);
