    int long_offsets_size, keys_size;
    if (!validate_input(scanf("%d", &long_offsets_size))) return EXIT_FAILURE;
    if (!validate_input(scanf("%d", &keys_size))) return EXIT_FAILURE;

    Record *records = allocate_records(keys_size);
    int *long_offsets = calloc(long_offsets_size, sizeof(int));
    if (!long_offsets) {
        fprintf(stderr, "Memory allocation failed.\n");
