        dataOut = std::min(static_cast<uLongf>(std::distance(itr, oss.str().end())), bufferSize - totalOut);
        memcpy(bufferPtr, itr, dataOut);
        totalOut += dataOut;
        bufferPtr += dataOut;
        itr += dataOut;
    }

    // Compress the data and write it to compressedData
    strm.next_in = reinterpret_cast<Bytef*>(buffer);
    strm.avail_in = totalOut;
    do {
        strm.next_out = reinterpret_cast<Bytef*>(&compressedData[dataOut]);
        strm.avail_out = bufferSize - dataOut;
        dataOut += deflate(&strm, Z_NO_FLUSH);
    } while (strm.avail_in != 0);
    deflateEnd(&strm);

