std::vector<Transaction> deserializeData(const std::vector<unsigned char>& compressedData) {
    // Decompress data using zlib
    uLongf totalOut = 0;
    unsigned char* buffer = new unsigned char[compressedData.size()];
    auto itr = compressedData.begin();

    uLongf totalIn = compressedData.size();
    uLongf dataIn = 0;

    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    inflateInit2(&strm, -MAX_WBITS | (WBITS_16 + 16)); // Set a higher windowbits for better compression ratio

    unsigned char* bufferPtr = reinterpret_cast<unsigned char*>(buffer);

    while (dataIn < totalIn) {
        strm.next_in = itr;
        strm.avail_in = totalIn - dataIn;
        strm.next_out = bufferPtr;
