    struct memblock* block = &manager->pool[manager->pool->count - 1];
    if (block->used >= block->capacity) {
        manager->pool->blocks = realloc(manager->pool->blocks, sizeof(*manager->pool->blocks) * ++manager->pool->count);
        block = &manager->pool->blocks[manager->pool->count - 1];
