void gen_rand_record(Record& record) {
    static std::mt19937 gen(std::random_device{}());
    record.key = gen() % KEY_MAX + 1;
    record.value = gen() % INT_MAX - (INT_MAX / 2);
    record.offset = static_cast<long>(records.size());
}

void add_record(Record& record) {
    std::unique_lock<std::mutex> lock(mtx);
    if (records.size() >= MAX_SIZE) {
        // Handle max size limit
        return;
    }
    gen_rand_record(record);
    records.push_back(record);
}

void process_records() {
    std::unique_lock<std::mutex> lock(mtx);
    auto iter = records.begin();
    while (iter != records.end()) {
        // Use external library for data processing here
        // ...
        iter = records.erase(iter);
        lock.unlock();
        std::this_thread::yield();
        lock.lock();
    }
}

int main() {
