// Function to allocate and initialize a transaction structure
transaction *init_transaction(size_t item_count) {
    transaction *transaction = malloc(sizeof(transaction));
    if (!transaction) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    transaction->item_count = item_count;
    transaction->items = calloc(item_count, sizeof(item *));
    if (!transaction->items) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(transaction);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < item_count; ++i) {
        transaction->items[i] = malloc(sizeof(item));
        if (!transaction->items[i]) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            for (size_t j = 0; j <= i; ++j)
                free(transaction->items[j]);
            free(transaction->items);
            free(transaction);
            exit(EXIT_FAILURE);
        }
        init_item(transaction->items[i]);
    }

    return transaction;
}

// Function to process the data using an external library, assuming it has a function process_data()
