        fprintf(stderr, "Error: External processing function is null\n");
        exit(EXIT_FAILURE);
    }

    process_data((const item **)transaction->items, transaction->item_count);
}

// Function to deallocate the transaction structure and its contents
void free_transaction(transaction *transaction) {
    for (size_t i = 0; i < transaction->item_count; ++i)
        free(transaction->items[i]);
    free(transaction->items);
    free(transaction);
}
