struct OctreeNode {
    float feature[8]; // Holds feature values for each octant
    size_t childCount = 0;
    std::unique_ptr<OctreeNode> children[8];
    size_t dataCapacity;
    std::vector<void*> data; // Stores data associated with this node
    std::mutex mutex;
};

class Octree {
public:
    Octree(size_t featureSize, size_t maxDepth, size_t leafNodes)
        : root_(nullptr), featureSize_(featureSize), maxDepth_(maxDepth), leafNodes_(leafNodes), dataCapacity_(featureSize_ * leafNodes_) {}

    int init() {
        if (!root_.unique()) {
            root_.reset(new OctreeNode{.dataCapacity = dataCapacity_});
            if (!root_) {
                return -1; // Memory allocation failure
            }
        }
        return 0;
    }

    void insertData(const void* data, size_t offset, size_t length) {
        auto node = root_.get();
        if (!node) {
            return; // Node not initialized or memory allocation failure
        }
        std::lock_guard<std::mutex> lock(node->mutex);

        for (size_t i = offset; i < length + offset && i < dataCapacity_; ++i) {
            node->data.push_back(data);
            if (node->childCount >= kLeafCapacity) {
                splitNode(node);
            }
        }
    }

private:
    void splitNode(OctreeNode* node) {
        std::unique_ptr<OctreeNode> newParent(new OctreeNode{.dataCapacity = dataCapacity_});
        if (!newParent) {
            return; // Memory allocation failure
        }

        std::lock_guard<std::mutex> lock(node->mutex);
        std::lock_guard<std::mutex> newLock(newParent->mutex);

        for (size_t i = 0; i < 8; ++i) {
            if (node->children[i]) {
                newParent->children[i] = std::move(node->children[i]);
            } else {
                newParent->children[i].reset(new OctreeNode{.dataCapacity = dataCapacity_});
                if (!newParent->children[i]) {
                    return; // Memory allocation failure
                }
                std::lock_guard<std::mutex> childLock(newParent->children[i]->mutex);
