        for (auto it = node->data.begin(); it != node->data.end() && it - node->data.cbegin() < kLeafCapacity; ++it) {
            auto index = getIndex((*it)->GetIndex());
            if (newParent->children[index]) {
                std::lock_guard<std::mutex> childLock(newParent->children[index]->mutex);
                newParent->children[index]->data.push_back(*it);
            } else {
                // Create a new leaf node and link it to the appropriate parent node
            }
        }

        node->childCount = kLeafCapacity;
    }

    size_t getIndex(size_t index) const {
