#include <lz4.h> // Include LZ4 library if you wish to use it for compression
#include <zlib.h> // Include zlib library if you wish to use it for compression

typedef struct data_block {
    uint64_t size;
    void* buffer;
    bool is_valid;
} DataBlock;

typedef struct entry {
    double timestamp;
    char* metadata;
    DataBlock data;
} Entry;

typedef struct node {
    Entry entry;
    struct node* next;
} Node;

Node* create_node(Entry e) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->entry = e;
    n->next = NULL;
    return n;
}

void free_node(Node* node) {
    free(node->entry.metadata);
    free(node->entry.data.buffer);
    free(node);
}

Node** create_list() {
    Node** list = (Node**)malloc(sizeof(Node*) * 100); // Initialize a list of 100 pointers for the nodes
    if (!list) return NULL;
    memset(list, 0, sizeof(Node*) * 100);
    return list;
}

void free_list(Node** list) {
    for (int i = 0; i < 100; ++i) {
        if (!list[i]) continue;
        Node* n = list[i];
        while (n) {
            Node* temp = n;
            n = n->next;
            free_node(temp);
        }
    }
    free(list);
}

