    // Allocate a new node for the entry
    Node* n = create_node((Entry){ .timestamp = timestamp, .metadata = metadata, .data = (DataBlock){ .size = size, .buffer = malloc(size), .is_valid = is_valid } });
    if (!n) return;

    // Compress the data using user-defined compression algorithm
    uint8_t* compressed_buffer = NULL;
    (*compression)(data, size, &compressed_buffer, *compressed_size);
    n->entry.data.buffer = compressed_buffer;
    n->entry.data.size = *compressed_size;

    // Add the node to the list, using a suitable data structure for efficient insertion
}

// Function to read an entry from the array, using an external compression library.
void read_entry(Node** list, int index, double* timestamp, char** metadata, uint8_t** data, uint64_t* size, bool* is_valid, void(*decompression)(uint8_t*, uint64_t, uint8_t**, int*), int* compressed_size, void* userdata) {
    // Get the node at the specified index and check for out of bounds errors
    if (index >= 100 || !list[index]) return;

    Node* n = list[index];

    *timestamp = n->entry.timestamp;
