    // Calculate the total memory required and allocate using calloc for proper initialization
    size_t memoryRequirement = get_memory_requirement(*num_readings);
    *array = (sensorReading**)malloc(memoryRequirement);
    if (*array == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Allocate memory for each sensorReading and initialize its pointer in the array
    *array = calloc(*num_readings, sizeof(sensorReading*));
