['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char* str;
    int flag;
} data_point;

struct dataset {
    void** arrays; // {double*, char**, data_point**}
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

struct cacher {
    struct dataset* datasets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
};

// Helper function for resizing array
void resize(void** array, size_t new_capacity) {
    void* new_arr = realloc(*array, new_capacity * sizeof(**array));
    if (!new_arr) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    *array = new_arr;
}

// Function to initialize and manage datasets
struct dataset* init_dataset() {
    struct dataset* ds = malloc(sizeof(*ds));
    if (!ds) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    ds->capacity = 3;
    ds->size = 0;
    ds->arrays = calloc(3, sizeof(void*));
    resize(ds->arrays[0], ds->capacity); // double
    resize(ds->arrays[1], ds->capacity); // char
    resize(ds->arrays[2], ds->capacity); // data_point
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

// Function to add new entries in dataset's arrays
void add_entry(struct dataset* ds, int array_idx, void* value) {
    pthread_mutex_lock(&ds->lock);
    if (ds->size == ds->capacity) {
        resize(ds->arrays[array_idx], ds->capacity * 2);
    }
    *(ds->arrays[array_idx] + ds->size++) = value;
    pthread_mutex_unlock(&ds->lock);
}

// Function to switch between datasets, ensuring efficient resource management
void switch_dataset(struct cacher* cache, size_t idx) {
    if (idx >= cache->count || idx < 0) {
        fprintf(stderr, "Invalid dataset index\n");
        exit(EXIT_FAILURE);
    }
    size_t i;
    for (i = 0; i < 3; ++i) {
        free(cache->datasets[idx].arrays[i]);
    }
    cache->datasets[idx] = init_dataset();
}

// Function to create and manage dataset cache, minimizing memory fragmentation
struct cacher* init_cacher(size_t capacity) {
    struct cacher* cache = malloc(sizeof(*cache));
    if (!cache) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    cache->count = 0;
    cache->capacity = capacity;
    cache->datasets = calloc(capacity, sizeof(struct dataset));
    for (size_t i = 0; i < capacity; ++i) {
        init_dataset();
    }
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Example usage with caching mechanism:
int main() {
    struct cacher* cache = init_cacher(10);
    // ... rest of your code using cached datasets ...
    pthread_mutex_destroy(&cache->lock);
    free(cache);
    return 0;
}
```

