int init_data_structures(size_t offset_size, size_t key_size, size_t record_count,
                          size_t* offsets, int* keys, record** records, int* log_level) {
    if (!(offset_size > 0 && key_size > 0 && record_count > 0)) {
        return -1; // Invalid input parameters
    }

    *offsets = malloc(offset_size * sizeof(long));
    if (*offsets == NULL) {
        return -2; // Out of memory
    }

    *keys = malloc(key_size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -2; // Out of memory
    }

    *records = malloc(record_count * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -2; // Out of memory
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i].value = rand() % 100; // Random number within range 0-99
        char str[100];
        snprintf(str, sizeof(str), "Record #%zu", i);
        (*records)[i].string = strdup(str);
        if ((*records)[i].string == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].string);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return -2; // Out of memory
        }
    }

    *log_level = 0; // Set log level to info (0) by default
    srand(time(NULL));

    return 0; // Successful memory allocation and initialization
}
