#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>
#include <hdf5.h>

// Data structure definition
typedef struct {
    double value;
    unsigned int timestamp;
    enum StatusFlag status;
} Data;

// Memory pool class definition
class MemoryPool {
public:
    MemoryPool(size_t size) : freeListHead_(nullptr), usedSize_(0), maxSize_(size) {}

    // Acquire a Data object from the memory pool
    Data* acquire() {
        if (freeListHead_) {
            Data *data = freeListHead_;
            freeListHead_ = data->next;
            data->next = nullptr;
            usedSize_++;
            return data;
        }
        if (usedSize_ < maxSize_) {
            Data* newData = static_cast<Data*>(::malloc(sizeof(Data)));
            newData->next = reinterpret_cast<Data*>(::aligned_alloc(64, sizeof(Data))); // Align to cache line size
            if (!newData->next) {
                ::free(newData);
                throw std::bad_alloc();
            }
            newData->next->next = nullptr;
            freeListHead_ = reinterpret_cast<Data*>(::aligned_alloc(64, sizeof(Data*))); // Align to cache line size
            if (!freeListHead_) {
                ::free(newData);
                throw std::bad_alloc();
            }
            freeListHead_ = newData;
            usedSize_++;
            return newData;
        }
        throw std::runtime_error("Memory pool is full");
    }

    // Release a Data object to the memory pool
    void release(Data* data) {
        if (data->next) {
            ::free(reinterpret_cast<void*>(data->next));
        }
        data->next = freeListHead_;
        freeListHead_ = data;
        usedSize_--;
    }

private:
    Data *freeListHead_;
    size_t usedSize_;
    const size_t maxSize_;
};

