        Data *dataChunk = dataPool_.acquire();
        for (size_t i = 0; i < chunkSize_; ++i) {
            dataChunk[i].value = generateData(...); // Fill the acquired Data objects with random values
            dataChunk[i].timestamp = ...; // Set timestamps according to current time or other strategy
        }
        pthread_mutex_unlock(&mutex_);
        return dataChunk;
    }

    // Release a chunk of Data objects back to the memory pool
    void releaseChunk(Data* dataChunk, size_t numItems) {
        pthread_mutex_lock(&mutex_);
        for (size_t i = 0; i < numItems; ++i) {
            dataPool_.release(&dataChunk[i]);
        }
        pthread_mutex_unlock(&mutex_);
    }

private:
    MemoryPool dataPool_;
    const size_t chunkSize_;
    pthread_mutex_t mutex_; // Thread-safe access to the data pool
};

