void addToMemory(record recordToAdd) {
    pthread_mutex_lock(&memory_lock);
    while (size == capacity) {
        pthread_cond_wait(&memory_notfull, &memory_lock);
    }
    memory[size] = recordToAdd;
    size++;
    if (size == capacity / 2) {
        resizeMemory(capacity * 2);
    }
    pthread_mutex_unlock(&memory_lock);
    pthread_cond_signal(&memory_notempty);
