    }
    record toReturn = memory[size - 1];
    size--;
    if (capacity / 4 < size) {
        resizeMemory(capacity / 2);
    }
    pthread_mutex_unlock(&memory_lock);
    pthread_cond_signal(&memory_notfull);
    return toReturn;
