        std::lock_guarded<std::mutex> lock(mtx);
        if (offset >= currentSize || offset < 0) {
            throw std::out_of_range("Invalid offset");
        }
        return records[offset];
    }

    void addRecord(Record record) {
        std::lock_guarded<std::mutex> lock(mtx);
        if (currentSize >= recordCapacity) {
            resize();
        }
        records[currentSize] = record;
        currentSize++;
    }

private:
