typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    size_t capacity;
    size_t count;
    record* data;
    pthread_mutex_t mutex;
    sem_t sem;
    void* logfile;
    char* config_path;
} record_manager;

record_manager* create_record_manager(const char* config_path) {
    record_manager* manager = malloc(sizeof(record_manager));
    manager->config_path = strdup(config_path);
    // Initialize mutex and semaphore for thread safety
    pthread_mutex_init(&(manager->mutex), NULL);
    sem_init(&(manager->sem), 0, 1);
    // Load configuration and memory allocation settings
    load_config(manager->config_path);
    // Allocate memory for records according to loaded config
    manager->capacity = get_capacity();
    manager->count = 0;
    manager->data = mmap(NULL, manager->capacity * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (manager->data == MAP_FAILED) {
        perror("mmap failed");
        free(manager);
        return NULL;
    }
    // Open log file for recording operations and errors
    manager->logfile = fopen("record_manager.log", "w+");
    if (manager->logfile == NULL) {
        perror("fopen failed");
        munmap(manager->data, manager->capacity * sizeof(record));
        free(manager);
        return NULL;
    }
    return manager;
}

void destroy_record_manager(record_manager* manager) {
    fclose(manager->logfile);
    munmap(manager->data, manager->capacity * sizeof(record));
    free(manager->config_path);
    free(manager);
}

size_t get_next_index(record_manager* manager) {
    size_t next_index;
    pthread_mutex_lock(&(manager->mutex));
    if (manager->count >= manager->capacity) {
        sem_wait(&(manager->sem));
    }
    next_index = manager->count;
    manager->count++;
    pthread_mutex_unlock(&(manager->mutex));
    return next_index;
}

void push_record(record_manager* manager, const record* record) {
    size_t index = get_next_index(manager);
    memcpy((manager->data + (index * sizeof(record))), record, sizeof(record));
}

record pop_record(record_manager* manager) {
    record empty_record = {0};
    size_t index;
    pthread_mutex_lock(&(manager->mutex));
    if (manager->count == 0) {
        // Implement pagination and efficient data loading techniques here
        // Call external library functions for data processing asynchronously
        record loaded_record = load_data();
        push_record(manager, &loaded_record);
        index = get_next_index(manager);
    } else {
        index = manager->count - 1;
        manager->count--;
    }
    pthread_mutex_unlock(&(manager->mutex));
    return (manager->data + (index * sizeof(record)));
}

