#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long id;
    double amount;
    char description[256];
} transaction;

// External financial processing library interface
extern void process_transaction(transaction* tx);

// Thread-safe queue structure for transactions
typedef struct QueueNode {
    transaction tx;
    struct QueueNode *next;
} QueueNode;

// Synchronize access to the queue using a mutex
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
QueueNode* head = NULL;
QueueNode* tail = NULL;

void enqueue(transaction tx) {
    QueueNode* new_node = (QueueNode*) malloc(sizeof(QueueNode));
    if (!new_node) {
        fprintf(stderr, "Out of memory!\n");
        exit(1);
    }

    new_node->tx = tx;
    new_node->next = NULL;

    pthread_mutex_lock(&queue_mutex);
    if (tail != NULL) {
        tail->next = new_node;
        tail = new_node;
    } else {
        head = tail = new_node;
    }
    pthread_mutex_unlock(&queue_mutex);
}

transaction* dequeue() {
    transaction* tx = NULL;
    QueueNode* old_head;

    pthread_mutex_lock(&queue_mutex);
    if (head != NULL) {
        old_head = head;
        head = head->next;
        if (head == NULL) tail = NULL;
        tx = &old_head->tx;
    }
    pthread_mutex_unlock(&queue_mutex);

    return tx;
}

void process_transactions(int n_threads, long max_queue_size) {
    pthread_t threads[n_threads];

    for (int i = 0; i < n_threads; ++i) {
        int rc = pthread_create(&threads[i], NULL, process_transaction_routine, NULL);
        if (rc) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            exit(1);
        }
    }

    long total_processed = 0;
    transaction* tx;
    double start_time = get_current_time();

    while ((tx = dequeue()) != NULL && total_processed < max_queue_size) {
        // Logging and performance monitoring can be added here
        process_transaction(tx);
        ++total_processed;
    }

    for (int i = 0; i < n_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    double elapsed_time = get_current_time() - start_time;
    printf("Processed %ld transactions in %.4fs\n", total_processed, elapsed_time);
}

// Implement the external financial processing library interface function here
void process_transaction_routine(void* arg) {
    // Use 'enqueue' to insert transactions into the queue for processing
    while ((transaction*) arg = dequeue()) {
        // Process the transaction and handle numerical precision, errors, etc.
        // ...
    }
}
