public class DynamicValueGenerator
{
    private readonly List<(double min, double max, bool isMinInclusive, bool isMaxInclusive)> _ranges;

    public DynamicValueGenerator()
    {
        _ranges = new List<(double, double, bool, bool)>();
    }

    public void AddRange(double min, double max, bool isMinInclusive = true, bool isMaxInclusive = true)
    {
        if (min > max)
            throw new ArgumentException("Invalid range definition: minimum value must be smaller than maximum value.");

        _ranges.Add((min, max, isMinInclusive, isMaxInclusive));
    }

    public int GetRandomInt(int index)
    {
        if (index >= _ranges.Count)
            throw new IndexOutOfRangeException("The specified range index does not exist.");

        var (min, max, minInclusive, maxInclusive) = _ranges[index];
        double randomValue;

        if (maxInclusive && minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min) + min;
        else if (!maxInclusive && !minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min) + min + 1;
        else if (!maxInclusive && minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min) + min;
        else // if (maxInclusive && !minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min) + min;

        return Convert.ToInt32(Math.Floor(randomValue));
    }

    public double GetRandomFloat(int index)
    {
        if (index >= _ranges.Count)
            throw new IndexOutOfRangeException("The specified range index does not exist.");

        var (min, max, minInclusive, maxInclusive) = _ranges[index];
        double randomValue;

        if (maxInclusive && minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min) + min;
        else if (!maxInclusive && !minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min);
        else if (!maxInclusive && minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min + 1) + min;
        else // if (maxInclusive && !minInclusive)
            randomValue = Common.Random.NextDouble() * (max - min + 1) + min;

        return randomValue;
    }

    public void RemoveRange(int index)
    {
        if (index >= _ranges.Count)
            throw new IndexOutOfRangeException("The specified range index does not exist.");

        _ranges.RemoveAt(index);
    }

    public override string ToString()
    {
        var builder = new System.Text.StringBuilder();

        if (_ranges.Count > 0)
        {
            int i = 1;
            builder.AppendLine("Defined ranges:");
            foreach (var range in _ranges)
            {
                builder.AppendFormat("Range {0}: [{(1:F2)}, {2:F2}]", i++, range.min, range.max);
