    if (it != events.end()) {
        auto nextIt = std::next(it);
        eventListMutex.lock();
        gameEvents.insert(nextIt, trigger + "trigger");
        eventListMutex.unlock();
    } else {
        eventListMutex.lock();
        gameEvents.push_back(trigger + "trigger");
        eventListMutex.unlock();
