            }
            outputFile.close();
        } else {
            std::cerr << "Failed to open state file\n";
        }
    });

    serviceThread.detach();

    auto actionSelector = [cooldownPeriod]() mutable {
        static int lastActionTime = 0;
        if (std::chrono::steady_clock::now().time_since_epoch().count() - lastActionTime > cooldownPeriod) {
            const char* actions[2] = {"Attack", "Defend"};
            int index = rand() % 2;
            std::cout << "Character performs: " << actions[index] << "\n";
            lastActionTime = std::chrono::steady_clock::now().time_since_epoch().count();
            return actions[index];
        } else {
            return "";
        }
    };

    messageQueue.push([actionSelector]() { actionSelector(); });
}
