public class PerformanceDataCollector
{
    private const int DefaultInterval = 60; // seconds
    private const int MinCacheSize = 100;
    private const double MaxHitRateTarget = 0.95;

    public string NodeId { get; }
    public TimeSpan Interval { get; set; }
