    public Cache CachedMetrics { get; private set; }

    public PerformanceDataCollector(string nodeId = null)
    {
        NodeId = string.IsNullOrEmpty(nodeId) ? GenerateUniqueNodeId() : nodeId;
        Interval = TimeSpan.FromSeconds(DefaultInterval);
        CachedMetrics = new Cache(MinCacheSize);
    }

    public void Start()
    {
        Task.Run(CollectAndLogMetrics);
    }

    private async Task CollectAndLogMetrics()
    {
        while (true)
        {
            await CollectMetricsAsync();
            LogMetrics();
            await Task.Delay((long)Interval.TotalMilliseconds);
        }
    }

    public void RecordMetric(string metricName, double value)
    {
        if (!Metrics.ContainsKey(metricName)) Metrics[metricName] = new Metric();
        Metrics[metricName].AddDataPoint(value);
        UpdateCacheIfNeeded(metricName);
    }

    public void SetInterval(TimeSpan interval)
    {
        if (interval < TimeSpan.Zero) throw new ArgumentOutOfRangeException("Interval must be a non-negative value");
        Interval = interval;
    }

    private void UpdateCacheIfNeeded(string metricName)
    {
        if (!CachedMetrics.IsFull) CachedMetrics.AddOrUpdate(metricName, Metrics[metricName].DataPoints);
        else EvictLeastRecentlyUsed();
    }

