        // Implement eviction policy based on LRU or another strategy of choice.
    }

    private string GenerateUniqueNodeId()
    {
        return $"{Guid.NewGuid():N}";
    }
}

public class Metric
{
    public List<double> DataPoints { get; set; } = new List<double>();

    public void AddDataPoint(double value)
    {
        DataPoints.Add(value);
        if (DataPoints.Count > 1000) DataPoints.RemoveAt(0); // Trim old data points to maintain recent history.
    }
}

public class Cache
{
    private readonly Dictionary<string, List<double>> _cache;
    private readonly int _sizeLimit;
    private readonly EvictionPolicy _evictionPolicy;

    public Cache(int sizeLimit = MinCacheSize, EvictionPolicy evictionPolicy = EvictionPolicy.LeastRecentlyUsed)
    {
        _sizeLimit = Math.Max(1, sizeLimit);
        _evictionPolicy = evictionPolicy;
        _cache = new Dictionary<string, List<double>>();
    }

    public bool IsFull => _cache.Count >= _sizeLimit;

    public void AddOrUpdate(string key, IEnumerable<double> values)
    {
        if (_cache.ContainsKey(key)) _cache[key] = new List<double>(values);
        else _cache.Add(key, new List<double>(values));
        UpdateCacheSize();
    }

    private void EvictLeastRecentlyUsed()
    {
        switch (_evictionPolicy)
        {
            case EvictionPolicy.LeastRecentlyUsed:
                _cache.OrderByDescending(x => x.Value[^1]).First().Value.Clear();
                break;
            // Add other eviction policies as needed.
            default:
                throw new NotSupportedException("Invalid EvictionPolicy specified.");
        }
    }

    private void UpdateCacheSize()
    {
        _cache.RemoveWhere(x => x.Value.Count > _sizeLimit);
    }
}

public enum EvictionPolicy
{
    LeastRecentlyUsed,
    // Add other eviction policies as needed.
}
