// Custom logging function with thread safety using pthread_mutex_t
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
void log(const char *message) {
    time_t now;
    struct tm* local;

    time(&now);
    local = localtime(&now);

    pthread_mutex_lock(&log_mutex);
    printf("[%02d:%02d:%02d] [INFO]: %s\n",
           local->tm_hour, local->tm_min, local->tm_sec, message);
    pthread_mutex_unlock(&log_mutex);
}

// Custom error handling function for email API
