['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    long value;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

Node** create_linked_list(int size) {
    Node** list = malloc(sizeof(Node*) * size);
    for (size_t i = 0; i < size; ++i) {
        list[i] = NULL;
    }
    return list;
}

long get_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

bool insert_record(Node** list, int key, long value) {
    for (size_t i = 0; i < array_size; ++i) {
        Node* current = list[i];
        while (current != NULL) {
            if (current->data.key == key) {
                return false; // Key already exists, fail insertion
            }
            current = current->next;
        }
    }

    for (size_t i = 0; i < array_size; ++i) {
        if (!list[i]) {
            list[i] = malloc(sizeof(Node));
            if (!list[i]) {
                perror("Memory allocation failed");
                return false; // Failed to allocate memory, fail insertion
            }
            list[i]->data.key = key;
            list[i]->next = NULL;
            list[i]->value = get_random_value(0, LONG_MAX);
            return true; // Successfully inserted the record
        }
    }

    Node** new_node_index = &list[(key % array_size)];
    *new_node_index = malloc(sizeof(Node));
    if (!*new_node_index) {
        perror("Memory allocation failed");
        return false; // Failed to allocate memory, fail insertion
    }
    (*new_node_index)->data.key = key;
    (*new_node_index)->value = get_random_value(0, LONG_MAX);
    (*new_node_index)->next = list[(*new_node_index - array_size)];
    list[(*new_node_index - array_size)] = *new_node_index;
    return true; // Successfully inserted the record
}

void free_linked_list(Node** list, int size) {
    for (size_t i = 0; i < size; ++i) {
        Node* temp = list[i];
        while (temp) {
            Node* next = temp->next;
            free(temp);
            temp = next;
        }
    }
}
```

