#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long timestamp;
    float reading;
    char type;
} sensor_data;

const char VALID_TYPES[] = {'T', 'P', 'H'}; // Temperature, Pressure, Humidity

#define MAX_RECORDS 100000
size_t num_records = 0;
sensor_data* data = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_record(long timestamp, float reading, char type) {
    if (num_records == MAX_RECORDS) return;

    pthread_mutex_lock(&mutex);
    if (num_records >= MAX_RECORDS / 2) {
        sensor_data* new_data = realloc(data, sizeof(sensor_data) * (MAX_RECORDS * 2));
        if (!new_data) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        data = new_data;
    }

    sensor_data* current = &data[num_records];
    current->timestamp = timestamp;
    current->reading = reading;
    current->type = type;

    if (num_records % 1000 == 0) compact(); // Compact every 1000 records
    num_records++;
    pthread_mutex_unlock(&mutex);
}

void compact() {
    pthread_mutex_lock(&mutex);
    size_t new_size = num_records * (MAX_RECORDS / num_records) + MAX_RECORDS;
    sensor_data* new_data = realloc(data, sizeof(sensor_data) * new_size);
    if (!new_data) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    data = new_data;

    for (size_t i = 0; i < num_records; ++i) {
        sensor_data* src = &data[i];
        if (i < num_records - MAX_RECORDS / 2) // Keep the most recent records
            memcpy(&data[i], src, sizeof(sensor_data));
    }

    data += num_records - MAX_RECORDS / 2;
    num_records = MAX_RECORDS / 2;
    pthread_mutex_unlock(&mutex);
}

