typedef struct {
    long value;
} offset_t;

typedef struct {
    int key;
    offset_t* data;
} record_t;

offset_t* init_offsets(size_t size) {
    offset_t *offsets = malloc(sizeof(offset_t) * size);
    if (!offsets) return NULL;

    // Initialize with unique pointers to a contiguous block
    void *mem = malloc((size_t)(size * sizeof(long)));
    if (!mem) {
        free(offsets);
        return NULL;
    }

    offsets[0].value = (long)mem;
    for (size_t i = 1; i < size; ++i) {
        offsets[i].value += sizeof(long) * i;
    }

    return offsets;
}

record_t* init_records(size_t num_keys, size_t min, size_t max) {
    int keys[num_keys];
    record_t *records = malloc(sizeof(record_t) * num_keys);
    if (!records) return NULL;

    // Generate unique random keys
    for (size_t i = 0; i < num_keys; ++i) {
        bool found = false;
        int key;
        do {
            key = rand() % (max - min + 1) + min;
        } while (found && key == keys[key]);
        keys[key] = true;
    }

    // Initialize records with random int values and their corresponding offsets
    for (size_t i = 0; i < num_keys; ++i) {
        records[i].key = keys[i];
        records[i].data = ((offset_t*)((long)keys[i] - sizeof(int))) + 1;
    }

    return records;
}

record_t* resize_records(record_t *records, size_t new_size) {
    if (new_size <= records) return records;

    // Reallocate and move existing records
    record_t *new_records = realloc(records, sizeof(record_t) * new_size);
    if (!new_records) return NULL;

    for (size_t i = 0; i < records && i < new_size; ++i) {
        new_records[i] = records[i];
    }

    // Initialize additional records with random int values and their corresponding offsets
    for (size_t i = records; i < new_size; ++i) {
        records[i].key = rand() % (max - min + 1) + min;
        records[i].data = ((offset_t*)((long)records[i].key - sizeof(int))) + 1;
    }

    return new_records;
}

record_t* create_arrays(size_t num_offsets, size_t num_keys, size_t min, size_t max) {
    offset_t *offsets = init_offsets(num_offsets);
    if (!offsets) return NULL;

    record_t *records = init_records(num_keys, min, max);
    if (!records) {
        free(offsets);
        return NULL;
    }

    return records;
}
