['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int key;
    long offset;
} record;

struct mem_block {
    void* data;
    size_t size;
    struct mem_block* next;
};

struct mem_allocator {
    struct mem_block* free_list;
    pthread_mutex_t lock;
};

struct mem_allocator allocator = { .free_list = NULL };

void init_mem_allocator() {
    pthread_mutex_init(&allocator.lock, NULL);
}

void* mem_alloc(size_t size) {
    struct mem_block* current = &allocator.free_list;
    void* result = NULL;

    pthread_mutex_lock(&allocator.lock);
    while (current != NULL && current->size < size) {
        current = current->next;
    }

    if (current == NULL) {
        current = malloc(sizeof(struct mem_block));
        if (current == NULL) {
            pthread_mutex_unlock(&allocator.lock);
            return NULL;
        }
        current->size = 0;
        current->next = allocator.free_list;
        allocator.free_list = current;
    }

    result = ((char*)current) + current->size;
    current->size -= size;

    if (current->size == 0) {
        free(current);
        current = NULL;
    }

    pthread_mutex_unlock(&allocator.lock);

    return result;
}

void mem_free(void* ptr) {
    struct mem_block* current = allocator.free_list;
    struct mem_block* previous = NULL;

    pthread_mutex_lock(&allocator.lock);

    while (current != NULL && current->next != NULL) {
        if ((char*)current->data + current->size == ptr) {
            if (previous == NULL) {
                allocator.free_list = current->next;
            } else {
                previous->next = current->next;
            }

            current->size += sizeof(struct mem_block);
            current->data = ptr;
            break;
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&allocator.lock);
}

void* records_array(size_t size) {
    return mem_alloc(sizeof(record)*size);
}

void process_batch(size_t size) {
    record* records = (record*)records_array(size);
    int* keys = (int*)mem_alloc(sizeof(int)*size);
    long* offsets = (long*)mem_alloc(sizeof(long)*size);

    // Initialize and fill data structures with unique random numbers.
    // ...

    // Deallocate memory when done.
    mem_free(records);
    mem_free(keys);
    mem_free(offsets);
}

void init() {
    srand(time(NULL));
    init_mem_allocator();
}
