// Custom memory management strategy using a slab allocator for efficient allocation and minimizing overhead
#define ALIGN_MASK (sizeof(Node) - 1)
#define SLAB_SIZE (64 * (ALIGN_MASK + sizeof(Node)))

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Node *slabs[SLAB_SIZE / sizeof(Node)]; // Array of slabs
size_t count = 0; // Number of used nodes

void init_memory() {
    for (size_t i = 0; i < SLAB_SIZE / sizeof(Node); ++i) {
        slabs[i] = mmap(NULL, SLAB_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (slabs[i] == MAP_FAILED) {
            fprintf(stderr, "Error: Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
    }
}

Node* get_node() {
    pthread_mutex_lock(&mutex);
    Node *current_slab = slabs[count / sizeof(Node)];
    if (current_slab + (count % sizeof(Node)) >= slabs[SLAB_SIZE / sizeof(Node)]) {
        init_memory();
        current_slab = slabs[count / sizeof(Node)];
    }
    Node *node = current_slab + count % sizeof(Node);
    node->next = NULL;
    ++count;
    pthread_mutex_unlock(&mutex);
    return node;
}

