```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class LargeDataProcessor {
    private static final int REFRESH_INTERVAL_SECONDS = 60;

    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            throw new IllegalArgumentException("Please provide the configuration file path.");
        }

        String configFilePath = args[0];

        ProcessBuilder pb = new ProcessBuilder();
        pb.command("/path/to/process_large_data.c"); // Replace this with your utility's path
        pb.directory(new File("."));
        Map<String, String> env = pb.environment();
        env.put("CONFIG_FILE", configFilePath);

        Process process = pb.start();

        InputStream is = process.getInputStream();
        InputStream es = process.getErrorStream();

        Executors.newSingleThreadReader(is).run();
        Executors.newSingleThreadReader(es).run();

        ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);
        executor.scheduleAtFixedRate(() -> {
            process.getOutputStream().close();
            process.destroyForcibly();
            Files.newInputStream(Paths.get(configFilePath)).close();
            process = pb.start();
            is = process.getInputStream();
            es = process.getErrorStream();
        }, REFRESH_INTERVAL_SECONDS, REFRESH_INTERVAL_SECONDS, TimeUnit.SECONDS);

        process.waitFor();

        executor.shutdownNow();
    }
}
