Next, create a shared memory manager (SharedMemoryManager.h) to handle concurrent access safely:

```cpp
#ifndef SHAREDMEMORYMANAGER_H
#define SHAREDMEMORYMANAGER_H

#include <sys/mman.h>
#include <vector>
#include <pthread.h>

class SharedMemoryManager {
public:
    SharedMemoryManager(size_t recordSize, size_t numRecords);
    ~SharedMemoryManager();
    Record* getData() const;
private:
    void* m_sharedMemory;
    size_t m_recordSize;
    size_t m_numRecords;
};

#endif // SHAREDMEMORYMANAGER_H
```

Create the implementation file (SharedMemoryManager.cpp) for the SharedMemoryManager class:

```cpp
#include "SharedMemoryManager.h"

#ifdef __linux__
#define PAGE_SIZE sysconf(_SC_PAGE_SIZE)
#else
#define PAGE_SIZE 4096
#endif

SharedMemoryManager::SharedMemoryManager(size_t recordSize, size_t numRecords) :
    m_recordSize(recordSize),
    m_numRecords(numRecords) {
    size_t sharedMemorySize = m_recordSize * m_numRecords + sizeof(pthread_mutex_t);
    void* shmAddress = mmap(NULL, sharedMemorySize, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shmAddress == MAP_FAILED) {
        throw std::runtime_error("Failed to map shared memory");
    }

    Record* data = static_cast<Record*>(shmAddress);
    for (size_t i = 0; i < m_numRecords; ++i) {
        new (data + i) Record();
    }

    pthread_mutex_init(static_cast<pthread_mutex_t*>(shmAddress), nullptr);
    m_sharedMemory = shmAddress;
}

SharedMemoryManager::~SharedMemoryManager() {
    if (munmap(m_sharedMemory, sizeof(Record) * m_numRecords + sizeof(pthread_mutex_t)) == -1) {
        throw std::runtime_error("Failed to unmap shared memory");
    }
}

Record* SharedMemoryManager::getData() const {
    return static_cast<Record*>(m_sharedMemory);
}
```

