};

void* alloc_mem(int size, const char *type) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate %s memory\n", type);
        pthread_exit(NULL);
    }
    return ptr;
}

void init_arrays(int *offsets, long size_offsets, int *keys, long size_keys, struct Record **records, long size_records) {
    offsets = alloc_mem(size_offsets * sizeof(int), "offset");
    keys = alloc_mem(size_keys * sizeof(int), "key");
    records = calloc(size_records, sizeof(struct Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate record memory\n");
        pthread_exit(NULL);
    }
}

void populate_arrays(int *offsets, long size_offsets, int *keys, long size_keys, struct Record **records, long size_records) {
