    for (long i = 0; i < size_records; ++i) {
        offsets[i] = rand() % size_offsets;
        keys[i] = rand() % size_keys;
        records[i]->value = rand() % INT_MAX;
    }
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void thread_function(int id) {
    for (long i = id; i < size_records; i += num_threads) {
        pthread_mutex_lock(&mutex);
            // Access and modify records, keys, and offsets here
        pthread_mutex_unlock(&mutex);
    }
}

int main(int argc, char **argv) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s [num_threads] [size_offsets] [size_keys] [size_records]\n", argv[0]);
        return -1;
    }

    long num_threads = atol(argv[1]);
    long size_offsets = atol(argv[2]);
    long size_keys = atol(argv[3]);
    long size_records = atol(argv[4]);

    // Initialize and populate arrays, and create threads
    int *offsets;
    int *keys;
    struct Record **records;
    init_arrays(offsets, size_offsets, keys, size_keys, records, size_records);
    populate_arrays(offsets, size_offsets, keys, size_keys, records, size_records);

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, &thread_function, (void*)i)) {
            fprintf(stderr, "Failed to create thread\n");
            return -1;
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Failed to join thread\n");
            return -1;
        }
    }

    // Cleanup and exit
