[' Below is a simple implementation using C++17 with an unordered_map (hash table) for fast lookup times and pthreads for multi-threaded access. The code also uses jsoncpp library for parsing JSON configuration files.

```cpp
#include <iostream>
#include <fstream>
#include <json/json.h>
#include <unordered_map>
#include <pthread.h>
#include <vector>
#include <cstdlib>
#include <sstream>
#include <string>
#include <sys/mman.h>

struct Entry {
    int key;
    long offset;
    std::string buffer;
};

class Collection {
public:
    Collection(const std::string& json_file, size_t max_entries);
    ~Collection();
    Entry* get(int key);
    void cleanup();

private:
    std::unordered_map<int, Entry*> entries;
    pthread_mutex_t mutex;
    size_t max_entries;
};

Collection::Collection(const std::string& json_file, size_t max_entries) {
    std::ifstream ifs(json_file);
    Json::CharReaderBuilder builder;
    Json::CharReader* reader = builder.newCharReader();
    Json::Value root;
    size_t num_entries = 0;

    pthread_mutex_init(&mutex, nullptr);
    max_entries = (max_entries > 10000) ? 10000 : max_entries;

    ifs.seekg(0, std::ios::end);
    size_t length = ifs.tellg();
    ifs.seekg(0, std::ios::beg);
    char* json_string = static_cast<char*>(mmap(nullptr, length + 1, PROT_READ, MAP_PRIVATE, fileno(ifs.rdbuf()), 0));
    ifs.close();

    Json::CharReaderCallback cb{[](const unsigned char* c, size_t s) {
        return static_cast<Json::CharReaderDelegate&>(*this).parse(c, c + s);
    }, static_cast<Collection*>(this)};

    bool parsing_success = reader->parse(json_string, json_string + length, &root, &cb);
    if (!parsing_success || root.isNull()) {
        std::cerr << "Error while parsing JSON file" << std::endl;
        free(json_string);
        return;
    }

    for (const auto& entry : root) {
        int key = static_cast<int>(entry.second["key"].asInt());
        long offset = entry.second["offset"].asLong();
        const char* buffer = entry.second["buffer"].asCString();

        if (key < 0 || key >= max_entries) {
            std::cerr << "Invalid key: " << key << std::endl;
            continue;
        }

        Entry* e = new Entry{key, offset, buffer};
        pthread_mutex_lock(&mutex);
        entries[key] = e;
        pthread_mutex_unlock(&mutex);
    }

    free(json_string);
}

Collection::~Collection() {
    for (auto& entry : entries) {
        delete entry.second;
    }
    pthread_mutex_destroy(&mutex);
}

Entry* Collection::get(int key) {
    if (key < 0 || key >= max_entries) {
        throw std::out_of_range("Invalid key");
    }

    auto iter = entries.find(key);
    if (iter != entries.end()) {
        pthread_mutex_lock(&mutex);
        Entry* e = iter->second;
        pthread_mutex_unlock(&mutex);
        return e;
    }

    return nullptr;
}

void Collection::cleanup() {
    for (auto& entry : entries) {
        delete entry.second;
    }
    entries.clear();
    pthread_mutex_destroy(&mutex);
}
```

This implementation provides a multi-threaded dynamic collection of `struct Entry` objects, managed from a JSON configuration file. The hash table ensures fast lookup times for specific entries based on their integer keys, and the mutex lock protects access to shared data when multiple threads are involved. The cleanup function properly releases all allocated resources.']

