3. Caching mechanism (simple LRU cache)

```cpp
#include <unordered_map>
#include <list>

class LRUCache {
public:
    LRUCache(size_t capacity) : _capacity(capacity), _cache() {}

    void access(int key) {
        auto it = _cache.find(key);
        if (it != _cache.end()) {
            _accessList.splice(_accessList.begin(), _accessList, it->second);
            it->second = &_data[it->first];
        }
    }

    Record& get(int key) {
        auto it = _cache.find(key);
        if (it != _cache.end())
            return *it->second;

        Record* newRec = &_data[key];
        // Load the record from data storage here
        _accessList.push_back(newRec);
        _cache[key] = newRec;
        if (_cache.size() > _capacity) {
            auto evictedKey = _accessList.back()->key;
            _cache.erase(evictedKey);
            _accessList.pop_back();
        }
        return *newRec;
    }

private:
    size_t _capacity;
    std::unordered_map<int, Record*> _cache;
    std::list<Record*> _data;   // Stores the actual records
    std::list<Record*> _accessList;  // Maintains the LRU order of accesses
};
