#include <sys/mman.h> // For memory mapping file
#include <stdbool.h>

// Metadata structure for each record
struct metadata {
    time_t last_accessed;
    size_t access_count;
};

// Record structure with unique key, offset, and metadata
struct record {
    int key;
    long offset;
    struct metadata meta;
};

// Global mutex for thread safety
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache layer for records
GSlabCache *cache;

// External key generation service (assume it returns an int)
int generate_key();

// Function to load record data from external storage
void load_record(struct record* rec);

// Function to save record data to external storage
void save_record(struct record* rec);

// Initialize a dynamically allocated array of records, supporting high concurrency and scalability
void init_records(size_t num_records, size_t cache_capacity) {
    pthread_mutex_t *per_record_locks = malloc(num_records * sizeof(pthread_mutex_t));
    struct record* records = calloc(num_records, sizeof(struct record));

    // Initialize the cache layer with the given capacity
    cache = gslab_cache_create(cache_capacity);

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_init(&per_record_locks[i], NULL);

        // Generate a unique key, load record data from external storage if it exists, and initialize metadata
        records[i].key = generate_key();
        records[i].offset = load_from_storage(records[i].key);
        records[i].meta.last_accessed = time(NULL);
        records[i].meta.access_count = 1;

        // Save the record to external storage if it doesn't exist yet
        if (records[i].offset == -1) {
            save_record(&records[i]);
        }

        // Map the record data into memory for efficient access
        void* mapped_data = mmap(NULL, sizeof(struct record), PROT_READ | PROT_WRITE, MAP_SHARED, open("storage.bin", O_RDWR), MAP_FAILED);
        if (mapped_data == MAP_FAILED) {
            perror("mmap");
            exit(1);
        }
        struct record* mapped_rec = (struct record*) mapped_data + (i * sizeof(struct record));
        memcpy(mapped_rec, &records[i], sizeof(struct record));
    }

    // Cache the records in the cache layer for efficient retrieval
    size_t num_cached = 0;
    for (size_t i = 0; i < num_records && num_cached < cache_capacity; ++i) {
        if (!gslab_cache_insert(cache, records[i].key, &records[i])) {
            num_cached++;
        }
    }

    // Free the local copies of the records and their locks
    free(per_record_locks);
}
