    time_t timestamp;
    int user_id;
    char buffer[128];
} Session;

Connection* initialize_connections(size_t num_connections) {
    Connection *connections = malloc(num_connections * sizeof(Connection));
    if (!connections) {
        perror("Memory allocation failed for connections");
        return NULL;
    }

    Session *sessions = malloc(num_connections * sizeof(Session));
    if (!sessions) {
        free(connections);
        perror("Memory allocation failed for sessions");
        return NULL;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (size_t i = 0; i < num_connections; ++i) {
        connections[i].id = i;
        connections[i].session = &sessions[i];
        pthread_mutex_init(&connections[i].lock, &attr);

        char prefix[] = "conn_";
        size_t len = strlen(prefix);
        strncpy(connections[i].buffer, prefix, len);
        sprintf(connections[i].buffer + len, "%ld", i);

        char session_prefix[] = "ses_";
        len = strlen(session_prefix);
        strncpy(sessions[i].buffer, session_prefix, len);
        for (size_t j = 0; j < 128 - len; ++j) {
            sessions[i].buffer[len + j] = rand() % 26 + 'a';
        }
    }

    pthread_mutexattr_destroy(&attr);
    return connections;
}
