int process_data(Transaction** transactions, size_t* transaction_count, const char termination_character, const char* names[], size_t name_count) {
    int max_value = INT_MIN;
    size_t allocated_transactions = 16;
    size_t current_transactions = 0;
    Transaction* transactions_arr = calloc(allocated_transactions, sizeof(Transaction));

    if (!transactions_arr) {
        log_error("Memory allocation failed");
        return -1;
    }

    for (;;) {
        Transaction* transaction = &transactions_arr[current_transactions];

        double value_d;
        float value_f;
        char c;
        size_t name_index = 0;

        if (scanf("%f%lf %c", &value_f, &value_d, &c) != 3 || c != termination_character) {
            log_error("Invalid data received");
            free(transactions_arr);
            return -1;
        }

        if (!validate_number(value_d, DBL_MAX)) {
            log_error("Double value overflow detected");
            free(transactions_arr);
            return -1;
        }

        if (validate_number(value_f, FLT_MAX)) {
            initialize_transaction(transaction, names[name_index % name_count]);
            transaction->value_f = value_f;
            transaction->value_d = value_d;

            if (max_value < value_d) {
                max_value = value_d;
            }

            if (current_transactions == allocated_transactions) {
                Transaction* new_arr = realloc(transactions_arr, current_transactions * 2 * sizeof(Transaction));

                if (!new_arr) {
                    log_error("Memory allocation failed");
                    free(transactions_arr);
                    return -1;
                }

                transactions_arr = new_arr;
                allocated_transactions *= 2;
            }

            current_transactions++;
        }
    }

    // Process and print the maximum value, free memory, etc. (depending on your requirements)

    return 0;
}
