    Cache cache;
    cache.Store(context.ConnectionInfo.title + "_" + fileKey, metadataJson.toStyledString(), time(NULL) + 60 * 60); // Cache the metadata for an hour

    std::string cachedMetadata = cache.Retrieve(context.ConnectionInfo.title + "_" + fileKey);

    if (!cachedMetadata.empty()) {
        response["metadata"] = Json::readString(cachedMetadata, NULL, false);
    } else {
