typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct MemoryBlock {
    void *data;
    size_t capacity;
    size_t length;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryBlock* memory_pool = NULL;
pthread_mutex_t memory_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

Record* create_record() {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    record->value = rand() % 100 + 1; // Random value within range [1, 100] to prevent overflow
    return record;
}

MemoryBlock* allocate_memory(size_t size) {
    MemoryBlock *new_block = malloc(sizeof(MemoryBlock));
    if (!new_block) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    new_block->capacity = size;
    new_block->length = 0;
    new_block->data = malloc(size);
    if (!new_block->data) {
        free(new_block);
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    new_block->next = memory_pool;
    memory_pool = new_block;
    return new_block;
}

void free_memory(MemoryBlock *block) {
    if (block->data) {
        free(block->data);
    }
    free(block);
}

void* get_memory() {
    pthread_mutex_lock(&memory_pool_mutex);
    MemoryBlock *temp = memory_pool;
    memory_pool = memory_pool->next;
    pthread_mutex_unlock(&memory_pool_mutex);

    void *data = temp->data;
    temp->length = 0;
    return data;
}

void return_memory(void *ptr, size_t length) {
    pthread_mutex_lock(&memory_pool_mutex);
    MemoryBlock *block = (MemoryBlock *)((char *)memory_pool - sizeof(MemoryBlock));
    block->length = length;
    pthread_mutex_unlock(&memory_pool_mutex);
}

