    manager->data = malloc(initial_capacity * sizeof(Record));
    if (!manager->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void memory_manager_destroy(struct MemoryManager* manager) {
    size_t i;
    for (i = 0; i < manager->size; ++i) {
        destroy_record(manager->data + i);
    }
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
}

struct MemoryManager* create_memory_manager(size_t initial_capacity, EVP_CIPHER_CTX* cipher_ctx, EVP_MD_CTX* md_ctx) {
    struct MemoryManager* manager = malloc(sizeof(struct MemoryManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    init_memory_manager(manager, initial_capacity);
    manager->cipher_ctx = cipher_ctx;
    manager->md_ctx = md_ctx;
    return manager;
}

void encrypt_record(Record* record) {
    if (!record->key || !manager->cipher_ctx) return;
    EVP_EncryptUpdate(manager->cipher_ctx, record->value, NULL, &record->key);
    EVP_EncryptFinal_ex(manager->cipher_ctx, record->value + EVP_CIPHER_CTX_size(manager->cipher_ctx), record->value, record->key);
}

void decrypt_record(Record* record) {
    if (!record->key || !manager->cipher_ctx) return;
    EVP_DecryptUpdate(manager->cipher_ctx, record->value, NULL, &record->key);
    EVP_DecryptFinal_ex(manager->cipher_ctx, record->value, record->value, record->key);
}

