#include <iostream>
#include <memory>
#include <random>
#include <thread>
#include <vector>
#include <chrono>
#include <mutex>
#include <atomic>
#include <boost/numeric/ublas/io.hpp>
#include <h5cpp/H5Cpp.h>

enum class Status { Ready, Computing, Done };

struct Data {
    double value;
    uint64_t timestamp;
    Status status;
};

class DataPool {
public:
    DataPool(size_t capacity) : data_(std::make_unique<Data[]>(capacity)), poolCapacity_(capacity), nextIndex_(0), curIndex_(0), lock_() {}

    Data& getData() {
        std::lock_guard<std::mutex> guard(lock_);
        if (nextIndex_ == poolCapacity_) {
            nextIndex_ = 0;
        }
        auto result = *data_[nextIndex_++];
        result.status = Status::Ready;
        return result;
    }

    void releaseData(size_t index) {
        std::lock_guard<std::mutex> guard(lock_);
        if (index >= poolCapacity_) {
            throw std::runtime_error("Invalid index");
        }
        data_[curIndex_++] = std::move(data_[index]);
    }

private:
    std::unique_ptr<Data[]> data_;
    const size_t poolCapacity_;
    size_t nextIndex_;
    size_t curIndex_;
    mutex lock_;
};

void compute(Data& data, double minVal, double maxVal) {
    data.value = (std::uniform_real_distribution<double>(minVal, maxVal))(generator_);
}

std::mt19937 generator_; // global random number generator
DataPool dataPool;

void processRecords(const std::vector<Data>& records) {
    for (auto& record : records) {
        if (record.status == Status::Ready) {
            record.status = Status::Computing;
            std::thread t([&]() { compute(record, -10, 10); });
            t.join();
            record.status = Status::Done;
        }
    }
