class DataManager {
public:
    explicit DataManager(int num_records) : data_(num_records), next_(0) {}

    ~DataManager() {
        for (auto& entry : data_) {
            if (entry.status != STATUS_COMPLETED) {
                std::cerr << "Memory leak detected!" << std::endl;
            }
        }
    }

    Data* nextFreeEntry() {
        auto i = next_;
        if (i >= data_.size()) {
            i = 0;
        }

        while (data_[i].status != STATUS_FREE) {
            ++i;
            if (i >= data_.size()) {
                i = 0;
            }
        }

        data_[i].status = STATUS_PROCESSING;
        next_ = (i + 1) % data_.size();
        return &data_[i];
    }

    void reset() {
        for (auto& entry : data_) {
            entry.setZero();
            entry(1) = time(nullptr);
            entry(2) = STATUS_FREE;
