#define RECORD_SIZE sizeof(struct record)
#define POOL_SIZE (1 << 20) // 1MB memory pool

typedef struct _record {
    long offset;
    int key;
    double value;
} record;

// Memory pool manager
typedef struct _mem_pool {
    void *buffer;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} mem_pool;

void mem_pool_init(mem_pool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = mmap(NULL, capacity * RECORD_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->buffer == MAP_FAILED) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        exit(-1);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

record *mem_pool_alloc(mem_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used < pool->capacity) {
        record *rec = pool->buffer + pool->used * RECORD_SIZE;
        pool->used++;
        pthread_mutex_unlock(&pool->lock);
        return rec;
    } else {
        pthread_mutex_unlock(&pool->lock);
        // Handle out-of-memory situation
    }
}

void mem_pool_free(mem_pool *pool, record *rec) {
    if (rec >= pool->buffer && rec < pool->buffer + pool->capacity * RECORD_SIZE) {
        pthread_mutex_lock(&pool->lock);
        pool->used--;
        memmove(pool->buffer + pool->used * RECORD_SIZE, rec, RECORD_SIZE);
        pthread_mutex_unlock(&pool->lock);
    } else {
        // Handle invalid record error
    }
}

// Logging and performance tracking functions (not provided for brevity)

