// Define the record structure
typedef struct Record {
    int key;
    long offset;
} Record;

// Define the configuration parameters
#define COLLECTION_SIZE 1024 // Adjust based on data size requirements
#define CACHE_LINE_SIZE (64)

// Function to allocate and initialize memory for collection of records
Record* init_collection() {
    // Calculate the number of cache lines needed for the collection
    size_t num_cache_lines = COLLECTION_SIZE / CACHE_LINE_SIZE + (COLLECTION_SIZE % CACHE_LINE_SIZE != 0);

    // Allocate and map memory with cache line alignment using mmap()
    void* aligned_memory = mmap(NULL, num_cache_lines * CACHE_LINE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (aligned_memory == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    Record* collection = aligned_memory;

    // Initialize the records in the collection
    for (size_t i = 0; i < COLLECTION_SIZE; ++i) {
        collection[i].key = 0;
        collection[i].offset = 0;
    }

    return collection;
}

// Function to clean up and deallocate memory for the collection of records
void cleanup_collection(Record* collection) {
    munmap(collection, COLLECTION_SIZE * sizeof(Record));
}

// Function to validate memory allocation success before proceeding
int is_valid_memory(void* ptr) {
    return ptr != NULL;
}

// Function to handle potential memory allocation failures gracefully
void handle_allocation_error(const char* message) {
    printf("%s\n", message);
    exit(1);
}

// Function to get the index of a record based on its key
size_t get_index(Record* collection, int key) {
    for (size_t i = 0; i < COLLECTION_SIZE; ++i) {
        if (collection[i].key == key) {
            return i;
        }
    }

    // Key not found, return an error index
    return ~(size_t)0;
}

// Function to insert a record into the collection, handling memory allocation and potential collisions
int insert_record(Record* collection, int key, long offset) {
    size_t index = get_index(collection, key);

    if (index == ~(size_t)0) {
        // Key not found, find the first available slot
        for (size_t i = 0; i < COLLECTION_SIZE; ++i) {
            if (collection[i].key == 0) {
                index = i;
                break;
            }
        }
    }

    if (index < COLLECTION_SIZE) {
        // Successfully inserted the record, update its key and offset values
        collection[index].key = key;
        collection[index].offset = offset;
        return 0;
    } else {
        handle_allocation_error("Maximum array size reached");
    }
}

// Function to retrieve a record from the collection based on its key
Record get_record(Record* collection, int key) {
    size_t index = get_index(collection, key);

    if (index != ~(size_t)0) {
        return collection[index];
    } else {
        Record empty_record = { .key = 0, .offset = 0 };
        return empty_record;
    }
}
```

