['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <atomic>

struct record {
    int value;
};

struct mem_manager {
    long* offsets;
    int* keys;
    struct record* records;
    size_t capacity;
    pthread_mutex_t mutex;
    std::atomic<size_t> usage;
};

void init_mem_manager(struct mem_manager* mm, size_t capacity) {
    mm->offsets = (long*)calloc(capacity, sizeof(long));
    mm->keys = (int*)calloc(capacity, sizeof(int));
    mm->records = (struct record*)calloc(capacity, sizeof(struct record));
    mm->capacity = capacity;
    pthread_mutex_init(&mm->mutex, NULL);
    mm->usage.store(0);
}

void resize_mem_manager(struct mem_manager* mm) {
    size_t new_capacity = mm->capacity * 2;
    long* new_offsets = (long*)realloc(mm->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(mm->keys, new_capacity * sizeof(int));
    struct record* new_records = (struct record*)realloc(mm->records, new_capacity * sizeof(struct record));

    if (new_offsets != NULL && new_keys != NULL && new_records != NULL) {
        mm->offsets = new_offsets;
        mm->keys = new_keys;
        mm->records = new_records;
        mm->capacity = new_capacity;
    } else {
        free(new_offsets);
        free(new_keys);
        free(new_records);
    }
}

void log_memory_usage(struct mem_manager* mm) {
    printf("Memory usage: %zu records\n", mm->usage.load());
}

int find_empty_slot(const struct mem_manager* mm) {
    pthread_mutex_lock(&mm->mutex);
    for (size_t i = 0; i < mm->usage.load(); ++i) {
        if (mm->keys[i] == -1) {
            pthread_mutex_unlock(&mm->mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&mm->mutex);

    if (mm->usage.load() >= mm->capacity) {
        resize_mem_manager(mm);
    }
    return (int)(mm->usage.load());
}

void allocate_record(struct mem_manager* mm, int key, const struct record& rec) {
    size_t slot = find_empty_slot(mm);

    pthread_mutex_lock(&mm->mutex);
    mm->keys[slot] = key;
    mm->records[slot] = rec;
    mm->usage.fetch_add(1, std::memory_order_relaxed);
    pthread_mutex_unlock(&mm->mutex);
}

struct record get_record(const struct mem_manager* mm, int key) {
    size_t slot = (size_t)key;

    if (slot >= mm->usage.load()) {
        return {};
    }

    pthread_mutex_lock(&mm->mutex);
    if (mm->keys[slot] == key) {
        struct record ret = mm->records[slot];
        pthread_mutex_unlock(&mm->mutex);
        return ret;
    }
    pthread_mutex_unlock(&mm->mutex);

    return {};
}
```
This code defines a `mem_manager` structure to manage memory for an array of 'long' offset values, an array of 'int' keys, and an array of 'record' structures. The function `init_mem_manager()` initializes the memory manager with a specified capacity, while `resize_mem_manager()` handles dynamic resizing based on usage.

The function `find_empty_slot()` finds an empty slot for allocation, considering concurrent access and potential need for resizing. The function `allocate_record()` allocates a new record with the provided key and value, and the function `get_record()` retrieves the record associated with the given key from the memory manager.

The memory usage can be logged using the `log_memory_usage()` function. Each of these functions is designed for thread-safety using a mutex lock to protect critical sections during concurrent access.

To integrate this code into an existing system, simply create an instance of the `mem_manager` structure and call the appropriate functions as needed. Optimizations such as memory alignment and prefetching may be added to further improve performance.']

