        records[i].offset = rand();
    }
    return records;
}

void check_alloc(const char *msg, void *ptr) {
    if (!ptr) {
        fprintf(stderr, "%s: Failed to allocate memory\n", msg);
        exit(EXIT_FAILURE);
    }
}

void cleanup(Record **records, int *keys, long *offsets) {
    free(records);
    free(keys);
    free(offsets);
}

void manage_memory(size_t n_records, size_t alignment) {
    Record *records = alloc_records(n_records);
    check_alloc("Record array", records);

    int *keys = alloc_keys(n_records);
    check_alloc("Key array", keys);

    long *offsets = alloc_offsets(n_records);
    check_alloc("Offset array", offsets);

    size_t record_alignment = align(sizeof(Record), alignment);
    size_t keys_offset_alignment = align((sizeof(int) + sizeof(long)), alignment);

    void *record_ptr = mmap(NULL, n_records * record_alignment, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (record_ptr == MAP_FAILED) {
        fprintf(stderr, "Failed to map memory for records\n");
        exit(EXIT_FAILURE);
    }

    void *keys_offset_ptr = mmap(NULL, n_records * keys_offset_alignment, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (keys_offset_ptr == MAP_FAILED) {
        fprintf(stderr, "Failed to map memory for keys and offsets\n");
        exit(EXIT_FAILURE);
    }

    memcpy((char*)record_ptr + align(i * record_alignment, alignment), records[i], sizeof(Record));
    memcpy((char*)keys_offset_ptr + i * keys_offset_alignment, &records[i].key, sizeof(int));
    memcpy((char*)keys_offset_ptr + (i * keys_offset_alignment) + sizeof(int), &records[i].offset, sizeof(long));

    // Rest of the program using record_ptr and keys_offset_ptr...

    cleanup(&records, keys, offsets);
    munmap(record_ptr, n_records * record_alignment);
    munmap(keys_offset_ptr, n_records * keys_offset_alignment);
}
