    bool status; // active by default
} record;

// Hash function for string keys
unsigned long hash(char* str, unsigned long size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % size;
}

// Thread-safe linked list node for key management
typedef struct Node {
    int key;
    struct Node* next;
} Node;

// Initialize and manage a thread-safe linked list for keys
Node* create_node(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

void lock_list(Node** head) {
    pthread_mutex_init(&((*head)->lock), NULL);
}

void unlock_list(Node** head) {
    pthread_mutex_destroy(&((*head)->lock));
}

void lock_node(Node** node) {
    pthread_mutex_lock(&((*node)->lock);
}

void unlock_node(Node** node) {
    pthread_mutex_unlock(&((*node)->lock));
}

// Initialize and manage a thread-safe queue for records
typedef struct Queue {
    record* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Queue;

Queue* create_queue(size_t capacity) {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;
    queue->data = calloc(capacity, sizeof(record));
    if (!queue->data) {
        free(queue);
        return NULL;
    }
    queue->capacity = capacity;
    queue->size = 0;
    pthread_mutex_init(&(queue->lock), NULL);
    return queue;
}

void enqueue(Queue* queue, record r) {
    lock_queue(queue);
    if (queue->size == queue->capacity) {
        // Handle overflow here if needed
    }
    memcpy(&(queue->data[queue->size]), &r, sizeof(record));
    ++(queue->size);
    unlock_queue(queue);
}

record dequeue(Queue* queue) {
    lock_queue(queue);
    record r = queue->data[0];
    memmove(&(queue->data[0]), &(queue->data[1]), sizeof(record)*(queue->size-1));
    --(queue->size);
    unlock_queue(queue);
    return r;
}

// Function to dynamically allocate and initialize the arrays as specified
record* init_arrays(char* str, size_t offsets_len, size_t records_len) {
    // Allocate memory for long offsets array
    long* offsets = (long*)calloc(offsets_len, sizeof(long));
    if (!offsets) return NULL;

    // Initialize unique offset values
    unsigned long hash_size = 10000001; // Prime number for better distribution
    Node* keys = create_node(NULL);
    lock_list(&keys);
    for (int i = 0; i < offsets_len; ++i) {
        unsigned long key = hash(str, hash_size);
        Node* node = keys;
        while (node && node->key != key) node = node->next;
        if (!node) { // New collision: create a new node
            node = create_node(key);
            lock_list(&keys);
            node->next = keys->next;
            keys->next = node;
            unlock_list(&keys);
        }
        offsets[i] = key; // Store the unique key as the offset value
    }
    unlock_list(&keys);
    free(keys);

    // Allocate memory for int keys array and hash function application
    int* keys_arr = (int*)malloc(records_len * sizeof(int));
    if (!keys_arr) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for record structures and thread-safe queue
    Queue* records_queue = create_queue(records_len);
    if (!records_queue) {
        free(keys_arr);
        free(offsets);
        return NULL;
    }

    // Initialize timestamp and status for each record structure
    for (int i = 0; i < records_len; ++i) {
        record r = { offsets[rand() % offsets_len], hash(str, hash_size), time(NULL), true };
        enqueue(records_queue, r);
    }

    // Set each record's int field to a random number within the range [1, 100]
    for (int i = 0; i < records_len; ++i) {
        record r = dequeue(records_queue);
        r.int_field = rand() % 100 + 1;
    }

    return records_queue->data;
}
```
