    Record* find(int key, bool create_if_not_exists = false) {
        std::unique_lock<std::mutex> lock(data_mutex);
        auto it = records.begin();
        for (; it != records.end(); ++it) {
            if (it->key == key) return &*it;
        }
        if (!create_if_not_exists) return nullptr;

        long nextOffset = *std::max_element(offsets.begin(), offsets.end()) + 1;
        it = records.emplace(it, Record{0, nextOffset});
        keys[it - keys.begin()] = key;
        offsets.push_back(nextOffset);
        return &*it;
    }

