const fs = require('fs-extra');
const readline = require('readline');
const chalk = require('chalk');
const { promisify } = require('util');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

async function processDirectory(dir, options) {
  const { chunkSize = 1024 * 64, concurrency = 4 } = options || {};

  let processedFilesCount = 0;
  let failedAttemptsCount = 0;

  const promises = [];

  const walk = promisify(fs.walk);

  try {
    const result = await walk(dir, { followLinks: false });

    for (const item of result) {
      if (item.isFile()) {
        promises.push(processFile(item, chunkSize));

        if (promises.length === concurrency) {
          await Promise.all(promises);
          promises.length = 0;
        }
      }
    }

    // Process the remaining promises
    await Promise.all(promises);
  } catch (error) {
    console.error(chalk.red(`Error processing directory: ${error}`));
  }

  console.log(
    chalk.green(`Successfully processed ${processedFilesCount} files.`),
    chalk.yellow(`Failed to process ${failedAttemptsCount} attempts.`)
  );

  rl.close();

  async function processFile(file, chunkSize) {
    try {
      const fileContent = [];
      const stream = fs.createReadStream(file.path, { encoding: 'utf8', highWaterMark: chunkSize });

      stream.on('data', data => fileContent.push(data));
      stream.on('error', error => handleError(error, file));
      stream.on('end', () => {
        processedFilesCount++;
        updateProgress();
        resolveFileContent({ [file.name]: fileContent.join('') });
      });
    } catch (error) {
      failedAttemptsCount++;
      handleError(error);
    }
  }

  function resolveFileContent(data) {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          if (!Array.isArray(data)) throw new Error('Invalid data structure');
          resolve(data);
        } catch (error) {
          reject(error);
        }
      }, 0);
    });
  }

  function handleError(error, file = 'Unknown File') {
    console.error(chalk.red(`Error processing file: ${file} - ${error}`));
    failedAttemptsCount++;
  }

  function updateProgress() {
    if (++processedFilesCount % 100 === 0) {
      console.log(
        chalk.yellow(`Processed ${processedFilesCount} files...`)
      );
    }
  }
}
```

You can use this function with the following call:

```javascript
processDirectory('./path/to/directory', { chunkSize: 1024 * 32, concurrency: 8 })
  .then(result => console.log(JSON.stringify(result)))
  .catch(error => console.error(chalk.red(error)));
```"]

[' ```javascript
function renderFooterScripts(scripts, config) {
  if (!Array.isArray(scripts)) throw new Error("scripts must be an array");
  const scriptMap = scripts.reduce((map, script) => {
    if (!script || !script.key || !config.conditionalInclusionMap[script.key]) return map;
    map[script.key] = script;
    return map;
  }, {});

  const includedScripts = [];
  const keysToInclude = Object.keys(config.conditionalInclusionMap).filter(k => config.conditionalInclusionMap[k]);
  let maxIncludedCount = 0;

  while (keysToInclude.length > 0 && maxIncludedCount < config.maxScriptCount) {
    const key = keysToInclude.pop();
    const script = scriptMap[key];
    if (!script) continue;

    maxIncludedCount++;
    includedScripts.push(script);
    if (config.loggingEnabled) console.log(`Including ${script.src}`);
  }

  // Sort the array to ensure consistent ordering in the footer
  includedScripts.sort((a, b) => a.key.localeCompare(b.key));

  return includedScripts;
}
```
