using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Data.Common;
using System.Transactions;

public class UserRegistrationService
{
    private readonly Func<DbConnection> _connectionFactory;
    private readonly TimeSpan _retryDelay = TimeSpan.FromSeconds(1);
    private readonly int _maxRetries = 3;

    public UserRegistrationService(Func<DbConnection> connectionFactory)
    {
        _connectionFactory = connectionFactory;
    }

    public async Task<User> RegisterAsync(string email, string password, Dictionary<string, string> personalData)
    {
        if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(password) || !personalData.Any())
            return null;

        var uniqueEmail = await CheckUniqueEmailAsync(email);

        if (!uniqueEmail)
            return null;

        using (var connection = _connectionFactory())
        {
            await UsingTransactionAsync(connection, async () =>
            {
                var user = new User { Email = email, Password = password };
                personalData.ToList().ForEach(kvp => user[kvp.Key] = kvp.Value);

                await SaveUserAsync(connection, user);
            });
        }

        return user;
    }

    private async Task<bool> CheckUniqueEmailAsync(string email)
    {
        bool unique = true;
        using (var connection = _connectionFactory())
        {
            await UsingTransactionAsync(connection, async () =>
            {
                var command = connection.CreateCommand();
                command.CommandText = "SELECT COUNT(*) FROM Users WHERE Email = @Email";
                command.Parameters.AddWithValue("@Email", email);

                unique = (await command.ExecuteScalarAsync<int>() <= 0);
            });
        }

        return unique;
    }

    private async Task SaveUserAsync(DbConnection connection, User user)
    {
        var retriesLeft = _maxRetries;

        Action registerUser = () =>
        {
            using (var transaction = new TransactionScope(TransactionScopeOption.RequiresNew))
            {
                user.Id = Guid.NewGuid();
                connection.Open();

                var command = connection.CreateCommand();
                command.CommandText = "INSERT INTO Users (Id, Email, Password) VALUES (@Id, @Email, @Password)";
                command.Parameters.AddWithValue("@Id", user.Id);
                command.Parameters.AddWithValue("@Email", user.Email);
                command.Parameters.AddWithValue("@Password", user.Password);

                try
                {
                    await command.ExecuteNonQueryAsync();
                    transaction.Complete();
                }
                catch (Exception ex) when (--retriesLeft > 0)
                {
                    if (ex is InvalidOperationException || ex is OptimisticConcurrencyException)
                        throw; // Retry only for transient errors, like concurrency conflicts

                    await Task.Delay(_retryDelay);
                    registerUser();
                }
            }
        };

        if (retriesLeft > 0)
            await registerUser();
        else
            await SaveUserAsyncWithPlaceholder(connection, user);
    }

    private async Task SaveUserAsyncWithPlaceholder(DbConnection connection, User user)
    {
        using (var transaction = new TransactionScope(TransactionScopeOption.RequiresNew))
        {
            user.Id = Guid.Empty; // Placeholder for unavailable database
            user["DatabaseStatus"] = "Unavailable";
            connection.Open();

            var command = connection.CreateCommand();
            command.CommandText = "INSERT INTO Users (Id, Email, Password) VALUES (@Id, @Email, @Password)";
            command.Parameters.AddWithValue("@Id", user.Id);
            command.Parameters.AddWithValue("@Email", user.Email);
            command.Parameters.AddWithValue("@Password", user.Password);

            try
            {
                await command.ExecuteNonQueryAsync();
                transaction.Complete();
            }
            catch (Exception ex) when (ex is InvalidOperationException || ex is OptimisticConcurrencyException)
            {
                // Continue with placeholder user, as database unavailability is expected to be temporary
            }
        }
    }

    private async Task UsingTransactionAsync<T>(DbConnection connection, Func<Task<T>> operation)
    {
        using (var transaction = new TransactionScope(TransactionScopeOption.RequiresNew))
        {
            connection.Open();
            return await operation().ContinueWith(task =>
            {
                if (task.IsCompletedSuccessfully)
                    transaction.Complete();
                else
                    transaction.Dispose(); // Cleanup in case of exception
            });
        }
    }
}
```

