typedef struct Error {
    int code;
    const char* message;
} Error;

Error validate_config(const char* server_address, uint16_t port, uint32_t max_connections, const char* log_level) {
    Error error = { 0 };

    // Validate server_address
    if (server_address == NULL || strlen(server_address) == 0) {
        error.code = 1;
        error.message = "Invalid IP address.";
        return error;
    }

    struct in6_addr addr;
    memset(&addr, 0, sizeof(addr));
    if (inet_pton(AF_INET6, server_address, &addr) <= 0) {
        error.code = 2;
        error.message = "Invalid IP address.";
        return error;
    }

    // Validate port
    if (port < 1 || port > 65535) {
        error.code = 3;
        error.message = "Port out of range.";
        return error;
    }

    // Validate max_connections
    if (max_connections <= 0) {
        error.code = 4;
        error.message = "Max connections must be greater than 0.";
        return error;
    }

    // Validate log_level
    size_t i;
    for (i = 0; i < sizeof(predefined_logging_levels) / sizeof(char*); ++i) {
        if (strcmp(log_level, predefined_logging_levels[i]) == 0)
            break;
    }
    if (i == sizeof(predefined_logging_levels) / sizeof(char*)) {
        error.code = 5;
        error.message = "Invalid log level.";
        return error;
    }

    return (Error){ .code = 0, .message = NULL };
}

