namespace LargeDatasetLoader
{
    public class CustomDataStructure : IDisposable
    {
        private BinaryReader _reader;
        private MemoryStream _stream;
        private bool _disposed;

        public CustomDataStructure(string filePath)
        {
            _stream = new MemoryStream();
            using (var zip = ZipFile.OpenRead(filePath))
            {
                var compressedEntry = zip.Entries.FirstOrDefault();
                if (compressedEntry == null) throw new Exception("Compressed file does not contain expected data.");

                using (var compressedStream = compressedEntry.Open())
                    CopyStream(compressedStream, _stream);
            }
            _reader = new BinaryReader(_stream);
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _reader.Dispose();
            _stream.Dispose();
        }

        private void CopyStream(Stream from, Stream to)
        {
            const int bufferSize = 4096;
            var bytesInBuffer = new byte[bufferSize];

            int bytesRead;
            while ((bytesRead = from.Read(bytesInBuffer, 0, bytesInBuffer.Length)) > 0)
                to.Write(bytesInBuffer, 0, bytesRead);
        }
    }

    public class LargeDatasetProcessor
    {
        private readonly ILogger<LargeDatasetProcessor> _logger;
        private ConcurrentQueue<CustomDataStructure> _dataStructuresQueue;
        private BlockingCollection<Task> _tasks;
        private int _threadCount;

        public LargeDatasetProcessor(ILogger<LargeDatasetProcessor> logger, int threadCount)
        {
            _logger = logger;
            _threadCount = threadCount;
            _dataStructuresQueue = new ConcurrentQueue<CustomDataStructure>();
            _tasks = new BlockingCollection<Task>(_threadCount);
        }

        public void AddFilesToProcess(params string[] filePaths)
        {
            foreach (var filePath in filePaths)
                _dataStructuresQueue.Enqueue(new CustomDataStructure(filePath));
        }

        public void StartProcessing()
        {
            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = _threadCount };
            Parallel.ForEach(_dataStructuresQueue, options, ProcessDataStructure);

            Task.WhenAll(_tasks.GetConsumingEnumerable()).Wait();
        }

        private void ProcessDataStructure(CustomDataStructure dataStructure)
