            try
            {
                using (var binaryFormatter = new BinaryFormatter())
                {
                    var objectFromStream = binaryFormatter.Deserialize(dataStructure._reader);
                    // Process the objectFromStream here
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing data structure.");
            }

            _tasks.Add(Task.Run(() => { })); // Mark the task as completed
        }
    }
}
