import java.util.logging.Logger;

public final class CustomDeserializer {
    private static final Logger LOGGER = Logger.getLogger(CustomDeserializer.class.getName());
    private static final Map<String, Class<?>> CLASS_MAPPINGS;
    private static final ConcurrentLinkedQueue<ByteBuffer> BUFFERS;
    private static final int MAX_NAME_LENGTH = 20; // Adjust as per the longest name in your predefined list
    private static final float MIN_FLOAT = -1000f;
    private static final float MAX_FLOAT = 1000f;
    private static final double MIN_DOUBLE = -1e16;
    private static final double MAX_DOUBLE = 1e16;

    static {
        CLASS_MAPPINGS = new EnumMap<>(String.class);
        // Add your class mappings here

        BUFFERS = new ConcurrentLinkedQueue<>();
    }

    public static <T> T deserialize(ByteBuffer buffer) throws ReflectiveOperationException {
        if (buffer == null || buffer.remaining() <= 0) {
            throw new IllegalArgumentException("Invalid input byte buffer");
        }

        String className = readString(buffer);
        Class<T> clazz = CLASS_MAPPINGS.get(className);
        if (clazz == null) {
            throw new IllegalArgumentException("Unsupported class: " + className);
        }

        Constructor<T> constructor = clazz.getDeclaredConstructor();
        constructor.setAccessible(true);

        T instance = constructor.newInstance();

        Map<String, Object> fields = new HashMap<>();

        while (buffer.hasRemaining()) {
            String fieldName = readString(buffer);
            Class<?> fieldType = resolveFieldType(fieldName);

            switch (fieldType.getSimpleName()) {
                case "Float":
                    float value = buffer.getFloat();
                    if (!isValidFloat(value)) {
                        throw new IllegalArgumentException("Invalid float value: " + value);
                    }
                    fields.put(fieldName, value);
                    break;
                case "Double":
                    double dValue = buffer.getDouble();
                    if (!isValidDouble(dValue)) {
                        throw new IllegalArgumentException("Invalid double value: " + dValue);
                    }
                    fields.put(fieldName, dValue);
                    break;
                case "CharSequence": // For char* in C++
                    int length = (int) buffer.get();
                    if (length <= 0 || length > MAX_NAME_LENGTH) {
                        throw new IllegalArgumentException("Invalid name length: " + length);
                    }
                    String name = readString(buffer, length);
                    fields.put(fieldName, normalizeName(name));
                    break;
                default:
                    throw new UnsupportedOperationException("Unsupported field type: " + fieldType.getName());
            }
        }

        for (Map.Entry<String, Object> entry : fields.entrySet()) {
            String fieldName = entry.getKey();
            Object fieldValue = entry.getValue();

            Field field = clazz.getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(instance, fieldValue);
        }

        logDeserializationProgress(className, instance);

        buffer.clear();
        BUFFERS.add(buffer);

        return instance;
    }

    private static String readString(ByteBuffer buffer) {
        int length = (int) buffer.get();
        ByteBuffer stringBuffer = BufferUtil.allocate(length + 1); // Allocate one extra byte for null terminator
        buffer.get(stringBuffer);
        return new String(stringBuffer, UTF_8);
    }

    private static String readString(ByteBuffer buffer, int length) {
        ByteBuffer stringBuffer = BufferUtil.allocate(length + 1); // Allocate one extra byte for null terminator
        buffer.get(stringBuffer, 0, length);
        return new String(stringBuffer, UTF_8);
    }

    private static Class<?> resolveFieldType(String fieldName) {
        // Implement a lookup mechanism to map field names to their corresponding types
    }

    private static boolean isValidFloat(float value) {
        return value >= MIN_FLOAT && value <= MAX_FLOAT;
    }

    private static boolean isValidDouble(double value) {
        return value >= MIN_DOUBLE && value <= MAX_DOUBLE;
    }

