use serde::Deserialize;
use tokio::runtime::Runtime;
use tokio::task::spawn;
use tokio_contrib::web::ClientBuilder;
use tokio_serde::json::FromJson;
use log::{debug, error};
use reqwest::Error as ReqwestError;
use structopt::StructOpt;

#[derive(Deserialize)]
struct Config {
    http: Vec<HttpTask>,
    websocket: Vec<WebsocketTask>,
    file_upload: Vec<FileUploadTask>,
}

#[derive(Deserialize)]
struct HttpTask {
    url: String,
    interval: u64,
    params: Option<Vec<String>>,
}

#[derive(Deserialize)]
struct WebsocketTask {
    url: String,
    interval: u64,
}

#[derive(Deserialize)]
struct FileUploadTask {
    file_path: PathBuf,
    target_url: String,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();

    let config = load_config().unwrap();

    let rt = Runtime::new().expect("Failed to create tokio runtime");

    for http_task in &config.http {
        spawn(async move { handle_http_task(http_task, &rt).await });
    }

    for websocket_task in &config.websocket {
        spawn(async move { handle_websocket_task(websocket_task, &rt).await });
    }

    for file_upload_task in &config.file_upload {
        spawn(async move { handle_file_upload_task(file_upload_task, &rt).await });
    }

    rt.block_on(tokio::task::yield_now()).await;

    Ok(())
}

fn load_config() -> Result<Config, serde_yaml::Error> {
    let mut path = env::current_exe().unwrap();
    path.pop();
    path.push("config.yaml");

    let file = OpenOptions::new()
        .read(true)
        .open(&path)
        .expect("Failed to open configuration file.");

    serde_yaml::from_reader(file).expect("Failed to parse configuration.")
}

async fn handle_http_task(task: &HttpTask, rt: &Runtime) -> Result<(), Box<dyn std::error::Error>> {
    let mut client = ClientBuilder::new()
        .build()
        .await
        .expect("Failed to create reqwest client.");

    loop {
        let response = client
            .get(&task.url)
            .query(&task.params)
            .send()
            .await?
            .error_for_status_ref()?;

        debug!(target: "http", "Sending HTTP request to {} every {}", task.url, task.interval);

        tokio::time::sleep(tokio::duration::Microseconds(task.interval)).await;
    }
}

