// Custom record structure for data processing
typedef struct record {
    long offset;
    int key;
    double value;
};

// Memory pool class for efficient allocation and deallocation
class RecordPool {
public:
    RecordPool(size_t num_records, size_t block_size) : block_size_(block_size), records_(alignUp(num_records, block_size)), next_(0) {}

    record* allocate() {
        if (next_ == records_)
            grow();
        return &records_[next_++];
    }

    void deallocate(record* rec) {
        if (rec >= records_ && rec < records_ + records_.size()) {
            memset(rec, 0, sizeof(*rec));
            next_--;
        }
    }

private:
    size_t alignUp(size_t n, size_t a) const { return (n + a - 1) & ~(a - 1); }
    size_t block_size_;
    std::vector<record> records_;
    size_t next_;

    void grow() {
        // Implement your memory growth strategy here, considering cache locality, performance, and resource utilization.
    }
};

// Custom record array with concurrent access support
