std::vector<std::string> readFile(const std::filesystem::path& path) {
    std::ifstream file(path);
    if (!file.is_open()) {
        std::cerr << "Error: Could not open file: " << path << '\n';
        throw std::runtime_error("File read error");
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(std::move(line));
    }
    return lines;
}

void writeFile(const std::filesystem::path& path, const std::vector<std::string>& data) {
    std::ofstream file(path);
    if (!file.is_open()) {
        std::cerr << "Error: Could not open file for writing: " << path << '\n';
        throw std::runtime_error("File write error");
    }

    for (const auto& line : data) {
        file << line << '\n';
    }
}

void processLine(const std::string& line, std::vector<double>& averages) {
    std::istringstream iss(line);
    double value;
    int count = 0;
    while (iss >> value) {
        if (count >= 2) {
            auto it = averages.rbegin();
            *it += value;
            ++it;
            ++count;
        } else {
            ++count;
        }
    }
}

void processBatch(const std::vector<std::string>& lines, std::vector<double>& averages) {
    for (const auto& line : lines) {
        processLine(line, averages);
    }
}

void workerThreadFunction(const std::vector<std::string>& lines, std::vector<double>& averages) {
    processBatch(lines, averages);
}

void selectStrategyAndProcess() {
    constexpr int cooldown_period = 9; // in seconds
    static std::atomic_int64_t last_change = std::clock() / CLOCKS_PER_SEC;

    if ((std::clock() / CLOCKS_PER_SEC - last_change) < cooldown_period) {
        return;
    }

    last_change = std::clock() / CLOCKS_PER_SEC;
    const int strategy = distribution(rand_engine);
}

void processFiles(const std::vector<std::filesystem::path>& inputPaths, const std::filesystem::path& outputPath) {
    std::mutex print_mutex;
    std::vector<double> averages;
    int num_threads = std::thread::hardware_concurrency();

    std::queue<std::vector<std::string>> lines_to_process;
    for (const auto& inputPath : inputPaths) {
        lines_to_process.push(readFile(inputPath));
    }

    std::vector<std::unique_ptr<std::thread>> threads;
    while (!lines_to_process.empty()) {
        selectStrategyAndProcess();

        auto batch = std::move(lines_to_process.front());
        lines_to_process.pop();

        std::vector<double> temp_averages(batch.size(), 0.0);
        averages.resize(0);

        threads.push_back(std::make_unique<std::thread>(workerThreadFunction, std::move(batch), std::ref(temp_averages)));
    }

    for (auto& thread : threads) {
        thread->join();
    }

    for (size_t i = 0; i < averages.size(); ++i) {
        averages[i] /= 2; // Divide by 2 because we're only using the last two values for each line.
    }

    std::vector<std::string> outputData;
    for (size_t i = 0; i < lines_to_process.front().size(); ++i) {
        auto it = averages.rbegin();
        outputData.push_back(std::to_string(*it++) + ','); // Add the average at the end of each line.
    }

    outputData.erase(outputData.end() - 1); // Remove the last comma.
    writeFile(outputPath, outputData);
}

int main(int argc, char** argv) {
    if (argc < 3) {
        std::cerr << "Usage: input_file1 [input_file2 ...] output_file\n";
        return -1;
    }

    const int numArgs = argc - 1;
    auto inputFiles = std::vector<std::filesystem::path>(numArgs);
    for (size_t i = 0; i < numArgs; ++i) {
        inputFiles[i] = argv[i + 1];
    }

    const std::filesystem::path outputPath = argv[argc - 1];
    processFiles(inputFiles, outputPath);

    return 0;
}
```
