class Document {
public:
    std::string title;
    int pageCount;
    double averageRating;

    Document(const std::string& title, int pageCount, double averageRating) : title(title), pageCount(pageCount), averageRating(averageRating) {}
};

class DocumentManager {
public:
    void addDocument(const Document& doc);
    Document getDocumentByTitle(const std::string& title) const;
    Document getDocumentByPageCount(int pageCount) const;

private:
    using Documents = std::map<std::string, std::unique_ptr<Document>>;
    static boost::thread_specific_ptr<Documents> documents_;

    void fetchAndParseData(); // Implement data retrieval from remote repositories
};

// External document indexing library integration
Elasticsearch::Client esClient;

boost::thread_specific_data<Documents>::type DocumentManager::documents_;

void DocumentManager::addDocument(const Document& doc) {
    auto& documents = documents_.get_pointer();
    documents->emplace(doc.title, std::unique_ptr<Document>(new Document(doc)));
}

Document DocumentManager::getDocumentByTitle(const std::string& title) const {
    const auto& documents = documents_.get_pointer();
    if (auto it = documents->find(title); it != documents->end()) {
        return *it->second;
    }
    throw std::runtime_error("Document not found");
}

Document DocumentManager::getDocumentByPageCount(int pageCount) const {
    const auto& documents = documents_.get_pointer();
    for (const auto& doc : *documents) {
        if (doc.second->pageCount == pageCount) {
            return *doc.second;
        }
    }
    throw std::runtime_error("Document not found");
}
