using System;
using System.Collections.Generic;

public class DynamicValueGenerator {
    private readonly List<Tuple<double, double, bool, bool>> ranges;

    public DynamicValueGenerator() {
        this.ranges = new List<Tuple<double, double, bool, bool>>();
    }

    public void AddRange(double min, double max, bool isMinInclusive, bool isMaxInclusive) {
        if (min >= max || (isMinInclusive && min == max) || (isMaxInclusive && min == max))
            throw new ArgumentException("Invalid range definition.");

        ranges.Add(new Tuple<double, double, bool, bool>(min, max, isMinInclusive, isMaxInclusive));
    }

    public int GetRandomInt(int index) {
        var range = ranges[index];
        return (int)GetRandomValue(range.Item1, range.Item2, range.Item3, range.Item4);
    }

    public double GetRandomValue(double min, double max, bool isMinInclusive, bool isMaxInclusive) {
        var index = ranges.FindIndex(r => r.Item1 == min && r.Item2 == max && r.Item3 == isMinInclusive && r.Item4 == isMaxInclusive);
        if (index >= 0) return ranges[index].Item1 + ((double)new Random().Next((int)((min - (isMinInclusive ? min : 0)) * 1000), (int)((max - (isMaxInclusive ? max : 1)) * 1000))) / 1000.0;
        else throw new ArgumentOutOfRangeException("Invalid range index.");
    }

    public override string ToString() {
        var sb = new System.Text.StringBuilder();
        int i = 0;
        foreach (var range in ranges) {
            if (i > 0) sb.Append(", ");
            sb.AppendFormat("{0}: [{1}, {2}{3}]", i, range.Item1, range.Item2, string.Join("", new[] { isMinInclusive ? "" : "-", isMaxInclusive ? "" : "~" }));
            i++;
        }
        return sb.ToString();
    }
}
