public static byte[] DecryptAES_CBC(byte[] ciphertext, byte[] key, byte[] iv) {
    using (AesManaged aes = new AesManaged()) {
        aes.Key = key;
        aes.IV = iv;
        aes.Padding = PaddingMode.PKCS7;

        ICryptoTransform decryptor = aes.CreateDecryptor();
