void* init_records(void *arg) {
    int numRecords = *(int*)arg;
    Record* records = new Record[numRecords];
    std::fill(records, records + numRecords, Record{}); //Initialize all records to default values

    for (int i = 0; i < numRecords; ++i) {
        generate_values(&records[i]);
    }
    return records;
}

void sort(Record* records, int length) {
    std::sort(std::begin(records), std::end(records), [](const Record& a, const Record& b) { return a.key < b.key; });
}

void cleanup(Record** records_ptr) {
    if (*records_ptr != nullptr) {
        delete[] *records_ptr;
        *records_ptr = nullptr;
    }
}
```

