typedef struct Record {
    int value;
} Record;

void generate_random(Record* record, int range) {
    record->value = rand() % range;
}

double calculate_average(const Record* records, size_t size) {
    double sum = 0.0;
    for (size_t i = 0; i < size; ++i)
        sum += records[i].value;
    return sum / size;
}

void deallocate(long* offsets, int* keys, Record* records, size_t offsets_size, size_t keys_size, size_t records_size) {
    free(offsets);
    free(keys);
    free(records);
}

void* mapper(void* arg) {
    size_t index = (size_t)arg;
    static Record records[1 << 10]; // Pre-allocated memory for future expansion
    if (index >= (size_t)arraySize)
        return NULL;

    generate_random(&records[index], 100);
    return &records[index];
}

void process_data(long* offsets, int* keys, size_t offsets_size, size_t keys_size, size_t records_size) {
    pthread_t threads[offsets_size];
    for (size_t i = 0; i < offsets_size; ++i)
        pthread_create(&threads[i], NULL, mapper, (void*)i);

    Record* final_records = malloc(offsets_size * records_size);
    for (size_t i = 0; i < offsets_size; ++i) {
        void* mapped_record = pthread_join(threads[i], (void**)&final_records + i * records_size);
        if (mapped_record != NULL)
            memcpy((Record*)offsets[i], mapped_record, sizeof(Record));
    }

    double average = calculate_average(final_records, offsets_size * records_size);

    deallocate(offsets, keys, final_records, offsets_size, keys_size, offsets_size * records_size);
}
```

