};

void sortTasks(std::vector<std::unique_ptr<Task>> &tasks) {
    // Replace this placeholder with your chosen sorting algorithm.
    std::sort(tasks.begin(), tasks.end(), [](const auto &a, const auto &b) {
        return a->priorityLevel < b->priorityLevel;
    });
}

void validateTasks(const std::vector<std::unique_ptr<Task>> &tasks) {
    // Validate the sorting algorithm by checking if the array is sorted as expected.
    for (size_t i = 1; i < tasks.size(); ++i) {
        if (tasks[i - 1]->priorityLevel > tasks[i]->priorityLevel) {
            std::cerr << "Error: The task vector is not correctly sorted." << std::endl;
