            .url(url)
            .post(formBody)
            .build();

        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new IOException("Unexpected code " + response);
            }

            String responseBody = response.body().string();
            JSONObject json = new JSONObject(responseBody);
            String accessTokenValue = json.getString("access_token");
            accessToken = new AccessToken(json.getString("token_type"), accessTokenValue, json.getLong("expires_in"));
            storeAccessToken();
            return accessToken;
        } catch (IOException | JSONException e) {
            throw new AuthenticationException(e);
        }
    }

    private static void storeAccessToken() {
        String tokenJson = new JSONObject()
            .put("token_type", accessToken.getTokenType())
            .put("access_token", accessToken.getAccessToken())
            .put("expires_in", accessToken.getExpiresIn())
            .toString();
        preferences.edit().putString(KEY_ACCESS_TOKEN, tokenJson).apply();
    }

    public static Theme getTheme() {
        if (currentTheme == null) {
            loadThemeAsync(() -> downloadThemeFromServer(), () -> loadThemeFromCache());
        }
        return currentTheme;
    }

    private static void loadThemeAsync(Runnable networkTask, Runnable cacheTask) {
        new AsyncTask<Void, Void, Theme>() {
            @Override
            protected Theme doInBackground(Void... voids) {
                try {
                    fileSemaphore.acquire();
                    return networkTask.run() ? downloadThemeFromServerAndApply() : cacheTask.run();
                } catch (InterruptedException e) {
                    // Handle interruptions gracefully
                } finally {
                    fileSemaphore.release();
                }
                return null;
            }
        }.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);
    }

    // Implement downloadThemeFromServer, applyTheme, loadThemeFromCache, etc. methods here...
}
