std::unique_ptr<int[]> createIntArray(size_t size) {
    auto ptr = std::unique_ptr<int[]>(new int[size]);
    std::fill(ptr.get(), ptr.get() + size, 0);
    return ptr;
}

std::unique_ptr<record[]> createRecordArray(size_t size) {
    auto ptr = std::unique_ptr<record[]>(new record[size]);
    std::uniform_int_distribution<> dis(1, 100);
    std::mt19937 gen(std::random_device{}());
    for (auto& rec : *ptr) {
        rec.value = dis(gen);
    }
    return ptr;
}

void updateAndInsert(std::forward_list<std::string>& dataList, const std::string& searchKey, const std::string& insertValue) {
    static std::unique_ptr<long[]> offsets = createIntArray(dataList.size() + 1); // Offset array for the forward_list
    static std::unique_ptr<int[]> keys = createIntArray(dataList.size()); // Integer key array to speed up searches
    static std::unique_ptr<record[]> records = createRecordArray(dataList.size()); // Array of custom record structures

    static std::mutex mutex;

    int key = 0;
    long* currentOffset = offsets.get();
    for (auto it = dataList.begin(); it != dataList.end(); ++it, ++currentOffset) {
        if (*it == searchKey) {
            // Found the search key, insert after this position
            auto newNode = std::make_forward_list_node(std::next(it), insertValue);
            dataList.insert_after(it, newNode);
            ++*currentOffset;
        } else {
            *currentOffset = key++; // Increment the offset and update the key
        }
    }

    // If searchKey was not found, append the insertValue at the end of dataList
    if (key == dataList.size()) {
        auto newNode = std::make_forward_list_node(dataList.end(), insertValue);
        dataList.insert_after(std::prev(dataList.end()), newNode);
        *currentOffset = key++; // Increment the offset for the newly inserted node
    }

    // Update the keys array based on the new offsets
    std::unique_lock<std::mutex> lock(mutex);
    auto it = dataList.begin();
    for (long i = 0; i < key; ++i) {
        keys[*it] = i;
        if (++it == dataList.end()) it = dataList.begin();
    }
}
