#include <atomic>
#include <vector>

class Record {
public:
    int value;
    explicit Record(int v) : value(v) {}
};

class DataProcessor {
private:
    std::forward_list<std::string> dataList;
    std::mutex mtx;
    std::atomic<size_t> nextId = 0;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
    std::vector<int> usedRecords;

    void generateUniqueRandomValue(std::vector<int>& values, int start, int end) {
        std::uniform_int_distribution<> dis(start, end);
        std::mt19937 gen;
        while (true) {
            int val = dis(gen);
            if (std::find(values.begin(), values.end(), val) == values.end()) {
                values.push_back(val);
                break;
            }
        }
    }

    void initializeDataStructures() {
        generateUniqueRandomValue(keys, 1, INT_MAX);
        for (int key : keys) {
            if (find(records.begin(), records.end(), Record{key}) == records.end()) {
                Record r(key);
                records.push_back(r);
                usedRecords.push_back(false);
            }
        }
    }

public:
    void insertString(const std::string& first, const std::string& second) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = dataList.begin();
        for (; it != dataList.end() && *it != first; ++it) {}
        if (it == dataList.end()) {
            dataList.push_back(second);
        } else {
            dataList.insert(++it, second);
        }
    }

    void manageData() {
        initializeDataStructures();
        int numThreads = std::thread::hardware_concurrency();
        std::vector<std::thread> threads(numThreads);
        for (auto& t : threads) {
            t = std::thread([this]() {
                for (int i = nextId; i < INT_MAX; i += numThreads) {
                    lock_guard<std::mutex> guard(mtx);
                    while (usedRecords[i % records.size()] == true) {}
                    usedRecords[i % records.size()] = true;
                    records[i % records.size()].value = i;
                }
            });
        }
        for (auto& t : threads) {
            t.join();
        }
    }
};
```
