import org.apache.logging.log4j.*;

public class RecordManager {
    private static final Logger logger = LogManager.getLogger(RecordManager.class);

    // System configuration parameters
    private static final int MAX_RECORDS = 10000;
    private static final int KEY_RANGE_MIN = 1;
    private static final int KEY_RANGE_MAX = 10000;
    private static final String STRING_CHARSET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private static final int THRESHOLD_PERCENTAGE = 75; // Maximum allowed memory usage as a percentage of total system memory

    // Thread-safe data structures and synchronization objects
    private ExpandableArrayList<Record> recordList;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();

    public RecordManager() {
        this.recordList = new ExpandableArrayList<>(MAX_RECORDS);
    }

    public void addRecord(long offset, int key) throws InterruptedException {
        // Validate key range
        if (key < KEY_RANGE_MIN || key > KEY_RANGE_MAX) {
            throw new IllegalArgumentException("Invalid key value.");
        }

        // Wait if the array list is full and notify when space becomes available
        lock.lock();
        try {
            while (recordList.size() == MAX_RECORDS) {
                notFull.await();
            }
            Record record = new Record(offset, key, generateRandomString());
            recordList.add(record);
            logger.info("Added record: {}", record);
            // Notify when a space is added to the array list
            lock.unlock();
            notFull.signalAll();
        } catch (Exception e) {
            lock.unlock();
            throw new RuntimeException(e);
        }
    }

    public Record getRecordByKey(int key) throws InterruptedException {
        // Synchronized search to ensure thread safety
        synchronized (recordList) {
            for (Record record : recordList) {
                if (record.getKey() == key) {
                    return record;
                }
            }
            throw new NoSuchElementException("No such record found.");
        }
    }

    private String generateRandomString() {
        Random random = new Random();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Math.min(10, STRING_CHARSET.length()); ++i) {
            int index = random.nextInt(STRING_CHARSET.length());
            sb.append(STRING_CHARSET.charAt(index));
        }
        return sb.toString();
    }

    // ... Implement methods to process records, integrate with external data processing libraries, monitor and adjust memory usage, handle synchronous and asynchronous data streams, etc.
}
