class Sensor {
public:
    virtual void collectData() = 0;
};

class TemperatureSensor : public Sensor {
public:
    void collectData() override {
        // Collect temperature data
    }
};

class HumiditySensor : public Sensor {
public:
    void collectData() override {
        // Collect humidity data
    }
};

class PressureSensor : public Sensor {
public:
    void collectData() override {
        // Collect pressure data
    }
};

class DynamicNetworkedSensorSystem {
private:
    std::map<std::string, std::unique_ptr<Sensor>> sensors;
    std::mutex mutex;
    std::condition_variable cv;
    int interval = 500000000; // in nanoseconds for 5 seconds
    int currentIntervalElapsed = 1; // 1 if the current interval has elapsed, 0 otherwise
    bool dataCollectionInProgress = false;

public:
    void addSensor(const std::string& type) {
        sensors[type] = std::make_unique<Sensor>(type);
    }

    void removeSensor(const std::string& type) {
        sensors.erase(type);
    }

    void startDataCollection() {
        std::unique_lock<std::mutex> lock(mutex);
        if (!currentIntervalElapsed || dataCollectionInProgress) {
            // Wait until the current interval has elapsed or no data collection is in progress
            cv.wait(lock, [this] { return !dataCollectionInProgress && currentIntervalElapsed; });
        }

        dataCollectionInProgress = true;
        for (auto& sensor : sensors) {
            sensor.second->collectData();
        }
        currentIntervalElapsed = 0;
        cv.notify_all();
    }

    // Implement methods to query the total number of times each sensor type has been used and configure logging mechanism here
};
