class MemoryPool {
public:
    void* allocate(size_t size) {
        if (freeBlocks.empty()) {
            void* newBlock = ::operator new(size);
            usedBlocks.push_back(newBlock);
        }
        void* block = freeBlocks.front();
        freeBlocks.pop_front();
        usedBlocks.erase(std::remove(usedBlocks.begin(), usedBlocks.end(), block), usedBlocks.end());
        return block;
    }

    void deallocate(void* ptr, size_t) {
        assert(std::find(usedBlocks.begin(), usedBlocks.end(), ptr) != usedBlocks.end());
        freeBlocks.push_back(ptr);
        usedBlocks.erase(std::find(usedBlocks.begin(), usedBlocks.end(), ptr));
    }

private:
    std::vector<void*> freeBlocks;
    std::vector<void*> usedBlocks;
};

class RecordAllocator {
public:
    void createRecord(record* rec, int value) {
        auto strPtr = std::unique_ptr<std::string>(new std::string(pool.template allocate<char>(10))); // 10 is an example size, adjust as needed
        int randVal = rand() % MAX_RANDOM_VALUE + MIN_RANDOM_VALUE;
        rec->value = value == -1 ? randVal : value;
        rec->str.swap(*strPtr);
        strPtr->resize(randVal % strPtr->size());
        std::copy_n(insertValue.cbegin(), randVal, strPtr->begin());
    }

    void deallocateRecord(record* rec) {
        pool.deallocate(rec->str.get(), rec->str->size());
        rec->str.reset();
    }

private:
    MemoryPool pool;
    int MAX_RANDOM_VALUE = 1000;
};

std::atomic<bool> g_shutdown{false};
std::mutex g_mutex;
void threadFunction(std::forward_list<std::string>& dataList, RecordAllocator& allocator) {
    for (;;) {
        if (g_shutdown) break;
        std::unique_lock<std::mutex> lock(g_mutex);
        // Wait for a new task to become available
        while (!tasks.empty()) {
            tasks.pop_front();
            auto [searchKey, insertValue] = tasks.front();
            tasks.pop_front();
            // Perform the actual work on the task here
            int pos = dataList.cbegin();
            auto it = std::find(dataList.begin(), dataList.end(), searchKey);
            if (it != dataList.end()) {
                pos = it;
                ++pos;
            }
            record* rec = new record();
            allocator.createRecord(rec, -1); // Use -1 to indicate that the value is generated randomly
            *pos = std::move(*rec->str);
            lock.unlock();
        }
    }
}

void updateAndInsert(std::forward_list<std::string>& dataList, const std::string& searchKey, const std::string& insertValue) {
    RecordAllocator allocator;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<record> records;

    if (!dataList.empty()) {
        offsets.push_back(0);
        keys.reserve(dataList.size());
        records.reserve(dataList.size() + 1);
    }

    int pos = std::find(dataList.begin(), dataList.end(), searchKey) != dataList.end() ?
              std::distance(dataList.begin(), std::find(dataList.begin(), dataList.end(), searchKey)) : -1;

    if (pos == -1 || pos >= static_cast<int>(records.size())) {
        // Insert at the end of the list
        records.resize(dataList.size() + 1);
        std::copy(dataList.begin(), dataList.end(), records.begin());
        records[pos] = record();
        allocator.createRecord(&records[pos], -1); // Use -1 to indicate that the value is generated randomly
    } else {
        // Insert after the first occurrence of searchKey
        std::rotate(records.cbegin() + pos, records.cbegin() + pos + 1, records.cend());
        records[pos] = record();
        allocator.createRecord(&records[pos], -1); // Use -1 to indicate that the value is generated randomly
    }

    dataList.splice(dataList.begin() + pos, std::move(records));
}

int main() {
    std::forward_list<std::string> dataList;
    dataList.push_front("example");
    dataList.push_front("first");
    RecordAllocator allocator;

    // Create a thread pool and manage tasks concurrently
    std::vector<std::thread> threads;
    std::queue<std::pair<const std::string, const std::string>> tasks;
    tasks.push_front(std::make_pair("first", "second"));
    tasks.push_front(std::make_pair("example", "third"));

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        threads.emplace_back(threadFunction, std::ref(dataList), std::ref(allocator));
    }

    // Signal the thread pool to shut down when we're done
    g_shutdown = true;
    for (auto& t : threads) t.join();
}']

