typedef struct LoggingFacility {
    char name[256];
    void* implementation;
    void* config; // Configuration parameters
    pthread_mutex_t mutex;
    struct LoggingFacility* next;
} LoggingFacility;

LoggingFacility* load_loggers(const char* lib_name) {
    void* handle = dlopen(lib_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error: Failed to load library %s\n", lib_name);
        return NULL;
    }

    char* error;
    LoggingFacility* facility = NULL;
    void* init_func = dlsym(handle, "init_logger");

    if ((error = dlerror()) != NULL) {
        fprintf(stderr, "%s\n", error);
        goto cleanup;
    }

    void* loader_context = NULL;
    facility = (*init_func)(loader_context);
    if (!facility) {
        goto cleanup;
    }

    if ((error = dlerror()) != NULL) {
        fprintf(stderr, "%s\n", error);
        goto cleanup;
    }

cleanup:
    if (handle) {
        dlclose(handle);
    }
    return facility;
}

LoggingFacility* get_loggers() {
    LoggingFacility* loggers = NULL;
    const char* libs[] = {"path/to/logger1", "path/to/logger2"};

    for (size_t i = 0; i < sizeof(libs) / sizeof(char*); ++i) {
        LoggingFacility* new_facility = load_loggers(libs[i]);
        if (!new_facility) continue;

        pthread_mutex_init(&new_facility->mutex, NULL);

        if (loggers) {
            while (loggers->next) {
                loggers = loggers->next;
            }
            loggers->next = new_facility;
        } else {
            loggers = new_facility;
        }
    }

    return loggers;
}

void log(LoggingFacility* facility, int level, const char* message) {
    pthread_mutex_lock(&facility->mutex);

    // Performance monitoring code goes here

    // Concurrency control code goes here

    // Configurable logging based on level and other parameters goes here

    printf("[%s] [%s]: %s\n", facility->name, log_level_to_string(level), message);

    pthread_mutex_unlock(&facility->mutex);
}

// Other functions for handling configuration, resource management, and external dependencies go here

// Utility function to convert int log levels to string representation
char* log_level_to_string(int level) {
    // Implement this function based on the logging facility's requirements
}
