const MessageService = require('./MessageService'); // External messaging service
const SensorReading = require('./SensorReading'); // Custom sensor reading object
const RandomGenerator = require('./RandomGenerator'); // Pre-existing random number generator API
const DataProcessingService = require('./DataProcessingService'); // External data processing service
const SHA256 = require('crypto-js/sha256'); // sha-256 hashing library
const cluster = require('cluster'); // For multi-threading support
const path = require('path'); // Node.js path module

if (cluster.isMaster) {
  const numWorkers = require('os').cpus().length;
  console.log(`Master clocking in with ${numWorkers} workers!`);
  for (let i = 0; i < numWorkers; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died with code: ${code}, signal: ${signal}`);
    cluster.fork(); // Fork a new worker to replace the dead one
  });
} else {
  const config = require(path.join(__dirname, 'sensorConfig.json')); // Load sensor configurations
  const dataBuffer = []; // In-memory buffer for temporary storage
  let currentInterval; // Variable interval for data collection

  function generateSensorReading() {
    return new SensorReading(new Date(), RandomGenerator.nextFromNormal(config[0].samplingRate), config[0].identifier, true);
  }

  function generateSHA256(input) {
    try {
      return SHA256(input).toString();
    } catch (error) {
      console.error(`Failed to generate SHA-256 hash: ${error}`);
      return null;
    }
  }

  function manageSensorDataStream() {
    // Initialize data collection with the provided interval
    currentInterval = setInterval(() {
      dataBuffer.push(generateSensorReading());
      DataProcessingService.processDataSync(dataBuffer); // Synchronous operation for initial processing

      // Notify subscribers of data collection state change (collection started)
      MessageService.notify('Data Collection Started');
    }, currentInterval);

    process.on('SIGINT', () => {
      clearInterval(currentInterval);
      DataProcessingService.processDataAsync(dataBuffer, (error, result) => {
        if (!error) {
          // Notify subscribers of data collection state change (collection paused)
          MessageService.notify('Data Collection Paused');
        } else {
          console.error(`Error during data processing: ${error}`);
        }
      });
      process.exit();
    });

    // Handle resuming and pausing the data collection with variable intervals
    process.stdin.on('data', (chunk) => {
      const command = chunk.toString().trim();
      if (command === 'resume') {
        clearInterval(currentInterval);
        currentInterval = setInterval(() => {
          // ...
        }, parseInt(process.env.COLLECTION_INTERVAL || '1000'));
      } else if (command === 'pause') {
        clearInterval(currentInterval);
      }
    });
  }

  manageSensorDataStream();
}
