#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <limits.h>

typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

struct Dataset {
    size_t size;
    Record *records;
    sem_t mutex;
    sem_t full;
    sem_t empty;
};

Dataset* create_dataset(size_t size) {
    if (size == 0) return NULL;

    Dataset *dataset = mmap(NULL, sizeof(Dataset), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!dataset) {
        perror("mmap failed");
        return NULL;
    }

    dataset->size = size;
    dataset->records = calloc(size, sizeof(Record));
    if (!dataset->records) {
        free(dataset);
        perror("calloc failed");
        return NULL;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    if (pthread_mutex_init(&dataset->mutex, &attr)) {
        free(dataset->records);
        free(dataset);
        perror("mutex init failed");
        return NULL;
    }

    sem_init(&dataset->empty, 0, size);
    sem_init(&dataset->full,  0, 0);

    return dataset;
}

void destroy_dataset(Dataset *dataset) {
    if (dataset) {
        sem_destroy(&dataset->mutex);
        sem_destroy(&dataset->empty);
        sem_destroy(&dataset->full);
        free(dataset->records);
        munmap(dataset, sizeof(Dataset));
    }
}

// Add your thread-safe functions for adding records to the dataset here.

void log_metrics(Dataset *dataset) {
    // Implement real-time monitoring and logging of memory usage and performance metrics.
}
```

