#include <boost/asio/io_service.hpp>
#include <boost/asio/strand.hpp>
#include <boost/format.hpp>
#include <json/json.h>

class MemoryPool {
public:
    void* allocate(size_t size, size_t alignment) {
        // Allocate from the memory pool if available, otherwise use posix_memalign
        if (!freeList_.empty()) {
            auto ptr = freeList_.front();
            freeList_.pop_front();
            return ptr;
        }
        void* result;
        if (posix_memalign(&result, alignment, size) == 0) {
            usedList_.push_back(result);
            return result;
        }
        throw std::bad_alloc();
    }

    void deallocate(void* ptr) {
        if (std::find(usedList_.begin(), usedList_.end(), ptr) != usedList_.end()) {
            usedList_.erase(std::remove(usedList_.begin(), usedList_.end(), ptr), usedList_.end());
            freeList_.push_back(ptr);
        } else {
            // Handle cases where the memory was not allocated from this pool
            std::cerr << "Trying to deallocate unallocated memory" << std::endl;
        }
    }

private:
    std::list<void*> freeList_;
    std::list<void*> usedList_;
};

struct APIRequest {
    boost::asio::io_service::strand strand;
    std::function<void(Json::Value&)> callback;
};

