        for (auto& product : response["data"]) {
            products.push_back(product);
        }

        if (response["meta"]["next_page_url"].isNull()) {
            // Last page of results, process and display products here
            // ...
        } else {
            // Make another API request for the next page of data
            // ...
        }
    }

    // Create an asio io_service to handle asynchronous API calls
    boost::asio::io_service ioService;

    // Handle multiple API requests concurrently with a strand
    APIRequest request = { ioService.get_strand(), apiCallback };

    while (startIndex < numRecords) {
        // Make an API request, passing in the current start index and page size
        Json::Value params;
        params["start_index"] = startIndex;
        params["page_size"] = pageSize;
        auto reqUrl = "https://api.example.com/inventory?" + Json::FastWriter(params).write();

        // Submit the API request asynchronously using the strand
        request.callback = [&](Json::Value& response) { request.strand.dispatch(std::bind(&apiCallback, std::placeholders::_1)); };
        boost::asio::ip::tcp::iostream apiStream;
        apiStream.exchange(reqUrl.c_str());
        apiStream >> response;

