#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct dataEntry {
    long* offset;
    int key;
} DataEntry;

// Allocate memory for an array of dataEntries and initialize with random values
DataEntry* createDataArray(size_t size, size_t keyRange, size_t offsetRange) {
    if (!(size > 0)) return NULL;

    DataEntry *data = mmap(NULL, sizeof(DataEntry) * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        data[i].offset = (long*)malloc(sizeof(long));
        if (data[i].offset == NULL) {
            perror("malloc");
            continue;
        }

        *data[i].offset = (rand() % offsetRange);
        data[i].key = rand() % keyRange;
    }

    return data;
}

// Resize the array dynamically when needed, using a heuristic to minimize resizing overhead
void resizeDataArray(DataEntry** data, size_t currentSize, size_t newSize, size_t threshold) {
    if (newSize > currentSize * threshold) {
        DataEntry *newData = createDataArray(newSize, *((*data)->key), *((*data)->offset));
        if (newData == NULL) return;

        memcpy(newData, *data, sizeof(DataEntry) * currentSize);
        free(*data);
        *data = newData;
    }
}
```

