    char email[100];
    time_t dob;
    enum { ACTIVE, INACTIVE } status;
} Profile;

struct ListNode {
    Profile profile;
    struct ListNode *next;
};

typedef struct {
    struct ListNode *head;
    struct ListNode *tail;
    int size;
    int max_size;
    sem_t mutex;
} List;

List* create_list(int max_size) {
    List* list = malloc(sizeof(List));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    sem_init(&list->mutex, 0, 1);
    return list;
}

Profile* find_profile_by_username(List *list, const char *username) {
    struct ListNode *current = list->head;
    while (current != NULL) {
        if (strcmp(current->profile.username, username) == 0)
            return &current->profile;
        current = current->next;
    }
    return NULL;
}

bool add_profile(List *list, const char *username, const char *email, time_t dob, enum status status) {
    sem_wait(&list->mutex);
    Profile* existing = find_profile_by_username(list, username);
    sem_post(&list->mutex);

    if (existing != NULL)
        return false;

    struct ListNode *new_node = malloc(sizeof(struct ListNode));
    strcpy(new_node->profile.username, username);
    strcpy(new_node->profile.email, email);
    new_node->profile.dob = dob;
    new_node->profile.status = status;
    new_node->next = NULL;

    sem_wait(&list->mutex);
    if (list->size < list->max_size) {
        if (list->head == NULL) {
            list->head = new_node;
            list->tail = new_node;
        } else {
            list->tail->next = new_node;
            list->tail = new_node;
        }
        list->size++;
    }
    sem_post(&list->mutex);

    return true;
}

void update_profile_status(List *list, int index, enum status new_status) {
    struct timespec timestamp;
    clock_gettime(CLOCK_MONOTONIC, &timestamp);

    sem_wait(&list->mutex);
    if (index >= 0 && index < list->size) {
        struct ListNode *current = list->head;
        for (int i = 0; i < index; i++)
            current = current->next;

        current->profile.status = new_status;
        log_modification(timestamp);
    }
    sem_post(&list->mutex);
}

