```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class Record
{
    public int Key { get; set; }
    public string TypeId { get; set; }
    public int Value { get; set; }
}

public class MemoryPoolManager
{
    private readonly MemoryPoolSlim<byte[]> _stringPool;
    private readonly MemoryPoolSlim<T> _memoryPool<T>();

    public MemoryPoolManager()
    {
        _stringPool = new MemoryPoolSlim<byte[]>(options => new byte[4096]);
        _memoryPool = new MemoryPoolSlim<T>(options => Activator.CreateInstance<T>());
    }

    public T Rent<T>() where T : new()
    {
        return _memoryPool.Rent();
    }

    public byte[] RentString(int length)
    {
        return _stringPool.Rent(length);
    }

    public void Return(T item) => _memoryPool.Return(item);
    public void Return(byte[] stringItem) => _stringPool.Return(stringItem);
}

public async Task ProcessTextFileWithResourceOptimization(string filePath, int chunkSize, int maxDegreeOfConcurrency, MemoryPoolManager memoryPoolManager)
{
    var semaphore = new SemaphoreSlim(maxDegreeOfConcurrency);
    var hashBuilder = SHA256.Create();
    var finalHash = new byte[hashBuilder.HashSize];
    var totalBytesRead = 0;
    var progressInterval = chunkSize * 10; // Adjust as needed

    using (var fileStream = File.OpenRead(filePath))
    {
        var buffer = memoryPoolManager.RentString(chunkSize);
        int bytesRead;

        do
        {
            await semaphore.WaitAsync();

            try
            {
                bytesRead = fileStream.ReadAsync(buffer, 0, buffer.Length).Result;
                totalBytesRead += bytesRead;

                if (bytesRead == 0) break;

                hashBuilder.TransformBlock(Encoding.UTF8.GetBytes(buffer), 0, bytesRead, finalHash, 0);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading file: {ex}");
            }

            semaphore.Release();

            if ((totalBytesRead % progressInterval) == 0)
                Console.WriteLine($"Processed {(totalBytesRead / progressInterval).ToString("N0")}% of the file.");
        }
        while (bytesRead > 0);

        hashBuilder.TransformFinalBlock(finalHash, 0, finalHash.Length);
        Console.WriteLine($"File Hash: {BitConverter.ToString(finalHash)}");
    }

    memoryPoolManager.Return(buffer);
}
```

