#define MAX_CAPACITY 10000
struct transaction {
    long id;
    double amount;
    char description[256];
    time_t timestamp;
};

typedef struct node {
    struct transaction data;
    struct node* next;
} node;

node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
volatile size_t length = 0;

void log_resource_usage() {
    // Implement resource usage logging here
}

void add_transaction(struct transaction transaction) {
    pthread_mutex_lock(&mutex);
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Out of memory\n");
        return;
    }
    memcpy(&new_node->data, &transaction, sizeof(struct transaction));
    new_node->next = head;
    head = new_node;
    length++;
    if (length >= MAX_CAPACITY) {
        node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = NULL;
        free(head);
        head = temp;
    }
    pthread_mutex_unlock(&mutex);
}

struct transaction* get_transaction_by_id(long id) {
    pthread_mutex_lock(&mutex);
    node* current = head;
    while (current != NULL) {
        if (current->data.id == id) {
            pthread_mutex_unlock(&mutex);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

