// Custom memory pool for dynamically allocated strings
struct string_pool {
    char **strings;
    size_t capacity;
    size_t used;
};

void init_string_pool(struct string_pool *pool, size_t capacity) {
    pool->strings = malloc(capacity * sizeof(char*));
    pool->capacity = capacity;
    pool->used = 0;
}

char* acquire_string_from_pool(struct string_pool *pool) {
    if (pool->used < pool->capacity)
        return pool->strings[pool->used++];
    else {
        char *new_string = malloc((1 << 16) * sizeof(char));
        pool->strings[pool->used++] = new_string;
        return new_string;
    }
}

void release_string_to_pool(struct string_pool *pool, char *string) {
    if (string >= pool->strings && string < pool->strings + pool->capacity) {
        pool->used--;
    } else {
        free(string);
    }
}

// Function for logging records
