int config_init(int path_count, int priority_count, Config **configs) {
    if (path_count <= 0 || priority_count < 0) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        return -1;
    }

    *configs = malloc(priority_count > path_count ? path_count : priority_count);
    int size = priority_count > path_count ? priority_count : path_count;

    for (int i = 0; i < size; ++i) {
        (*configs)[i].priority = 0;
        (*configs)[i].path = malloc(1);
        (*configs)[i].path[0] = '\0';
    }

    if (priority_count > path_count) {
        for (int i = size; i < priority_count; ++i) {
            (*configs)[i].priority = 0;
            (*configs)[i].path = malloc(1);
            (*configs)[i].path[0] = '\0';
        }
    } else {
        for (int i = size; i < path_count; ++i) {
            (*configs)[i].priority = 0;
            (*configs)[i].path = malloc(1);
            (*configs)[i].path[0] = '\0';
        }
    }

    if (size > 0) {
        int sum_priority = 0;
        for (int i = 0; i < size; ++i) {
            sum_priority += (*configs)[i].priority;
        }
        float avg_priority = sum_priority / size;

        for (int i = 0; i < size; ++i) {
            if (i < priority_count)
                (*configs)[i].priority = (int)avg_priority;
            else
                (*configs)[i].priority = 0;

            if (i < priority_count)
                (*configs)[i].path = malloc(1);
            else
                (*configs)[i].path = NULL;
        }
    }

    return 0;
}

