#include <openssl/evp.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

struct memory_pool {
    size_t capacity;
    size_t used;
    record *data;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool *pool, size_t initial_size) {
    pool->capacity = initial_size;
    pool->used = 0;
    pool->data = malloc(initial_size * sizeof(record));
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
}

record *alloc_record(struct memory_pool *pool) {
    if (pool->used >= pool->capacity) {
        size_t new_capacity = 2 * pool->capacity;
        record *new_data = realloc(pool->data, new_capacity * sizeof(record));
        if (!new_data) {
            fprintf(stderr, "Failed to reallocate memory for memory pool\n");
            exit(EXIT_FAILURE);
        }
        pool->capacity = new_capacity;
        pool->data = new_data;
    }
    record *record = &pool->data[pool->used++];
    // Initialize the record with random value to prevent overflow
    record->value = rand() % RAND_MAX;
    return record;
}

void free_record(struct memory_pool *pool, record *record) {
