public:
    std::shared_ptr<Record> allocate() {
        std::unique_lock<std::mutex> lock(mtx_);
        if (!freeList_.empty()) {
            auto result = freeList_.front();
            freeList_.pop_front();
            return result;
        }
        // Allocate new memory if necessary.
