#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    size_t capacity;
    size_t size;
    int *data;
} IntCollection;

IntCollection* create_int_collection(size_t initial_capacity) {
    IntCollection *ic = malloc(sizeof(IntCollection));
    if (!ic) return NULL;

    ic->capacity = initial_capacity;
    ic->size = 0;
    ic->data = mmap(NULL, initial_capacity * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ic->data == MAP_FAILED) {
        free(ic);
        return NULL;
    }

    return ic;
}

void resize_int_collection(IntCollection *ic, size_t new_capacity) {
    if (new_capacity <= ic->size) return;

    int *temp = mmap(NULL, new_capacity * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (temp == MAP_FAILED) return;

    memcpy(temp, ic->data, ic->size * sizeof(int));
    munmap(ic->data, ic->capacity * sizeof(int));

    ic->capacity = new_capacity;
    ic->data = temp;
}

void populate_randomly(IntCollection *ic, int min, int max) {
    for (size_t i = 0; i < ic->size; ++i) {
        ic->data[i] = rand() % (max - min + 1) + min;
    }
}

void serialize(IntCollection *ic, const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) return;

    write(fd, ic->data, ic->size * sizeof(int));
    close(fd);
}

void free_int_collection(IntCollection *ic) {
    munmap(ic->data, ic->capacity * sizeof(int));
    free(ic);
}
```

