device* create_devices(size_t num_devices, size_t samples_per_device) {
    size_t total_samples = num_devices * samples_per_device;
    size_t alignment = 16; // Consider alignment requirements for the external library
    size_t device_size = sizeof(device);
    size_t sample_size = sizeof(device.data[0]);
    size_t data_alignment = alignof(device.data[0].value);
    size_t data_offset = (alignment - data_alignment) % alignment;
    size_t data_padding = samples_per_device * data_offset;

    device* devices = calloc(num_devices, device_size + data_padding);
    if (!devices) {
        perror("Failed to allocate memory for devices");
        exit(EXIT_FAILURE);
    }

    device* current_device = (device*)(((uintptr_t)devices + data_padding) & ~(alignment - 1));

    srand((unsigned int)time(NULL));

