        return WebClient.builder()
                .clientConnector(new ReactorClientHttpConnector())
                .exchangeFunction(Function.identity())
                .defaultHeader("Accept", "application/json")
                .filter((request, next) -> next.apply(request).log())
                .retrier(RetrybackoffSpec.fromThrowablePredicate(throwable -> throwable instanceof RuntimeException, Duration.ofSeconds(5))
                        .maxRetries(3))
                .doOnError(exchange -> LOG.error("Request failed: {}", exchange.toString()))
                .filter((webExchange, next) -> {
                    Function<ServerWebExchange, Mono<Flux<byte[]>>> function = brokers.get(webExchange.getRequest().getURI().getHost());
                    if (function != null) {
                        return next.apply(webExchange).flatMap(function);
                    } else {
                        throw new RuntimeException("Unsupported message broker");
                    }
                })
                .metrics(meterRegistry, "message-broker", PrometheusConfig.DEFAULT)
                .build();
    }

