typedef struct {
    long offset;
    int key;
} record;

void init_memory(size_t size, size_t *num_allocated) {
    void* memory_pool = mmap(NULL, size * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memory_pool == MAP_FAILED) {
        fprintf(stderr, "Memory mapping failed\n");
        exit(EXIT_FAILURE);
    }

    *num_allocated = size;
}

record* get_record(size_t *index) {
    if (*index >= *num_allocated) {
        fprintf(stderr, "Index out of range\n");
        exit(EXIT_FAILURE);
    }

    return (record*) memory_pool + *index;
}

void free_memory() {
    munmap((void*) memory_pool, *num_allocated * sizeof(record));
}
