    if (pool == NULL || rec == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    // Implement caching strategy here

    pool->data[pool->used - 1] = *rec;
    pool->used--;
    pthread_mutex_unlock(&pool->lock);
