struct memory_pool* create_memory_pool(size_t num_elements, size_t range, unsigned int seed) {
    struct memory_pool* pool = malloc(sizeof(struct memory_pool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);

    pool->num_elements = num_elements;
    pool->offsets = calloc(num_elements + 1, sizeof(long));
    pool->keys = calloc(num_elements, sizeof(int));
    pool->records = malloc(num_elements * sizeof(record));
    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        pool->records[i].value = random() % range;
    }

    seed_rand(seed);

    pool->byte_count = sizeof(long) * (num_elements + 1) + sizeof(int) * num_elements + num_elements * sizeof(record);

    return pool;
}

void destroy_memory_pool(struct memory_pool* pool) {
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

bool try_allocate_memory(struct memory_pool* pool, size_t byte_count) {
    void* data = malloc(byte_count);
    if (!data) return false;

    // synchronize access to the allocated block
    pthread_mutex_lock(&pool->lock);

    long offset = *pool->offsets++;
    pool->byte_count += byte_count;

    pthread_mutex_unlock(&pool->lock);

    memset(data, 0, byte_count);
    return true;
}

