// Custom allocator with memory pooling and statistics
struct allocator {
    void* pool;
    size_t used;
    size_t free;
    size_t total;
};

void init_allocator(struct allocator* alloc, size_t total) {
    // Initialize the memory pool
    alloc->pool = malloc(total);
    if (!alloc->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    alloc->used = 0;
    alloc->free = total;
    alloc->total = total;
}

void* alloc(struct allocator* alloc, size_t size) {
    if (alloc->free + size > alloc->total) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }

    void* ptr = (char*)alloc->pool + alloc->free;
    alloc->free += size;
    alloc->used += size;

    return ptr;
}

void free(struct allocator* alloc, void* ptr) {
    alloc->free += (ptr - (char*)alloc->pool);
    alloc->used -= (ptr - (char*)alloc->pool);
}

