using System;
using System.Collections.Concurrent;
using System.Data.Common;
using System.Data.Entity;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Npgsql;
using NpgsqlTypes;

public class DataProcessor
{
    private readonly string _connectionString;
    private readonly string _queryString;
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly int _batchSize;

    public DataProcessor(string connectionString, string queryString, int batchSize = 1000)
    {
        _connectionString = connectionString;
        _queryString = queryString;
        _batchSize = batchSize;
    }

    public async IAsyncEnumerable<T> Process()
    {
        using var dbContext = new MyDbContext(_connectionString);
        var command = PrepareCommand(dbContext);
        var records = new DataRecord[Environment.WorkingSet > 10_000_000 ? (int)Math.Ceiling((double)Environment.WorkingSet / 20) : 1000];
        int count = 0;

        while (true)
        {
            await ProcessBatch(command, records[count]);
            if (++count == records.Length)
            {
                yield return SerializeAndCache(records);
                Array.Copy(records, 0, records, count, records.Length - count);
                count = 0;
            }
        }
    }

    private NpgsqlCommand PrepareCommand(DbContext dbContext)
    {
        var command = new NpgsqlCommand(_queryString, new NpgsqlConnection(dbContext.Database.GetDbConnection().ConnectionString));
        command.Parameters.Add("@filter", NpgsqlDbType.Json);
        return command;
    }

    private async Task ProcessBatch(NpgsqlCommand command, DataRecord[] batch)
    {
        for (int i = 0; i < batch.Length; i += _batchSize)
        {
            int endIndex = Math.Min(_batchSize + i, batch.Length);
            var filter = FilterParameters; // replace with your filtering mechanism
            await Parallel.ForEachAsync(batch.AsEnumerable().Skip(i).Take(endIndex - i), new ParallelOptions { MaxDegreeOfParallelism = 10000 }, async (record, state) =>
            {
                try
                {
                    command.Parameters["@filter"].Value = filter;
                    var reader = await command.ExecuteReaderAsync();
                    if (await reader.ReadAsync())
                    {
                        record.Offset = reader.GetInt32(0);
                        record.Key = reader.GetInt32(1);
                        record.Value = reader.GetDouble(2);
                    }
                }
                catch (OutOfMemoryException)
                {
                    Console.WriteLine("Out of memory error, skipping");
                }
            });
        }
    }

    private T SerializeAndCache<T>(DataRecord[] records)
    {
        var serializedRecords = new List<byte>();
        using (var writer = new BinaryWriter(new MemoryStream()))
        {
            foreach (var record in records)
            {
                writer.Write(record.Offset);
                writer.Write(BitConverter.GetBytes(record.Key));
                writer.Write(BitConverter.GetBytes(record.Value));
            }
            serializedRecords = writer.BaseStream.ToArray();
        }

        var key = JsonConvert.SerializeObject(serializedRecords);
        _cache[key] = serializedRecords;
        return (T)(object)JsonConvert.DeserializeObject<T>(key);
    }
}

public struct DataRecord
{
    public long Offset { get; set; }
    public int Key { get; set; }
    public double Value { get; set; }
}
