#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>
#include <limits.h>

typedef struct record {
    int key;
    double value;
    char *str;
} Record;

typedef struct dataset {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    void (*sort_func)(Record*, size_t);
    bool log_enabled;
    double lower_threshold;
    double upper_threshold;
} Dataset;

void init_dataset(Dataset *dataset, size_t initial_capacity) {
    dataset->records = malloc(initial_capacity * sizeof(Record));
    if (!dataset->records) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    dataset->capacity = initial_capacity;
    dataset->size = 0;
    pthread_mutex_init(&dataset->mutex, NULL);
    dataset->sort_func = NULL;
    dataset->log_enabled = false;
    dataset->lower_threshold = DBL_MIN;
    dataset->upper_threshold = DBL_MAX;
}

void destroy_dataset(Dataset *dataset) {
    for (size_t i = 0; i < dataset->size; ++i) {
        free(dataset->records[i].str);
    }
    free(dataset->records);
    pthread_mutex_destroy(&dataset->mutex);
}

void log(const char *message, Dataset *dataset) {
    if (dataset->log_enabled) {
        printf("%s\n", message);
    }
}

void add_record(Dataset *dataset, int key, double value, const char *str) {
    pthread_mutex_lock(&dataset->mutex);

    if (dataset->size == dataset->capacity) {
        size_t new_capacity = dataset->capacity * 2;
        Record *new_records = realloc(dataset->records, new_capacity * sizeof(Record));
        if (!new_records) {
            log("Error: Memory allocation failure during record addition\n", dataset);
            pthread_mutex_unlock(&dataset->mutex);
            return;
        }
        dataset->records = new_records;
        dataset->capacity = new_capacity;
    }

    Record *record = &dataset->records[dataset->size];
    record->key = key;
    record->value = value;
    size_t len = strlen(str) + 1;
    record->str = malloc(len);
    if (!record->str) {
        log("Error: Memory allocation failure during string allocation\n", dataset);
        pthread_mutex_unlock(&dataset->mutex);
        return;
    }
    memcpy(record->str, str, len);

    ++dataset->size;

    pthread_mutex_unlock(&dataset->mutex);
}

void filter(Dataset *dataset) {
    pthread_mutex_lock(&dataset->mutex);

    Record *filtered_records = malloc(dataset->size * sizeof(Record));
    size_t filtered_size = 0;

    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i].value > dataset->upper_threshold ||
           dataset->records[i].value < dataset->lower_threshold) {
            continue;
        }
        filtered_records[filtered_size] = dataset->records[i];
        ++filtered_size;
    }

    free(dataset->records);
    dataset->records = filtered_records;
    dataset->capacity = filtered_size;
    dataset->size = filtered_size;

    pthread_mutex_unlock(&dataset->mutex);
}

// Implement sorting and other functionalities using an external library, such as qsort or a custom sorting algorithm.
