// Global variables for chunk size and random range
#define CHUNK_SIZE (1024 * 1024)
#define RANDOM_RANGE (1000)

typedef struct {
    long offset;
    int key;
} Record;

// Custom memory allocator function, optional for optimization
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Deserialization function for a single record
Record deserialize_record(const void* data) {
    Record record = *(Record*)data;
    // Checksum verification and error handling can be added here
    return record;
}

// Function to process and transform records from the binary file
void processAndTransformRecords(const char* filename, int* long_offsets, int* int_keys, size_t capacity) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Could not open file %s\n", filename);
        return;
    }

    void* map_base;
    size_t map_size = CHUNK_SIZE;
    size_t bytes_read;
    int chunk_count = 0;
    Record* current_chunk = my_malloc(map_size * sizeof(Record));

    while ((bytes_read = fread(map_base = mmap(NULL, map_size, PROT_READ, MAP_PRIVATE, fileno(file), 0), map_size)) > 0) {
        for (size_t i = 0; i < bytes_read / sizeof(Record); ++i) {
            Record record = deserialize_record((const void*)(map_base + i * sizeof(Record)));
            int_keys[record.key] = rand() % RANDOM_RANGE + 1; // Modify the key value with randomization
            long_offsets[chunk_count * (bytes_read / sizeof(Record)) + i] = record.offset;
        }
        chunk_count++;
        if (chunk_count == capacity) {
            break;
        }
    }

    munmap(map_base, map_size);
    fclose(file);
}
