    sysinfo info;
    if (sysinfo(&info) == -1) return NULL;

    ResourceInfo *resources = malloc(sizeof(ResourceInfo) * 3); // Assuming 3 resources for example purposes

    strncpy(resources[0].type, "CPU", sizeof(resources[0].type));
    resources[0].id = 0;
    resources[0].usage_percentage = (float)(info.loads[0] + info.loads[1] + info.loads[2]) * 100 / 3;
    resources[0].peak_usage = info.procs;

    strncpy(resources[1].type, "Memory", sizeof(resources[1].type));
    resources[1].id = 1;
    resources[1].usage_percentage = (float)info.mem_total * 100 / info.mem_unit.mem_total; // Using mem_unit for example purposes
