    private readonly IDatabaseFactory _databaseFactory;
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly IDistributedCache _cache;
    private readonly ServiceBusSender _sender;

    public PageElementUpdaterService(
        ILogger<PageElementUpdaterService> logger,
        IDatabaseFactory databaseFactory,
        IServiceScopeFactory scopeFactory,
        IDistributedCache cache,
        ServiceBusSender sender)
    {
        _logger = logger;
        _databaseFactory = databaseFactory;
        _scopeFactory = scopeFactory;
        _cache = cache;
        _sender = sender;
    }

    public async Task<HttpResponseMessage> UpdateElementAsync(string sectionId, string elementId, string content)
    {
        if (!ValidateRequestOrigin())
            return new HttpResponseMessage(HttpStatusCode.Forbidden);

        using var scope = _scopeFactory.CreateScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<DatabaseContext>();

        // Validate user permissions, retrieve page template and handle CMS downtime gracefully
        var permissionCheckResult = await CheckPermissionsAndRetrievePageTemplateAsync(dbContext, sectionId);
        if (!permissionCheckResult.Success)
            return new HttpResponseMessage(HttpStatusCode.Forbidden);

        // Optimistic locking to prevent concurrent updates
        var optimisticLockToken = await GetOptimisticLockTokenAsync(dbContext, sectionId, elementId);

        try
        {
            if (optimisticLockToken != content)
                throw new OptimisticConcurrencyException();

            // Update the element's HTML content in the database and cache
            await UpdateElementInDatabaseAndCacheAsync(dbContext, sectionId, elementId, content);

            // Log changes for auditing purposes
            LogChangesAsync(dbContext, sectionId, elementId, content);

            // Notify subscribers about the change asynchronously through a reliable message broker service
            await SendNotificationMessageAsync(_sender, sectionId, elementId, content);
        }
        catch (OptimisticConcurrencyException)
        {
            _logger.LogError("Conflict occurred while updating the specified section");
            return new HttpResponseMessage(HttpStatusCode.Conflict);
        }

        return new HttpResponseMessage(HttpStatusCode.OK);
    }

    // Implementation details for methods omitted for brevity
}
