#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { START, PROCESSING, COMPLETED } status_t;

struct data_entry {
    double value;
    char str[256];
    status_t status;
};

void read_log(FILE *fp, struct data_entry **data, size_t *count) {
    // Allocate initial memory for array and set counter to 0
    *data = malloc(*count * sizeof(**data));
    size_t i = 0;

    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        // Parse each line into a data_entry struct
        sscanf(line, "%lf %255s %s", &((*data)[i].value), (*data)[i].str, ((*data)[i].status == START) ? "START" : ((*data)[i].status == PROCESSING) ? "PROCESSING" : "COMPLETED");

        // If the line is malformed or a duplicate, skip it
        if (feof(fp)) break;
        for (size_t j = 0; j < i; ++j) {
            if (!strcmp((*data)[i].str, (*data)[j].str) && (*data)[i].value == (*data)[j].value) {
                ++i;
                break;
            }
        }

        // If the allocated memory is exhausted, reallocate more
        if (i == *count) {
            *count *= 2;
            *data = realloc(*data, *count * sizeof(**data));
        }

        ++i;
    }
}

void sort_and_filter(struct data_entry *data, size_t count, double cutoff, status_t filter) {
    qsort(data, count, sizeof(struct data_entry), (int (*)(const void *, const void *))compare);

    // Perform in-place sort based on descending double values and filtering based on the specified enum value.
    size_t j = 0;
    for (size_t i = 0; i < count; ++i) {
        if (data[i].value > cutoff && data[i].status == filter) {
            swap(&data[j], &data[i]);
            ++j;
        }
    }

    // Set the length of the new array to 'j' and free the remaining memory.
    count = j;
    data = realloc(data, count * sizeof(**data));
}

int compare(const void *a, const void *b) {
    return ((struct data_entry *)a)->value > ((struct data_entry *)b)->value ? 1 : -1;
}

void swap(struct data_entry *a, struct data_entry *b) {
    struct data_entry temp = *a;
    *a = *b;
    *b = temp;
}

// Main function to run the entire process.
int main(int argc, char **argv) {
    if (argc != 2) return -1;

    FILE *fp = fopen(argv[1], "r");
    if (!fp) return -1;

    size_t count = 8; // Initial array size
    struct data_entry *data;
    read_log(fp, &data, &count);

    sort_and_filter(data, count, DBL_MIN, COMPLETED);

    fclose(fp);
    free(data);

    return 0;
}
```
