2. Below is a JavaScript function for handling file uploads from URLs that supports large files, handles network delays, manages retries for failed uploads, and logs errors gracefully. This function should be integrated into a larger application where each `record` can be linked to a specific file being processed.

```javascript
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const formidable = require('formidable');
const { v4: uuidv4 } = require('uuid');

function uploadFileFromUrl(fileUrl, destinationDirectory, onProgress) {
    const outputPath = path.join(destinationDirectory, `${uuidv4()}.${path.extname(fileUrl)}`);
    const form = new formidable({
        multiples: false,
        uploadDir: destinationDirectory,
        keepExtensions: true,
        onProgress: onProgress,
        encoding: 'utf-8'
    });

    return new Promise((resolve, reject) => {
        form.on('fileBegin', (name, file) => {
            fs.mkdirSync(destinationDirectory, { recursive: true });
        });

        form.on('error', (err) => {
            console.error(`Error during file upload: ${err}`);
            reject(err);
        });

        form.on('end', () => {
            resolve({ outputPath, size: form._totalBytesExpected });
        });

        const request = axios.get(fileUrl, { responseType: 'stream' });
        request.on('error', (err) => {
            console.error(`Error downloading file from URL: ${err}`);
            reject(err);
        });
        form.parse(request);
    });
}
```

