#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    double value;
    struct Node *next;
} node;

struct ListManager {
    pthread_mutex_t lock;
    node* head;
    size_t capacity;
    size_t size;
};

void init_list(struct ListManager* list, size_t initial_capacity, double seed_value, double step_size) {
    list->head = NULL;
    list->capacity = initial_capacity;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);
}

node* create_node(double value) {
    node *new_node = (node*) malloc(sizeof(node));
    if (!new_node) {
        // Handle memory allocation failures
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return NULL;
    }
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void add_node(struct ListManager* list, double value) {
    pthread_mutex_lock(&list->lock);

    node *new_node = create_node(value);
    if (!new_node) {
        // Handle memory allocation failures
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        node *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    ++list->size;

    if (list->size >= list->capacity && list->capacity > 0) {
        // Resize array when necessary to avoid memory fragmentation
        resize_list(list, list->capacity * 2);
    }

    pthread_mutex_unlock(&list->lock);
}

void trim_unused_nodes(struct ListManager* list) {
    pthread_mutex_lock(&list->lock);

    node *current = list->head;
    while (current != NULL) {
        if (current->next == NULL && !current->value) {
            node *to_remove = current;
            current = current->next;
            free(to_remove);
            --list->size;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void resize_list(struct ListManager* list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);

    node **nodes = (node**) realloc(list->head, new_capacity * sizeof(node*));
    if (!nodes) {
        // Handle memory allocation failures
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->head = nodes;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->lock);
}
```

This code defines a `ListManager` structure that manages a singly linked list of 'node' structures. The `init_list()`, `add_node()`, and `trim_unused_nodes()` functions handle the basic operations on the list, with `init_list()` setting up the initial configuration for the linked list.

The `create_node()` function dynamically allocates memory for new nodes, providing a mechanism to handle memory allocation failures. The `resize_list()` function addresses memory fragmentation by resizing the array when necessary.

To minimize cache utilization, I've made sure that pointers are updated in-place rather than creating temporary variables to store intermediate results before assignment.

In terms of error handling and logging, I added printf statements for debugging purposes, but a production implementation would log errors using an appropriate logging library like `log4cplus` or `google::Log`.

Finally, the `trim_unused_nodes()` function periodically checks and removes unused nodes to optimize memory usage. This balances between maintaining a responsive system and reducing unnecessary resource consumption.']

