#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char str[256];
    enum status {ACTIVE, INACTIVE} status;
    int category;
} data_entry;

enum category {CAT1, CAT2, CAT3, CAT4};

void* read_file(const char *filename, size_t *doubles, size_t *strings, data_entry **entries, int *categories, pthread_barrier_t *barrier) {
    FILE *file = fopen(filename, "r");
    char line[4096];
    size_t i = 0;

    while (fgets(line, sizeof(line), file)) {
        data_entry *entry = malloc(sizeof(data_entry));
        sscanf(line, "%lf %s %d %d", &entry->value, entry->str, &(int)&entry->status, &(int)&entry->category);
        (*entries)[i++] = entry;
        (*categories)[i - 1] = entry->category;
    }
    fclose(file);

    pthread_barrier_wait(*barrier);
}

void sort_data_entries(size_t n, data_entry *entries) {
    qsort(entries, n, sizeof(data_entry), [](const void *a, const void *b) -> int { return ((data_entry*)a)->value - ((data_entry*)b)->value; });
}

void filter_and_group(size_t n, data_entry *entries, size_t *num_in_category, double *averages, double *max_doubles) {
    int categories[4] = {0};
    for (size_t i = 0; i < n; ++i)
        categories[entries[i].category]++;

    for (size_t i = 0; i < 4; ++i)
        num_in_category[i] = categories[i];

    for (size_t i = 0; i < 4; ++i) {
        size_t count = num_in_category[i];
        double sum = 0.0;

        for (size_t j = 0; j < count; ++j)
            sum += entries[i*count + j].value;

        averages[i] = sum / count;
    }

    *max_doubles = -1.0;
    for (size_t i = 0; i < n; ++i) {
        if (entries[i].value > *max_doubles)
            *max_doubles = entries[i].value;
    }
}

data_entry* process_file(const char *filename, enum status status, int category, size_t *num_entries, double *averages, double *max_double) {
    pthread_barrier_t barrier;
    pthread_init(&barrier, NULL);

    size_t doubles = 0, strings = 0, num_threads = 1 + (strlen(filename) % 4);
    data_entry *entries = NULL, *categories = malloc(sizeof(int) * num_threads);

    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, read_file, filename, &doubles, &strings, &entries, categories + (i * (4/num_threads)), &barrier))
            fprintf(stderr, "Error: Failed to create thread.\n");
    }

    pthread_barrier_wait(barrier);

    sort_data_entries(doubles, entries);

    size_t filtered_count = 0;
    for (size_t i = 0; i < doubles; ++i) {
        if (entries[i].status == status && entries[i].category == category)
            ++filtered_count;
    }

    data_entry *result = malloc(sizeof(data_entry) * filtered_count);
    size_t result_index = 0;

    for (size_t i = 0; i < doubles; ++i) {
        if (entries[i].status == status && entries[i].category == category) {
            result[result_index++] = entries[i];
        }
    }

    free(entries);
    free(categories);

    filter_and_group(filtered_count, result, num_entries, averages, max_double);

    free(result);

    return NULL;
}
```
