['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct Node {
    int key;
    char* value;
} Node;

typedef struct Array {
    Node* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    bool compact;
    size_t compaction_interval;
    clock_t last_compact;
} Array;

Array* array_create(const char* base, size_t initial_size, size_t compaction_interval) {
    Array* arr = malloc(sizeof(Array));
    if (!arr) return nullptr;

    arr->data = malloc(initial_size * sizeof(Node));
    if (!arr->data) goto fail;

    arr->size = initial_size;
    arr->capacity = initial_size;
    arr->compact = true;
    arr->compaction_interval = compaction_interval;
    arr->last_compact = 0;

    for (size_t i = 0; i < initial_size; ++i) {
        arr->data[i].key = i;
        char* key_str = strdup(base);
        if (!key_str) goto fail;
        sprintf(key_str + strlen(base), "%lu", i);
        arr->data[i].value = key_str;
    }

    pthread_mutex_init(&arr->lock, nullptr);
    return arr;

fail:
    if (arr) {
        free(arr);
    }
    return nullptr;
}

void array_destroy(Array* arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->data[i].value);
    }
    free(arr->data);
    free(arr);
}

void array_compact(Array* arr) {
    if (arr->last_compact + arr->compaction_interval >= clock()) return;

    size_t free_pos = 0;
    for (size_t i = 1; i < arr->size; ++i) {
        if (!arr->data[i].value) continue;

        free_pos = i + 1;
        break;
    }

    size_t merged_nodes = 0;
    for (size_t src = free_pos, dest = src; dest < arr->size; ++src, ++dest) {
        if (!arr->data[dest].value) continue;

        pthread_mutex_lock(&arr->lock);
        if (!arr->data[src].value) {
            arr->data[src] = arr->data[dest];
            arr->data[dest].value = nullptr;
            merged_nodes++;
        }
        pthread_mutex_unlock(&arr->lock);
    }

    if (merged_nodes > 0) {
        size_t new_size = (arr->size - merged_nodes) * 2;
        Node* new_data = realloc(arr->data, new_size * sizeof(Node));
        if (!new_data) return;
        arr->data = new_data;
        arr->capacity = new_size;
    }
    arr->last_compact = clock();
}

int array_get(Array* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    int key = arr->data[index].key;
    pthread_mutex_unlock(&arr->lock);
    return key;
}

const char* array_get_value(Array* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    char* value = arr->data[index].value;
    pthread_mutex_unlock(&arr->lock);
    return value;
}
```

This code defines a dynamic array of `Node` structures and provides functions to create, destroy, get key/values, and compact the memory. The array is thread-safe due to the use of a mutex lock for synchronization during concurrent access and updates from multiple threads. A configurable memory compaction feature has been implemented, which periodically scans the array to identify and reassign contiguous memory blocks for unused nodes. The frequency of these compactions can be adjusted using the `compaction_interval` parameter.

Error handling is minimal in this code example, but you should extend it to handle allocation failures and offer meaningful error messages to aid debugging and recovery. Additionally, consider integrating this function into a larger system, considering its interaction with external data sources and potential integration points, ensuring seamless operation within the broader context.']

