#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>

typedef struct {
    int key;
    int value;
    char str[256]; // Max string length of 255 characters (including null terminator)
} Record;

int is_valid_input(unsigned int n, unsigned long max_memory) {
    return n > 0 && n <= INT_MAX / sizeof(long) && n * sizeof(Record) + 2 * n * sizeof(int) <= max_memory;
}

void* reallocate(void* ptr, size_t old_size, size_t new_size) {
    void* new_ptr = realloc(ptr, new_size);
    if (!new_ptr) {
        fprintf(stderr, "Memory allocation error.\n");
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

void initialize_records(Record* records, unsigned int n) {
    for (unsigned int i = 0; i < n; ++i) {
        records[i].key = rand() % INT_MAX;
        int str_len = rand() % 256 + 1; // Generate a random string length between 1 and 255 characters
        memset(records[i].str, '\0', sizeof(records[i].str)); // Initialize the string with a null terminator
        for (int j = 0; j < str_len && j < 255; ++j) {
            records[i].str[j] = rand() % 128 + 'a'; // Generate random strings excluding null characters
        }
        records[i].value = rand() % 10000 - 5000; // Generate random integer values within [-5000, 5000)
    }
}

int main(void) {
    unsigned int n_records;
    long max_memory;

    printf("Enter the number of records: ");
    scanf("%u", &n_records);

    if (!is_valid_input(n_records, (long)(-1))) { // Prevent overflow and ensure valid input
        fprintf(stderr, "Invalid input. Please enter a value between 1 and the maximum allowed number of records.\n");
        return EXIT_FAILURE;
    }

    max_memory = (long)(n_records * sizeof(Record)) + 2 * n_records * sizeof(int);

    long* offsets = malloc(sizeof(long));
    int* keys1 = malloc(sizeof(int));
    int* keys2 = malloc(sizeof(int));
    Record* records = NULL;

    while (max_memory < 2 * n_records * sizeof(Record) + 4 * n_records * sizeof(int)) {
        max_memory *= 2;
    }

    records = reallocate(records, 0, max_memory - (2 * n_records * sizeof(int)));
    offsets = reallocate(offsets, sizeof(long), max_memory / sizeof(Record) + 1);
    keys1 = reallocate(keys1, sizeof(int), n_records);
    keys2 = reallocate(keys2, sizeof(int), n_records);

    offsets[0] = 0;
    for (unsigned int i = 1; i <= n_records; ++i) {
        offsets[i] = offsets[i - 1] + sizeof(int) * 2 + sizeof(Record);
    }

    initialize_records(records, n_records);

    for (unsigned int i = 0; i < n_records; ++i) {
        keys1[i] = records[offsets[i]].key;
        keys2[(i + 1) % n_records] = records[offsets[i]].key;
    }

    return EXIT_SUCCESS;
