// Metric structure definition
struct Metric {
    std::chrono::nanoseconds timestamp;
    char category;
    double value;
    const char* label; // Dynamically determined based on user input
    size_t labelLen;
};

class MetricList {
public:
    explicit MetricList(size_t capacity) : data(capacity), nextIndex(0), head(nullptr), tail(nullptr) {}

    ~MetricList() {
        while (!data.empty()) {
            auto metric = data.front();
            delete[] metric.label;
            data.pop_front();
        }
    }

    // Add a metric to the list
    void addMetric(const char* category, double value, const char* label, size_t labelLen) {
        if (nextIndex >= data.capacity()) {
            resize();
        }

        auto newMetric = &data[nextIndex++];
        newMetric->timestamp = std::chrono::nanoseconds(std::chrono::steady_clock::now().time_since_epoch());
        newMetric->category = category;
        newMetric->value = value;
        newMetric->label = new char[labelLen + 1]; // Plus one for null terminator
        std::copy(label, label + labelLen, newMetric->label);
        newMetric->label[labelLen] = '\0';
        newMetric->labelLen = labelLen;

        if (!head) {
            head = &data[nextIndex - 1]; // Previous element is the head when the list is empty
            tail = &data[nextIndex - 1];
        } else {
            tail->next = newMetric;
            tail = newMetric;
        }
    }

    // Compute aggregate statistics and integrate with external data processing library
    void processMetrics() {
        // Implement your data processing logic here using the aggregate metrics
    }

private:
    std::vector<Metric> data;
    size_t nextIndex;
    Metric* head;
    Metric* tail;

    void resize() {
        // Implement a memory management strategy that prevents leaks and ensures efficient use of system resources
    }
};

// Thread-safe wrapper for MetricList
class ThreadSafeMetricList : public MetricList {
public:
    explicit ThreadSafeMetricList(size_t capacity) : MetricList(capacity), mtx() {}

    void addMetric(const char* category, double value, const char* label, size_t labelLen) {
        std::unique_lock<std::mutex> lock(mtx);
        MetricList::addMetric(category, value, label, labelLen);
    }

private:
    std::mutex mtx;
};
