['```c
#include <dlfcn.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unordered_map>
#include <mutex>

typedef std::unordered_map<std::string, void*> LibraryCache;
typedef std::mutex LibraryCacheMutex;

LibraryCache g_libraryCache;
LibraryCacheMutex g_libraryCacheMutex;

int loadLibrary(const char* path) {
    if (!path || *path == '\0') {
        return 0;
    }

    void* handle = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return 0;
    }

    std::unique_lock<LibraryCacheMutex> lock(g_libraryCacheMutex);
    g_libraryCache[path] = handle;
    lock.unlock();

    return 1;
}

typedef void* (*LibrarySymbolLoader)(void*);

void* loadSymbol(const char* path, const char* symbolName) {
    if (!path || !symbolName || *path == '\0' || *symbolName == '\0') {
        return nullptr;
    }

    std::unique_lock<LibraryCacheMutex> lock(g_libraryCacheMutex);
    auto iter = g_libraryCache.find(path);
    if (iter == g_libraryCache.end()) {
        return nullptr;
    }

    LibrarySymbolLoader loader = reinterpret_cast<LibrarySymbolLoader>(dlsym(iter->second, "dlsym"));
    if (!loader) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return nullptr;
    }

    return loader(iter->second);
}

void unloadLibrary(const char* path) {
    if (!path || *path == '\0') {
        return;
    }

    std::unique_lock<LibraryCacheMutex> lock(g_libraryCacheMutex);
    auto iter = g_libraryCache.find(path);
    if (iter == g_libraryCache.end()) {
        return;
    }

    dlclose(iter->second);
    g_libraryCache.erase(iter);
}
```

This code provides a basic implementation for loading and unloading shared libraries at runtime in a multi-threaded environment. It uses a cache to store loaded libraries for quick retrieval, employs mutexes to manage concurrent access, and handles errors gracefully by providing error messages and returning appropriate results.']

