typedef struct record {
    long offset;
    int key;
    int value;
} record_t;

struct thread_data {
    size_t start;
    size_t end;
    record_t* records;
    pthread_mutex_t* mutexes;
};

void init_records(size_t num_records, record_t** records, size_t key_size) {
    *records = (record_t*)calloc(num_records, sizeof(record_t));
    if (!(*records)) return;

    for (size_t i = 0; i < num_records; ++i) {
        // Derive a key using desired method (user input or environmental variable)
        unsigned char key[32]; // Key size depends on algorithm used
        derive_key(key, key_size);

        // Apply non-linear transformation to the key
        int transformed_key = transform_key(key);

        // Initialize record with derived key and randomly generated value
        (*records)[i].key = transformed_key;
        (*records)[i].value = random();
    }
}

void* process_records(void* data) {
    struct thread_data* td = (struct thread_data*)data;
    record_t* records = td->records;
    pthread_mutex_t* mutexes = td->mutexes;
    size_t start = td->start;
    size_t end = td->end;

    for (size_t i = start; i < end; ++i) {
        pthread_mutex_lock(&mutexes[i]);

        // Apply desired transformation algorithm to the value using the key
        records[i].value = transform_value(records[i].key, records[i].value);

        pthread_mutex_unlock(&mutexes[i]);
    }

    return NULL;
}

void process_large_dataset(size_t num_records, size_t key_size, size_t batch_size, size_t thread_pool_size, const char* encryption_mode) {
    record_t* records;
    pthread_mutex_t* mutexes = (pthread_mutex_t*)calloc(num_records, sizeof(pthread_mutex_t));
    if (!mutexes) return;

    init_records(num_records, &records, key_size);

    pthread_t* threads = (pthread_t*)malloc(thread_pool_size * sizeof(pthread_t));
    struct thread_data* thread_datas = (struct thread_data*)calloc(thread_pool_size, sizeof(struct thread_data));

    size_t num_batches = num_records / batch_size;
    for (size_t i = 0; i < num_batches; ++i) {
        thread_datas[i].start = i * batch_size;
        thread_datas[i].end = (i == num_batches - 1) ? num_records : (i + 1) * batch_size;
        thread_datas[i].records = records;
        thread_datas[i].mutexes = mutexes;
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setscope(&attr, PTHREAD_SCOPE_SYSTEM); // Use system-wide scheduling
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    for (size_t i = 0; i < thread_pool_size; ++i) {
        pthread_create(&threads[i], &attr, process_records, &thread_datas[i]);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < thread_pool_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(records);
    free(mutexes);
    free(thread_datas);
    free(threads);
}
