                        !entry.TryGetProperty("status", out JsonElement statusEl) ||
                        !entry.TryGetProperty("errorCount", out JsonElement errorCountEl))
                    {
                        _logger.LogWarning($"Missing or invalid field(s) in configuration entry.");
                        return;
                    }

                    ApiConfig config = new()
                    {
                        Endpoint = endpointEl.GetString(),
                        Token = tokenEl.GetString(),
                        Timeout = timeoutEl.GetInt32(),
                        LastAccessed = lastAccessedEl.GetDateTime(),
                        Status = (Status)statusEl.GetInt32(),
                        ErrorCount = errorCountEl.GetInt32()
                    };

                    apiConfigs[config.Endpoint] = config;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to process configuration entry.");
                }
            });
        });

        foreach (var apiConfig in apiConfigs.Values.ToList())
        {
            try
            {
                var (token, status) = await _apiTokenCache.GetOrAddAsync(apiConfig.Endpoint, cancellationToken);

                if (status != Status.Valid)
                    apiConfig.Status = status;
                else
                    apiConfig.LastAccessed = DateTime.UtcNow;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to retrieve token for API configuration.");
            }
        }

        return apiConfigs;
    }
}
```

This code is a starting point and may require further adjustments to meet your exact requirements. It demonstrates the usage of asynchronous operations, memory caching, logging and validation of JSON structure. Keep in mind that this example assumes the existence of an ILogger and IMemoryCache implementation provided by Microsoft's .NET Core framework.']

