record* init_data(size_t size) {
    record *data = malloc(size * sizeof(record));

    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return nullptr;
    }

    for (size_t i = 0; i < size; ++i) {
        data[i].value = rand() % 20001 - 10000;
    }

    qsort(data, size, sizeof(record), [](const void *a, const void *b) {
        return ((record*)a)->value - ((record*)b)->value;
    });

    int keys[1000];
    int unique_keys[5001] = {0};

    for (size_t i = 0; i < size; ++i) {
        int key = data[i].value + 5000;

        if (!unique_keys[key]) {
            unique_keys[key] = true;
            keys[data[i].index] = key;
        } else {
