typedef struct {
    int key;
    long offset;
} record;

enum status_codes {
    SUCCESS = 0,
    MEMORY_ERROR = -1,
    INVALID_INPUT = -2,
};

int allocate_and_initialize_data(size_t *long_arr_size, size_t *int_arr_size, size_t *record_count, int **long_arr, int **int_arr, record ***records) {
    if (*long_arr_size <= 0 || *int_arr_size <= 0 || *record_count <= 0)
        return INVALID_INPUT;

    // Allocate offset and key arrays
    *long_arr = malloc(*long_arr_size * sizeof(long));
    if (!*long_arr)
        return MEMORY_ERROR;

    *int_arr = calloc(*int_arr_size, sizeof(int));
    if (!*int_arr) {
        free(*long_arr);
        return MEMORY_ERROR;
    }

    // Allocate initial size for record array and calculate required capacity
    *records = malloc(*record_count * sizeof(record));
    if (!*records) {
        free(*long_arr);
        free(*int_arr);
        return MEMORY_ERROR;
    }

    // Calculate needed capacity for record array to account for potential future additions
    size_t records_capacity = *record_count + *record_count / 2; // reserve extra space

    *records = realloc(*records, records_capacity * sizeof(record));
    if (!*records) {
        free(*long_arr);
        free(*int_arr);
        return MEMORY_ERROR;
    }

    srand(time(NULL));

    // Randomly initialize offset and key fields, ensuring no duplicates
    for (size_t i = 0; i < *record_count; ++i) {
        int j = 0;
        do {
            (*records)[i].key = (*int_arr)[j];
            (*records)[i].offset = (*long_arr)[j];
            j++;
        } while (j < *int_arr_size && (*records + i)->key == (*int_arr)[j]);

        // If no unused key is found, reuse the current one and generate a new offset
        if (j >= *int_arr_size) {
            int existing_key = (*records)[i].key;
            for (size_t k = 0; k < i; ++k) {
                if ((*records + k)->key == existing_key) {
                    (*records)[i].key = existing_key;
                    break;
                }
            }
            (*records)[i].offset = rand();
        }
    }

    return SUCCESS;
}
