int create_data_set(size_t num_timestamps, size_t num_temp_points, const char *temp_dataset1[], const char *temp_dataset2[], data_point **data) {
    if (!num_timestamps || !num_temp_points || !temp_dataset1 || !temp_dataset2 || !(data))
        return 1; // Invalid input

    size_t max_timestamp_idx = num_timestamps - 1;
    char **timestamps = calloc(num_timestamps, sizeof(char*));
    if (!timestamps)
        return 2; // Allocation error

    float *temps = calloc(2 * num_temp_points, sizeof(float));
    if (!temps) {
        free(timestamps);
        return 3; // Allocation error
    }

    for (size_t i = 0; i < num_temp_points; ++i) {
        temps[2 * i] = temp_dataset1[i];
        temps[2 * i + 1] = temp_dataset2[i];
    }

    data_point **data_points = calloc(num_timestamps, sizeof(data_point*));
    if (!data_points) {
        free(timestamps);
        free(temps);
        return 4; // Allocation error
    }

    for (size_t i = 0; i < num_timestamps; ++i) {
        size_t j, count = 0, found = 0;
        for (j = 0; j < i && !found; ++j) {
            if (!strcmp(timestamps[j], timestamps[i])) {
                found = 1;
            }
        }

        if (!found) {
            data_points[i] = malloc(sizeof(data_point));
            if (!data_points[i]) {
                free(timestamps);
                free(temps);
                for (size_t k = 0; k < i; ++k) {
                    free(data_points[k]);
                }
                free(data_points);
                return 5; // Allocation error
            }

            data_points[i]->timestamp = timestamps[i] = strdup(timestamps[i]);
            float interpolated_temp = linear_interpolation(temps, temp_dataset1, temp_dataset2, i, j);
            data_points[i]->temperature = interpolated_temp;
        } else {
            data_points[i] = data_points[j];
        }
    }

    *data = data_points;
    return 0; // Success
}

float linear_interpolation(const float *temps, const char **temp_dataset1, const char **temp_dataset2, size_t idx1, size_t idx2) {
    if (idx1 == idx2)
        return temps[2 * idx1];

    float t = (idx2 - idx1) / static_cast<float>(idx2 - idx1);
    return temps[2 * idx1] + t * (temps[2 * idx2] - temps[2 * idx1]);
}
