typedef struct {
    float value_f;
    int value_i;
    bool value_b;
    char str[256]; // Adjust this size based on your expected maximum string length
} dataPoint;

typedef struct MemManager {
    dataPoint* dataPoints;
    size_t capacity;
    size_t used;
    size_t max_string_size;
} MemManager;

MemManager* create_mem_manager(size_t initial_capacity, size_t max_string_size) {
    MemManager* mm = (MemManager*)malloc(sizeof(MemManager));
    mm->dataPoints = (dataPoint*)calloc(initial_capacity, sizeof(dataPoint));
    mm->capacity = initial_capacity;
    mm->used = 0;
    mm->max_string_size = max_string_size;
    return mm;
}

void resize_mem_manager(MemManager* mm) {
    dataPoint* temp_dataPoints = (dataPoint*)realloc(mm->dataPoints, (mm->capacity * 2) * sizeof(dataPoint));
    if (!temp_dataPoints) {
        fprintf(stderr, "Out of memory error\n");
        return;
    }
    mm->dataPoints = temp_dataPoints;
    mm->capacity *= 2;
}

void free_mem_manager(MemManager* mm) {
    free(mm->dataPoints);
    free(mm);
}

void add_dataPoint(MemManager* mm, const char* string, float value_f, int value_i, bool value_b) {
    if (mm->used == mm->capacity) {
        resize_mem_manager(mm);
    }
    dataPoint* dp = &mm->dataPoints[mm->used];
    strncpy(dp->str, string, mm->max_string_size);
    dp->value_f = value_f;
    dp->value_i = value_i;
    dp->value_b = value_b;
    mm->used++;
}

void print_dataPoints(MemManager* mm) {
    for (size_t i = 0; i < mm->used; ++i) {
        printf("String: %s, Value F: %.2f, Value I: %d, Value B: %d\n", mm->dataPoints[i].str, mm->dataPoints[i].value_f, mm->dataPoints[i].value_i, mm->dataPoints[i].value_b);
    }
}
