const axios = require('axios');
const FormData = require('form-data');
const Worker = require('worker_threads');

// External service URL
const SERVICE_URL = 'https://external-processing-service.com';

// Worker data structure
class UploadWorkerData {
  constructor(file, index, callback) {
    this.file = file;
    this.index = index;
    this.callback = callback;
  }
}

class FileMetadata {
  constructor(offset, key, timestamp) {
    this.offset = offset;
    this.key = key;
    this.timestamp = timestamp;
  }
}

// Main function to upload multiple files asynchronously using Axios and FormData
async function uploadFiles(fileUrls, processService) {
  // Initialize file metadata list and worker queue
  const fileMetadata = [];
  const workerQueue = new Map();

  try {
    // Download files and store their metadata for later use
    for (let i = 0; i < fileUrls.length; i++) {
      const response = await fetch(fileUrls[i]);
      const contentType = response.headers.get('content-type');
      const fileSize = response.headers.get('content-length');
      const chunks = Array.from({ length: Number(fileSize) }, () => new Uint8Array(response.slice(Math.min(i * 1024, response.size), Math.min((i + 1) * 1024, response.size))));

      fileMetadata.push(new FileMetadata(i, i, Date.now()));
    }

    // Initialize worker threads with batchSize and concurrency limits based on system resources
    const batchSize = Math.min(fileUrls.length / 2, Worker.workers.length * 2);
    const concurrencyLimit = Math.min(Math.floor(Worker.workers.availableParallelJobs / 4), fileUrls.length);

    // Create worker threads to handle uploads in parallel and manage progress/errors via a MessageChannel
    for (let i = 0; i < batchSize; i += concurrencyLimit) {
      const chunk = fileUrls.slice(i, i + concurrencyLimit);
      const workerData = new Worker(`worker.js`, {
        workerData: JSON.stringify({ fileUrls: chunk, serviceURL: SERVICE_URL })
      });

      workerQueue.set(workerData.id, new UploadWorkerData(null, i, (progress, error) => {
        if (error) console.error(`Error uploading file ${i}:`, error);
        else console.log(`Progress for file ${i}:`, progress);
      }));
    }

    // Process worker results and update file metadata when complete
    for (const [workerId, workerData] of workerQueue) {
      const workerResult = await workerData.terminate();
      if (workerResult.progress !== undefined) {
        fileMetadata[workerResult.index].progress = workerResult.progress;
      }
    }
  } catch (error) {
    console.error('Error uploading files:', error);
  }

  // Prepare and send batches to the external service, handling timeouts and retries
  const batchFiles = chunkBatch(fileMetadata, batchSize);
  for (const batch of batchFiles) {
    try {
      const response = await axios.post(`${SERVICE_URL}/batch`, batch, {
        headers: { 'Content-Type': 'application/json' },
        maxRedirects: 0,
        timeout: 60 * 1000 // 1 minute request timeout
      });

      // Handle response and update file metadata accordingly
      for (let i = 0; i < batch.length; i++) {
        const index = batch[i].key;
        if (response.data[index] !== undefined) {
          fileMetadata[index].status = 'processed';
          fileMetadata[index].timestamp = Date.now();
          console.log(`File ${index} processed successfully.`);
        } else {
          fileMetadata[index].error = `Error processing file ${index}: ${response.data[index]}`;
          console.error(fileMetadata[index].error);
        }
      }
    } catch (error) {
      console.error(`Error sending batch to service: ${error}`);
    }
  }
}

// Helper function to chunk an array into smaller batches based on size
function chunkBatch(arr, size) {
  const chunks = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
