#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <memory>
#include <json/json.h> // External data processing library (JSON format)
#include <sstream>

struct Record {
    int key;
    long offset;
};

class MemoryPool {
public:
    std::unique_ptr<Record[]> allocate(size_t size) {
        if (freeList.empty()) {
            auto newData = std::make_unique<Record[]>(size);
            for (auto& r : newData) {
                r.key = -1; // Mark as unused
                r.offset = 0;
                freeList.push_back(std::move(r));
            }
        }
        auto data = freeList.back();
        freeList.pop_back();
        return std::move(data);
    }

    void deallocate(Record* record) {
        record->key = -1; // Mark as unused
        freeList.push_back(*record);
    }

private:
    std::vector<Record> freeList;
};

std::mutex mtx; // Mutex for thread safety
MemoryPool memPool; // Memory pool instance

void populateRecords(Record* records, size_t count, int minKey, int maxKey) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr(minKey, maxKey);

    for (size_t i = 0; i < count; ++i) {
        records[i].key = distr(gen);
        records[i].offset = i * 100; // Simple resizing strategy: fixed step between elements
    }
}

void processRecords(std::unique_ptr<Record[]> records, size_t count) {
    Json::Value root;
    Json::FastWriter writer;

    std::unique_lock<std::mutex> lock(mtx);

    for (size_t i = 0; i < count; ++i) {
        // Process each record and store the result in JSON format
        auto record = records[i];
        Json::Value data;
        data["key"] = record.key;
        data["offset"] = record.offset;
        root[i] = data;
    }

    std::string jsonStr = writer.write(root);
    // Handle the processed JSON data using the external library
}

int main() {
    const int minKey = 0;
    const int maxKey = 1000;
    const size_t recordCount = 100000;
    const size_t threadCount = std::thread::hardware_concurrency();

    std::unique_ptr<Record[]> records = memPool.allocate(recordCount);
    populateRecords(records.get(), recordCount, minKey, maxKey);

    std::vector<std::thread> threads;
    for (size_t i = 0; i < threadCount; ++i) {
        threads.push_back(std::thread(processRecords, std::ref(records), std::ref(recordCount)));
    }

    for (auto& t : threads) {
        t.join();
    }

    memPool.deallocate(records.get());
    return 0;
}
