void init_memory_pool(MemoryPool *mp, size_t size, size_t capacity) {
    mp->pool = mmap(NULL, capacity * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mp->pool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

