{
    private const int ChunkSize = 1024 * 1024; // 1MB chunks
    private const int HashBufferSize = SHA256.HashSize / 8; // 32 bytes for SHA-256
    private const int MaxOffsetsCount = 1000000; // Max count of offset values
    private const int KeyRangeStart = 1;
    private const int KeyRangeEnd = 1000000;
    private const int RandomValueRangeStart = 0;
    private const int RandomValueRangeEnd = 10000000;
    private readonly ConcurrentQueue<long> _offsetsQueue;
    private readonly SemaphoreSlim _semaphore;
    private byte[] _hashBuffer;
    private SHA256 _sha256;
    private long _processedBytes;
    private long _totalBytes;
    private int _numOfRecordsProcessed;
    private BlockDisposeBlock _memoryManager;

    public ProcessTextFileWithMemoryManagement(int concurrencyDegree)
    {
        _offsetsQueue = new ConcurrentQueue<long>();
        _semaphore = new SemaphoreSlim(concurrencyDegree);
        _hashBuffer = new byte[HashBufferSize];
        _sha256 = SHA256.Create();
        _memoryManager = new BlockDisposeBlock();
    }

    public void ProcessFile(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException($"The specified file '{filePath}' does not exist.");

        var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read);
        _totalBytes = stream.Length;

        using (stream)
        {
            long position = 0;
            while (position < _totalBytes)
            {
                _semaphore.Wait();

                var chunkSize = Math.Min(ChunkSize, _totalBytes - position);
                var offsetBuffer = _memoryManager.Allocate<long>(MaxOffsetsCount);
                var recordBuffer = _memoryManager.Allocate<Record>((int)(chunkSize / sizeof(Record)));
                var keyBuffer = _memoryManager.Allocate<int>(MaxOffsetsCount);
                var typeIdentifierBuffer = _memoryManager.Allocate<string>(MaxOffsetsCount, Encoding.UTF8);

                try
                {
                    position += chunkSize;
                    stream.Position = position;

                    var reader = new BinaryReader(stream);
                    for (var i = 0; i < chunkSize / sizeof(Record); ++i)
                    {
                        var record = reader.ReadStruct<Record>(true);
                        if (!ValidateRecord(record))
                            continue;

                        _numOfRecordsProcessed++;
                        offsetBuffer[^1] = position - (chunkSize - sizeof(Record));
                        recordBuffer[i] = record;
                        keyBuffer[^1] = record.Key;
                        typeIdentifierBuffer[^1] = record.TypeIdentifier;
                    }

                    Parallel.ForEach(offsetBuffer.TakeWhile(o => o > 0), options => ProcessChunk(offsetBuffer, recordBuffer, keyBuffer, typeIdentifierBuffer, position));

                    _processedBytes += chunkSize;
                    _semaphore.Release();
                }
                catch (Exception ex) when (!(ex is OutOfMemoryException)) // Handle only specific OutOfMemoryException cases
                {
                    Console.WriteLine($"Error processing file: {ex}");
                }
            }
        }
    }

    private void ProcessChunk(long[] offsets, Record[] records, int[] keys, string[] typeIdentifiers, long chunkStartPosition)
    {
        var hashes = new byte[offsets.Length][];
        Parallel.ForEach(offsets, o =>
        {
            if (o <= 0)
                return;

            var position = chunkStartPosition + o;
            using (var stream = new FileStream("large_text_file", FileMode.Open, FileAccess.Read))
            {
                stream.Seek(position, SeekOrigin.Begin);
                stream.ReadExact(_hashBuffer, 0, _hashBuffer.Length);
                hashes[offsets.ToList().IndexOf(o)] = _hashBuffer;
            }
        });

        var finalHash = CalculateFinalHash(hashes);
        // Implement saving the final hash in binary or base64 format, caching strategies, logging memory usage and additional tasks here...
    }

    private bool ValidateRecord(Record record)
    {
        if (record.Key < KeyRangeStart || record.Key > KeyRangeEnd || record.Value >= RandomValueRangeEnd || record.TypeIdentifier.Length > 128)
            return false;

        // Implement custom logic to validate and process each record type based on the structure and requirements...
    }

    private byte[] CalculateFinalHash(byte[][] hashes)
    {
        var combinedHash = new byte[hashes.Sum(h => h.Length)];
        var combinedHashIndex = 0;

        Parallel.ForEach(hashes, hash => Array.Copy(hash, 0, combinedHash, combinedHashIndex, hash.Length));

        using (SHA256 sha256 = SHA256.Create())
            combinedHash = sha256.ComputeHash(combinedHash);

        return combinedHash;
    }
}

