#define SET_SIZE 1024 // Adjust based on use case
struct sets {
    set elements[SET_SIZE];
};

void make_set(int i) {
    if (i < SET_SIZE && elements[i].count == 0) {
        elements[i].parent = i;
        elements[i].count = 1;
    }
}

int find_set(int i) {
    int root = i;
    while (elements[root].parent != root) {
        root = elements[root].parent;
    }
    return root;
}

void union_sets(int x, int y) {
    int xr = find_set(x);
    int yr = find_set(y);

    if (xr == yr) return;

    if (elements[xr].count < elements[yr].count) {
        elements[yr].parent = xr;
        elements[xr].count += elements[yr].count;
    } else {
        elements[xr].parent = yr;
        elements[yr].count += elements[xr].count;
    }
}

