    ht->load_factor = lf;
    ht->table = calloc(size, sizeof(ht_node*));
}

unsigned long hash(unsigned long key) {
    return key % ht->size;
}

void resize_hash(hash_table *ht) {
    unsigned long old_size = ht->size;
    unsigned long new_size = old_size * 2;

    hash_table temp;
    init_hash(&temp, new_size, ht->load_factor);

    for (unsigned long i = 0; i < old_size; ++i) {
        ht_node *current = ht->table[i];
        while (current != NULL) {
            ht_node *next = current->next;
            unsigned long index = hash(current->data.key);
            free(current);
            current = next;
            if (temp.table[index] == NULL) {
                temp.table[index] = current;
            } else {
                ht_node *head = temp.table[index];
                while (head->next != NULL) {
                    head = head->next;
                }
                head->next = current;
            }
        }
    }

    free(ht->table);
    ht->table = temp.table;
}

void insert_hash(hash_table *ht, record data) {
