            current = current->next;
        }
        current->next = malloc(sizeof(ht_node));
        current->next->data = data;
        current->next->next = NULL;
    }

    if ((double)ht->table[index]->count / ht->size >= ht->load_factor) {
        resize_hash(ht);
    }
}

