fn manage_directory(path: &Path, forced: bool, config: Config, lock: Lock) -> Result<(), ()> {
    if !is_valid_path(config.read().unwrap(), path) {
        return Err(()); // Return early if the path is not valid according to the whitelist.
    }

    let mut attempt_queue = VecDeque::new();
    attempt_queue.push_back((path.to_owned(), 0));

    while let Some((current_path, attempts)) = attempt_queue.pop_front() {
        if atomic(|lock| create_directory(&current_path, &config, lock)).is_ok() {
            set_env_var("DIRECTORY", current_path.to_string_lossy().into_owned(), &config);
            return Ok(());
        }

        let sleep_duration = match attempts {
            0 => Duration::from_secs(1), // Initial delay
            _ => Duration::from_secs((2 ** attempts) as u64), // Exponential backoff
        };

        thread::sleep(sleep_duration);
        attempt_queue.push_back((current_path, attempts + 1));
    }

    if forced {
        force_recreate(&path, &config);
    } else {
        log_directory_creation(path, Err(())); // Log the failed creation attempt without fallback
    }

    Err(())
}
