1. Memory Pool:
Create a custom memory pool class that uses a slab allocation strategy for efficient memory management. Implement a locking mechanism for thread safety.

```cpp
#include <iostream>
#include <pthread.h>
#include <vector>

template<typename T>
class MemoryPool {
private:
    std::vector<T*> free_list;
    std::vector<std::vector<T>> slabs;
    size_t slab_size;
    pthread_mutex_t mutex;

public:
    MemoryPool(size_t initial_slab_size) : slab_size(initial_slab_size), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    T* allocate() {
        pthread_mutex_lock(&mutex);
        if (!free_list.empty()) {
            T* object = free_list.back();
            free_list.pop_back();
            pthread_mutex_unlock(&mutex);
            return object;
        }

        if (slabs.empty() || slabs.back().size() == 0) {
            slabs.push_back(std::vector<T>(slab_size));
            for (auto& slab : slabs) {
                if (slab.size() > 0) break;
            }
        }

        T* object = &slabs[slabs.size() - 1][slabs[slabs.size() - 1].size()];
        slabs[slabs.size() - 1].push_back(T());
        pthread_mutex_unlock(&mutex);
        return object;
    }

    void deallocate(T* object) {
        pthread_mutex_lock(&mutex);
        free_list.push_back(object);
        pthread_mutex_unlock(&mutex);
    }
};
```

