#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_SIZE 10000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct HashNode {
    Record data;
    struct HashNode* next;
} HashNode;

struct Hashtable {
    unsigned int size;
    HashNode** table;
};

// Custom memory allocation function
typedef void* (*AllocFunc)(size_t);

void initHashtable(struct Hashtable* ht, AllocFunc alloc) {
    ht->size = MAX_SIZE;
    ht->table = (HashNode**)calloc(MAX_SIZE, sizeof(HashNode*));
    if (!ht->table) {
        printf("Error: Failed to allocate memory for hashtable.\n");
        exit(1);
    }
    for (unsigned int i = 0; i < MAX_SIZE; ++i) {
        ht->table[i] = NULL;
    }
}

HashNode* createNode(Record data, AllocFunc alloc) {
    return (HashNode*)alloc(sizeof(HashNode));
}

unsigned int hashFunction(const unsigned int size, unsigned int key) {
    return key % size;
}

void insertRecord(struct Hashtable* ht, Record data) {
    HashNode** slot = &ht->table[hashFunction(ht->size, data.key)];
    HashNode* current = *slot;

    while (current != NULL) {
        if (current->data.key == data.key) {
            current->offset += data.offset;
            return;
        }
        current = current->next;
    }

    // Allocate and initialize new node with given data and next pointer as NULL
    HashNode* new_node = createNode(data, malloc);
    new_node->next = *slot;
    *slot = new_node;
}

