        free(tempRecords);
        return -1;
    }

    // Reinitialize the sorted array with valid records only
    for (int i = 0; i < numRecords; ++i) {
        (*records)[i] = tempRecords[i];
    }

    free(tempRecords + numRecords);

    return numRecords;
}

void* compareRecords(const void* a, const void* b, size_t size) {
    const Record* recordA = (const Record*)a;
    const Record* recordB = (const Record*)b;

    if (recordA->key < recordB->key) return -1;
    if (recordA->key > recordB->key) return 1;

    return 0;
}
