        data = (entry*)malloc(capacity * sizeof(entry));
        if (!data) {
            log_error("Memory allocation failure");
            return NULL;
        }
    }

    entry* new_data = realloc(data, (size + 1) * sizeof(entry));
    if (!new_data) {
        log_error("Memory allocation failure");
        return NULL;
    }

    capacity = size + 1;
    data = new_data;
    return &data[capacity - 1];
}

void init_entry(entry* entry, double value, const char* str, size_t length) {
