void processRecordsAndModifyList(std::forward_list<std::string>& list, long offset, int key, std::vector<Record, Allocator>& records, bool readOptimized, const Allocator& alloc) {
    if (records.empty()) { // Empty vector check
        if (!readOptimized) {
            records.resize(1, Record(std::rand((unsigned long long)1 << 32 - offset % 32, std::rand((unsigned long long)1 << 32 - key % 32)));
        }
