        std::mt19937 rng(seed);
        std::uniform_int_distribution<> dist(0, (unsigned long long)1 << 32 - (readOptimized ? 32 : 0));
        Record newRecord(dist(rng));

        auto it = list.begin();
        if (it != list.end() && *it == list.front()) { // Find first occurrence of the string
            it = list.insert(++it, list.front());
            list.erase(list.begin());
            records.push_back(newRecord, alloc);
        } else { // Append the second string argument and record to the end
            list.push_back(list.front());
            if (!readOptimized) {
                records.push_back(newRecord, alloc);
            }
        }
    }

    if (!readOptimized && list.size() > 1000) { // Optimize for write performance with large lists
        list.resize(list.size() / 2);
    }
