typedef struct {
    float timestamp;
    int buffer_len;
    char* buffer;
} Event;

void init_event_array(Event** events, size_t num_events, float* timestamps, int* buffer_lens) {
    for (size_t i = 0; i < num_events; ++i) {
        // Check if memory allocation is successful and if data is valid.
        if (!timestamps[i] || !buffer_lens[i]) {
            fprintf(stderr, "Invalid or missing data at index %zu\n", i);
            return;
        }

        // Calculate the required buffer size and align it to a suitable value.
        size_t buf_size = buffer_lens[i];
        size_t aligned_buf_size = (buf_size + sizeof(char) - 1) & ~(sizeof(char) - 1);

        // Allocate memory for the event and the buffer.
        Event* event = realloc(*events, ((i + 1) * sizeof(Event)));
        if (!event) {
            fprintf(stderr, "Out of memory\n");
            return;
        }
        (*events) = event;

        char* buffer = malloc(aligned_buf_size);
        if (!buffer) {
            fprintf(stderr, "Out of memory\n");
            free(*events + i);
            return;
        }

        // Initialize the event and set its buffer pointer.
        (*events)[i].timestamp = timestamps[i];
        (*events)[i].buffer_len = buffer_lens[i];
        (*events)[i].buffer = buffer;
    }
}
