['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    char identifier;
    unsigned int value;
} Item;

typedef struct Node {
    Item item;
    struct Node *next;
} Node;

struct Collection {
    size_t size;
    size_t capacity;
    Node **items;
    pthread_mutex_t mutex;
    FILE *log_file;
};

void create_collection(struct Collection *col, size_t initial_size) {
    col->size = 0;
    col->capacity = initial_size;
    col->items = calloc(initial_size, sizeof(Node*));
    if (!col->items) {
        fprintf(stderr, "Failed to allocate memory for collection\n");
        exit(1);
    }

    col->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void log_operation(struct Collection *col, const char *operation) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    fprintf(col->log_file, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
            tm_now->tm_year + 1900, tm_now->tm_mon + 1, tm_now->tm_mday,
            tm_now->tm_hour, tm_now->tm_min, tm_now->tm_sec, operation);
}

Node* create_node(const Item item) {
    Node *new_node = (Node *) malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        exit(1);
    }

    new_node->item = item;
    new_node->next = NULL;

    return new_node;
}

void insert(struct Collection *col, const Item item) {
    pthread_mutex_lock(&col->mutex);

    if (col->size == col->capacity) {
        size_t new_capacity = 2 * col->capacity;
        Node **new_items = realloc(col->items, new_capacity * sizeof(Node*));
        if (!new_items) {
            fprintf(stderr, "Failed to allocate memory for expanded collection\n");
            pthread_mutex_unlock(&col->mutex);
            exit(1);
        }
        col->items = new_items;
        col->capacity = new_capacity;
    }

    unsigned long index = item.identifier % col->capacity;
    Node *head = &col->items[index];
    Node *new_node = create_node(item);

    if (head->next) {
        new_node->next = head->next;
        head->next = new_node;
    } else {
        col->items[index] = new_node;
    }

    log_operation(col, "inserted");
    pthread_mutex_unlock(&col->mutex);
}

// Implement other functions for lookup, update, and deletion operations here
```

