        int startIndex = i * eventChunkSize;
        int endIndex = (i == numThreads - 1) ? events.size() : (i + 1) * eventChunkSize;
        chunks[i].reset(new Event[endIndex - startIndex]);

        auto chunkEvents = std::unique_ptr<Event[]>(chunks[i].get());
        std::copy(eventArray->begin() + startIndex, eventArray->begin() + endIndex, chunkEvents->begin());

        threads.emplace_back([this, &events, compress, startIndex, endIndex] (EventChunk& e) mutable {
            for (size_t i = startIndex; i < endIndex; ++i) {
                auto& event = events[i];
                initializeEvent(e + (i - startIndex), event.timestamp, event.buffer_length, compress);
            }
        }, std::ref(chunks[i]));
    }

    for (auto& t : threads) {
        t.join();
    }

    // Merge the chunks back into the main array and update the total memory usage
    std::move(chunks[0].release(), std::end(eventArray));

    {
        std::lock_guard<std::mutex> lock(g_mutex);
        totalMemory += eventArray->size() * sizeof(Event); // Calculate the total memory used by the array

        for (const auto& e : *eventArray) {
            if (e.compressedBuffer) {
                maxMemory = std::max(maxMemory, getCompressedSize(e.buffer_length));
            }
        }
    }
}

