```java
import java.sql.*;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
import static java.lang.String.format;

public class SessionAggregator {
    private final Supplier<Connection> connectionSupplier;
    private Map<String, LocalDateTime> lastSessionIds = new ConcurrentHashMap<>();
    private Map<String, Long> sessionDurationMap = new ConcurrentHashMap<>();
    private static final int MAX_SESSION_ID_LENGTH = 32;

    public SessionAggregator(Supplier<Connection> connectionSupplier) {
        this.connectionSupplier = Objects.requireNonNull(connectionSupplier);
    }

    public String aggregateMetrics(String sessionId) {
        if (sessionId == null || sessionId.isEmpty() || sessionId.length() > MAX_SESSION_ID_LENGTH) {
            System.err.println("Warning: Invalid session ID: " + sessionId);
            return "";
        }

        LocalDateTime lastSessionTime = lastSessionIds.get(sessionId);
        if (lastSessionTime != null) {
            long duration = System.currentTimeMillis() - lastSessionTime.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
            sessionDurationMap.put(sessionId, duration);
        } else {
            try (Connection connection = connectionSupplier.get()) {
                PreparedStatement stmt = connection.prepareStatement("SELECT start_time FROM Sessions WHERE user_id = ?");
                stmt.setString(1, sessionId);
                ResultSet rs = stmt.executeQuery();
                if (rs.next()) {
                    lastSessionTime = LocalDateTime.ofInstant(rs.getTimestamp("start_time").toLocalDateTime(), ZoneId.systemDefault());
                    lastSessionIds.put(sessionId, lastSessionTime);
                }
            } catch (SQLException e) {
                // Handle database errors gracefully
            }
        }

        if (lastSessionTime != null) {
            long duration = System.currentTimeMillis() - lastSessionTime.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
            double avgActivity = sessionDurationMap.getOrDefault(sessionId, 0L) / (System.currentTimeMillis() - lastSessionTime.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli());
            String result = format("Session duration: %d ms, Average activity: %.2f", duration, avgActivity);
            return result;
        } else {
            return "No session found for ID: " + sessionId;
        }
    }
}
