#include <boost/asio.hpp>
#include <boost/noncopyable.hpp>

class Event {
public:
    explicit Event(std::string description)
        : description_(std::move(description)) {}

    void set_id() {
        if (++id_ == std::numeric_limits<int>::max()) id_ = 0;
        id_ = id_;
    }

    int get_id() const { return id_; }

    long get_timestamp() const { return timestamp_; }

    const std::string& get_description() const { return description_; }

private:
    static std::atomic<int> id_;
    long timestamp_;
    std::string description_;
};

std::atomic<int> Event::id(0);

class DynamicList {
public:
    void add_event(const std::string& description) {
        events_.emplace_back(description);
        events_.back().set_id();
        events_.back().timestamp_ = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
    }

    const Event& get_event(int id) {
        for (const auto& event : events_) {
            if (event.get_id() == id)
                return event;
        }
        throw std::out_of_range("Event not found");
    }

    void remove_event(int id) {
