void process_events(DynamicList& list, LoggingService& service) {
    std::queue<Event> ring_buffer;
    std::mutex mtx;
    std::condition_variable cv;

    auto push_event = [&](const Event& event) {
        std::unique_lock<std::mutex> lock(mtx);
        ring_buffer.push(event);
        cv.notify_one();
    };

    auto process_and_log_events = [&]() {
        while (true) {
