            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this]() { return !ring_buffer.empty(); });
                if (!ring_buffer.empty()) {
                    event = ring_buffer.front();
                    ring_buffer.pop();
                }
            }

            if (!event.get_description().empty())
                service.log(event);
        }
    };

    // Create and start a thread pool to process events concurrently.
}

