#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

struct collection {
    size_t size;
    size_t capacity;
    record *data;
    pthread_mutex_t mutex;
};

struct collection* create_collection(size_t initial_capacity) {
    struct collection *col = malloc(sizeof(struct collection));
    col->size = 0;
    col->capacity = initial_capacity;
    col->data = calloc(initial_capacity, sizeof(record));
    if (!col->data) {
        free(col);
        return NULL;
    }
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

bool add_record(struct collection *col, const record *rec) {
    pthread_mutex_lock(&col->mutex);
    if (col->size == col->capacity) {
        size_t new_capacity = col->capacity ? col->capacity * 2 : 4;
        record *new_data = realloc(col->data, new_capacity * sizeof(record));
        if (!new_data) {
            pthread_mutex_unlock(&col->mutex);
            return false;
        }
        col->data = new_data;
        col->capacity = new_capacity;
    }
    memcpy(&col->data[col->size], rec, sizeof(record));
    col->size++;
    pthread_mutex_unlock(&col->mutex);
    return true;
}

const record* get_record(const struct collection *col, int key) {
    pthread_mutex_lock(&col->mutex);
    for (size_t i = 0; i < col->size; ++i) {
        if (col->data[i].key == key) {
            record *res = &col->data[i];
            pthread_mutex_unlock(&col->mutex);
            return res;
        }
    }
    pthread_mutex_unlock(&col->mutex);
    return NULL;
}

bool update_record(struct collection *col, int key, const record *new_rec) {
    const record *old_rec = get_record(col, key);
    if (!old_rec) {
        return false;
    }
    memcpy(old_rec, new_rec, sizeof(record));
    return true;
}

void serialize_collection(const struct collection *col, FILE *fp) {
    pthread_mutex_lock(&col->mutex);
    fwrite(&col->size, sizeof(size_t), 1, fp);
    for (size_t i = 0; i < col->size; ++i) {
        fwrite(&col->data[i].offset, sizeof(long), 1, fp);
        fwrite(&col->data[i].key, sizeof(int), 1, fp);
        fwrite(&col->data[i].value, sizeof(int), 1, fp);
    }
    pthread_mutex_unlock(&col->mutex);
}

void deserialize_collection(struct collection *col, FILE *fp) {
    pthread_mutex_lock(&col->mutex);
    size_t size;
    fread(&size, sizeof(size_t), 1, fp);
    col->size = size;
    free(col->data);
    col->capacity = size;
    col->data = malloc(size * sizeof(record));
    for (size_t i = 0; i < size; ++i) {
        fread(&col->data[i].offset, sizeof(long), 1, fp);
        fread(&col->data[i].key, sizeof(int), 1, fp);
        fread(&col->data[i].value, sizeof(int), 1, fp);
    }
    pthread_mutex_unlock(&col->mutex);
}
```

