#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include "external_library.h" // Include the header for your external data processing library

typedef struct Record {
    int value;
    size_t str_len;
    char *str;
} Record;

// Memory pool for Records
struct MemoryPool {
    size_t capacity;
    size_t used;
    Record **records;
};

void init_memory_pool(struct MemoryPool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->records = malloc(capacity * sizeof(Record*));
}

Record* mempool_alloc(struct MemoryPool *pool) {
    if (pool->used == pool->capacity) return NULL;
    Record *rec = pool->records[pool->used++];
    rec->value = 0;
    rec->str_len = 0;
    rec->str = NULL;
    return rec;
}

void mempool_free(struct MemoryPool *pool, Record *rec) {
    if (!rec) return;
    rec->value = 0;
    rec->str_len = 0;
    rec->str = NULL;
    pool->used--;
}

// Function to create a dynamic dataset of records
void create_dataset(struct MemoryPool *pool, size_t num_records, int min, int max) {
    for (size_t i = 0; i < num_records; ++i) {
        Record *rec = mempool_alloc(pool);
        if (!rec) continue;

        // Ensure random number is within bounds and avoid integer overflow
        rec->value = (rand() % (max - min + 1)) + min;
        if (rec->value > INT32_MAX || rec->value < INT32_MIN) {
            mempool_free(pool, rec);
            continue;
        }

        // Generate a random variable-length string with special characters and null bytes
        char str[100];
        for (size_t j = 0; j < sizeof(str); ++j) {
            str[j] = (char)(rand() % 256);
        }
        rec->str_len = strlen(str);
        rec->str = malloc(rec->str_len + 1);
        memcpy(rec->str, str, rec->str_len);
        rec->str[rec->str_len] = '\0';
    }
}

// Function to manage the dataset, handling concurrent access and data processing
void process_dataset(struct MemoryPool *pool, size_t num_records, void (*process)(const Record *)) {
    // Initialize a thread-safe counter for iteration
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t processed = 0;

    pthread_t threads[num_records];

    // Create and start worker threads
    for (size_t i = 0; i < num_records; ++i) {
        Record *rec = mempool_alloc(pool);
        if (!rec) continue;

        pthread_create(&threads[i], NULL, [=]() {
            // Lock the mutex before accessing the dataset to ensure thread safety
            pthread_mutex_lock(&mutex);
            int idx = processed++;
            pthread_mutex_unlock(&mutex);

            Record *record = mempool_alloc(pool);
            if (record) {
                memcpy(record, rec, sizeof(Record));
                process(record);
                mempool_free(pool, record);
            }
        });
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

