void resize_keys(int new_capacity) {
    int *temp_keys = malloc(new_capacity * sizeof(int));
    check_memory(temp_keys);

    if (size < new_capacity) {
        memcpy(temp_keys, keys, size * sizeof(int));
    }

    free(keys);
    keys = temp_keys;
    capacity = new_capacity;
}

void initialize() {
    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % 20001 - 10000;
        check_memory(records);
    }

    hash_library_init(keys, size); // Initialize hashing strategy
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s NUMBER\n", argv[0]);
        return EXIT_FAILURE;
    }

    size = atoi(argv[1]);
    capacity = size + (size / 2); // Minimize cache misses by overallocating
    resize_keys(capacity);

    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % 1000001; // Populate with unique integers within 0-1,000,000 range
    }

