#define LOG_ENTRY_SIZE (sizeof(time_t) + MAX_MSG_LEN + sizeof(int))
#define MEM_POOL_INITIAL_SIZE 4096
#define CHECKSUM_SHIFT 32

typedef struct {
    time_t timestamp;
    char message[MAX_MSG_LEN];
    int severity;
} log_entry;

struct log_pool {
    void* pool_base;
    size_t pool_size;
    size_t used;
};

struct log_manager {
    pthread_mutex_t mutex;
    struct log_pool mem_pool;
    log_entry* buffer;
    size_t buffer_size;
    size_t num_threads;
    bool exporting;
    FILE* output_file;
    char* output_format;
};

void log_manager_init(struct log_manager* manager, size_t num_threads) {
    manager->num_threads = num_threads;
    manager->exporting = false;
    // Initialize memory pool
    manager->mem_pool.pool_base = mmap(NULL, MEM_POOL_INITIAL_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    manager->mem_pool.pool_size = MEM_POOL_INITIAL_SIZE;
    manager->mem_pool.used = 0;

    // Initialize buffer and lock
    manager->buffer = calloc(1, sizeof(log_entry));
    manager->buffer_size = 1;
    pthread_mutex_init(&manager->mutex, NULL);
}

void* log_pool_alloc(struct log_pool* pool) {
    void* ptr = (char*)pool->pool_base + pool->used;
    if ((pool->used + LOG_ENTRY_SIZE) > pool->pool_size) {
        pool->pool_size *= 2;
        pool->pool_base = realloc(pool->pool_base, pool->pool_size);
    }
    pool->used += LOG_ENTRY_SIZE;
    return ptr;
}

void log(struct log_manager* manager, time_t timestamp, const char* message, int severity) {
    // Acquire lock
    pthread_mutex_lock(&manager->mutex);

    // Allocate a new log entry from the memory pool or buffer (if available)
    log_entry* entry;
    if (manager->mem_pool.used >= manager->mem_pool.pool_size - LOG_ENTRY_SIZE) {
        entry = realloc(manager->buffer, manager->buffer_size * 2 * sizeof(log_entry));
        if (!entry) {
            // Handle out-of-memory error
            printf("Out of memory!\n");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->buffer = entry;
        manager->buffer_size *= 2;
    } else {
        entry = (log_entry*)manager->mem_pool.pool_base + manager->mem_pool.used / LOG_ENTRY_SIZE;
        manager->mem_pool.used += LOG_ENTRY_SIZE;
    }

    // Set log entry fields
    entry->timestamp = timestamp;
    strcpy(entry->message, message);
    entry->severity = severity;

    // Release lock
    pthread_mutex_unlock(&manager->mutex);
}

void start_export(struct log_manager* manager, const char* output_file_path, const char* output_format) {
    manager->exporting = true;
    manager->output_file = fopen(output_file_path, "w");
    if (!manager->output_file) {
        // Handle file open error
        printf("Could not open output file!\n");
        return;
    }
    manager->output_format = strdup(output_format);
}

void stop_export(struct log_manager* manager) {
    manager->exporting = false;
    fclose(manager->output_file);
}

