pthread_mutex_t metadataLock = PTHREAD_MUTEX_INITIALIZER;
uint64_t nextID = 0;

char* generateID() {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&hashContext);
    SHA256_Update(&hashContext, &nextID, sizeof(nextID));
    SHA256_Final(hash, &hashContext);

    char id[32 + 1];
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf(&id[i * 2], "%02x", hash[i]);
    }
    id[SHA256_DIGEST_LENGTH * 2] = '\0';
    nextID++;

    return id;
}

