    response["message"] = "success";

    auto imageMetadata = imageMetadataPool.get();
    pthread_mutex_lock(&metadataLock);
    ImageInfo* currentImage = nullptr;
    for (size_t i = 0; i < MAX_IMAGES; ++i) {
        if (!imageMetadata[i].path.empty() && imageMetadata[i].status == UPLOADING) {
            currentImage = &imageMetadata[i];
            break;
        }
    }
    pthread_mutex_unlock(&metadataLock);

    if (currentImage) {
        if (Validate(currentImage->path)) {
            Transform(currentImage->path, currentImage->width, currentImage->height);
            Save(generateID(), currentImage->path, currentImage->width, currentImage->height);
            currentImage->status = READY;

            pthread_mutex_lock(&metadataLock);
            if (context.callback) {
                Json::Value data;
                data["id"] = currentImage->path;
                data["width"] = currentImage->width;
                data["height"] = currentImage->height;
                context.callback(data);
            }
            pthread_mutex_unlock(&metadataLock);
        } else {
            response["message"] = "error";
        }
    }

    context.callback(response);
}
