#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h> // For mmap() and munmap() for external data source integration

typedef struct {
    int id;
    char description[100];
    int priority;
} task;

typedef struct task_node {
    task* data;
    struct task_node* next;
} task_node;

task_node* head = NULL;
pthread_mutex_t tasks_lock;

void add_task(int id, const char* description, int priority) {
    task_node* new_node = malloc(sizeof(task_node));
    new_node->data = malloc(sizeof(task));
    new_node->next = head;
    new_node->data->id = id;
    strncpy(new_node->data->description, description, 100); // Limit to 100 characters
    new_node->data->priority = priority;
    pthread_mutex_lock(&tasks_lock);
    head = new_node;
    pthread_mutex_unlock(&tasks_lock);
}

void iterate_tasks() {
    task_node* current = head;
    pthread_mutex_lock(&tasks_lock);
    while (current != NULL) {
        printf("ID: %d\nDescription: %s\nPriority: %d\n", current->data->id, current->data->description, current->data->priority);
        current = current->next;
    }
    pthread_mutex_unlock(&tasks_lock);
}

void integrate_external_source() {
    void* data_ptr = mmap(NULL, SIZE_MAX, PROT_READ, MAP_ANONYMOUS | MAP_SHARED, -1, 0); // Replace SIZE_MAX with appropriate size for your platform
    if (data_ptr == MAP_FAILED) {
        perror("mmap failed");
        return;
    }

    // Read and process data from the external source here...

    munmap(data_ptr, SIZE_MAX); // Unmap the shared memory region
}
```
