#include <stdbool.h>

typedef struct SensorData {
    float temperature;
    float humidity;
    int measurementCount; // Number of measurements stored
    unsigned char* detailedMeasurements; // Array for storing detailed measurements
} SensorData;

typedef struct SensorConfig {
    const char* name;
    size_t max_measurements;
} SensorConfig;

void createSensorData(SensorConfig* config, SensorData** data) {
    *data = malloc(sizeof(SensorData));
    if (!*data) {
        fprintf(stderr, "Error: Failed to allocate memory for sensor data.\n");
        return;
    }

    SensorData* new_sensor = *data;
    new_sensor->temperature = 0.0f;
    new_sensor->humidity = 0.0f;
    new_sensor->measurementCount = 0;
    new_sensor->detailedMeasurements = calloc(config->max_measurements, sizeof(char));
    if (!new_sensor->detailedMeasurements) {
        fprintf(stderr, "Error: Failed to allocate memory for detailed measurements.\n");
        free(*data);
        *data = NULL;
        return;
    }
}

void appendSensorData(SensorConfig* config, SensorData* data, float temperature, float humidity, const char* detailedMeasurement) {
    if (data->measurementCount >= config->max_measurements) {
        fprintf(stderr, "Error: Data overflow for sensor %s. Cannot append measurement.\n", config->name);
        return;
    }

    data->temperature = temperature;
    data->humidity = humidity;

    // Copy detailedMeasurement to the appropriate array index
    strncpy(&(data->detailedMeasurements[data->measurementCount]), detailedMeasurement, config->max_measurements);
    data->measurementCount++;
}
