#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    char* id;
    struct Record* next;
} Record;

Record* create_record(int index, int value_range) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->key = rand() % value_range;
    asprintf(&(new_record->id), "ID%ld", index);
    new_record->offset = 0;
    new_record->next = NULL;

    return new_record;
}

void resize_string_pool(char** pool, size_t* capacity, size_t* length) {
    if (*capacity == *length) {
        *capacity *= 2;
        char* new_pool = realloc(*pool, *capacity * sizeof(char));
        if (!new_pool) return;
        *pool = new_pool;
    }
}

char* get_unique_id(size_t index, size_t* length) {
    resize_string_pool((char**)&g_string_pool, &g_string_capacity, &g_string_length);
    char* id = g_string_pool + *length;
    asprintf(id, "ID%ld", index);
    (*length)++;
    return id;
}

Record** create_linked_list(size_t num_records, int value_range, int seed) {
    srand(seed);

    Record** linked_list = (Record**)malloc(num_records * sizeof(Record*));
    if (!linked_list) return NULL;

    g_string_pool = malloc(1024); // initialize string pool with a small buffer
    g_string_capacity = 1024;
    g_string_length = 0;

    for (size_t i = 0; i < num_records; ++i) {
        Record* new_record = create_record(i, value_range);
        if (!new_record) break;

        if (!linked_list[i]) // first record of the linked list
            linked_list[i] = new_record;
        else {
            Record* current = linked_list[0];
            while (current->next)
                current = current->next;
            current->next = new_record;
        }
    }

    return linked_list;
}

void free_linked_list(Record** linked_list, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        Record* current = linked_list[i];
        while (current) {
            Record* temp = current;
            current = current->next;
            free(temp->id);
            free(temp);
        }
    }
    free(linked_list);
}
