#include "Transformation.h"
#include "Storage.h"

#define CHUNK_SIZE 10000

typedef struct {
    Measurement* measurements;
    size_t capacity;
    size_t length;
} MeasurementPool;

MeasurementPool* createMeasurementPool(size_t initialCapacity) {
    MeasurementPool* pool = (MeasurementPool*) malloc(sizeof(MeasurementPool));
    pool->capacity = initialCapacity;
    pool->length = 0;
    pool->measurements = (Measurement*) calloc(initialCapacity, sizeof(Measurement));
    return pool;
}

void freeMeasurementPool(MeasurementPool* pool) {
    if (pool != NULL) {
        free(pool->measurements);
        free(pool);
    }
}

void* processAndPersistMeasurements(void* data) {
    MeasurementPool* measurementPool = static_cast<MeasurementPool*>(data);

    // Validate, Transform and Save data
    for (size_t i = 0; i < measurementPool->length; ++i) {
        validateMeasurement(&measurementPool->measurements[i]);
        transformMeasurement(&measurementPool->measurements[i]);
        saveMeasurement(&measurementPool->measurements[i]);
    }

    // Free memory and return
    freeMeasurementPool(measurementPool);
    pthread_exit(0);
}

void processAndPersistDataStream(std::istream& input, std::ostream& output) {
    MeasurementPool* measurementPool = createMeasurementPool(CHUNK_SIZE);

    char line[256];
    size_t count = 0;
    while (input.getline(line, sizeof(line))) {
        // Parse line and store measurement into the pool
        Measurement measurement;
        if (parseMeasurementLine(line, &measurement)) {
            if (measurementPool->length == measurementPool->capacity) {
                MeasurementPool* newPool = createMeasurementPool(measurementPool->capacity * 2);
                memcpy(newPool->measurements, measurementPool->measurements, measurementPool->length * sizeof(Measurement));
                freeMeasurementPool(measurementPool);
                measurementPool = newPool;
            }
            measurementPool->measurements[measurementPool->length++] = measurement;
        }

        if (count % CHUNK_SIZE == CHUNK_SIZE - 1) {
            pthread_t threadId;
            pthread_create(&threadId, NULL, processAndPersistMeasurements, measurementPool);
            count = 0;
        } else {
            ++count;
        }
    }

    if (measurementPool->length > 0) {
        pthread_t threadId;
        pthread_create(&threadId, NULL, processAndPersistMeasurements, measurementPool);
    }

    output << "\n"; // Write newline character to separate processed data from the original input in CSV format
}

int main() {
    std::ifstream inputFile("measurements.csv");
    std::ofstream outputFile("processed_measurements.csv");

    if (!inputFile.is_open()) {
        std::cerr << "Error: Unable to open input file." << std::endl;
        return 1;
    }

    if (!outputFile.is_open()) {
        std::cerr << "Error: Unable to open output file." << std::endl;
        return 2;
    }

    processAndPersistDataStream(inputFile, outputFile);

    inputFile.close();
    outputFile.close();

    return 0;
}
