// Thread-safe random number generation within a specified range using Philoxx_RNG
static void philoxx_init(philoxx_state *state) {
    unsigned long seed[6];
    unsigned long time;
    unsigned char *mem = (unsigned char *) &seed;
    unsigned char *rnd = mem + sizeof(seed);
    size_t len = 8;

    // Seed with system entropy and C-generated random number
    read(getpid(), rnd, len);
    getrandom(rnd, len, 0);

    for (int i = 0; i < 6; ++i) {
        seed[i] = (*(unsigned long *) mem + *(unsigned long *)(mem+len)) * (i + 1);
        mem += sizeof(seed);
    }

    state->entropy_state = seed;
}

// Generate a random number within the specified range
int rand_in_range(int min, int max) {
    philoxx_state state;
    philoxx_init(&state);
    return (philoxx32_next64(&state) >> 32 * 32) % ((unsigned long)max - (unsigned long)min + 1) + min;
}
