// Encryption key setup for AES-CBC with PKCS7 padding using OpenSSL EVP API
EVP_CIPHER_CTX *init_encrypt_ctx(const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_encryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv, 1);
    return ctx;
}

// Decryption function for AES-CBC with PKCS7 padding using OpenSSL EVP API
int decrypt_aes_cbc(const unsigned char *in, size_t inlen, unsigned char *out, size_t outlen, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX ctx;
    int len = 0;
    if (init_encrypt_ctx(key, iv)) {
        EVP_decryptUpdate(&ctx, out, &len, in, inlen);
        EVP_decryptFinal_ex(&ctx, out + len, &outlen - len);
    }
    return 0; // Successful decryption returns 0, error is signaled by a non-zero value
}

// C# AES Decryption Method (using BouncyCastle library)
byte[] DecryptAesCbc(byte[] ciphertext, byte[] key, byte[] iv) {
    ICryptoTransform transform = new AesCbcEngine(new ParametersWithIV(KeyParameter.CreateKey(key), new ByteArray(iv)));
    MemoryStream plaintext = new MemoryStream();
    CryptoStream cs = new CryptoStream(plaintext, transform, CryptoStreamMode.Decode);
    cs.Write(ciphertext, 0, ciphertext.Length);
    cs.FlushFinalBlock();
    return plaintext.ToArray();
}
