        void* new_data = thread_safe_malloc((*pool->size + BATCH_SIZE) * sizeof(struct sensor));
        memmove(new_data, (*pool->data), (*pool->size) * sizeof(struct sensor));
        munmap((*pool->data), *pool->size * sizeof(struct sensor));
        free(*pool);
        *pool = (mem_pool*) new_data;
        (*pool)->size += BATCH_SIZE;
        (*pool)->count++;
    }

    // Generate random reading within the specified range
    struct sensor* sensor = &((*pool->data)[*len]);
    sensor->reading = (double)rand() / RAND_MAX * (max - min) + min;
    sensor->timestamp = time(NULL);
    sensor->status = ACTIVE;
    (*len)++;
}

// Function to process and calculate statistics for a batch of records (thread-safe)
void process_batch(struct sensor** arr, size_t* len, mem_pool** pool) {
    if (!*arr || !*len) return;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t threads[NUM_THREADS];

    size_t batch_size = *len < BATCH_SIZE ? *len : BATCH_SIZE;
    for (size_t i = 0; i < batch_size; ++i) {
        struct sensor* sensor = &((*arr)[i]);
        pthread_create(&threads[i], NULL, [sensor]() {
            process_sensor(sensor);
            return NULL;
        });
    }

    for (size_t i = 0; i < batch_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    double mean_val, variance_val, stddev_val;
    mean_val = mean((*arr), batch_size);
    variance_val = variance((*arr), batch_size, mean_val);
    stddev_val = standard_deviation(variance_val);

    // Periodically verify the accuracy of computed statistics (not shown here)
}

