#include <sys/mman.h> // For memory validation and leak detection

typedef struct Record {
    long offset;
    int key;
    double value;
    time_t timestamp;
    bool status;
} Record;

void initialize_record(Record* record, long offset, int key, double min_value, double max_value, time_t min_timestamp, time_t max_timestamp, bool default_status) {
    record->offset = offset;
    record->key = (rand() % (key == INT32_MAX ? RAND_MAX : key)) + 1; // Use rand() % key for smaller keys to avoid overflow
    record->value = min_value + ((max_value - min_value) * rand() / RAND_MAX);
    record->timestamp = min_timestamp + (rand() / (RAND_MAX/(max_timestamp - min_timestamp)));
    record->status = default_status;
}

Record* create_record_array(size_t size, long offset, int key, double min_value, double max_value, time_t min_timestamp, time_t max_timestamp, bool default_status) {
    Record* records = (Record*)mmap(NULL, size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        initialize_record(&records[i], offset + i, key, min_value, max_value, min_timestamp, max_timestamp, default_status);
    }

    return records;
}

void process_records(Record* records, size_t size, double threshold) {
    qsort(records, size, sizeof(Record), (int (*)(const void*, const void*))compare_timestamps); // Sort in descending order of timestamps using provided compare function

    for (size_t i = 0; i < size && records[i].timestamp >= max_timestamp - threshold; ++i) {
        if (!records[i].status) { // Process only non-flagged records
            // Integrate with external data processing library here, e.g., using provided functions or APIs
        }
    }
}

int compare_timestamps(const void* a, const void* b) {
    return (b - a > 0) ? -1 : ((b - a) < 0 ? 1 : 0);
}

void cleanup() {
    if (munmap((void*)MAP_START, MAP_LENGTH) == -1) {
        perror("munmap failed");
    }
}

int main(int argc, char* argv[]) {
    srand(time(NULL)); // Seed random number generator with current time

    size_t size = strtol(argv[1], NULL, 10);
    long offset = strtol(argv[2], NULL, 10);
    int key = argc > 3 ? atoi(argv[3]) : INT32_MAX;
    double min_value = strtod(argv[4], NULL);
    double max_value = strtod(argv[5], NULL);
    time_t min_timestamp = strtoul(argv[6], NULL, 10);
    time_t max_timestamp = strtoul(argv[7], NULL, 10);
