```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Npgsql;
using Newtonsoft.Json;
using Accord.MachineLearning;

namespace DataProcessingPipeline
{
    public class Record
    {
        public long Offset { get; set; }
        public int Key { get; set; }
        public double Value { get; set; }
    }

    public class Processor
    {
        private readonly NpgsqlConnection _connection;
        private readonly string _query;
        private readonly Dictionary<string, object> _params = new Dictionary<string, object>();
        private List<Record> _records = new List<Record>();
        private SemaphoreSlim _semaphore = new SemaphoreSlim(10); // Adjust concurrency level here
        private CancellationTokenSource _cancellationTokenSource;

        public Processor(string connectionString, string query, IDictionary<string, object> params)
        {
            _connection = new NpgsqlConnection(connectionString);
            _query = query;
            _params.UnionWith(params);
        }

        public async Task StartAsync()
        {
            _cancellationTokenSource = new CancellationTokenSource();
            await Task.WhenAll(Enumerable.Range(0, 10).Select(async i =>
            {
                await ProcessDataAsync();
            }));
        }

        private async Task ProcessDataAsync()
        {
            try
            {
                await _semaphore.WaitAsync(_cancellationTokenSource.Token);

                using var reader = await ExecuteQueryAsync();
                while (await reader.ReadAsync())
                {
                    var record = new Record
                    {
                        Offset = reader.GetInt64(0),
                        Key = reader.GetInt32(1),
                        Value = reader.GetDouble(2)
                    };
                    _records.Add(record);
                }
            }
            catch (Exception ex)
            {
                // Log exception here
            }
            finally
            {
                _semaphore.Release();
            }
        }

        private async Task<IDataReader> ExecuteQueryAsync()
        {
            using var command = new NpgsqlCommand(_query, _connection);
            _params.ToList().ForEach(kv => command.Parameters.AddWithValue(kv.Key, kv.Value));
            await _connection.OpenAsync();
            return await command.ExecuteReaderAsync();
        }
    }
}
```

