List* create_list(int size, void (*init)(void*)) {
    List* list = malloc(sizeof(List));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for list.\n");
        return NULL;
    }
    list->size = size;
    list->nodes = calloc(size, sizeof(Node*));
    if (init) {
        pthread_t threads[size];
        for (int i = 0; i < size; ++i) {
            void* arg = &((int*)init)[i];
            pthread_create(&threads[i], NULL, random_init, arg);
            pthread_join(threads[i], NULL);
            list->nodes[i] = malloc(sizeof(Node));
            if (!list->nodes[i]) {
                fprintf(stderr, "Error: Failed to allocate memory for node.\n");
                return NULL;
            }
            memcpy(list->nodes[i], init(arg), sizeof(Node));
        }
