typedef struct Record {
    int key;
    pthread_mutex_t lock;
    long offset;
} Record;

Record* create_record(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    pthread_mutex_init(&record->lock, NULL);
    record->offset = offset;
    return record;
}

void destroy_record(Record* record) {
    free(record);
}

Record** create_records(size_t max_records, size_t num_records, long min_offset, long max_offset, unsigned int seed) {
    Record** records = (Record**)malloc((max_records + 1) * sizeof(Record*));
    if (!records) return NULL;

    srand(seed);

    size_t index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % max_records;
        } while (index >= key && index + 1 < key);

        Record* record = create_record(key, min_offset + rand() % (max_offset - min_offset + 1));
        records[index] = record;
        ++index;
    }

    return records;
}

void destroy_records(Record** records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        Record* record = records[i];
        if (record) destroy_record(record);
    }
    free(records);
}

Record** manage_records(size_t max_records, size_t num_records, long min_offset, long max_offset, unsigned int seed) {
    Record** records = create_records(max_records, num_records, min_offset, max_offset, seed);
    if (!records) return NULL;

    // Thread-safe access to the record array
    pthread_mutex_t array_lock;
    pthread_mutex_init(&array_lock, NULL);

    // Implementation of the memory allocation strategy here

    // Function entry and exit points for proper memory management
    void* old_array;
    Record** new_records = records;

    while (true) {
        pthread_mutex_lock(&array_lock);
        if (!new_records || num_records == max_records) {
            old_array = new_records;
            new_records = realloc(new_records, ((max_records * 2) + 1) * sizeof(Record*));
            if (!new_records) {
                pthread_mutex_unlock(&array_lock);
                break;
            }
            max_records *= 2;
        }
        pthread_mutex_unlock(&array_lock);

        Record* record = create_record(rand() % max_records, min_offset + rand() % (max_offset - min_offset + 1));
        if (record) {
            pthread_mutex_lock(&array_lock);
            size_t index;
            for (index = 0; index < num_records && records[index] && records[index]->key <= record->key; ++index) {}
            records[index] = record;
            ++num_records;
            pthread_mutex_unlock(&array_lock);
        }
    }

    destroy_records(old_array, num_records);
    pthread_mutex_destroy(&array_lock);

    return new_records;
}
