    }
    return lists;
}

void initialize(List* list, unsigned int cap) {
    list->cap = cap;
    Node* node = create_node();
    if (!node) {
        log("Error while creating a new node.");
        return;
    }
    for (unsigned int i = 0; i < cap; ++i, node = node->next) {
        node->d = ((double)rand() / RAND_MAX) * 1.0;
        node->i = rand() % arg_int_range + arg_int_min;
        node->c = (char)(rand() % 95 + 33); // Excluding newline and null characters
        node->next = create_node();
    }
    list->head = node;
}

void free_lists(List** lists, unsigned int num_lists) {
    for (unsigned int i = 0; i < num_lists; ++i) {
        if (lists[i]) {
            Node* cur = lists[i]->head;
            while (cur) {
                Node* temp = cur;
                cur = cur->next;
                free(temp);
            }
            free(lists[i]);
        }
    }
    free(lists);
}

int main(int argc, char** argv) {
    if (argc < 3) {
        log("Usage: ./program num_lists arg_int_range");
        return -1;
    }
    unsigned int num_lists = atoi(argv[1]);
    unsigned int arg_int_range = atoi(argv[2]);
    List** lists = create_lists(num_lists);
    if (!lists) {
        log("Program failed to allocate memory for linked lists.");
        return -1;
    }

    double start_time = get_time();
    unsigned long total_memory = 0;

    for (unsigned int i = 0; i < num_lists; ++i) {
        if (!lists[i]) continue;
        total_memory += get_memory_usage();
        initialize(lists[i], 100);
    }

    double elapsed_time = get_time() - start_time;
    log(("Allocated a total of %lu bytes across %u lists, with %u nodes each.")
        , total_memory, num_lists, 100);
    log(("Elapsed time: %.6f seconds", elapsed_time));

    free_lists(lists, num_lists);

    return 0;
}
