// Thread-safe list for efficient handling of simultaneous access
typedef pthread_mutex_t lock_t;
typedef struct node_list {
    node **nodes;
    size_t capacity;
    size_t count;
    lock_t lock;
} node_list;

// Initialize and lock a node list
node_list* init_node_list(size_t initial_capacity) {
    node_list *list = malloc(sizeof(node_list));
    if (!list) return NULL;
    list->nodes = calloc(initial_capacity, sizeof(node*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Thread-safe add node to a node list
void push_node(node_list* list, const node* n) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->nodes = realloc(list->nodes, list->capacity * sizeof(node*));
    }
    list->nodes[list->count] = malloc(sizeof(node));
    if (!list->nodes[list->count]) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    memcpy(list->nodes[list->count], n, sizeof(node));
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

// Function to manage memory for an array of record structures
void* create_records(size_t num_records, size_t max_nodes, size_t max_allowed_memory, double median, double mdev) {
    struct mem_tracker tracker = { 0 };
    init_mem_tracker(&tracker, max_allowed_memory);

    record* records = mmap(NULL, num_records * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!records) {
        perror("mmap");
        goto error;
    }

    node_list* id_list = init_node_list(num_nodes = min(max_nodes, num_records));
    if (!id_list) {
        munmap(records, num_records * sizeof(record));
        perror("init_node_list");
        goto error;
    }

    for (size_t i = 0; i < num_records; ++i) {
        int id = rand() % max_nodes;
        if (!id_list->nodes[id]) {
            node* n = malloc(sizeof(node));
            if (!n) {
                perror("malloc");
                goto error;
            }
            n->val = (double)(rand() % 1000 + 1); // Customizable initialization pattern
            n->id = id;
            n->ch = 'A' + rand() % 26;
            push_node(id_list, n);
        }

        record* r = records + i;
        r->id = i;
        r->value = calloc(1, sizeof(double));
        if (!r->value) {
            perror("calloc");
            goto error;
        }
        r->list = malloc(id_list->count * sizeof(node*));
        if (!r->list) {
            free(r->value);
            perror("malloc");
            goto error;
        }

        for (size_t j = 0; j < id_list->count; ++j) {
            r->list[j] = id_list->nodes[j];
        }

        // Apply filtering algorithm to maintain statistical relevance while optimizing for data integrity
        for (size_t j = 0; j < id_list->count; ++j) {
            if (!is_statistically_relevant(r->list[j]->val, &median, &mdev)) {
                free(id_list->nodes[j]);
                memmove(id_list->nodes + j, id_list->nodes + j + 1, (id_list->count - j - 1) * sizeof(node*));
                --id_list->count;
            }
        }
    }

    // Lock and return the node list for further processing
    pthread_mutex_lock(&id_list->lock);
    return id_list;

error:
    munmap(records, num_records * sizeof(record));
    free(id_list);
    free_mem_tracker(&tracker);
    return NULL;
}

// Function to free memory tracked by create_records
void free_mem_tracker(struct mem_tracker* tracker) {
    if (tracker->value) free(tracker->value);
    if (tracker->id_list) free_node_list(tracker->id_list);
}

// Function to free a node list
void free_node_list(node_list* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->nodes[i]);
    }
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
    free(list);
}']

