#include <time.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct record {
    int value;
} Record;

typedef struct collection {
    size_t capacity;
    size_t size;
    Record* records;
} Collection;

Collection* init_collection(size_t initial_capacity, size_t max_value) {
    if (initial_capacity == 0) return NULL;

    Collection* collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < collection->capacity && i < max_value; ++i) {
        collection->records[i].value = rand() % max_value;
    }

    return collection;
}

void resize_collection(Collection* collection, size_t new_capacity) {
    if (new_capacity <= collection->size) return;

    Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) {
        perror("Reallocation failed");
        free(collection);
        exit(EXIT_FAILURE);
    }

    collection->records = new_records;
    collection->capacity = new_capacity;
}

int serialize_collection(const Collection* collection, int fd) {
    if (write(fd, &collection->capacity, sizeof(size_t)) != sizeof(size_t)) {
        perror("Failed to write capacity");
        return -1;
    }

    for (size_t i = 0; i < collection->size; ++i) {
        if (write(fd, &collection->records[i].value, sizeof(int)) != sizeof(int)) {
            perror("Failed to write record");
            return -1;
        }
    }

    return 0;
}

int deserialize_collection(Collection* collection, int fd) {
    size_t capacity;
    if (read(fd, &capacity, sizeof(size_t)) != sizeof(size_t)) {
        perror("Failed to read capacity");
        return -1;
    }

    free(collection->records);
    collection->records = mmap(NULL, capacity * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
    if (mmap == MAP_FAILED) {
        perror("Mmap failed");
        return -1;
    }

    collection->capacity = capacity;
    collection->size = capacity;

    return 0;
}

void destroy_collection(Collection* collection) {
    munmap(collection->records, collection->capacity * sizeof(Record));
    free(collection);
}
