    char status[10];
} Project;

int projects_count = 0;
Project* projects;
size_t capacity = 0;

void resize(size_t new_capacity) {
    if (new_capacity <= capacity) return;

    Project* new_projects = realloc(projects, new_capacity * sizeof(Project));
    if (!new_projects) {
        fprintf(stderr, "Failed to allocate memory for projects.\n");
        exit(1);
    }
    projects = new_projects;
    capacity = new_capacity;
}

