    if (projects_count == capacity) resize(capacity * 2);

    Project* project = &projects[projects_count];
    project->priority = (projects_count + 1); // You might want to get priority from user input
    project->estimated_start_date = time(NULL);
    project->estimated_end_date = project->estimated_start_date + 10 * 24 * 60 * 60; // Estimated end date is 10 days ahead of start date
    project->actual_start_date = 0;
    project->actual_end_date = 0;
    strcpy(project->status, "In Progress"); // You might want to get status from user input or external library

    projects_count++;
}

void serialize() {
    json_object* obj = json_object_new_array();
    for (int i = 0; i < projects_count; ++i) {
        Project project = projects[i];
        json_object* item = json_object_new_object();

        json_object_object_add(item, "priority", json_int_from_long((long int)project.priority));
        json_object_object_add(item, "estimated_start_date", json_time_t_to_string(project.estimated_start_date));
        json_object_object_add(item, "estimated_end_date", json_time_t_to_string(project.estimated_end_date));
        json_object_object_add(item, "actual_start_date", json_time_t_to_string(project.actual_start_date));
        json_object_object_add(item, "actual_end_date", json_time_t_to_string(project.actual_end_date));
        json_object_object_add(item, "status", json_string((const char*) project.status));

        json_object_array_add(obj, item);
    }

    const char* json_string = json_object_to_json_string_pretty(obj);
    printf("%s\n", json_string);
    gjson_free(json_string);
}
