#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>

// Define record structure
typedef struct {
    int key;
    long offset;
    double weight;
} Record;

// Validate memory allocation and handle overflow conditions
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory Allocation Error\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Limit values within a specified range (int and double)
void limit_value(double* value, double min, double max) {
    if (*value < min)
        *value = min;
    else if (*value > max)
        *value = max;
}

// Function to initialize data structures for large-scale dataset processing
Record* init_data(size_t num_records, size_t offset_array_len, size_t key_array_len, size_t weight_array_len) {
    Record* records = safe_malloc(num_records * sizeof(Record));
    long* offsets = safe_malloc((offset_array_len + num_records) * sizeof(long));
    int* keys = safe_malloc(key_array_len * sizeof(int));
    double* weights = safe_malloc(weight_array_len * sizeof(double));

    // Map offsets array to contiguous memory block for efficient access
    mmap((void*)offsets, (num_records + offset_array_len) * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    // Initialize offset array with zero values
    memset(offsets, 0, (num_records + offset_array_len) * sizeof(long));

    // Initialize weights within a specified range
    for (size_t i = 0; i < weight_array_len; ++i) {
        limit_value(&weights[i], -1.0, 1.0);
    }

    // Initialize records with random keys, offsets and weights
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % key_array_len;
        records[i].offset = offsets[i];
        records[i].weight = weights[rand() % weight_array_len];

        // Ensure no overflow conditions when setting offset values
        if (records[i].offset + num_records > offset_array_len) {
            fprintf(stderr, "Offset Overflow Error\n");
            exit(EXIT_FAILURE);
        }

        offsets[i + num_records] = records[i].offset + 1;
    }

    return records;
}

// Thread-safe version of init_data using pthreads for concurrent access
void* threaded_init_data(size_t num_records, size_t offset_array_len, size_t key_array_len, size_t weight_array_len, pthread_mutex_t* lock) {
    Record* records = safe_malloc(num_records * sizeof(Record));
    long* offsets = safe_malloc((offset_array_len + num_records) * sizeof(long));
    int* keys = safe_malloc(key_array_len * sizeof(int));
    double* weights = safe_malloc(weight_array_len * sizeof(double));

    // Map offsets array to contiguous memory block for efficient access
    mmap((void*)offsets, (num_records + offset_array_len) * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    // Initialize offset array with zero values
    memset(offsets, 0, (num_records + offset_array_len) * sizeof(long));

    // Initialize weights within a specified range
    for (size_t i = 0; i < weight_array_len; ++i) {
        limit_value(&weights[i], -1.0, 1.0);
    }

    pthread_t threads[num_records];
    Record thread_record;
    long thread_offset;

    for (size_t i = 0; i < num_records; ++i) {
        thread_record.key = -1;
        thread_record.offset = offsets[i];
        thread_record.weight = weights[rand() % weight_array_len];

        pthread_create(&threads[i], NULL, &init_record, (void*)&thread_record);
        pthread_mutex_lock(lock);
        offsets[i + num_records] = thread_offset = thread_record.offset + 1;
        pthread_mutex_unlock(lock);
    }

    for (size_t i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    return records;
}

// Function to initialize a single record structure
void* init_record(void* record_ptr) {
    Record* record = (Record*)record_ptr;

    // Ensure no overflow conditions when setting offset values within the thread
    if (record->offset + 1 > offsets[record->key]) {
        fprintf(stderr, "Offset Overflow Error\n");
        exit(EXIT_FAILURE);
    }

    record->key = rand() % key_array_len;
    record->offset = offsets[record->key];
    record->weight = weights[rand() % weight_array_len];

    pthread_mutex_lock(&lock);
    offsets[record->key] = record->offset + 1;
    pthread_mutex_unlock(&lock);

    return NULL;
}
