};

class DynamicCollection {
public:
    DynamicCollection(size_t initialSize, float growthFactor, size_t maxCapacity)
        : _data(), _currentSize(initialSize), _growthFactor(growthFactor), _maxCapacity(maxCapacity) {}

    ~DynamicCollection() { clear(); }

    void addRecord();
    void removeRecord(size_t index);
    const Record& getRecord(size_t index) const;
    size_t size() const { return _data.size(); }
    void saveStateToFile(const std::string& filename);
    void loadStateFromFile(const std::string& filename);
    bool isSerializedDataValid(const uint8_t* data, size_t length) const;

private:
    void resize();
    void clear();

    std::vector<Record> _data;
    size_t _currentSize;
    float _growthFactor;
    size_t _maxCapacity;
    DataProcessingLibrary _externalLib;
};

void DynamicCollection::addRecord() {
    // Ensure we don't exceed maxCapacity
    if (_data.size() >= _maxCapacity) return;

    // Use random device to generate a value within the specified range
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100); // Adjust this range as needed

    _data.push_back({dis(gen)});
    resize();
}

void DynamicCollection::removeRecord(size_t index) {
    if (index >= _data.size()) return;
    _data.erase(_data.begin() + index);
    resize();
}

const Record& DynamicCollection::getRecord(size_t index) const {
    if (index >= _data.size()) throw std::out_of_range("Index out of range.");
    return _data[index];
}

