#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <time.h>

typedef struct {
    int offset;
    int key;
    int value;
    int id;
} Record;

typedef struct Node {
    Record* data;
    struct Node *next;
} Node;

Node* create_node(Record* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void delete_node(Node** head, Node* node) {
    if (*head == node) {
        *head = node->next;
    } else {
        Node* current = *head;
        while (current && current->next != node) {
            current = current->next;
        }
        if (current) {
            current->next = node->next;
        }
    }
    free(node);
}

Record* create_record(int offset, int key, int min_value, int max_value, int key_threshold) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->id = offset * key % INT_MAX;
    record->value = min_value + rand() % (max_value - min_value + 1);

    if (record->key > key_threshold) {
        free(record);
        return NULL;
    }
    return record;
}

void parse_json(char* json, Node** head) {
    JsonArray* array = json_tokener_parse_ex(json, JSON_TOKEN_TYPE_ARRAY, "records");
    for (int i = 0; i < array->count; ++i) {
        JsonObject* obj = json_object_get_item(array->data[i], "record").val.o;
        Record* record = create_record(json_object_get_integer(obj, "offset"),
                                       json_object_get_integer(obj, "key"),
                                       json_object_get_integer(obj, "min_value"),
                                       json_object_get_integer(obj, "max_value"),
                                       json_object_get_integer(obj, "key_threshold"));
        if (record) {
            Node* node = create_node(record);
            node->next = *head;
            *head = node;
        }
    }
}

void log_dataset_modification() {
    // Integrate with your existing logging system here
}

void free_dataset(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp->data);
        free(temp);
    }
}
```

