#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <dlfcn.h>

typedef struct {
    int key;
    time_t timestamp;
    int status;
} Record;

// Function to validate memory allocation and ensure no leaks occur
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of Memory\n");
        exit(1);
    }
    return ptr;
}

// Function to initialize arrays with random values within a specified range
void init_arrays(long *offsets, int n, long min, long max) {
    for (int i = 0; i < n; ++i)
        offsets[i] = rand() % (max - min + 1) + min;
}

// Function to initialize record arrays with random keys and timestamps
void init_records(Record *records, int n) {
    for (int i = 0; i < n; ++i) {
        records[i].key = rand() % MAX_KEY;
        records[i].timestamp = time(NULL);
        records[i].status = 0;
    }
}

// Function to generate random numbers within a specified range, handling potential overflow conditions gracefully
long safe_rand(long min, long max) {
    if (RAND_MAX < (max - min + 1))
        return rand() % (max - min + 1) + min;

    long range = (long)(pow(2, 31) / (max - min + 1));
    long r = (rand() & 0x7FFFFFFF) * range;
    if (r > max)
        return max;
    return r * (max - min + 1) / range + min;
}

// Function to manage memory usage and clean up strategy for large datasets
void cleanup_large_dataset(long *offsets, Record *records, int *keys, int capacity) {
    if (capacity > MAX_CAPACITY) {
        free(offsets);
        free(records);
        free(keys);

        offsets = safe_malloc((MAX_CAPACITY / 2) * sizeof(long));
        records = safe_malloc((MAX_CAPACITY / 2) * sizeof(Record));
        keys = safe_malloc((MAX_CAPACITY / 2) * sizeof(int));
    }
}

// Function to perform operations on the records using an external library (dynamically loaded when necessary)
typedef void (*process_fn)(const Record*, int);
void process_records(Record *records, int n, process_fn process) {
    void *handle = dlopen("libdata_processing.so", RTLD_NOW);
    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        exit(1);
    }

    process = dlsym(handle, "process_records");

    (process)(records, n);

    dlclose(handle);
}

// Function to manage concurrent access to shared resources safely
pthread_mutex_t mutex;
void lock() { pthread_mutex_lock(&mutex); }
void unlock() { pthread_mutex_unlock(&mutex); }

// Main function for batch processing with memory management and performance optimization
int main(int argc, char **argv) {
    srand(time(NULL));

    long *offsets = safe_malloc(MAX_DATASET_SIZE * sizeof(long));
    int *keys = safe_malloc(MAX_DATASET_SIZE * sizeof(int));
    Record *records = safe_malloc(MAX_DATASET_SIZE * sizeof(Record));

    int n_records = argc > 1 ? atoi(argv[1]) : DEFAULT_N_RECORDS;
    int capacity = (n_records * 2 + MAX_CAPACITY / 4) * sizeof(long); // Estimate memory usage for large datasets

    pthread_mutex_init(&mutex, NULL);

    init_arrays(offsets, capacity, MIN_OFFSET, MAX_OFFSET);
    init_records(records, n_records);
    keys[n_records - 1] = n_records; // Last key value is the number of records

    for (int i = 0; i < n_records; ++i) {
        lock();
        int idx = binary_search(keys, 0, n_records - 1, offsets[i]);
        if (idx == -1) { // Empty dataset or very large dataset
            cleanup_large_dataset(offsets, records, keys, capacity);
            capacity *= 2;
            offsets = realloc(offsets, capacity * sizeof(long));
            keys = realloc(keys, capacity * sizeof(int));
            records = realloc(records, capacity * sizeof(Record));
        }
        keys[idx + 1] = offsets[i]; // Insert key value at the correct index
        records[idx].key = i;
        unlock();
    }

    process_records(records, n_records, process_function);

    pthread_mutex_destroy(&mutex);

    free(offsets);
    free(records);
    free(keys);

    return 0;
