    Node* head;
    Node* tail;
    size_t capacity;
    size_t size;
} Record;

Record* create_record(size_t capacity) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation failure for Record");
        return NULL;
    }

    record->head = record->tail = NULL;
    record->capacity = capacity;
    record->size = 0;

    Node* node = (Node*)malloc(sizeof(Node) * capacity);
    if (!node) {
        perror("Memory allocation failure for Nodes");
        free(record);
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) {
        node[i].next = (i + 1 < capacity) ? &node[i + 1] : NULL;
        record->head = &node[0];
        record->tail = &node[capacity - 1];
    }

    return record;
}

