#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <cstdlib>
#include <new>
#include <stdexcept>
#include <thread>
#include <mutex>

// External data source interface
struct IExternalData {
    virtual ~IExternalData() {}
    virtual std::unordered_map<int, long> loadMap() = 0;
};

// Record structure
struct Record {
    long* offset;
    int* key;
    int value;
};

// Custom exception for memory allocation failures
class MemoryException : public std::runtime_error {
public:
    explicit MemoryException(const char* msg) : runtime_error(msg) {}
};

// Allocate and manage dynamic memory
Record* allocateRecords(size_t num, IExternalData& externalData, long offsets[], int keys[]) {
    auto records = static_cast<Record*>(std::aligned_alloc(sizeof(Record), alignof(Record)));
    if (!records) throw MemoryException("Failed to allocate memory for records");

    try {
        std::unique_ptr<long[]> alignedOffsets(static_cast<long*>(::operator new(num * sizeof(long), alignof(long))));
        if (!alignedOffsets.get()) throw MemoryException("Failed to allocate aligned memory for offsets");

        std::copy(offsets, offsets + num, alignedOffsets.get());

        std::unique_ptr<int[]> alignedKeys(static_cast<int*>(::operator new(num * sizeof(int), alignof(int))));
        if (!alignedKeys.get()) throw MemoryException("Failed to allocate aligned memory for keys");

        std::copy(keys, keys + num, alignedKeys.get());

        for (size_t i = 0; i < num; ++i) {
            records[i].offset = &alignedOffsets[i];
            records[i].key = &alignedKeys[i];
            auto it = externalData.loadMap().find(*records[i].key);
            if (it == externalData.loadMap().end()) continue; // Skip invalid or missing keys
            *records[i].offset = it->second;
            records[i].value = std::rand() % 100 + 1; // Ensure value is within [1, 100]
        }
    } catch (...) {
        if (records) free(records);
        throw;
    }

    return records.release();
}

int main(int argc, char* argv[]) {
    const int min = std::clamp(std::stoi(argv[1]), 1, INT_MAX);
    const int max = std::clamp(std::stoi(argv[2]), min + 1, INT_MAX);
    const size_t numRecords = std::max(std::min(static_cast<size_t>(std::rand() % 900 + 100), 1000), 10);

    // Load external data source and validate input range
    IExternalData* externalData = new MyExternalData(); // Replace with your actual implementation
    std::unordered_map<int, long> map = externalData->loadMap();

    for (const auto& entry : map) {
        if (entry.first < min || entry.first > max) {
            delete externalData;
            throw std::invalid_argument("Invalid key range: min=" + std::to_string(min) + ", max=" + std::to_string(max));
        }
    }

    long offsets[numRecords];
    int keys[numRecords];

    for (size_t i = 0; i < numRecords; ++i) {
        keys[i] = min + static_cast<int>(std::rand() % ((max - min) + 1));
        offsets[i] = map[keys[i]];
    }

    Record* records = allocateRecords(numRecords, *externalData, offsets, keys);

    // Use the records as needed...

    if (records) {
        for (Record& record : *records) {
            delete[] record.offset;
            delete[] record.key;
        }
        delete[] records;
    }

    delete externalData;

    return 0;
}
```

