typedef struct {
    char *key;
    double value;
} entry;

typedef struct hash_table {
    int capacity;
    int size;
    entry **table;
    pthread_mutex_t lock;
} hash_table;

hash_table *create_hash_table(int initial_size, double min_value, double max_value) {
    hash_table *ht = malloc(sizeof(hash_table));
    ht->capacity = initial_size;
    ht->size = 0;
    ht->table = calloc(initial_size, sizeof(entry*));
    for (int i = 0; i < initial_size; ++i) {
        ht->table[i] = NULL;
    }
    ht->lock = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));
    for (int i = 0; i < ht->capacity; ++i) {
        entry *e = malloc(sizeof(entry));
        e->key = strdup(""); // replace with key initialization logic
        e->value = (min_value + (max_value - min_value) * rand() / RAND_MAX);
        ht->table[hash_function(e->key, ht->capacity)] = e;
    }

    return ht;
}

int hash_function(char *key, int capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = (hash << 5) + hash + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

entry *find_or_insert(hash_table *ht, char *key) {
    int index = hash_function(key, ht->capacity);
    pthread_mutex_lock(&ht->lock);
    entry **bucket = &ht->table[index];
    while (*bucket != NULL && strcmp((*bucket)->key, key)) {
        bucket = &(*bucket)->next;
    }

    if (*bucket == NULL) { // key not found
        entry *e = malloc(sizeof(entry));
        e->key = strdup(key);
        e->value = (double)((min_value + (max_value - min_value) * rand() / RAND_MAX));
        e->next = *bucket;
        *bucket = e;
        ++ht->size;
    }

    pthread_mutex_unlock(&ht->lock);
    return *bucket;
}

void print_stats(hash_table *ht) {
    printf("Hash Table Stats:\n");
    printf("- Number of entries: %d\n", ht->size);
    printf("- Collisions: %lld\n", (llong)(ht->capacity - 1) * ht->size / 2);
    printf("- Memory usage: %d bytes\n", sizeof(hash_table) + ht->capacity * sizeof(entry*));
}

void destroy_hash_table(hash_table *ht) {
    for (int i = 0; i < ht->capacity; ++i) {
        entry *current = ht->table[i];
        while (current != NULL) {
            entry *next = current->next;
            free(current->key);
            free(current);
            current = next;
        }
    }
    free(ht->table);
    free(ht);
}
