#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *str;
    int id;
    float value;
} item;

typedef struct collection_t {
    size_t capacity;
    size_t count;
    item *items;
    pthread_mutex_t mutex;
} collection;

collection* create_collection(size_t initial_capacity) {
    collection *coll = malloc(sizeof(collection));
    coll->capacity = initial_capacity;
    coll->count = 0;
    coll->items = calloc(initial_capacity, sizeof(item));
    coll->mutex = PTHREAD_MUTEX_INITIALIZER;
    return coll;
}

void destroy_collection(collection *coll) {
    for (size_t i = 0; i < coll->count; ++i) {
        free(coll->items[i].str);
    }
    free(coll->items);
    free(coll);
}

void default_init_item(item *item) {
    item->id = -1;
    item->value = 0.0f;
    item->str = strdup("Default Value");
}

item* get_item_at_index(collection *coll, size_t index) {
    pthread_mutex_lock(&coll->mutex);
    if (index >= coll->count) {
        pthread_mutex_unlock(&coll->mutex);
        return NULL;
    }
    item *item = &coll->items[index];
    pthread_mutex_unlock(&coll->mutex);
    return item;
}

void update_item(collection *coll, size_t index, const char *new_message) {
    item *item = get_item_at_index(coll, index);
    if (item == NULL) {
        // Handle out-of-bounds error here
        return;
    }
    pthread_mutex_lock(&coll->mutex);
    free(item->str);
    item->str = strdup(new_message);
    pthread_mutex_unlock(&coll->mutex);
}

void extend_collection(collection *coll) {
    if (coll->capacity == coll->count) {
        size_t new_capacity = 2 * coll->capacity + 1;
        item *new_items = realloc(coll->items, new_capacity * sizeof(item));
        if (!new_items) {
            // Handle memory allocation error here
            return;
        }
        coll->items = new_items;
        coll->capacity = new_capacity;
    }
}

collection* resize_collection(collection *coll, size_t new_size) {
    if (new_size <= coll->count) {
        // No resizing needed when the requested size is smaller or equal to the current count.
        return coll;
    }

    collection *new_coll = create_collection(new_size);
    memcpy(new_coll->items, coll->items, sizeof(item) * coll->count);
    destroy_collection(coll);
    return new_coll;
}
```

