#include <stdbool.h>
#include <limits.h>

// Custom error handling function
void err_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

typedef struct {
    char key[10];
    int value;
} Record;

// Function to generate a unique key as string of alphanumeric characters
char* generate_key() {
    static char chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    static thread_local unsigned int index = 0;

    // Generate a unique index within the character array bounds
    unsigned int i = index % (sizeof(chars) - 1);
    char key[11]; // For null terminator

    // Fill the key array with random characters from chars[]
    for (int j = 0; j < 10; ++j) {
        key[j] = chars[i++];
    }

    index++;
    return key;
}

// Function to allocate memory and initialize required data structures
Record* init_data(int num_records, int min_val, int max_val, int num_offsets, int num_keys) {
    // Allocate memory for offsets
    long *offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) return NULL;

    // Initialize offsets with non-zero values
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = i + 1;
    }

    // Allocate memory for keys
    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize keys with positive values
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = i + 1;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records with unique keys and random values
    for (int i = 0; i < num_records; ++i) {
        int key_index = i % num_keys;
        if (key_index >= num_keys) key_index -= num_keys;
        strcpy(records[i].key, generate_key());
        records[i].value = rand() % (max_val - min_val + 1) + min_val;

        // Handle key collisions by appending a suffix to the duplicate keys
        while (find(keys, key_index, num_keys) != -1) {
            int suffix_index = 0;
            strcpy(records[i].key, generate_key());
            for (int j = 0; j < strlen(records[i].key); ++j) {
                if (records[i].key[j] == '_') {
                    suffix_index = j + 1;
                    break;
                }
            }
            sprintf(&records[i].key[suffix_index], "_%d", key_index);
        }

        // Store the index of this record's key in the keys array
        keys[key_index] = i;
    }

    return records;
}

// Function to validate input parameters and check for duplicate keys within the keys array
int find(const int *keys, const int key_index, const int num_keys) {
    for (int i = 0; i < num_keys; ++i) {
        if (i == key_index) continue;
        if (!strcmp(keys[i].key, keys[key_index].key)) return i;
    }
    return -1;
}

// Logging function for memory allocation and deallocation events
void log_memory(const char *action, const void *ptr, size_t size) {
    FILE *log = fopen("memlog.txt", "a");
    if (log) {
        fprintf(log, "%s %p: %zu bytes\n", action, ptr, size);
        fclose(log);
    }
}

// Function to free allocated memory and log the event
void free_and_log(const void *ptr, const size_t size) {
    log_memory("deallocate", ptr, size);
    free(ptr);
}

// Main function for managing dynamic memory allocation
int main() {
    // Get environment variables for configuration
    int num_records = getenv("NUM_RECORDS") ? atoi(getenv("NUM_RECORDS")) : 10;
    int min_val = getenv("MIN_VAL") ? atoi(getenv("MIN_VAL")) : 0;
    int max_val = getenv("MAX_VAL") ? atoi(getenv("MAX_VAL")) : 100;
    int num_offsets = getenv("NUM_OFFSETS") ? atoi(getenv("NUM_OFFSETS")) : 10;
    int num_keys = getenv("NUM_KEYS") ? atoi(getenv("NUM_KEYS")) : num_offsets;

    // Validate input parameters
    if (num_records <= 0 || min_val > max_val || num_offsets <= 0 || num_keys < 0 || num_keys > num_offsets) {
        fprintf(stderr, "Invalid input parameters\n");
        return 1;
    }

    // Allocate memory for records and log the event
    Record *records = init_data(num_records, min_val, max_val);
    if (!records) return 1;
    log_memory("allocate", records, num_records * sizeof(Record));

    // Perform some operations on the data here...

    // Free allocated memory and log the event
    free_and_log(records, num_records * sizeof(Record));

    return 0;
}

This code includes a main function that initializes data using environment variables for configuration, validates input parameters, allocates memory for records, performs some operations on the data (you can add your own logic here), and frees allocated memory. It also logs memory allocation and deallocation events to a file.']

