typedef struct {
    double price;
    char name[256];
    char description[512];
    char category[32];
} Product;

struct product_collection {
    size_t count;
    size_t capacity;
    Product* products;
};

void update_prices(struct product_collection* pc, double min, double max) {
    for (size_t i = 0; i < pc->count; ++i)
        pc->products[i].price = min + (rand() % ((max - min) + 1));
}

void filter_by_category(struct product_collection* pc, const char* category, size_t* num_in_cat) {
    *num_in_cat = 0;
    for (size_t i = 0; i < pc->count; ++i) {
        if (strcmp(pc->products[i].category, category) == 0)
            (*num_in_cat)++;
    }
}

size_t total_products_per_category(struct product_collection* pc) {
    size_t num_categories = 1;
    size_t* categories_count = malloc(sizeof(size_t) * num_categories);
    categories_count[0] = 0;

    for (size_t i = 0; i < pc->count; ++i) {
        int found = 0;
        for (size_t j = 0; j < num_categories; ++j) {
            if (strcmp(pc->products[i].category, categories_count[j]) == 0) {
                found = 1;
                break;
            }
        }

        if (!found) {
            categories_count[num_categories++] = 0;
        }

        categories_count[strcmp(pc->products[i].category, categories_count[0])]++;
    }

    free(categories_count);

    return num_categories;
}

struct product_collection* create_product_collection(size_t initial_capacity) {
    struct product_collection* pc = malloc(sizeof(struct product_collection));
    pc->count = 0;
    pc->capacity = initial_capacity;
    pc->products = calloc(initial_capacity, sizeof(Product));

    return pc;
}

void free_product_collection(struct product_collection* pc) {
    free(pc->products);
    free(pc);
}
