int initialize_components(size_t arraySize, size_t numRecords, int minValue, int maxValue) {
    long *offsets = calloc(arraySize, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for offsets.\n");
        return 0;
    }

    int *keys = calloc(numRecords, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error allocating memory for keys.\n");
        free(offsets);
        return 0;
    }

    record *records = malloc(numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error allocating memory for records.\n");
        free(keys);
        free(offsets);
        return 0;
    }

    pid_t childPid;
    int status;

    srand(time(NULL));

    for (size_t i = 0; i < arraySize; ++i) {
        offsets[i] = i;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        keys[i] = rand() % (maxValue - minValue + 1) + minValue;
        records[i].key = keys[i];
        records[i].offset = offsets[keys[i]];
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    if ((childPid = fork()) < 0) {
        fprintf(stderr, "Error forking process.\n");
        free(records);
        free(keys);
        free(offsets);
        return 0;
    } else if (childPid == 0) {
        // Child process executes command here
        // ...
        _exit(EXIT_SUCCESS);
    } else {
        waitpid(childPid, &status, 0);
        if (WIFEXITED(status)) {
            // Command executed successfully, continue with the main process
            //...
        } else {
            fprintf(stderr, "Child process encountered an error and did not exit cleanly.\n");
            free(records);
            free(keys);
            free(offsets);
            return 0;
        }
    }

    free(records);
    free(keys);
    free(offsets);

    return 1;
}
