void init_and_free(long *arr, int *keys, Record **records, size_t n, int min, int max) {
    if (n <= 0 || min >= max || max < min) {
        free(arr);
        free(keys);
        for (size_t i = 0; i < n; ++i) {
            free(records[i]->value);
            free(records[i]);
        }
        free(records);
        return;
    }

