    keys = malloc(n * sizeof(int));
    records = malloc(n * sizeof(Record));

    if (!arr || !keys || !records) {
        free(arr);
        free(keys);
        for (size_t i = 0; i < n; ++i) {
            free(records[i]->value);
            free(records[i]);
        }
        free(records);
        return;
    }

    // Initialize offset array and key array with user-provided values.
    for (size_t i = 0; i < n; ++i) {
        arr[i] = i;
        keys[i] = i;
    }

    // Initialize record structures with randomly generated integers within the specified range.
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        records[i]->value = malloc(sizeof(int));
        *records[i]->value = rand() % (max - min + 1) + min;
    }
