#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int key;
    char data[10];
    float value;
};

struct HashTable {
    unsigned long size;
    unsigned long capacity;
    struct Record** table;
    pthread_mutex_t lock;
};

void init_hash(struct HashTable* table, unsigned long capacity) {
    table->size = 0;
    table->capacity = capacity;
    table->table = calloc(capacity, sizeof(struct Record*));
    if (!table->table) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        exit(EXIT_FAILURE);
    }
    table->lock = PTHREAD_MUTEX_INITIALIZER;
}

unsigned long hash(struct HashTable* table, int key) {
    return (key % table->capacity + table->capacity) % table->capacity;
}

int find_empty(struct HashTable* table, unsigned long index) {
    for (unsigned long i = index; i < table->capacity; ++i) {
        if (!table->table[i])
            return i;
    }
    return hash(table, index + 1);
}

void resize_hash(struct HashTable* table) {
    struct HashTable new_table;
    new_table.capacity *= 2;
    init_hash(&new_table, new_table.capacity);

    for (unsigned long i = 0; i < table->capacity; ++i) {
        if (table->table[i]) {
            struct Record* record = table->table[i];
            unsigned long new_index = hash(&new_table, record->key);
            int empty_index = find_empty(&new_table, new_index);
            memcpy(new_table.table[empty_index], record, sizeof(struct Record));
        }
    }

    free(table->table);
    table->table = new_table.table;
}

void insert_record(struct HashTable* table, int key, const char* data, float value) {
    pthread_mutex_lock(&table->lock);

    struct Record record = {key, {data}, value};
    unsigned long index = hash(table, key);
    int empty_index = find_empty(table, index);

    if (empty_index != index) {
        for (unsigned long i = index; i < empty_index; ++i) {
            if (!table->table[i]) continue;

            struct Record* cur_record = table->table[i];
            unsigned long new_index = hash(table, cur_record->key);

            if (new_index == empty_index) {
                memmove(table->table + empty_index + 1, table->table + empty_index, (index - empty_index) * sizeof(struct Record*));
                memcpy(table->table[empty_index], &record, sizeof(struct Record));
                break;
            }
        }
    } else {
        table->table[empty_index] = malloc(sizeof(struct Record));
        if (!table->table[empty_index]) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            pthread_mutex_unlock(&table->lock);
            return;
        }
        memcpy(table->table[empty_index], &record, sizeof(struct Record));
    }

    ++table->size;

    if (table->size > table->capacity * 0.75) {
        resize_hash(table);
    }

    pthread_mutex_unlock(&table->lock);
}

struct Record* find_record(struct HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash(table, key);
    int empty_index = find_empty(table, index);

    for (unsigned long i = index; i < empty_index || i < table->capacity; ++i) {
        if (i == empty_index && table->table[i]) {
            struct Record* record = table->table[i];
            pthread_mutex_unlock(&table->lock);
            return record;
        }

        if (i < table->capacity && table->table[i]) {
            struct Record* cur_record = table->table[i];
            if (cur_record->key == key) {
                pthread_mutex_unlock(&table->lock);
                return cur_record;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_record(struct HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash(table, key);
    int empty_index = find_empty(table, index);

    for (unsigned long i = index; i < empty_index || i < table->capacity; ++i) {
        if (i == empty_index && table->table[i]) {
            struct Record* record = table->table[i];
            if (record->key == key) {
                free(table->table[i]);
                memmove(table->table + i, table->table + i + 1, (table->capacity - (i+1)) * sizeof(struct Record*));
                --table->size;
                pthread_mutex_unlock(&table->lock);
                return;
            }
        }

        if (i < table->capacity && table->table[i]) {
            struct Record* cur_record = table->table[i];
            if (cur_record->key == key) {
                free(table->table[i]);
                memmove(table->table + i, table->table + i + 1, (empty_index - i) * sizeof(struct Record*));
                --table->size;
                pthread_mutex_unlock(&table->lock);
                return;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void cleanup(struct HashTable* table) {
    for (unsigned long i = 0; i < table->capacity; ++i) {
        if (table->table[i]) free(table->table[i]);
    }
    free(table->table);
    pthread_mutex_destroy(&table->lock);
}
