    KeyData* keys = key_alloc(1024);
    RecordData* records = record_alloc(512);
    Command* commands = command_alloc(256);

    // Initialize large integer 'offset' values, integers 'keys', and complex 'record' structures with pseudo-random numbers
    for (size_t i = 0; i < 1024; ++i) {
        offsets[i].offset = rand() % INT_MAX;
        keys[i].key = rand() % 1000000;
