        commands[i].env_vars = malloc(ENV_SIZE * sizeof(char));
        strcpy(commands[i].script_path, "/path/to/script.sh");
        snprintf(commands[i].env_vars, ENV_SIZE, "VAR1=%d VAR2=%lf", keys[i].key, records[i].dbl);
        commands[i].child_pid = 0;
        commands[i].timeout = time(NULL) + 5; // Set timeout to 5 seconds
    }

    // Execute each command asynchronously using fork, execve, and waitpid system calls with a timeout mechanism
    for (size_t i = 0; i < 256; ++i) {
        pid_t child = fork();
        if (child == 0) { // Child process
            execl("/bin/sh", "/bin/sh", "-c", commands[i].script_path, commands[i].env_vars, NULL);
            perror("execv failed");
            exit(1);
        } else if (child > 0) { // Parent process
            commands[i].child_pid = child;
            continue;
        } else { // Fork failed
            perror("fork failed");
            continue;
        }

        int status;
        if (waitpid(commands[i].child_pid, &status, WNOHANG) > 0) {
            if (!WIFEXITED(status)) { // Command didn't exit cleanly
                fprintf(stderr, "Command %d failed\n", i);
            }
        }

        if (time(NULL) > commands[i].timeout) { // Timeout reached
            kill(commands[i].child_pid, SIGTERM);
            if (waitpid(commands[i].child_pid, &status, 0) <= 0) { // Failed to reap zombie process
                perror("waitpid failed");
            }
        }
    }

    // Free memory and return status
    for (size_t i = 0; i < 1024; ++i) offset_free(offsets + i);
    for (size_t i = 0; i < 1024; ++i) key_free(keys + i);
    for (size_t i = 0; i < 512; ++i) record_free(records + i);
    for (size_t i = 0; i < 256; ++i) command_free(commands + i);

    return 1; // Success
}
