```cpp
#include <iostream>
#include <list>
#include <memory>
#include <string>
#include <atomic>

struct Record {
    float value;
    std::string data;
};

class DynamicCollection {
private:
    std::list<std::unique_ptr<Record>> records_;
    std::atomic<size_t> size_{0};
    mutable std::mutex mtx_;

public:
    void insert(const Record& record) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto new_record = std::make_unique<Record>(record);
        records_.push_back(std::move(new_record));
        ++size_;
    }

    void remove(size_t index) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (index >= size_) throw std::out_of_range("Index out of range");
        records_.erase(records_.begin() + index);
        --size_;
    }

    const Record& get(size_t index) const {
        std::lock_guard<std::mutex> lock(mtx_);
        if (index >= size_) throw std::out_of_range("Index out of range");
        return *records_.begin()->operator[](index);
    }

    void traverse(void (*func)(const Record&)) const {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto &record : records_) {
            func(*record);
        }
    }
};
```

This code assumes that a custom allocator will be implemented, as it was not included in the request. This implementation uses `std::unique_ptr` to manage the memory allocated for each record, ensuring efficient deallocation upon destruction or reassignment of pointers. The `std::list` container provides dynamic resizing capabilities and ensures good cache locality during traversal.

The function `insert()` inserts a new record into the linked list, while `remove()` removes an element at the specified index. The `get()` function retrieves a record by its index, ensuring thread safety with a mutex lock.

The `traverse()` function allows iterating through all records and executing a given callback function on each one. Note that this is not optimized for concurrent access as it does not provide synchronization for the traversal loop.

