public:
    DataStructures(size_t offsetSize, size_t keySize, size_t initialCapacity) :
        offsets_(nullptr), keys_(nullptr), records_(nullptr), capacity_(initialCapacity) {
        initialize();
    }

    ~DataStructures() {
        if (offsets_) delete[] offsets_;
        if (keys_) delete[] keys_;
        if (records_) {
            for (auto& rec : *records_) {
                if (rec.data) delete[] rec.data;
            }
            delete records_;
        }
    }

    void initialize() {
        std::unique_ptr<std::mutex> mutex(new std::mutex);
        allocateMemory(offsetSize, keySize, *mutex);
        initRecords(*mutex);
    }

    // Allocate memory for the data structures with thread-safe operations
    void allocateMemory(size_t offsetSize, size_t keySize, std::unique_ptr<std::mutex>& mtx) {
        std::lock_guard<std::mutex> lock(*mtx);
        if (capacity_ >= offsetSize + keySize + capacity_) return;  // Ensure growth strategy

        void* tempOffsets = nullptr;
        void* tempKeys = nullptr;
        void* tempRecords = nullptr;
        try {
            tempOffsets = operator new[](offsetSize * sizeof(long));
            tempKeys = operator new[](keySize * sizeof(int));
            tempRecords = operator new[](keySize * sizeof(record));
        } catch (std::bad_alloc&) {
            // Handle memory allocation errors gracefully
            if (tempOffsets) operator delete[](static_cast<char*>(tempOffsets));
            if (tempKeys) operator delete[](static_cast<char*>(tempKeys));
            if (tempRecords) operator delete[](static_cast<char*>(tempRecords));
            throw;  // Rethrow the exception to be caught by the caller
        }

        offsets_ = static_cast<long*>(tempOffsets);
        keys_ = static_cast<int*>(tempKeys);
        records_ = static_cast<record*>(tempRecords);
        capacity_ += offsetSize + keySize;
    }

    // Initialize the records with random data and integrate with the external library
    void initRecords(std::unique_ptr<std::mutex>& mtx) {
        std::lock_guard<std::mutex> lock(*mtx);
        std::default_random_engine generator;
        std::uniform_int_distribution<> distribution(-100000, 100000);

        for (size_t i = 0; i < keys_->size(); ++i) {
            records_[i].data = new int;
            *records_[i].data = distribution(generator);
            // Perform additional operations with the external library, e.g., filtering based on state and key values
        }
    }

private:
    long* offsets_;
    int* keys_;
    std::vector<record>* records_;  // Use a vector for easy memory deallocation
    size_t capacity_;
};
