#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct transaction {
    long timestamp;
    int status_code;
    char* transaction_id;
} Transaction;

struct transactions_manager {
    Transaction** transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

// Generate unique transaction ID based on current time and a counter
char* generate_transaction_id() {
    time_t now = time(NULL);
    static long counter = 0;
    char timestamp[20];
    sprintf(timestamp, "%ld", (long)now);
    char id[32];
    sprintf(id, "%s%06ld", timestamp, counter++);
    return strdup(id);
}

// Create and initialize transactions manager with given capacity
struct transactions_manager* create_transactions_manager(size_t capacity) {
    struct transactions_manager* manager = malloc(sizeof(*manager));
    manager->capacity = capacity;
    manager->count = 0;
    manager->transactions = calloc(capacity, sizeof(Transaction*));
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Add a new transaction to the transactions manager, locking the mutex before modification
void add_transaction(struct transactions_manager* manager, Transaction* transaction) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count == manager->capacity) {
        // Resize array if needed
        Transaction** new_transactions = realloc(manager->transactions, manager->capacity * 2 * sizeof(Transaction*));
        if (!new_transactions) {
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->transactions = new_transactions;
        manager->capacity *= 2;
    }
    transaction->transaction_id = generate_transaction_id();
    manager->transactions[manager->count++] = transaction;
    pthread_mutex_unlock(&manager->mutex);
}

// Retrieve a specific transaction by its transaction ID, locking the mutex before searching
Transaction* get_transaction_by_id(struct transactions_manager* manager, const char* transaction_id) {
    Transaction** transactions = manager->transactions;
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(transaction_id, transactions[i]->transaction_id) == 0) {
            Transaction* transaction = transactions[i];
            pthread_mutex_unlock(&manager->mutex);
            return transaction;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}
