typedef struct {
    pthread_mutex_t mutex;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
} Pipeline;

Pipeline* create_pipeline(int num_offsets, int num_keys, int min_value, int max_value) {
    Pipeline* pipeline = new Pipeline();
    memset(pipeline, 0, sizeof(Pipeline));

    pipeline->offsets.reserve(num_offsets);
    pipeline->keys.reserve(num_keys);
    pipeline->records.reserve(num_keys);

    for (int i = 0; i < num_offsets; ++i) {
        pipeline->offsets.push_back(i * sizeof(Record));
    }

    pthread_mutex_init(&pipeline->mutex, nullptr);
    return pipeline;
}

void* process_key(void* arg) {
    Pipeline* pipeline = static_cast<Pipeline*>(arg);
    int key;
    while (true) {
        // Assuming that you have a mechanism to get the next search_key
        if (!(key = getNextSearchKey())) break;

        pthread_mutex_lock(&pipeline->mutex);
        auto it = std::find(pipeline->keys.begin(), pipeline->keys.end(), key);
        if (it != pipeline->keys.end()) {
            int random_value = static_cast<int>(std::rand() % (max_value - min_value + 1)) + min_value;
            auto record_it = std::find(pipeline->records.begin(), pipeline->records.end(), *(it));
            *(record_it->value) = random_value;
        }
        pthread_mutex_unlock(&pipeline->mutex);
    }
    return nullptr;
}

void update_records(Pipeline* pipeline, int search_key, int new_value) {
    if (!pipeline) return;

    pthread_mutex_lock(&pipeline->mutex);
    auto it = std::find(pipeline->keys.begin(), pipeline->keys.end(), search_key);
    if (it != pipeline->keys.end()) {
        auto record_it = std::find(pipeline->records.begin(), pipeline->records.end(), *(it));
        *(record_it->value).value = new_value;
    }
    pthread_mutex_unlock(&pipeline->mutex);
}

int main() {
    Pipeline* pipeline = create_pipeline(10, 20, 1, 100);
    std::vector<std::thread> threads;

    for (size_t i = 0; i < 4; ++i) {
        threads.push_back(std::thread(process_key, pipeline));
    }

    // Update a record in the main thread for demonstration purposes
    update_records(pipeline, 5, 50);

    for (auto& t : threads) {
        t.join();
    }

    delete pipeline;
}
