    // Allocate memory for arrays
    offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        perror("Error: Failed to allocate memory for offset array");
        return;
    }
    keys = calloc(size, sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Error: Failed to allocate memory for key array");
        return;
    }
    records = malloc(sizeof(Record*) * size);
    if (!records) {
        free(offsets);
        free(keys);
        perror("Error: Failed to allocate memory for record pointers");
        return;
    }

    // Initialize key array with unique sequential integers
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(lock);
        while (1) {
            if (!keys[i]) {
                keys[i] = i + 1;
                break;
            }
        }
        pthread_mutex_unlock(lock);
    }

    // Populate record structures with unique random values within specified range
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            free(offsets);
            free(keys);
            free(records);
            perror("Error: Failed to allocate memory for record");
            return;
        }

        record->value = rand() % 100 + 1;
        record->offset = offsets;

        // Assign pointers in record structures to avoid collisions with existing keys and offsets
        long* current_offset = offsets;
        size_t j = 0;
        while (j < i) {
            if (keys[j] == record->value || (current_offset + j < offsets + size && *(current_offset + j) == record->value)) {
                break;
            }
            ++j;
        }
        if (j == i) {
            *record->offset = *(current_offset++) = i;
        } else {
            free(record);
        }

        records[i] = record;
    }
}

// Function to free allocated memory before returning
