#include <pthread.h>
#include <semaphore.h>
#include <sys/time.h>
#include <time.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct transaction {
    long timestamp;
    int status_code;
    char *transaction_id;
    double amount;
} Transaction;

struct hash {
    unsigned long hash_value;
};

struct transaction_log {
    Transaction **transactions;
    size_t capacity;
    size_t count;
    sem_t mutex;
    sem_t compression_mutex;
    size_t max_size;
};

void generate_transaction_id(char *transaction_id, struct hash *hash) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[16];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y%m%d_%H%M%S", timeinfo);

    hash->hash_value = hash_func(transaction_id, strlen(transaction_id));

    snprintf(transaction_id, 64, "%s_%lu", time_str, hash->hash_value);
}

unsigned long hash_func(const char *data, size_t length) {
    unsigned long hash = 5381;
    int c;

    while ((c = *(unsigned char *)data)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
        data++;
    }

    return hash % MAX_HASH_VALUE;
}

struct transaction_log *init_transaction_log(size_t max_size) {
    struct transaction_log *log = malloc(sizeof(struct transaction_log));
    log->transactions = calloc((size_t)(max_size / 2 + 1), sizeof(Transaction*));
    log->capacity = (size_t)(max_size / 2 + 1);
    log->count = 0;
    sem_init(&log->mutex, 0, 1);
    sem_init(&log->compression_mutex, 0, 1);
    log->max_size = max_size;

    return log;
}

void add_transaction(struct transaction_log *log, Transaction *transaction) {
    sem_wait(&log->mutex);

    if (log->count >= log->capacity) {
        // Handle overflow and potential compression here
    }

    size_t index = hash_func(transaction->transaction_id, strlen(transaction->transaction_id)) % log->capacity;
    log->transactions[index] = transaction;

    sem_post(&log->mutex);
}

Transaction *get_transaction_by_id(struct transaction_log *log, const char *transaction_id) {
    sem_wait(&log->mutex);

    for (size_t i = 0; i < log->capacity; ++i) {
        if (strcmp(log->transactions[i]->transaction_id, transaction_id) == 0) {
            Transaction *transaction = log->transactions[i];
            sem_post(&log->mutex);
            return transaction;
        }
    }

    sem_post(&log->mutex);

    return NULL;
}

void update_transaction(struct transaction_log *log, const char *transaction_id, int status_code) {
    Transaction *transaction = get_transaction_by_id(log, transaction_id);

    if (transaction) {
        transaction->status_code = status_code;
    }
}

// Implement periodic compression and memory management functions here
```

In this code, we have a `TransactionLog` struct that manages an array of transactions. The log is initialized with a specified maximum size to ensure no more than that amount of memory is used at any given time. The addition, retrieval, and updating of transactions are managed using semaphores for concurrent access control.

