#include <limits.h>

typedef struct {
    int device_id;
    char sensor_type[32];
    float temperature;
    float humidity;
} sensor_metadata;

struct bst_node {
    sensor_metadata data;
    struct bst_node *left, *right;
};

typedef struct bst_node* bst_node_t;

bst_node_t create_bst_node(const sensor_metadata* metadata) {
    bst_node_t node = malloc(sizeof(struct bst_node));
    if (!node) return NULL;
    node->data = *metadata;
    node->left = node->right = NULL;
    return node;
}

bst_node_t bst_insert(bst_node_t root, const sensor_metadata* metadata) {
    if (!root) return create_bst_node(metadata);
    int cmp = strcmp(metadata->sensor_type, root->data.sensor_type);
    if (cmp < 0) root->left = bst_insert(root->left, metadata);
    else if (cmp > 0) root->right = bst_insert(root->right, metadata);
    else {
        printf("Duplicate device ID: %d\n", metadata->device_id);
        free(metadata);
    }
    return root;
}

bst_node_t bst_find(const bst_node_t root, int device_id) {
    if (!root) return NULL;
    int cmp = root->data.device_id - device_id;
    if (cmp < 0) return bst_find(root->right, device_id);
    else if (cmp > 0) return bst_find(root->left, device_id);
    else return root;
}

void* allocate_memory(size_t size) {
    void *memory = malloc(size + sizeof(bst_node_t) + sizeof(long*) + sizeof(float*) * 2 + sizeof(sensor_metadata*) * INT_MAX);
    if (!memory) return NULL;
    memset(memory, 0, size + sizeof(bst_node_t) + sizeof(long*) + sizeof(float*) * 2 + sizeof(sensor_metadata*) * INT_MAX);
    return (char *)memory + sizeof(bst_node_t);
}

void setup_system(size_t capacity, int seed, bst_node_t* bst) {
    char* data = allocate_memory(capacity);
    if (!data) return;

    long* timestamps = (long *)data;
    float* sensor_readings = (float*)((char*)timestamps + sizeof(long)*capacity);
    sensor_metadata* metadata = (sensor_metadata*)((char*)sensor_readings + sizeof(float)*capacity);

    // Populate arrays with simulated data using the provided seed.
    for (size_t i = 0; i < capacity; ++i) {
        timestamps[i] = i;
        sensor_readings[i] = (float)(rand_r(&seed));
        metadata[i].device_id = i;
        metadata[i].sensor_type[0] = 'T';
        metadata[i].temperature = 25.0 + (float)rand_r(&seed)/100.0;
        metadata[i].humidity = 60.0 + (float)rand_r(&seed)/100.0;
    }

    *bst = bst_insert(*bst, &metadata[0]);
}

void deallocate_memory(char* memory) {
    free(memory);
}
