#include <iostream>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <thread>
#include <future>
#include <system_error>

class DataRecord {
public:
    int key;
    float precisionValue;
    char statusFlag;

    DataRecord(int k, float p, char sf) : key(k), precisionValue(p), statusFlag(sf) {}
};

class RandomNumberGenerator {
private:
    std::unordered_map<int, std::unique_ptr<DataRecord>> records;
    std::mutex mtx;
    size_t recordCount = 0;
    size_t memoryPoolSize = 1024;
    std::vector<std::unique_ptr<DataRecord>> memoryPool;

public:
    RandomNumberGenerator() {
        initializeMemoryPool();
    }

    DataRecord* getOrCreateRecord(int key) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = records.find(key);
        if (it != records.end()) {
            return it->second.get();
        }

        if (memoryPool.empty()) {
            initializeMemoryPool();
        }

        DataRecord* record = memoryPool.back().release();
        record->key = key;
        record->precisionValue = 0.f;
        record->statusFlag = '\0';
        records[key] = std::unique_ptr<DataRecord>(record);
        ++recordCount;
        return record;
    }

    void initializeMemoryPool() {
        if (memoryPoolSize <= recordCount) {
            memoryPoolSize *= 2;
        }

        for (size_t i = 0; i < memoryPoolSize - recordCount; ++i) {
            memoryPool.push_back(std::make_unique<DataRecord>(-1, 0.f, '\0'));
        }
    }
};
```

