#include <sys/mman.h> // For memory pool management

typedef struct record {
    int key;
    float weight;
    char identifier[256];
    pthread_mutex_t mutex;
} Record;

// Memory pool configuration
#define MEMORY_POOL_SIZE (1024 * 1024) // 1MB
sem_t memory_pool;

// Function to initialize a record structure with random values and unique identifier
void init_record(Record* record) {
    srand(time(NULL));
    record->key = rand() % 1000000 + 1;
    record->weight = (float)(rand() % 100000 + 1) / 100.0;
    snprintf(record->identifier, sizeof(record->identifier), "%lu", pthread_self());
}

// Memory pool management functions
void* memory_pool_alloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory from the pool\n");
        exit(EXIT_FAILURE);
    }
    sem_post(&memory_pool);
    return ptr;
}

void memory_pool_free(void* ptr) {
    if (munmap(ptr, malloc_usable_size((char*)ptr)) == -1) {
        fprintf(stderr, "Failed to free memory from the pool\n");
        exit(EXIT_FAILURE);
    }
    sem_wait(&memory_pool);
}

// Function to create and initialize a dynamic dataset of 'record' structures
Record* create_dataset(size_t num_records) {
    Record* records = memory_pool_alloc(num_records * sizeof(Record));
    for (size_t i = 0; i < num_records; ++i) {
        init_record((Record*)&records[i]);
        pthread_mutex_init(&records[i].mutex, NULL);
    }
    return records;
}

