typedef std::unique_ptr<LogData> LogDataUPtr;
typedef boost::spsc_queue<LogDataUPtr> LogQueue;

class Logger {
public:
    explicit Logger(size_t bufferSize) : bufferSize_(bufferSize), logQueue_(bufferSize), data_(std::make_unique<LogData>()), isRunning_(true) {}

    ~Logger() { stop(); }

    void start() {
        mainThread_ = std::thread(&Logger::run, this);
    }

    void stop() {
        isRunning_.store(false, std::memory_order_release);
        logQueue_.push(std::move(data_));
        mainThread_.join();
    }

    void addEntry(const logEntry& entry) {
        logQueue_.push(std::make_unique<LogData>({ { boost::to_upper_copy(entry.message), entry }, }));
    }

