        BoostLogger(); // Initialize Boost Logging
        processLogEntries();
    }

    size_t bufferSize_;
    LogQueue logQueue_;
    std::unique_ptr<LogData> data_;
    std::thread mainThread_;
    std::atomic_bool isRunning_;
};
