            close(sockfd);
            continue;
        }

        // Parse the received data and fill the DataBlock structure
        // ...

        close(sockfd);
    }

    return NULL;
}

DataProcessor* create_data_processors(size_t count) {
    DataProcessor* processors = calloc(count, sizeof(DataProcessor));

    if (!processors) {
        fprintf(stderr, "Failed to allocate memory for data processors\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        processors[i].block = calloc(1, sizeof(DataBlock));
        if (!processors[i].block) {
            fprintf(stderr, "Failed to allocate memory for data block %zu\n", i);
            free_data_processors(processors, i);
            exit(EXIT_FAILURE);
        }

        data_block_init(processors[i].block, i);
        processors[i].metadata = malloc(1024 * sizeof(char));
        if (!processors[i].metadata) {
            fprintf(stderr, "Failed to allocate memory for metadata of data block %zu\n", i);
            free_data_processors(processors, i);
            exit(EXIT_FAILURE);
        }
        memset(processors[i].metadata, 0, 1024 * sizeof(char));

        pthread_mutex_init(&processors[i].mutex, NULL);
    }

    return processors;
}

void free_data_blocks(DataBlock* blocks, size_t count) {
