        if (blocks[i].data) {
            free(blocks[i].data);
            blocks[i].data = NULL;
        }
    }
}

void free_data_processors(DataProcessor* processors, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (processors[i].block) {
            free_data_blocks(processors[i].block, 1);
            free(processors[i].block);
            processors[i].block = NULL;
        }
        if (processors[i].metadata) {
            free(processors[i].metadata);
            processors[i].metadata = NULL;
        }
    }
    free(processors);
    processors = NULL;
}

void data_processor_init(DataProcessor* dp, void (*process)(DataBlock*)) {
