}

void execute_data_processors(DataProcessor* processors, size_t count) {
    pthread_t threads[MAX_PROCESSORS];

    for (size_t i = 0; i < count && i < MAX_PROCESSORS; ++i) {
        if (pthread_create(&threads[i], NULL, data_fetcher, &processors[i]) != 0) {
            perror("Failed to create thread");
            free_data_processors(processors, i);
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < count && i < MAX_PROCESSORS; ++i) {
        pthread_join(threads[i], NULL);
    }
}
