    size_t data_size;
};

typedef struct DataProcessor {
    const DataBlock* data_ref;
    char* metadata;
    void (*process)(const DataBlock*);
};

struct MemoryPool {
    void* memory_start;
    size_t memory_size;
    size_t current_pos;
    pthread_mutex_t lock;
};

struct ConcurrentLog {
    struct MemoryPool data_pool;
    struct MemoryPool metadata_pool;
    DataProcessor* processors;
    size_t num_processors;
    pthread_t threads[NUM_THREADS];
    sem_t sync;
};

ConcurrentLog init_concurrent_log(size_t num_processors) {
    ConcurrentLog log = {0};
    log.num_processors = num_processors;
    log.sync = sem_init(NUM_THREADS, 0, 0);
    return log;
}

DataBlock* allocate_data_block(ConcurrentLog* log) {
    void* memory = NULL;
    size_t data_alignment = sizeof(double) * alignof(double);
    size_t metadata_alignment = 16;

    sem_wait(&log->sync);
    if (log->data_pool.current_pos + sizeof(DataBlock) + log->num_processors > log->data_pool.memory_size) {
        void* new_memory = mmap(NULL, log->data_pool.memory_size * 2, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_memory == MAP_FAILED) {
            perror("mmap failed");
            sem_post(&log->sync);
            return NULL;
        }
        log->data_pool.memory_start = new_memory;
        log->data_pool.memory_size *= 2;
    }

    memory = (char*)log->data_pool.memory_start + log->data_pool.current_pos;
    log->data_pool.current_pos += sizeof(DataBlock) + log->num_processors;

    DataBlock* data_block = (DataBlock*)memory;
    data_block->id = -1; // Set this later with network data
    data_block->data = (double*)((char*)data_block + sizeof(DataBlock));
    data_block->data_size = 0;

    sem_post(&log->sync);
    return data_block;
}

void free_data_block(ConcurrentLog* log, DataBlock* data_block) {
    sem_wait(&log->sync);
    // Handle data block re-use or deallocation as needed
    memset(data_block, 0, sizeof(DataBlock) + log->num_processors);
    sem_post(&log->sync);
}

