[" ```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

struct MemoryManager {
    Record* records;
    long* offsets;
    int num_records;
    int max_per_record;
    int capacity;
    pthread_mutex_t lock;
};

struct MemoryManager* memory_manager_init(int max_per_record, int initial_capacity) {
    struct MemoryManager* mm = malloc(sizeof(struct MemoryManager));
    mm->records = calloc(initial_capacity, sizeof(Record));
    mm->offsets = calloc(initial_capacity, sizeof(long));
    mm->num_records = 0;
    mm->max_per_record = max_per_record;
    mm->capacity = initial_capacity;
    pthread_mutex_init(&mm->lock, NULL);
    return mm;
}

void memory_manager_cleanup(struct MemoryManager* mm) {
    free(mm->records);
    free(mm->offsets);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

int memory_manager_expand(struct MemoryManager* mm, int new_capacity) {
    if (new_capacity <= mm->capacity) return 0;

    Record* new_records = realloc(mm->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    long* new_offsets = realloc(mm->offsets, new_capacity * sizeof(long));
    if (!new_offsets) {
        free(new_records);
        return -1;
    }

    mm->records = new_records;
    mm->offsets = new_offsets;
    mm->capacity = new_capacity;
    return 0;
}

int memory_manager_add_record(struct MemoryManager* mm, int key) {
    pthread_mutex_lock(&mm->lock);

    if (mm->num_records >= mm->capacity) {
        if (memory_manager_expand(mm, mm->capacity * 2) < 0) {
            pthread_mutex_unlock(&mm->lock);
            return -1;
        }
    }

    int index = mm->num_records++;
    Record* record = &mm->records[index];
    long offset = mm->offsets[index];

    record->key = key;
    record->offset = offset;
    record->value = rand() % (2 * mm->max_per_record + 1);

    pthread_mutex_unlock(&mm->lock);
    return index;
}

int memory_manager_get(struct MemoryManager* mm, int key) {
    pthread_mutex_lock(&mm->lock);

    for (int i = 0; i < mm->num_records; ++i) {
        if (mm->records[i].key == key) {
            pthread_mutex_unlock(&mm->lock);
            return mm->records[i].value;
        }
    }

    pthread_mutex_unlock(&mm->lock);
    return -1;
}
```

