} Record;

struct record_pool {
    void *mem_block;
    size_t capacity;
    size_t count;
};

static inline Record* get_record(struct record_pool *pool) {
    return (Record*)((char*)pool->mem_block + pool->count * sizeof(Record));
}

void log_alloc(const char *message) {
