}

// Use a custom malloc implementation for better cache locality and reduced fragmentation
void* my_malloc(size_t size, const char *file, int line) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        fprintf(stderr, "Error allocating memory at %s:%d\n", file, line);
        exit(EXIT_FAILURE);
    }
    log_alloc("Allocation");
    return ptr;
}

// A function to read initial data from a file, ensuring robust error handling for I/O issues
void load_data(struct record_pool *pool) {
    FILE *file = fopen("records.txt", "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    size_t capacity = 10000;
    pool->capacity = capacity;
    pool->count = 0;

    Record *records = (Record*)my_malloc(capacity * sizeof(Record), __FILE__, __LINE__);
    pool->mem_block = records;

    while (!feof(file)) {
        Record record;
        fscanf(file, "%ld %d %f", &record.offset, &record.key, &record.value);
        if (pool->count >= capacity) {
            capacity *= 2;
            records = (Record*)realloc(records, capacity * sizeof(Record));
            pool->mem_block = records;
        }

        memcpy(get_record(pool), &record, sizeof(Record));
        pool->count++;
    }

    fclose(file);
}

// Thread-safe function to compute the weighted average of offset and key
void compute_value(struct record *record) {
    record->value = WEIGHT_OFFSET * (float)record->offset + WEIGHT_KEY * (float)record->key;
}

// Implement a thread pool for handling concurrent access to the record array from multiple threads
#define NUM_THREADS 8
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* worker(void *arg) {
    struct record *records = arg;

    for (size_t i = 0; i < pool->count; ++i) {
        pthread_mutex_lock(&mutex);
        compute_value(get_record(pool) + i);
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int main() {
    struct record_pool pool;
    load_data(&pool);

    pthread_t threads[NUM_THREADS];

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, worker, &pool)) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error joining thread");
            exit(EXIT_FAILURE);
        }
    }

    munmap(pool.mem_block, pool.capacity * sizeof(Record));
    log_dealloc("Deallocation");

    return 0;
}
