const unsigned int RECORD_SIZE = 16;

struct Record {
    int index;
    std::vector<long> offsets;
    std::vector<int> keys;
};

class ThemeCache {
private:
    std::map<std::string, std::pair<unsigned char*, size_t>> cache;
    std::vector<Record> records;
    unsigned int currentIndex = 0;

    // Function to handle potential I/O errors gracefully
    std::pair<unsigned char*, size_t> readFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary | std::ios::ate);
        if (!file.is_open()) return {nullptr, 0};
        size_t filesize = file.tellg();
        unsigned char* buffer = new unsigned char[filesize];
        file.seekg(0);
        file.read((char*)buffer, filesize);
        file.close();
        return {buffer, filesize};
    }

public:
    // Function to initialize AES-256-CBC cipher
    AES_KEY* initCipher(const std::string& password) {
        unsigned char key[32];
        SHA256((const unsigned char*)password.c_str(), password.length(), key);
        AES_set_encrypt_key(key, 256, &ctx);
        return &ctx;
    }

    // Function to add a record, handling memory allocation and balancing between the number of records and the maximum allowable size per record
    void addRecord() {
        if (records.empty()) {
            records.push_back(Record{currentIndex++, {}, {}});
            return;
        }

        Record& lastRecord = records.back();
        size_t currentSize = lastRecord.offsets.size() + lastRecord.keys.size() * sizeof(int);

