#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Custom hash function, using Jenkins Hash
unsigned int jenkins_hash(const char *str) {
    unsigned int hash = 0;
    unsigned int len = strlen(str);

    for (int i = 0; i < len; ++i) {
        hash += hash * PRIME + str[i];
    }

    return hash % NUM_RECORDS;
}

typedef struct Record {
    int value;
} Record;

int initialize(size_t array_size, size_t num_records, int min_value, int max_value) {
    long *offsets = (long*)malloc(array_size * sizeof(long));
    if (!offsets) return -1; // Error: memory allocation failed for offsets

    int *keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1; // Error: memory allocation failed for keys
    }

    Record *records = NULL;

    if (num_records > 0) {
        records = (Record*)calloc(NUM_RECORDS, sizeof(Record));
        if (!records) {
            free(offsets);
            free(keys);
            return -1; // Error: memory allocation failed for records
        }
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Initialize offset array and keys
    for (size_t i = 0; i < array_size; ++i) {
        offsets[i] = i;
    }

    // Shuffle keys to minimize key collisions
    for (int i = num_records - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        int temp = keys[j];
        keys[j] = keys[i];
        keys[i] = temp;
    }

    // Initialize records array with random values
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[keys[i]].value = keys[i];
    }

    return 0; // Success
}

// Thread-safe deallocation function
void free_resources(Record **records, long *offsets, int *keys) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);

    pthread_mutex_unlock(&mutex);
}
```

